<?php

function generateRandomString($length, $charSet = null) {
    if (!$charSet) {
        $charSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-={}[]|;:,.<>?/~`\'';
    }
    $randomString = '';
    $validChars = str_split($charSet);
    for ($i = 0; $i < $length; $i++) {
        $randomString .= $validChars[rand(0, count($validChars) - 1)];
    }
    return $randomString;
}

function hashPassword($password, $algorithm, $rounds = 12) {
    if (!in_array($algorithm, ['bcrypt', 'sha256'])) {
        throw new Exception("Unsupported hash algorithm: {$algorithm}");
    }
    $salt = uniqid();
    switch ($algorithm) {
        case 'bcrypt':
            return password_hash($password . $salt, PASSWORD_BCRYPT, ['cost' => $rounds]);
        case 'sha256':
            return hash('sha256', $password . $salt);
    }
}

function verifyPassword($hashedPassword, $plaintextPassword, $algorithm) {
    if (!in_array($algorithm, ['bcrypt', 'sha256'])) {
        throw new Exception("Unsupported hash algorithm: {$algorithm}");
    }
    switch ($algorithm) {
        case 'bcrypt':
            return password_verify($plaintextPassword, $hashedPassword);
        case 'sha256':
            return hash('sha256', $plaintextPassword) === $hashedPassword;
    }
}

// Usage example
$randomStringLength = 10;
$charSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
