```java
public JsonNode getPokemonWeaknesses(int pokemonId) {
    PokemonResponse pokemonData = cache.get(pokemonId);
    if (pokemonData != null) return OBJECT_MAPPER.valueToTree(pokemonData);

    Request request = new Request.Builder()
            .url(BASE_URL + "/pokemon/" + pokemonId)
            .build();

    try (Response response = HTTP_CLIENT.newCall(request).execute()) {
        if (!response.isSuccessful()) throw ExceptionUtil.createHttpException(response);

        JsonNode node = OBJECT_MAPPER.readTree(response.body().byteStream());
        PokemonResponse newPokemonData = OBJECT_MAPPER.treeToValue(node.get("pokemon"), PokemonResponse.class);
        cache.put(pokemonId, newPokemonData);

        return OBJECT_MAPPER.valueToTree(newPokemonData);
    } catch (IOException e) {
        Logger.error("Error fetching Pokemon data", e);
        throw ExceptionUtil.createApiException("Failed to connect to the API");
    }
}
