char* get_full_path(const char *path, size_t max_size, bool is_absolute) {
    if (strlen(path) >= max_size) {
        fprintf(stderr, "Error: Path exceeded maximum buffer size.\n");
        return NULL;
    }

    char *full_path = malloc(max_size + 1);
    if (!full_path) {
        fprintf(stderr, "Error: Failed to allocate memory for full path.\n");
        return NULL;
    }

    ssize_t path_len = strlen(path);

    // Check if the path is absolute or not
    if (!is_absolute && *(path + path_len - 1) != '/') {
        char cwd[PATH_MAX];
        if (getcwd(cwd, sizeof(cwd)) == NULL) {
            fprintf(stderr, "Error: Failed to get current working directory.\n");
            free(full_path);
            return NULL;
        }

        // Add the current working directory to the path if it's not absolute
        snprintf(full_path, max_size + 1, "%s/%s", cwd, path);
    } else {
        strncpy(full_path, path, max_size);
    }

    // Handle tilde (~) as a shorthand for home directory
    if (strlen(full_path) >= 2 && full_path[0] == '~' && full_path[1] != '/') {
        char homedir[PATH_MAX];
        if (getenv("HOME") != NULL && strlen(getenv("HOME")) + path_len < max_size) {
            strncpy(homedir, getenv("HOME"), PATH_MAX);
            snprintf(full_path, max_size + 1, "%s/%s", homedir, &full_path[1]);
        } else {
            fprintf(stderr, "Error: Home directory not found or path exceeded maximum buffer size.\n");
            free(full_path);
            return NULL;
        }
    }

    if (strlen(full_path) >= max_size) {
        fprintf(stderr, "Error: Full path exceeded maximum buffer size.\n");
        free(full_path);
        return NULL;
    }

    return full_path;
}
