#include <iostream>
#include <vector>
#include <unordered_map>
#include <fstream>
#include <sstream>
#include <cstdlib>

template<typename T>
class SpatialHashGrid {
private:
    size_t width, height, depth;
    size_t bucketSize;
    size_t maxEntriesPerBucket;
    std::vector<std::unordered_map<size_t, T>> grid;

public:
    SpatialHashGrid(size_t _width, size_t _height, size_t _depth, size_t _bucketSize, size_t _maxEntriesPerBucket, std::vector<T>& data)
        : width(_width), height(_height), depth(_depth), bucketSize(_bucketSize), maxEntriesPerBucket(_maxEntriesPerBucket), grid(depth) {
        if (_width == 0 || _height == 0 || _depth == 0 || _bucketSize == 0 || _maxEntriesPerBucket <= 0) {
            std::cerr << "Invalid input. Please provide valid grid dimensions, bucket size, and maximum entries per bucket." << std::endl;
            exit(1);
        }

        for (size_t i = 0; i < depth; ++i)
            grid[i].resize((width * height) / bucketSize + (_maxEntriesPerBucket > 0 ? _maxEntriesPerBucket : 1));

        if (!data.empty()) {
            size_t index = hashFunction(0, 0, 0, data[0]);
            for (size_t i = 0; i < data.size(); ++i)
                grid[index / bucketSize][index % bucketSize] [i] = data[i];
        }
    }

    size_t hashFunction(size_t x, size_t y, size_t z, T value) const {
        auto hash = std::hash<T>{}(value);
        return (x * width + y) * depth + z + (hash % bucketSize);
    }

    void insert(const T& value) {
        size_t index = hashFunction(0, 0, 0, value);
        if (grid[index / bucketSize][index % bucketSize].size() < maxEntriesPerBucket)
            grid[index / bucketSize][index % bucketSize][grid[index / bucketSize][index % bucketSize].size()] = value;
    }

    T query(const T& value) const {
        size_t index = hashFunction(0, 0, 0, value);
        auto it = grid[index / bucketSize][index % bucketSize].find(value);
        return it != grid[index / bucketSize][index % bucketSize].end() ? it->second : T();
    }

    void serialize(const std::string& filename) const {
        std::ofstream outfile(filename);
        if (!outfile.is_open()) {
            std::cerr << "Failed to open file for writing." << std::endl;
            return;
        }

        for (size_t i = 0; i < depth; ++i) {
            for (size_t j = 0; j < grid[i].size(); ++j) {
                auto it = grid[i][j].cbegin();
                auto end = grid[i][j].cend();
                outfile << i * grid[i].size() + j << ' ';
                while (it != end) {
                    outfile << it->first << ' ' << it->second << '\n';
                    ++it;
                }
            }
        }
    }
};
