async function uploadFileFromUrl(url) {
  try {
    const metadata = extractMetadataFromUrl(url);
    const mimeType = metadata.mimeType;
    const fileSize = metadata.size;

    if (fileSize > 50 * 1024 * 1024) { // 50MB limit exceeded
      const archive = createArchive(url, maxChunkSize);
      for await (const chunk of archive) {
        uploadFileToS3(chunk.path, generateUniqueFilename());
      }
    } else {
      const filePath = downloadUrlToTempFile(url);
      uploadFileToS3(filePath, generateUniqueFilename());
    }

    // Log successful upload details
    winston.info(`Uploaded ${mimeType} file with size ${fileSize} bytes`);

    return generatePublicUrl(fileKey);
  } catch (error) {
    let retriesLeft = retryAttempts;
    while (retriesLeft > 0 && error instanceof Error) {
      winston.warn(`Error uploading file: ${error.message}. Retrying in ${Math.pow(2, retriesLeft - 1)} seconds...`);
      await new Promise((resolve) => setTimeout(resolve, Math.pow(2, retriesLeft - 1) * 1000));
      try {
        // Repeat the upload process with the same arguments
        retriesLeft--;
        throw error;
      } catch (rethrowError) {
        error = rethrowError;
      }
    }

    // Handle other errors and log appropriate messages
  }
}

