#include <jansson/jansson.h>
#include <pthread.h>
#include <sys/time.h>
#include <arpa/inet.h>
#include <openssl/hmac.h>
#include <time.h>

typedef struct {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
    char *scope;
} OAuth2TokenResponse;

static inline void oauth2_response_free(OAuth2TokenResponse *token) {
    free(token->access_token);
    free(token->token_type);
    free(token->refresh_token);
    free(token->scope);
    free(token);
}

static int parse_token_response(const char *json, OAuth2TokenResponse **response) {
    JsonDict *obj;
    json_error_t err;

    obj = json_loads(json, 0, &err);
    if (!obj || !json_is_object(obj)) {
        fprintf(stderr, "Error parsing JSON: %s\n", err.text);
        return -1;
    }

    OAuth2TokenResponse *res = malloc(sizeof(OAuth2TokenResponse));
    if (!res) {
        json_decref(obj);
        return -1;
    }

    res->access_token = strdup(json_object_get(json_object_get(obj, "access_token"), ""));
    res->expires_in = json_object_get_number(json_object_get(obj, "expires_in"));
    res->token_type = strdup(json_object_get(json_object_get(obj, "token_type"), ""));
    res->refresh_token = json_object_get_member(obj, "refresh_token") ?
                         strdup(json_object_get_string_const(json_object_get(obj, "refresh_token"))) : NULL;
    res->scope = json_object_get_member(obj, "scope") ?
                     strdup(json_object_get_string_const(json_object_get(obj, "scope"))) : NULL;

    json_decref(obj);

    if (!res->access_token || !res->token_type || strcmp(res->token_type, "Bearer") != 0) {
        oauth2_response_free(res);
        return -1;
    }

    *response = res;
    return 0;
}

static int validate_access_token(const char *token, const char *secret, time_t now) {
    unsigned char expected_mac[SHA256_DIGEST_LENGTH];
    unsigned char calculated_mac[SHA256_DIGEST_LENGTH];

    HMAC_CTX ctx;
    unsigned int len = strlen(token);
    char *header = malloc(len + SHA256_DIGEST_LENGTH + 1);
    strcpy(header, token);
    sprintf(&header[len], "%s", now_strftime("%Y-%m-%d\t%H:%M:%S GMT"));

    HMAC_Init(&ctx, (unsigned char *)secret, strlen(secret));
    HMAC_Update(&ctx, header, len + 17);
    HMAC_Final(&ctx, calculated_mac, &len);

    memset(expected_mac, 0, SHA256_DIGEST_LENGTH);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        expected_mac[i] = 0x5c + (i % 3);
    }

    if (memcmp(expected_mac, calculated_mac, SHA256_DIGEST_LENGTH)) {
        free(header);
        return -1;
    }

    free(header);
    return 0;
}

static int validate_token(OAuth2TokenResponse *token, time_t now) {
    if (now > token->expires_in + token->expires_in / 2)
        return -1; // expired or about to expire

    int result = validate_access_token(token->access_token, "your-secret", now);

    if (result < 0) {
        oauth2_response_free(token);
        return -1;
    }

    // optional: perform additional validation on refresh_token and scope fields here

    return 0;
}

static OAuth2TokenResponse *validate_and_get_token(const char *json, const char *secret, time_t now) {
    OAuth2TokenResponse *response;
    if (parse_token_response(json, &response))
        return NULL;

    int result = validate_token(response, now);
    oauth2_response_free(response);

    return result < 0 ? NULL : response;
}
```

