#include <boost/asio/io_service.hpp>
#include <boost/asio/ip/tcp.hpp>
#include <boost/serialization/access.hpp>
#include <boost/serialization/vector.hpp>
#include <boost/serialization/map.hpp>
#include <boost/archive/text_oarchive.hpp>
#include <boost/archive/text_iarchive.hpp>

namespace RandomGenerator {
    class MT19937Generator {
        std::mt19937 engine;
        unsigned long long seed;
        int min, max;
        mutex mtx;
        boost::asio::io_service ioService;
        boost::asio::ip::tcp::socket socket;
        bool connectedToDatabase;

    public:
        MT19937Generator(unsigned long long seed = std::random_device()(), int min = 0, int max = RAND_MAX) : seed(seed), min(min), max(max), engine(seed), connectedToDatabase(false) {}

        void connectToDatabase(const std::string& host, const std::string& port) {
            try {
                tcp::resolver resolver(ioService);
                auto endpoints = resolver.resolve(host, port);
                socket.connect(endpoints.begin()->second);
                connectedToDatabase = true;
            } catch (const std::exception& e) {
                std::cerr << "Error connecting to database: " << e.what() << std::endl;
            }
        }

        void saveSeed() const {
            if (!connectedToDatabase) throw std::runtime_error("Not connected to the database");
            oarchive ar(ioService);
            ar & seed;
            boost::asio::write(socket, boost::asio::buffer(ar.data(), ar.written()));
        }

        unsigned long long getSeed() const {
            if (!connectedToDatabase) throw std::runtime_error("Not connected to the database");
            iarchive ar(ioService);
            ar & seed;
            return seed;
        }

        int random(int range = RAND_MAX) {
            if (range < 1 || max - min + 1 > static_cast<int>(range)) throw std::invalid_argument("Invalid range");
            boost::uniform_int_distribution<> dist(min, max);
            std::lock_guard<std::mutex> lk(mtx);
            return dist(engine);
        }
    };

    // Boost Serialization support for MT19937Generator class
    BOOST_CLASS_VERSION(RandomGenerator::MT19937Generator, 0)
    BOOST_SERIALIZATION_SPLIT_MEMBER()

    template<typename Archive>
    void serialize(Archive& ar, RandomGenerator::MT19937Generator& gen, const unsigned int version) {
        ar & gen.seed;
    }
}

// Unit Test implementation for the RandomGenerator::MT19937Generator class
#include <gtest/gtest.h>
#include "RandomGenerator.hpp"

