    RandomGenerator::MT19937Generator gen(123456);
    for (int i = 0; i < 100; ++i) {
        int num = gen.random();
        EXPECT_TRUE(num >= 0 && num <= RAND_MAX);
    }
}

TEST(RandomGenerator, RangeTest) {
    RandomGenerator::MT19937Generator gen(123456, 1, 10);
    for (int i = 0; i < 100; ++i) {
        int num = gen.random();
        EXPECT_TRUE(num >= 1 && num <= 10);
    }
}

