using System;
using UnityEngine;

public abstract class ValueGenerator
{
    private float _minValue;
    private float _maxValue;
    protected DistributionType _distributionType;

    public ValueGenerator(float minValue, float maxValue, DistributionType distributionType)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _distributionType = distributionType;
    }

    public float FloatValue()
    {
        return GetDistribution().GetRandomFloat(_minValue, _maxValue);
    }

    public int IntValue()
    {
        return Mathf.RoundToInt(GetDistribution().GetRandomFloat(_minValue, _maxValue));
    }

    protected abstract IDistribution GetDistribution();

    public override string ToString()
    {
        return $"ValueGenerator {{ Min: {_minValue}, Max: {_maxValue}, Distribution: {_distributionType.ToString()} }}";
    }

    protected void OnDistributionChanged(DistributionType newDistributionType)
    {
        _distributionType = newDistributionType;
        GC.Collect(); // Clean up resources
    }
}

public enum DistributionType
{
    Uniform,
    Gaussian,
    Custom // Extend this enumeration for other distribution types as needed
}

public interface IDistribution
{
    float GetRandomFloat(float minValue, float maxValue);
}

