function updateClinicStatus($clinic_id, $new_status, $last_modified_ip) {
    // Database connection details
    $dbhost = 'your_dbhost';
    $dbuser = 'your_dbuser';
    $dbpass = 'your_dbpassword';
    $dbname = 'your_dbname';

    // Error log file path
    $errorLogFile = 'error_log.txt';

    // Initialize rate limiter variables
    $ipAddress = $_SERVER['REMOTE_ADDR'];
    $rateLimitInterval = 60; // In seconds (1 minute)
    $rateLimitCount = 5;
    $currentTime = time();
    $lastUpdateTime = isset($_SESSION['last_update_time'][$ipAddress]) ? $_SESSION['last_update_time'][$ipAddress] : 0;

    // Check if rate limit has been exceeded for the current IP address within the specified interval
    if (($currentTime - $lastUpdateTime) < ($rateLimitInterval)) {
        sleep(($rateLimitInterval - ($currentTime - $lastUpdateTime))); // Wait until it's time to update again
        return 'Rate limit exceeded. Please try again later.';
    }

    $_SESSION['last_update_time'][$ipAddress] = $currentTime; // Update the last update time for this IP address

    try {
        // Create a new PDO instance and prepare the SQL statement
        $pdo = new PDO("mysql:host=$dbhost;dbname=$dbname", $dbuser, $dbpass);
        $stmt = $pdo->prepare("UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?");
        $stmt->execute([$new_status, $last_modified_ip, $clinic_id]);

        // Check the number of rows affected and return appropriate message
        if ($stmt->rowCount() == 1) {
            return 'Clinic status updated successfully.';
        } else {
            return 'Error: Clinic not found.';
        }
    } catch (PDOException $e) {
        // Log the error message to the error log file and return an error message
        file_put_contents($errorLogFile, date('Y-m-d H:i:s') . ' - ' . $e->getMessage() . "\n", FILE_APPEND);
        return 'Error: ' . $e->getMessage();
    }
}
