class AsyncReducer {
  constructor(apiService) {
    this.apiService = apiService;
  }

  async reduceArray(array, initialValue, callback) {
    if (!Array.isArray(array)) {
      throw new Error('Input must be an array');
    }

    const chunkSize = 1000; // Adjust as needed
    let reducedValue = initialValue;
    let activePromises = [];

    for (let i = 0; i < array.length; i += chunkSize) {
      const chunk = array.slice(i, i + chunkSize);
      const promise = this._reduceChunk(chunk).catch(error => {
        console.error(`Error in chunk reduction: ${error}`);
      });
      activePromises.push(promise);
    }

    await Promise.all(activePromises);

    return reducedValue;
  }

  async _reduceChunk(chunk) {
    const fetchedValues = await this._fetchNumbersFromApi(chunk);

    let reducedValue = this._applyCallback(fetchedValues[0], null);
    for (let i = 1; i < fetchedValues.length; ++i) {
      reducedValue = this._applyCallback(reducedValue, fetchedValues[i]);
    }

    return reducedValue;
  }

  _fetchNumbersFromApi(numbers) {
    // Simulate an asynchronous API call using promises.
