    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (Math.random() > 0.5) {
          resolve(numbers.map(number => Number(number)));
        } else {
          reject(new Error('API fetch failed'));
        }
      }, Math.floor(Math.random() * 1000)); // Simulate network latency
    });
  }

  _applyCallback(accumulatedValue, currentNumber) {
    if (typeof this.callback !== 'function') {
      throw new Error('Callback function is not defined');
    }

    return this.callback(accumulatedValue, currentNumber);
  }
}

