struct Character {
    std::string currentAttack;
    unsigned long lastUsed[3]{};
};

void attack(Character& character) {
    auto now = std::chrono::system_clock::now();
    double nextAttackTime[3]{};

    // Calculate next attack time for each type based on the previous attacks
    for (size_t i = 0; i < 3; ++i) {
        if (character.lastUsed[i] != 0) {
            auto elapsedSeconds = std::chrono::duration_cast<std::chrono::seconds>(now - std::chrono::system_clock::from_time_t(character.lastUsed[i].time since_epoch())).count();
            nextAttackTime[i] = elapsedSeconds + (6.0 * (i == 0) + 12.0 * (i == 1) + 3.0 * (i == 2));
        } else {
            nextAttackTime[i] = 0;
        }
    }

    // Randomly select an attack with cooldown checks
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 2);
    size_t randomIndex = dis(gen);

    if (nextAttackTime[randomIndex] > 0 && now.time_since_epoch() - character.lastUsed[randomIndex].timeSinceEpoch() >= nextAttackTime[randomIndex]) {
        character.currentAttack = ("Slash", "Fireball", "Poison Dart")[randomIndex];
        character.lastUsed[randomIndex] = now;

        std::ofstream logFile("attack_log.txt", std::ios::app);
        if (logFile.is_open()) {
            logFile << std::to_string(now.time_since_epoch()) + " - " + character.currentAttack << '\n';
            logFile.close();
        }
    }
}
