```javascript
const express = require('express');
const axios = require('axios');
const redis = require('redis');
const client = redis.createClient();
const app = express();

// Middleware to handle requests and responses
app.use(express.json());

// API endpoint for fetching weather data
app.get('/weather/:location', async (req, res) => {
  const { location } = req.params;
  try {
    // Fetch current weather from OpenWeatherMap API
    const currentWeatherResponse = await axios.get(`https://api.openweathermap.org/data/2.5/weather?q=${location}&units=metric&appid={YOUR_API_KEY}`);
    // Cache the response in Redis for a specified time (e.g., 60 minutes)
    client.setex(`currentWeather-${location}`, 3600, JSON.stringify(currentWeatherResponse.data));

    const forecastResponse = await axios.get(`https://api.openweathermap.org/data/2.5/forecast?q=${location}&units=metric&appid={YOUR_API_KEY}`);
    // Cache the response in Redis for a specified time (e.g., 1 hour)
    client.setex(`forecast-${location}`, 3600, JSON.stringify(forecastResponse.data));

    const monthlyStatsResponse = await axios.get(`https://api.climateapi.io/v2/history?q=${location}&start_time=1y&end_time=now&units=metric&lang=en&format=json&apikey={YOUR_API_KEY}`);
    // Cache the response in Redis for a specified time (e.g., 7 days)
    client.setex(`monthlyStats-${location}`, 604800, JSON.stringify(monthlyStatsResponse.data));

    const historicalEventsResponse = await axios.get(`https://api.climateapi.io/v2/history?q=${location}&start_time=1y&end_time=now&events=heatwave,coldspell&units=metric&lang=en&format=json&apikey={YOUR_API_KEY}`);
    // Cache the response in Redis for a specified time (e.g., 7 days)
    client.setex(`historicalEvents-${location}`, 604800, JSON.stringify(historicalEventsResponse.data));

    res.json({
      current_weather: currentWeatherResponse.data,
      forecast: forecastResponse.data.list.slice(1, 8), // Assuming the response has a list of 40 daily forecasts
      monthly_statistics: monthlyStatsResponse.data.data[0],
      historical_events: historicalEventsResponse.data.data
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Start the server on a specified port (e.g., 3000)
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
