```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int capacity;
    int size;
    int *data;
} Array;

Array create_array(int capacity) {
    Array arr = {capacity, 0, malloc(sizeof(int) * capacity)};
    return arr;
}

void resize_array(Array* arr, int new_capacity) {
    if (new_capacity <= arr->size) return;

    int *new_data = realloc(arr->data, sizeof(int) * new_capacity);
    if (!new_data) {
        fprintf(stderr, "Error: out of memory\n");
        exit(EXIT_FAILURE);
    }
    arr->data = new_data;
    arr->capacity = new_capacity;
}

void add_to_array(Array* arr, int value) {
    if (arr->size == arr->capacity) resize_array(arr, 2 * arr->capacity);
    arr->data[arr->size] = value;
    ++arr->size;
}

bool is_integer(const char *str) {
    int i = 0;
    while (str[i] != '\0') {
        if (!isdigit(str[i])) return false;
        ++i;
    }
    return true;
}

int find_largest(const Array arr) {
    int largest = arr.data[0];
    for (int i = 1; i < arr.size; ++i) {
        if (arr.data[i] > largest) largest = arr.data[i];
    }
    return largest;
}

void sort_array(Array* arr) {
    for (int i = 0; i < arr->size - 1; ++i) {
        for (int j = i + 1; j < arr->size; ++j) {
            if (arr->data[i] > arr->data[j]) {
                int temp = arr->data[i];
                arr->data[i] = arr->data[j];
                arr->data[j] = temp;
            }
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s filename\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    Array numbers = create_array(8);
    char c;
    while ((c = getc(file)) != EOF) {
        if (is_integer((char *)&c)) add_to_array(&numbers, c - '0');
    }
    fclose(file);

    sort_array(&numbers);

    int largest = find_largest(numbers);
    printf("Largest integer: %d\n", largest);

    free(numbers.data);
    return EXIT_SUCCESS;
}
```

