<?php
declare(ticks=1);

class ConfigurationScript {
    private $environment;
    private $configurationCache = [];
    private $autoloaders = [];

    public function __construct($environment) {
        if (!in_array($environment, ['development', 'staging', 'production'])) {
            throw new Exception("Invalid environment: '$environment'");
        }
        $this->environment = $environment;
    }

    private function loadEnvFile() {
        $envFiles = glob(__DIR__ . '/.env', GLOB_BRACE);
        if (empty($envFiles)) {
            return [];
        }
        $data = [];
        foreach ($envFiles as $file) {
            $lines = file($file);
            foreach ($lines as $line) {
                if (trim($line) === '' || strpos($line, '#') === 0) {
                    continue;
                }
                list($key, $value) = explode('=', $line, 2);
                $data[strtolower(trim($key))] = trim($value);
            }
        }
        return $data;
    }

    private function loadConfiguration() {
        $envData = $this->loadEnvFile();
        $configFile = "configuration_{$this->environment}.php";
        $defaultConfigFile = "configuration_default.php";
        if (file_exists($configFile)) {
            include $configFile;
        } elseif (file_exists($defaultConfigFile)) {
            include $defaultConfigFile;
        }
        $configuration = array_merge($envData, $this->configurationCache);
        $this->configurationCache = $configuration;
        return $configuration;
    }

    private function loadAutoloaders() {
        $composerAutoloaderPath = __DIR__ . '/vendor/autoload.php';
        if (file_exists($composerAutoloaderPath)) {
            $this->autoloaders[] = require $composerAutoloaderPath;
        }
        // Add additional autoloaders here...
    }

    public function execute() {
        set_error_handler(function ($severity, $message, $file, $line) {
            logger($severity . ': ' . $message . ', file: ' . $file . ', line: ' . $line);
        });
        register_shutdown_function(function () {
            // Call this function here to ensure all output is captured in the log.
            logger('Fatal error:');
            restore_error_handler();
        });

        $this->loadAutoloaders();

        try {
            $configuration = $this->loadConfiguration();
            foreach ($configuration as $key => $value) {
                if (is_callable($value)) {
                    call_user_func($value);
                } elseif (!empty($value)) {
                    putenv("{$key}={$value}");
                }
            }
        } catch (Exception $e) {
            logger('Critical error: ' . $e->getMessage());
        }
    }

    // Add a function to reload the configuration here if needed...
}

function logger($message) {
    // Implement logging functionality here, e.g., writing to a log file or sending messages to an external service.
}
