import json
import requests
import logging
import sys
from typing import Dict, Any
from dataclasses import dataclass, field

class ConfigurationFile:
    def __init__(self, file_path: str):
        self.file_path = file_path

    def load(self) -> Dict[str, Any]:
        try:
            with open(self.file_path, 'r') as config_file:
                config = json.load(config_file)
                return config
        except FileNotFoundError as e:
            logging.error(f"Configuration file '{self.file_path}' not found. Error: {e}")
        except Exception as e:
            logging.error(f"An error occurred while loading the configuration file '{self.file_path}'. Error: {e}")
        finally:
            config_file.close() if config_file else None

class APIConfiguration:
    def __init__(self, api_url: str):
        self.api_url = api_url

    def fetch(self) -> Dict[str, Any]:
        try:
            response = requests.get(self.api_url)
            if response.status_code != 200:
                logging.error(f"Failed to fetch configuration from API '{self.api_url}'. Response status code: {response.status_code}")
                raise Exception("API request failed.")
            return response.json()
        except requests.RequestException as e:
            logging.error(f"An error occurred while fetching configuration from API '{self.api_url}'. Error: {e}")

@dataclass
class Configuration:
    config: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self):
        self.api = APIConfiguration("YOUR_API_URL")

    def update(self):
        remote_config = self.api.fetch()
        local_config = ConfigurationFile("CONFIG_FILE_PATH").load()
        self.config.update(remote_config)
        self.config.update(local_config)

def main():
    config = Configuration("CONFIG_FILE_PATH")
    config.update()
    logging.info("Configuration updated successfully.")

if __name__ == "__main__":
    main()
