// Global variables for logging and progress tracking
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static bool is_converting = false;
static char log_buffer[1024] = { 0 };

void log(const char* message) {
    pthread_mutex_lock(&log_mutex);
    sprintf(log_buffer, "[%s] %s\n", __func__, message);
    printf("%s", log_buffer);
    pthread_mutex_unlock(&log_mutex);
}

void* convert_image_chunks(ConvertJPEGToPDF convert, ImageService service, char* input, char* output, char** chunks, size_t count) {
    void* metadata = service.fetch_metadata(input);
    if (!metadata) {
        log("Failed to fetch metadata.");
        return 1;
    }

    // Simulate progress and status updates
    log("Starting conversion...");
    for (size_t i = 0; i < count; ++i) {
        log(/* Log the current chunk's progress and status */);
        int error = convert(chunks[i], output, NULL, 0);
        if (error != ERROR_SUCCESS) {
            log("Error during conversion.");
            service.cleanup(metadata);
            return error;
        }
    }

    // Clean up the metadata and mark the conversion as complete
    service.cleanup(metadata);
    log("Conversion completed.");

    return ERROR_SUCCESS;
}

int convert_image(char* input, char* output, ImageService service) {
    if (!input || !output || !service.fetch_metadata) {
        log("Invalid input or missing external service function.");
        return ERROR_INVALID_INPUT;
    }

    // Initialize the conversion process
    is_converting = true;

    // Simulate loading image chunks asynchronously
    char** chunks = malloc(10 * sizeof(char*));
    for (size_t i = 0; i < 10; ++i) {
        snprintf(chunks[i], sizeof(chunks[i]), "%d.jpeg", i); // Replace with actual chunk loading code
    }
    size_t count = 10;

    pthread_t conversion_thread;
    int error = pthread_create(&conversion_thread, NULL, convert_image_chunks, (void*)service.fetch_metadata, input, output, chunks, count);
    if (error != 0) {
        log("Error creating conversion thread.");
        is_converting = false;
        return ERROR_NETWORK;
    }

    // Wait for the conversion to finish and clean up resources
    pthread_join(conversion_thread, NULL);
    free(chunks);
    is_converting = false;

    if (errno != 0) {
        log("Error during conversion.");
        return ERROR_CONVERSION;
    }

    return ERROR_SUCCESS;
}
