import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.amazonaws.services.kms.AWSKMS;
import com.amazonaws.services.kms.AWSKMSClientBuilder;
import com.amazonaws.services.kms.model.DecryptRequest;
import com.amazonaws.services.kms.model.DecryptResult;
import redis.clients.jedis.Jedis;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.*;

@RestController
public class AuthController {
    private static final String KMS_KEY_ID = "your-kms-key-id";
    private static final long JWT_TTL_SECONDS = 3600; // 1 hour
    private static Jedis jedisPool = new JedisPool("localhost");
    private AWSKMS kmsClient = AWSKMSClientBuilder.standard().build();

    @PostMapping("/token")
    public ResponseEntity<String> getToken(@RequestBody Map<String, String> credentials) {
        // Validate credentials and user roles/permissions
        if (!validateCredentials(credentials)) {
            return new ResponseEntity<>(HttpStatus.UNAUTHORIZED);
        }

        try (Jedis jedis = jedisPool.getResource()) {
            String keyId = getKeyIdFromCacheOrKMS();
            byte[] decryptedKey = decryptKey(keyId);
            Algorithm algorithm = Algorithm.RSA256((new String(decryptedKey, StandardCharsets.UTF_8)));

            // Generate JWT and add expiration time
            Date expirationDate = Date.from(Instant.now().plusSeconds(JWT_TTL_SECONDS));
            Map<String, Object> claims = new HashMap<>();
            claims.put("exp", expirationDate);
            String token = JWT.create()
                    .withClaim("sub", credentials.get("username"))
                    .withClaim("role", "user") // replace with the appropriate role
                    .withExposedHeader("Authorization")
                    .withIssuer("your-issuer")
                    .withNotBefore(Instant.now())
                    .withJWTId(UUID.randomUUID().toString())
                    .withIssuedAt(Instant.now())
                    .withExpiresAt(expirationDate)
                    .sign(algorithm);

            // Cache the key ID for next JWT generation
            jedis.setex("jwt-key", 86400, keyId); // cache for 1 day

            return new ResponseEntity<>(token, HttpStatus.OK);
        } catch (NoSuchAlgorithmException | InvalidKeySpecException e) {
            logError(e);
            return new ResponseEntity<>(HttpStatus.INTERNAL_SERVER_ERROR);
        } catch (AmazonServiceException e) {
            logError(e);
            return new ResponseEntity<>(HttpStatus.SERVICE_UNAVAILABLE);
        }
    }

    private String getKeyIdFromCacheOrKMS() {
        // Get the key ID from cache if it's available, otherwise retrieve it from KMS
        String keyId = jedisPool.getResource().get("jwt-key");
        if (keyId == null) {
            DecryptRequest decryptRequest = new DecryptRequest()
                    .withKeyId(KMS_KEY_ID)
                    .withEncryptedData(getKeyDataFromKMS());
            DecryptResult result = kmsClient.decrypt(decryptRequest);
            keyId = result.getPlaintext().getAttribute("keyId");
            // Cache the key ID for future use
            jedisPool.getResource().setex("jwt-key", 86400, keyId);
        }
        return keyId;
    }

    private byte[] getKeyDataFromKMS() throws AmazonServiceException, AmazonClientException {
        // Retrieve the key data from KMS as a string and convert it to bytes
