#include <stdio.h>
#include <stdlib.h>
#include <time.h>

/* Define NFAPI_CRC_INDICATION_PDU_T structure */
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

/* Function to log errors and warnings */
void logErrorOrWarning(const char *message, const char *filename, int lineNumber) {
    FILE *logFile = stderr;
    fprintf(logFile, "[%s:%d] %s\n", filename, lineNumber, message);
}

/* Function to validate input parameters */
int validateInputs(size_t *listSize, int maxStructures) {
    if (maxStructures <= 0 || listSize == NULL || *listSize > maxStructures) {
        logErrorOrWarning("Invalid input parameters", __FILE__, __LINE__);
        return -1;
    }
    return 0;
}

/* Function to populate the NFAPI_CRC_INDICATION_PDU_T structures */
int populateNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T **crcList, size_t *listSize, int maxStructures) {
    int retVal = 0;
    int i;

    if (validateInputs(listSize, maxStructures) != 0) return -1;

    *crcList = malloc(maxStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crcList == NULL) {
        logErrorOrWarning("Memory allocation failed", __FILE__, __LINE__);
        retVal = -1;
    } else {
        *listSize = 0;

        srand(time(NULL));

        for (i = 0; i < maxStructures && *listSize < maxStructures; ++i) {
            (*crcList)[*listSize].RX_UE_INFORMATION_TAG = i + 1;
            (*crcList)[*listSize].RNTI = rand() % 0x7FFF + 1;
            (*crcList)[*listSize].CRC_INDICATION_REL8_TAG[0] = (uint8_t)(rand() & 0xFF);
            (*crcList)[*listSize].CRC_INDICATION_REL8_TAG[1] = (uint8_t)(((*crcList)[*listSize].CRC_INDICATION_REL8_TAG[0] >> 1) | ((rand() & 0x80) >> 7));
            (*crcList)[*listSize].CRC_INDICATION_REL8_TAG[2] = (uint8_t)(((*crcList)[*listSize].CRC_INDICATION_REL8_TAG[1] >> 3) | ((rand() & 0x70) >> 4));
            (*crcList)[*listSize].CRC_INDICATION_REL8_TAG[3] = (uint8_t)(((*crcList)[*listSize].CRC_INDICATION_REL8_TAG[2] >> 1) | ((rand() & 0x80) >> 7));
            ++(*listSize);
        }
    }

    return retVal;
}
