using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Microsoft.Extensions.Logging;

public class WebsiteManager
{
    private readonly ILogger<WebsiteManager> _logger;
    private readonly HttpClient _httpClient;

    public WebsiteManager(ILogger<WebsiteManager> logger, HttpClient httpClient)
    {
        _logger = logger;
        _httpClient = httpClient;
    }

    public async Task AddAndStartWebsite(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError($"The specified directory does not exist: {directoryPath}");
            throw new DirectoryNotFoundException();
        }

        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            _logger.LogError($"A web.config file is required in the specified directory: {directoryPath}");
            throw new FileNotFoundException();
        }

        try
        {
            var response = await _httpClient.PostAsJsonAsync($"https://your-web-server-management-api-url/addwebsite", new { DirectoryPath = directoryPath, SiteName = siteName });
            if (!response.IsSuccessStatusCode)
            {
                var errorResponse = await response.Content.ReadFromJsonAsync<ErrorResponse>();
                _logger.LogError($"Failed to add website: {errorResponse?.Message}");
                throw new Exception(errorResponse?.Message);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError($"An error occurred while communicating with the web server management API: {ex.Message}");
            throw;
        }

        try
        {
            await _httpClient.PostAsync($"https://your-web-server-management-api-url/startwebsite/{siteName}", new StringContent(""));
        }
        catch (Exception ex)
        {
            _logger.LogError($"An error occurred while starting the website: {ex.Message}");
            throw;
        }

        _logger.LogInformation($"Successfully added and started website: {siteName} in directory: {directoryPath}");
    }
}

public class ErrorResponse
{
    public string Message { get; set; }
}
