        scanf("%d", &arr[i]);
    }
}

void findLargest(int *arr, int size) {
    int max = arr[0];

    for (int i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    printf("The largest integer is: %d\n", max);
}

int main() {
    const int size = 5;
    int numbers[size];

    createSemaphore(1);

    readIntegers(numbers, size);

    findLargest(numbers, size);

    deleteSemaphore();

    return 0;
}
