using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Net.Http;
using System.Text;

public class FileHashChecker
{
    private readonly HttpClient _httpClient;

    public FileHashChecker(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<bool> CheckFileHashAsync(string filePath)
    {
        try
        {
            using (var stream = File.OpenRead(filePath))
            {
                var md5 = MD5.Create();
                var hash = await ComputeHashChunkByChunkAsync(stream, md5);

                return await VerifyHashAsync(hash);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error while processing file: {ex}");
            return false;
        }
    }

    private async Task<byte[]> ComputeHashChunkByChunkAsync(Stream stream, MD5 md5)
    {
        const int chunkSize = 4096;
        var buffer = new byte[chunkSize];
        var hashData = md5.ComputeHash(buffer);
        var hashBytes = new List<byte>();

        while (true)
        {
            var bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length);
            if (bytesRead == 0) break;

            md5.TransformBlock(buffer, 0, bytesRead, hashData, 0);
            hashBytes.AddRange(hashData);
        }

        md5.TransformFinalBlock(Array.Empty<byte>(), 0, 0);
        return hashBytes.ToArray();
    }

    private async Task<bool> VerifyHashAsync(byte[] hash)
    {
        var content = Convert.ToBase64String(hash);
        var response = await _httpClient.GetAsync($"{API_URL}/verify/{content}");
        return response.IsSuccessStatusCode;
    }
}
