fn run_query(data: Vec<u8>) -> Result<DataTableReader, String> {
    let start = Instant::now();

    let data_str = std::str::from_utf8(&data).context("Failed to convert byte array to string")?;
    let command = Command::new("your-database-command")
        .arg(data_str)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .spawn()
        .context("Failed to spawn command process")?;

    let output = command.wait_with_output().context("Command execution failed")?;

    if !output.status.success() {
        let err = std::str::from_utf8(&output.stderr).unwrap();
        return Err(err.to_string());
    }

    let reader = DataSourceReader::new(CSV::new(FileFormatOptions::default(), String::new()))
        .context("Failed to create CSV reader")?;

    match reader.next() {
        Some(_) => reader.collect().boxed().map_err(|e| e.to_string()),
        None => Err("No data returned from the database".to_string()),
    }
}

fn early_error(msg: &str) -> ! {
