const fs = require('fs');
const axios = require('axios');
const path = require('path');
const yargs = require('yargs/yargs');
const { hideBin } = require('yargs/helpers');

// Function to fetch metadata from external API (Replace with your actual API implementation)
async function fetchMetadata(filePath) {
  const response = await axios.get(`https://api.example.com/files/${encodeURIComponent(filePath)}`);
  return response.data;
}

// Function to read file synchronously and validate the extension
function readFileSyncAndValidate(filePath) {
  const extname = path.extname(filePath);
  const validExtensions = ['.txt', '.md', '.json'];

  if (!validExtensions.includes(extname)) {
    throw new Error(`Invalid file extension: ${extname}`);
  }

  return fs.readFileSync(filePath, 'utf8');
}

// Main function to process files
async function processFiles(files) {
  try {
    for (const file of files) {
      const content = readFileSyncAndValidate(file);
      const metadata = await fetchMetadata(file);

      // Process the file content and metadata here...

      console.log(`File: ${file}\nContent: ${content}\nMetadata:`, metadata);
    }
  } catch (error) {
    if (error.message.includes('Cannot find')) {
      console.error(`Error: File not found: ${error.message}`);
    } else if (error.message.includes('Invalid file extension')) {
      console.error(`Error: Invalid file extension: ${error.message}`);
    } else if (error.response && error.response.status !== 200) {
      console.error(`Error: Failed to fetch metadata for the file: ${error.response.statusText}`);
    } else {
      console.error('Error:', error.message);
    }
  }
}

// Handle user input and call processFiles function
const argv = yargs(hideBin(process.argv[0])).option('files', {
  alias: 'f',
  describe: 'The path or list of paths to the files to be processed.',
  type: 'string',
}).argv;

if (!argv.files) {
  console.error('Please provide a valid file path or list of file paths using --files flag.');
  process.exit(1);
}

const files = argv.files.split(','); // Split the file path or list of paths by comma
processFiles(files);
