using System;
using System.IO;
using System.Net;
using System.Text;
using System.Threading.Tasks;
using System.Linq;
using System.Security.Cryptography;
using System.Collections.Generic;
using Microsoft.Extensions.Logging;

public class WebsiteManager
{
    private readonly ILogger<WebsiteManager> _logger;
    // External API management service
    private readonly IApiManager _apiManager;

    public WebsiteManager(ILogger<WebsiteManager> logger, IApiManager apiManager)
    {
        _logger = logger;
        _apiManager = apiManager;
    }

    public async Task<int> AddAndStartWebsite(string directoryPath, string siteName)
    {
        // Check if web.config exists in the specified directory
        if (!File.Exists($"{directoryPath}/web.config"))
        {
            _logger.LogError("Missing web.config file.");
            return 1; // Error code for missing web.config
        }

        // Calculate MD5 hash of web.config file (assuming FileManager has methods ReadFileChunks and CalculateMD5)
        var md5Hex = await FileManager.CalculateMD5(directoryPath, "web.config");

        // Add the website to the specified directory and start it (replace with actual implementation)
        int result = await _apiManager.AddWebsiteAsync(directoryPath, siteName);

        if (result != 0)
        {
            _logger.LogError($"Failed to add and start website '{siteName}'.");
            return result; // Error code for API interaction error
        }

        // You can further optimize this by using async/await or threading when downloading large files
        var webConfigUrl = new Uri("http://example.com/web.config");
        byte[] fileBytes;
        using (var client = new WebClient())
        {
            var resumedDownloadTask = ResumeDownload(client, webConfigUrl);
            fileBytes = await resumedDownloadTask;
        }

        // Calculate MD5 hash of the downloaded file
        md5Hex = CalculateMD5(Encoding.UTF8.GetString(fileBytes));

        if (md5Hex != "expected_hash")
        {
            _logger.LogError("Downloaded web.config file has an incorrect hash.");
            return 3; // Error code for incorrect downloaded file hash
        }

        return 0; // Success
    }

    private async Task<byte[]> ResumeDownload(WebClient client, Uri uri)
    {
        var filePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "downloads", uri.LocalPath);
        if (File.Exists(filePath))
        {
            var fileLength = new FileInfo(filePath).Length;
            client.Headers[HttpRequestHeader.Range] = $"bytes={fileLength}-";
        }

        // Download the file in chunks
        using (var response = await client.OpenAsync(uri))
        {
            var bufferSize = 1024 * 64; // Set your desired chunk size
            var bytes = new byte[bufferSize];
            var totalBytesDownloaded = 0;

            while (true)
            {
                int bytesRead = await response.ReadAsync(bytes, 0, bufferSize);
                if (bytesRead <= 0) break; // End of the stream

                using (var fs = new FileStream(filePath, FileMode.Append, FileAccess.Write))
                {
                    await fs.WriteAsync(bytes, 0, bytesRead);
                    totalBytesDownloaded += bytesRead;
                }
            }

            return File.ReadAllBytes(filePath);
        }
    }

    private static string CalculateMD5(string input)
    {
        using (var md5 = MD5.Create())
        {
            var bytes = Encoding.UTF8.GetBytes(input);
            return BitConverter.ToString(md5.ComputeHash(bytes)).Replace("-", "").ToLower();
        }
    }
}
