#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct UserSession {
    int UserId;
    int SessionId;
    struct TrafficStats {
        int incomingBytes;
        int outgoingBytes;
    } TrafficStats;
} UserSession;

#define MAX_SESSIONS 100
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
UserSession* sessionList = NULL;
int currentSize = 0;

void trafficStatsInit(UserSession* session) {
    session->TrafficStats.incomingBytes = rand() % 1000 + 500;
    session->TrafficStats.outgoingBytes = rand() % 1000 + 500;
}

void addSession(UserSession* session) {
    pthread_mutex_lock(&list_mutex);
    if (currentSize < MAX_SESSIONS) {
        sessionList[currentSize] = *session;
        currentSize++;
    } else {
        free(session);
    }
    pthread_mutex_unlock(&list_mutex);
}

void* createSession(void* arg) {
    UserSession session;
    trafficStatsInit(&session);
    addSession(&session);
    return NULL;
}

void initList() {
    if (sessionList) free(sessionList);
    sessionList = malloc(MAX_SESSIONS * sizeof(UserSession));
    if (!sessionList) return;
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, createSession, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            exit(1);
        }
    }
}
