using System;
using System.IO;
using System.Security.Cryptography;
using System.Security.Cryptography.CryptoStream;
using System.Text;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Linq;

public class DecryptionService
{
    private readonly ICryptoTransform _decryptor;
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public DecryptionService(byte[] key, byte[] iv)
    {
        if (key.Length < 16 || key.Length > 32) throw new ArgumentException("Invalid AES-CBC Key Length.");
        if (iv.Length != 16) throw new ArgumentException("Invalid IV Length.");

        using (var aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            _decryptor = aes.CreateDecryptor();
        }
    }

    public void DecryptFile(Stream input, Stream output)
    {
        using (var cts = new CryptoStream(input, _decryptor, CryptoStreamMode.Read))
        {
            cts.CopyTo(output);
        }
    }

    public byte[] DecryptData(byte[] encryptedData)
    {
        using (var ms = new MemoryStream(encryptedData))
        using (var memoryStream = new MemoryStream())
        {
            DecryptFile(ms, memoryStream);
            return memoryStream.ToArray();
        }
    }

    public void RotateKey()
    {
        // Implement key rotation logic here
    }
}

public static class PaddingSchemeExtensions
{
    private const byte PKCS7PaddingByte = (byte)'%';
    private const int ANSIX923PaddingSize = 8;

    public static byte[] EncryptWithPkcs7(this ICryptoTransform transform, byte[] data)
        => data.Concat(new byte[GetRequiredPaddingSize(data)])
            .ToArray();

    public static byte[] DecryptWithoutPadding(this ICryptoTransform transform, byte[] data)
    {
        int paddingByteIndex = Array.LastIndexOf(data, PKCS7PaddingByte);
        if (paddingByteIndex != -1 && paddingByteIndex < data.Length - 1)
            return data[..paddingByteIndex];

        throw new InvalidDataException("Invalid padding found.");
    }

    public static byte[] DecryptWithPkcs7(this ICryptoTransform transform, byte[] data)
    {
        var decrypted = transform.DecryptWithoutPadding(data);
        var paddingByte = PKCS7PaddingByte;
        int paddingSize = decrypted[^1];
        if (paddingByte != PKCS7PaddingByte || paddingSize < 1 || paddingSize > decrypted.Length)
            throw new InvalidDataException("Invalid padding found.");

        return decrypted[..^(paddingSize + 1)];
    }

    public static byte[] EncryptWithANSIX923(this ICryptoTransform transform, byte[] data)
    {
        int remainingBytes = data.Length % ANSIX923PaddingSize;
        if (remainingBytes > 0) data = data.Concat(new byte[ANSIX923PaddingSize - remainingBytes]).ToArray();
        return transform.TransformFinalBlock(data, 0, data.Length);
    }

    private static int GetRequiredPaddingSize(byte[] data)
    {
        int paddingByteCount = (data.Length + ANSIX923PaddingSize - 1) / ANSIX923PaddingSize;
        return paddingByteCount * ANSIX923PaddingSize - data.Length;
    }
}
