import java.util.*;
import java.sql.*;
import java.time.Instant;
import java.io.PrintWriter;

class DisjointSet {
    private int[] parent;
    private int[] rank;

    DisjointSet(int size) {
        this.parent = new int[size];
        this.rank = new int[size];
        for (int i = 0; i < size; ++i) {
            parent[i] = i;
            rank[i] = 1;
        }
    }

    int find(int x) {
        if (x != parent[x]) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
                rank[rootY] += rank[rootX];
            } else {
                parent[rootY] = rootX;
                rank[rootX] += rank[rootY];
            }
        }
    }
}

class DisjointPairsCounter {
    private static final String DB_URL = "jdbc:mysql://localhost/database";
    private static final String DB_USER = "user";
    private static final String DB_PASSWORD = "password";

    public int countDisjointPairs(int[] arr, boolean removeDuplicates) {
        if (arr.length <= 1) return arr.length == 0 ? 0 : 1;

        DisjointSet ds = new DisjointSet(arr.length);
        Map<Integer, Integer> counts = new HashMap<>();
        int count = 0;

        for (int i = 0; i < arr.length; ++i) {
            if (!removeDuplicates || !counts.containsKey(arr[i])) {
                counts.put(arr[i], counts.getOrDefault(arr[i], 0) + 1);
                int root = ds.find(arr[i]);
                ds.union(root, i);
            }
        }

        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int key = entry.getKey();
            int value = entry.getValue();
            if (value > 1) {
                for (int j = 0; j < value - 1; ++j) {
                    count += ds.find(key + j) != ds.find(key + (j + 1));
                }
            }
        }

        return count;
    }

    void validate(int[] arr, int groundTruth) {
        if (arr.length == 0) throw new IllegalArgumentException("Array cannot be empty.");

        int actual = this.countDisjointPairs(arr, true);
        if (actual != groundTruth) {
            throw new RuntimeException("Invalid result: Expected " + groundTruth + ", but got " + actual);
        }
    }

    void logResult(int[] arr, boolean removeDuplicates, int count, long executionTimeMillis) {
        System.out.printf("Array: %s, Remove Duplicates: %b, Count: %d, Execution Time (ms): %d%n", Arrays.toString(arr), removeDuplicates, count, executionTimeMillis);
    }
}
