<?php

class ClinicStatusUpdater {
    private $db;
    private $apiKeyValidation;
    private $rateLimiter;
    private $errorLogFile = 'error_log.txt';

    public function __construct(PDO $db, ApiKeyValidator $apiKeyValidation, RateLimiter $rateLimiter) {
        $this->db = $db;
        $this->apiKeyValidation = $apiKeyValidation;
        $this->rateLimiter = $rateLimiter;
    }

    public function updateClinicStatus($clinic_id, $new_status, $last_modified_ip) {
        if (!$this->rateLimiter->allow($last_modified_ip)) {
            return 'Rate limit exceeded for this IP address';
        }

        try {
            $stmt = $this->db->prepare('UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_at = NOW() WHERE id = ?');
            $stmt->execute([$new_status, $last_modified_ip, $clinic_id]);
        } catch (Exception $e) {
            file_put_contents($this->errorLogFile, "Error updating clinic status: {$e->getMessage()}\n", FILE_APPEND);
            return 'An error occurred while updating the clinic status';
        }

        if (!$this->apiKeyValidation->isValid($last_modified_ip, $stakeholder_api_key)) {
            return 'Invalid stakeholder API key';
        }

        try {
            file_get_contents("https://example-api.com/notify?clinic_id={$clinic_id}&new_status={$new_status}");
        } catch (Exception $e) {
            file_put_contents($this->errorLogFile, "Error notifying stakeholders: {$e->getMessage()}\n", FILE_APPEND);
            return 'An error occurred while notifying stakeholders';
        }

        return 'Clinic status updated successfully and notified stakeholders';
    }
}

