    // Mark the resource as deleted and save it to the database
    await resource.destroy();

    // Create a new resource with default values
    const newResource = await Resource.create({ /* default values */ });

    res.json(newResource);
  } catch (err) {
    console.error(err);
    res.status(500).send('Error during deletion process.');
  }
});
