    public class ElementController : ApiController
    {
        private readonly IElementService _elementService;
        private readonly ICachingService _cachingService;

        public ElementController(IElementService elementService, ICachingService cachingService)
        {
            _elementService = elementService;
            _cachingService = cachingService;
        }

        // POST api/element
        [HttpPost]
        public async Task<IHttpActionResult> UpdateElementAsync(int pageSectionId, int elementId, string htmlContent)
        {
            if (!ModelState.IsValid)
                return BadRequest(ModelState);

            var user = HttpContext.Current.User as ApplicationUser; // Assuming you're using ASP.NET Identity
            if (user == null || !user.HasPermissionToUpdateElement())
                return Unauthorized();

            try
            {
                await _elementService.UpdateElementAsync(pageSectionId, elementId, htmlContent);

                // Atomic operation complete, clear cache for the affected page section
                _cachingService.RemoveCacheEntry(pageSectionId);

                return Content("{\"message\":\"Successfully updated. Please refresh.\"}", "application/json");
            }
            catch (Exception ex)
            {
                // Log the exception for further analysis
                // Return an error message to the client
                return InternalServerError(ex);
            }
        }
    }
}
```

