    {
        _httpClient = httpClient;
        _cache = new ConcurrentDictionary<string, string>();
        _rateLimitInterval = 1000; // 1 second
        _rateLimitDuration = TimeSpan.FromMilliseconds(_rateLimitInterval);
    }

    public async Task HashFileAsync(string filePath)
    {
        using (var stream = File.OpenRead(filePath))
        {
            await HashStreamAsync(stream, HashFinalize);
        }
    }

    private async Task HashStreamAsync(Stream inputStream, Action<MD5> hashHandler)
    {
        byte[] buffer = new byte[8192]; // Buffer size can be adjusted based on your preference

        try
        {
            using (var md5 = MD5.Create())
            {
                while (true)
                {
                    int readBytes = await inputStream.ReadAsync(buffer, 0, buffer.Length);
                    if (readBytes == 0) break;

                    md5.TransformBlock(buffer, 0, readBytes, _);
                }

                md5.TransformFinalBlock(_emptyByteArray, 0, 0); // Add this for the final transformation in case there's any remaining data in the buffer after reading
                hashHandler(md5);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error while hashing file: {ex}");
        }
    }

    private void HashFinalize(MD5 md5Hash)
    {
        var hash = BitConverter.ToString(md5Hash.Hash).Replace("-", string.Empty);
        VerifyAndCacheHash(hash).Wait();
    }

    private async Task VerifyAndCacheHash(string hash)
    {
        if (_rateLimiter.AcquireToken())
        {
            try
            {
                var response = await _httpClient.GetAsync($"api/verify/{hash}");
                response.EnsureSuccessStatusCode();
                _cache[hash] = hash;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error while verifying hash: {ex}");
            }
            finally
            {
                _rateLimiter.Release();
            }
        }
        else
        {
            await Task.Delay(_rateLimitDuration); // Wait until the rate limit expires
            VerifyAndCacheHash(hash);
        }
    }

    private RateLimiter _rateLimiter = new RateLimiter(_rateLimitInterval, TimeSpan.FromMilliseconds(100)); // 100ms resolution for rate limiting
}

public class RateLimiter
{
    private readonly int interval;
    private readonly TimeSpan duration;
    private long lastAcquired = DateTimeOffset.UtcNow.ToUnixTimeSeconds();

    public RateLimiter(int interval, TimeSpan duration)
    {
        this.interval = interval;
        this.duration = duration;
    }

    public bool AcquireToken()
    {
        long current = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        if (current - lastAcquired >= duration.TotalSeconds)
        {
            lastAcquired = current;
            return true;
        }

        return false;
    }
}
