char* AppendSlashIfNeeded(char* str, size_t limit)
{
    if (strlen(str) >= limit)
        return NULL;

    char* newStr = malloc((limit + 1) * sizeof(char));
    strcpy(newStr, str);
    str[limit] = '/';
    newStr[limit + 1] = '\0';

