import java.lang.reflect.InvocationTargetException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

@Service
public class DynamicDeserializer {
    private static final Logger LOGGER = LoggerFactory.getLogger(DynamicDeserializer.class);
    private final ClassProvider classProvider;
    private final CacheManager cacheManager;
    private final RestTemplate restTemplate;
    private final ObjectMapper objectMapper;
    private final Map<String, Pokemon> pokemonCache;
    private final ScheduledExecutorService executor;
    private final int cacheSize;
    private final long timeoutMillis;
    private final int maxRetries;

    public DynamicDeserializer(ClassProvider classProvider, CacheManager cacheManager, RestTemplate restTemplate, ObjectMapper objectMapper, @Value("${pokemon.cache-size}") int cacheSize, @Value("${pokemon.timeout-millis}") long timeoutMillis, @Value("${pokemon.max-retries}") int maxRetries) {
        this.classProvider = classProvider;
        this.cacheManager = cacheManager;
        this.restTemplate = restTemplate;
        this.objectMapper = objectMapper;
        this.pokemonCache = new ConcurrentHashMap<>();
        this.executor = Executors.newScheduledThreadPool(2);
        this.cacheSize = cacheSize;
        this.timeoutMillis = timeoutMillis;
        this.maxRetries = maxRetries;
    }

    @Cacheable("pokemon")
    public Pokemon deserialize(String pokemonId) {
        // Validate input and ensure it's a valid Pokemon ID
        if (!isValidPokemonId(pokemonId)) {
            throw new IllegalArgumentException("Invalid Pokemon ID: " + pokemonId);
        }

        Pokemon pokemon;
        if (pokemonCache.containsKey(pokemonId)) {
            // Use cached version of the Pokemon object
            pokemon = pokemonCache.get(pokemonId);
        } else {
            try {
                JsonNode rootNode = restTemplate.getForObject(buildUrl(pokemonId), JsonNode.class, timeoutMillis);

                if (rootNode == null) {
                    throw new IOException("Empty response received from the API");
                }

                // Deserialize JSON to Pokemon object
                Class<?> pokemonClass = classProvider.getPokemonClass(rootNode.get("name").textValue());
                if (pokemonClass == null) {
                    throw new IOException("Unable to find a suitable class for the deserialized data");
                }
                pokemon = objectMapper.treeToValue(rootNode, pokemonClass);

                // Save Pokemon object in cache, if cache size allows it
                pokemonCache.putIfAbsent(pokemonId, pokemon);
                pruneCache();
            } catch (IOException e) {
                handleError(e);
            } catch (IllegalAccessException | InstantiationException | InvocationTargetException e) {
                throw new RuntimeException("Failed to instantiate Pokemon object", e);
            }
        }

        // Fetch and merge evolution details if needed
        if (!pokemon.isFinalForm()) {
            String nextEvolutionId = pokemon.getNextEvolutionId();
            if (nextEvolutionId != null) {
                Pokemon nextEvolution = deserialize(nextEvolutionId);
                // Combine weaknesses and evolution details of current and next stages
                List<String> combinedWeaknesses = new ArrayList<>(pokemon.getWeaknesses());
                combinedWeaknesses.addAll(nextEvolution.getWeaknesses());
                pokemon.setWeaknesses(combinedWeaknesses);
                // Set the next evolution details of the current Pokemon object
                pokemon.setNextEvolutionId(nextEvolutionId);
                pokemon.setNextEvolutionName(nextEvolution.getName());
            }
        }

        return pokemon;
    }

    private void pruneCache() {
        if (pokemonCache.size() > cacheSize) {
            List<Map.Entry<String, Pokemon>> entriesToRemove = new ArrayList<>(pokemonCache.entrySet());
            entriesToRemove.sort(Map.Entry.<String, Pokemon>comparingByValue().reversed());
            for (int i = pokemonCache.size() - cacheSize; i < pokemonCache.size(); ++i) {
                String key = entriesToRemove.get(i).getKey();
                pokemonCache.remove(key);
                LOGGER.info("Removed Pokemon ID from cache: {}", key);
            }
        }
    }

    private UriComponentsBuilder buildUrl(String pokemonId) {
        // Construct URL for API request, handling different APIs based on the Pokemon ID format (e.g., Pokedex or Bulbapedia)
        // ...
    }

    // Other utility methods for validating input, handling errors, and configuring retry strategies
    // ...
}
