private class DownloadThemeTask(val context: Context, val theme: String) : AsyncTask<Void, Void, Bitmap?>() {
    override fun doInBackground(vararg params: Void?): Bitmap? {
        try {
            val client = OkHttpClient()
            val request = Request.Builder().url("https://your-theme-server.com/$theme").build()
            val response = client.newCall(request).execute()
            if (!response.isSuccessful) return null
            return BitmapFactory.decodeStream(response.body?.byteStream())
        } catch (e: Exception) {
            return null
        }
    }

    override fun onPostExecute(result: Bitmap?) {
        super.onPostExecute(result)
        if (result != null) ThemeCache(context).putThemeBitmap(theme, result)
    }
}

