```java
import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.ClassLoader;
import java.sql.Connection;
import java.util.Optional;
import java.util.logging.Logger;

public class Deserializer {
    private static final Logger LOGGER = Logger.getLogger(Deserializer.class.getName());

    public static <T> T deserialize(byte[] data, Class<T> clazz) throws RuntimeException {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            T obj = (T) ois.readObject();
            return obj;
        } catch (ClassNotFoundException | IOException e) {
            LOGGER.severe("Error deserializing object: " + e.getMessage());
            throw new RuntimeException("Failed to deserialize object", e);
        } catch (ClassCastException e) {
            // Handle version mismatches or unsupported class versions
            if (!handleVersionMismatch(e, clazz)) {
                LOGGER.severe("Failed to deserialize object due to unsupported class version: " + e.getMessage());
                throw new RuntimeException("Unsupported class version during deserialization", e);
            }
        } catch (IllegalAccessException | InvocationTargetException e) {
            LOGGER.severe("Error invoking constructor for deserialized object: " + e.getMessage());
            throw new RuntimeException("Failed to invoke constructor for deserialized object", e);
        }
    }

    private static <T> boolean handleVersionMismatch(ClassCastException e, Class<T> clazz) {
        String versionClassName = getClassNameForVersion(e.getUndeclaredType(), clazz);
        if (versionClassName != null) {
            try {
                Class<?> versionClass = Class.forName(versionClassName);
                return deserialize(e.getUndeclaredThrowable(), versionClass).getClass().equals(clazz);
            } catch (ClassNotFoundException | InstantiationException | IllegalAccessException e1) {
                LOGGER.severe("Failed to load compatible class for handling version mismatch: " + e1.getMessage());
            }
        }
        return false;
    }

    private static String getClassNameForVersion(Class<?> clazz, Class<?> fallbackClazz) {
        ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
        while (clazz != null) {
            if (clazz.equals(fallbackClazz)) {
                return fallbackClazz.getName();
            }
            String versionName = clazz.getSimpleName() + "$Version";
            try {
                Class<?> versionClass = classLoader.loadClass(versionName);
                return versionClass.getName();
            } catch (ClassNotFoundException e) {
                clazz = clazz.getSuperclass();
            }
        }
        return null;
    }
}
```

