```python
import os
import re
import logging
import glob
from datetime import datetime
from io import StringIO

def process_log_file(directory, config):
    log_level = getattr(logging, config['log_level'].upper(), None)
    logging.basicConfig(level=log_level, format='%(asctime)s - %(message)s')

    timestamp_format = config['timestamp_format']
    buffer_size = config['buffer_size']

    def is_log_file(filename):
        return any(filename.endswith(ext) for ext in config['file_extensions'])

    def extract_timestamp(line):
        timestamp_pattern = re.compile(r'(?:' + '|'.join([re.escape(fmt) for fmt in timestamp_format]) + r')')
        match = timestamp_pattern.search(line)
        if match:
            return datetime.strptime(match.group(), timestamp_format)
        else:
            logging.warning(f'Invalid timestamp format in line: {line}')
            return None

    def read_lines_in_chunks(file):
        chunk = StringIO()
        for chunk in iter(lambda: file.read(buffer_size), b''):
            yield chunk.getvalue()
            chunk.truncate(0)

    def find_logfiles(directory):
        logfiles = []
        for path, _, files in os.walk(directory):
            for file in files:
                if is_log_file(file):
                    logfiles.append((path, file))
        return logfiles

    def process_single_logfile(filename):
        with open(filename) as f:
            sorted_lines = sorted([extract_timestamp(line.strip()) if extract_timestamp else None for line in read_lines_in_chunks(f)], reverse=True)

            sequence_number = 1
            prev_timestamp = None
            for timestamp in sorted_lines:
                if timestamp:
                    if prev_timestamp:
                        if timestamp > prev_timestamp:
                            sequence_number += 1
                    prev_timestamp = timestamp
            else:
                logging.warning(f'No valid timestamp found in {filename}')

            if sequence_number:
                logging.info(f'Last line sequence number in {filename}: {sequence_number}')

    logfiles = find_logfiles(directory)
    for filename, _ in logfiles:
        process_single_logfile(filename)

# Unit tests
import unittest

class TestProcessLogFile(unittest.TestCase):
    def setUp(self):
        self.config = {
            'file_extensions': ['.log', '.txt'],
            'timestamp_format': ['%Y-%m-%d %H:%M:%S', '%m/%d/%Y %H:%M:%S'],
            'buffer_size': 1024,
            'log_level': 'INFO'
        }

    def test_no_timestamp(self):
        process_log_file('tests/data/noid-timestamp.txt', self.config)
        log_entries = [e for e in logging.getLogger().history if 'No valid timestamp found' in e.message]
        self.assertEqual(len(log_entries), 1)

    def test_multiple_timestamps(self):
        process_log_file('tests/data/multiple-timestamps.log', self.config)
        log_entries = [e for e in logging.getLogger().history if 'Last line sequence number' in e.message]
        self.assertEqual(len(log_entries), 1)

    def test_invalid_timestamp(self):
        process_log_file('tests/data/invalid-timestamp.txt', self.config)
        log_entries = [e for e in logging.getLogger().history if 'Invalid timestamp format' in e.message]
        self.assertEqual(len(log_entries), 1)

if __name__ == '__main__':
    unittest.main()
