#include <stdio.h>
#include <stdlib.h>
#include <openssl/ssl.h>
#include <openssl/err.h>
#include <string.h>
#include <syslog.h>

typedef enum { AES_256, ChaCha20, SHA_256, SHA_384, SHA_512 } Algorithm;

typedef struct Config {
    char *algorithms;
    FILE *log_file;
} Config;

SSL_library_init();
OpenSSL_add_all_algorithms();
ERR_load_BIO_strings();

void init_secure_messaging(const Config* config) {
    SSL_CTX* ctx = NULL;
    const char* algorithms = config->algorithms;
    const char* token = ",";
    int enabled_algorithms[5] = {0};

    int i, len = strlen(algorithms);
    for (i = 0; i < len; ) {
        int pos = strcspn(&algorithms[i], token);
        Algorithm alg = static_cast<Algorithm>(atoi(&algorithms[i]));
        if (alg >= AES_256 && alg <= SHA_512)
            enabled_algorithms[alg] = 1;
        i += pos + strlen(token);
    }

    SSL_CTX_set_options(ctx, SSL_OP_ALL | SSL_OP_NO_SSLv2 | SSL_OP_NO_SSLv3);

    for (i = AES_256; i <= SHA_512; ++i) {
        if (!enabled_algorithms[i]) continue;

        const EVP_CIPHER* enc_alg = NULL;
        const EVP_MD* hash_alg = NULL;

        switch (i) {
            case AES_256:
                enc_alg = EVP_aes_256_cbc();
                break;
            case ChaCha20:
                // Plugin system would be used here for future algorithm additions.
                break;
            case SHA_256:
                hash_alg = EVP_sha256();
                break;
            case SHA_384:
                hash_alg = EVP_sha384();
                break;
            case SHA_512:
                hash_alg = EVP_sha512();
                break;
        }

        if (!enc_alg || !hash_alg) {
            syslog(LOG_ERR, "Failed to initialize algorithm %d.", i);
            continue;
        }

        if (SSL_CTX_set_cipher_list(ctx, SSL_CIPHER_get_name(enc_alg)) <= 0) {
            syslog(LOG_ERR, "Failed to set encryption algorithm for ctx.");
            continue;
        }

        if (SSL_CTX_set_md(ctx, hash_alg) <= 0) {
            syslog(LOG_ERR, "Failed to set hashing algorithm for ctx.");
            continue;
        }
    }

    if (!ctx) {
        syslog(LOG_ERR, "Secure messaging initialization failed.");
        ERR_print_errors_fp(config->log_file);
    }
}
