```rust
use std::env;
use std::fs::{File, OpenOptions};
use std::io::{BufWriter, Write};
use std::os::unix::process::ExitStatusExt;
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::sync::Lazy;
use std::time::Instant;
use sync_diag::SyncLazy;
use rustc_driver::{CargoToml, Config, Driver, ErrorKind, ExitCode};

static ICE_HOOK: SyncLazy<Box<dyn FnMut(&str)>> = SyncLazy::new(|| Box::new(|s| println!("{}", s)));

fn measure_and_log_duration(start: Instant, name: &str) {
    let duration = start.elapsed();
    eprintln!( "Compilation of '{}' took {} seconds.", name, duration.as_secs_f64());
}

fn monitor_rss() -> Result<u64, Box<dyn std::error::Error>> {
    use rss::{RSS, Sample};

    let mut rss = RSS::new().with_sample_interval(1).start();
    loop {
        match rss.snapshot()? {
            Some(sample) => sample.print(),
            None => break,
        }
        std::thread::sleep(std::time::Duration::from_secs(1));
    }

    Ok(rss.total_rss())
}

fn run_rustc(source_file: &PathBuf) -> Result<ExitCode, Box<dyn std::error::Error>> {
    let source_dir = source_file.parent().unwrap();
    let mut config = Config::new();
    let cargo_toml = CargoToml::load(&source_dir)?;
    config.cargo_toml(cargo_toml);

    let start = Instant::now();
    let (exit_code, stdout, stderr) = rustc_driver::command(config, &[source_file])
        .stderr(Stdio::piped())
        .stdout(Stdio::piped())
        .log_hooks(vec![ICE_HOOK.as_ref()])
        .catch_with_exit_code(|err| {
            if let Some(e) = err.downcast_ref::<ErrorKind>() {
                eprintln!("error: {}", e);
            }
            ExitCode::FAILURE
        })?
        .spawn()?;

    monitor_rss().unwrap();
    measure_and_log_duration(start, source_file.to_str().unwrap());
    monitor_rss().unwrap();

    Ok(exit_code)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <source file>", args[0]);
        std::process::exit(1);
    }

    let source_file = PathBuf::from(args[1].as_str());
    match run_rustc(&source_file) {
        Ok(ExitCode::SUCCESS) => std::process::exit(0),
        Err(_) | Ok(code) if code.success() => {
            eprintln!("Compilation failed with exit code: {}", code);
            std::process::exit(1)
        }
    }
}
```

