function findElements(root, selector, testFunc, maxDepth = Infinity) {
  if (!root || !root instanceof Node) throw new Error('Invalid root node');
  if (!selector) throw new Error('Invalid selector');

  const traverse = (node, depth = 0) => {
    if (depth > maxDepth) return [];

    let matchesSelector = node.matches ? node.matches(selector) : Array.from(node.classList).includes(selector);
    if (matchesSelector) {
      const result = testFunc?.(node) || true;
      if (result) return [node];
    }

    let results = [];
    for (const child of node.children) results = [...results, ...traverse(child, depth + 1)];
    return results;
  };

  return traverse(root);
}
