        if (!SCHEMA.getField(" sensors").getSchema().isValid(sensorDataMap)) {
            // Return an error response or throw an exception
        }

        Connection connection = DriverManager.getConnection("jdbc:cassandra://localhost/my_keyspace");
        try (PreparedStatement statement = connection.prepareStatement("INSERT INTO sensor_data (id, timestamp, data) VALUES (?, ?, ?)")) {
            statement.setString(1, UUID.randomUUID().toString());
            statement.setObject(2, Instant.now());
            statement.setString(3, sensorData);
            statement.executeUpdate();
        } catch (SQLException e) {
