public class FileSummaryGenerator {
 private static final int THREAD_POOL_SIZE = 5;
 private List<String> keywords;
 private String outputFormat;
 private String apiKey;
 private String apiUrl;
 private ExecutorService executor;

 public FileSummaryGenerator(List<String> keywords, String outputFormat, String apiKey, String apiUrl) {
 this.keywords = keywords;
 this.outputFormat = outputFormat;
 this.apiKey = apiKey;
 this.apiUrl = apiUrl;
 this.executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
 }

 public void generateSummaryReport(Path directory) throws IOException, URISyntaxException, ExecutionException, InterruptedException {
 List<Future<Map<String, Long>>> futures = new ArrayList<>();
 for (File file : directory.toFile().listFiles()) {
 if (!file.isDirectory() && file.canRead()) {
 Callable<Map<String, Long>> task = () -> countKeywords(file);
 futures.add(executor.submit(task));
 }
 }
 Map<String, Long> totalSummary = new HashMap<>();
 for (Future<Map<String, Long>> future : futures) {
 totalSummary.putAll(future.get());
 }
 generateReport(totalSummary);
 uploadReport();
 }

 private Map<String, Long> countKeywords(File file) throws IOException {
 Matcher matcher;
 Pattern pattern = Pattern.compile("(\\b" + String.join("\\b|\\b", keywords) + "\\b)", Pattern.CASE_INSENSITIVE);
 Map<String, Long> summary = new HashMap<>();
 try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
 String line;
 long lineNumber = 0;
 while ((line = reader.readLine()) != null) {
 lineNumber++;
 matcher = pattern.matcher(line);
 if (matcher.find()) {
 summary.merge(line, 1L, Long::sum);
 summary.put("total_lines", lineNumber);
 }
 }
 }
 return summary;
 }

 private void generateReport(Map<String, Long> summary) throws IOException {
 // Implement the report generation logic based on the outputFormat (e.g., CSV, JSON, etc.)
 // For simplicity, let's assume a basic CSV format for this example
 PrintWriter writer = new PrintWriter("summary_report.csv");
 writer.println("Keyword,Count,Percentage");
 summary.forEach((key, value) -> {
 double percentage = (double) value / summary.getOrDefault("total_lines", 0L) * 100;
 writer.println(key + "," + value + "," + String.format("%.2f", percentage) + "%");
 });
 writer.close();
 }

 private void uploadReport() {
 // Implement the API integration logic to upload the report file
 HttpClient httpClient = HttpClients.createDefault();
 HttpUriRequest request = new HttpPut(new URI(apiUrl));
 request.addHeader("Authorization", "Bearer " + apiKey);
 FileBody reportFile = new FileBody(new File("summary_report.csv"));
 request.setEntity(request.getRequestEntity().setTextCharset("UTF-8").setContent(reportFile));
 CloseableHttpResponse response = httpClient.execute(request);
 // Handle the API response here, e.g., check the status code and process any notifications
 }

 private void shutdown() {
 if (executor != null) {
 executor.shutdown();
 try {
 executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
 } catch (InterruptedException e) {}
 }
 }
}
