using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using System.Diagnostics;
using System.Linq;

public class ManageWebsiteLifecycle
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<ManageWebsiteLifecycle> _logger;
    private readonly TimeSpan _retryInterval = TimeSpan.FromSeconds(5);

    public ManageWebsiteLifecycle(HttpClient httpClient, ILogger<ManageWebsiteLifecycle> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    public async Task ManageWebsiteAsync(string directoryPath, string siteName, Operation operation)
    {
        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError("Invalid directory path: {Directory}", directoryPath);
            throw new ArgumentException($"Invalid directory path: {directoryPath}");
        }

        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            _logger.LogError("Missing web.config file at: {WebConfig}", webConfigPath);
            throw new FileNotFoundException($"Missing web.config file at: {webConfigPath}");
        }

        var apiResponse = await PerformApiOperation(operation, siteName);

        if (!apiResponse.Success)
        {
            _logger.LogError("Error performing API operation on website: {Site}", siteName);
            throw new Exception($"Error performing API operation on website: {siteName}");
        }

        _logger.LogInformation("Successfully performed API operation on website: {Site}", siteName);
    }

    private async Task<ApiResponse> PerformApiOperation(Operation operation, string siteName)
    {
        try
        {
            var apiUrl = "https://your-api.com/websites"; // Replace with actual API URL
            switch (operation)
            {
                case Operation.Add:
                    _httpClient.PostAsync($"{apiUrl}/{siteName}", new StringContent(""));
                    break;
                case Operation.Remove:
                    _httpClient.DeleteAsync($"{apiUrl}/{siteName}");
                    break;
                case Operation.Start:
                    _httpClient.PostAsync($"{apiUrl}/{siteName}/start", new StringContent(""));
                    break;
                case Operation.Stop:
                    _httpClient.PostAsync($"{apiUrl}/{siteName}/stop", new StringContent(""));
                    break;
                case Operation.Restart:
                    _httpClient.PostAsync($"{apiUrl}/{siteName}/restart", new StringContent(""));
                    break;
            }
            return new ApiResponse { Success = true };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while performing API operation on website: {Site}", siteName);
            await Task.Delay(_retryInterval);
            return await PerformApiOperation(operation, siteName); // Retry the operation after a configurable delay
        }
    }
}

public enum Operation
{
    Add,
    Remove,
    Start,
    Stop,
    Restart
}

public class ApiResponse
{
    public bool Success { get; set; }
}
