    private readonly Dictionary<string, IDistribution> _distributions;
    private DistributionBase _currentDistribution;
    private float _min;
    private float _max;

    public DynamicValueGenerator()
    {
        // Initialize the configuration system and load the available distributions
        _distributions = new Dictionary<string, IDistribution>();

        var configManager = new ConfigurationManager();  // Use your custom ConfigurationManager class here
        foreach (var distribution in configManager.GetDistributions())
        {
            _distributions[distribution.Type] = distribution.CreateInstance();
        }
    }

    public void SetDistribution(string type, params object[] parameters)
    {
        if (!_distributions.TryGetValue(type, out var distribution))
            throw new KeyNotFoundException($"Invalid distribution type: {type}");

        _currentDistribution = distribution.CreateInstance();

        switch (type)
        {
            case nameof(GaussianDistribution):
                _min = parameters[0] as float;
                _max = parameters[1] as float;
                break;
            case nameof(UniformDistribution):
                _min = parameters[0] as float;
                _max = parameters[1] as float;
                break;
            case nameof(ExponentialDistribution):
                _min = parameters[0] as float;
                _max = parameters[1] as float;
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(type), type, "Invalid distribution type.");
        }
    }

    public float GenerateFloat()
    {
        if (_currentDistribution == null)
            throw new InvalidOperationException("No current distribution set.");

        return _currentDistribution.GenerateFloat();
    }

    public int GenerateInteger()
    {
        if (_currentDistribution == null)
            throw new InvalidOperationException("No current distribution set.");

        return (int)_currentDistribution.GenerateFloat();
    }

    public override string ToString()
    {
        var parameters = _currentDistribution switch
        {
            GaussianDistribution gd => $"Gaussian({gd._mean}, {gd._stdDeviation})",
            UniformDistribution ud => $"Uniform({_min}, {_max})",
            ExponentialDistribution ed => $"Exponential({_lambda})",
            _ => ""
        };

        return $"Current distribution: {_currentDistribution.GetType().Name} | Range: {_min}-{_max} | Parameters: {parameters}";
    }
}
