import json
import logging
import time
from typing import Dict, Any, Callable, List
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor, as_completed

class APIResponseValidator:
    def __init__(self, services: Dict[str, tuple[Callable[[str], Dict[str, Any]], dict]]):
        self.services = services
        self.service_profiles = defaultdict(lambda: {}, services)
        self.logger = logging.getLogger(__name__)

    def _validate_response(self, service_name, response: str) -> Dict[str, Any]:
        validator, required_fields = self.services[service_name]
        try:
            parsed_response = json.loads(response)
            for field in required_fields:
                if field not in parsed_response:
                    raise ValueError(f"Missing required field '{field}' in response from service '{service_name}'")
            optional_fields = set(parsed_response.keys()) - set(required_fields)
            profile = {k: v for k, v in parsed_response.items() if k in self.service_profiles[service_name]['unified_profile_format']}
            profile.update({k: parsed_response[k] for k in optional_fields})
            return profile
        except Exception as e:
            self.logger.error(f"Error while validating response from service '{service_name}': {str(e)}", exc_info=True)
            raise

    def _retry_api_call(self, service_name, url, retry_attempts=0):
        if retry_attempts >= self.services[service_name][1]['max_retries']:
            raise Exception(f"Maximum retries reached for service '{service_name}'")

        try:
            response = requests.get(url)
            if response.status_code == 200:
                return self._validate_response(service_name, response.text)
            else:
                self.logger.warning(f"Received non-200 status code {response.status_code} from service '{service_name}'")
        except Exception as e:
            self.logger.error(f"Error while making API call to service '{service_name}': {str(e)}", exc_info=True)

        backoff = 2 ** retry_attempts
        time.sleep(backoff)
        return self._retry_api_call(service_name, url, retry_attempts + 1)

    def validate_user_profiles(self, user_ids: List[str], service_urls: Dict[str, str]) -> Dict[str, Dict[str, Any]]:
        with ThreadPoolExecutor() as executor:
            futures = [executor.submit(self._retry_api_call, service_name, service_url) for service_name, service_url in service_urls.items()]
            user_profiles = defaultdict(lambda: {}, user_ids)
            for future in as_completed(futures):
                service_profile = future.result()
                if service_profile:
                    user_profiles[user_ids[future.key]].update(service_profile)
        return {k: v for k, v in user_profiles.items() if v}
```

