// Function prototypes
static void log_message(const char *message);
void exec_command(pid_t child_pid, const char *command);
int check_process_status(pid_t child_pid);
void signal_handler(int signum);

/**
 * runCommandBackground - Runs a given command in the background using fork and waitpid system calls.
 *
 * @param command: The command to be executed.
 * @param timeout: The timeout in seconds to wait for the command to start.
 * @param retries: The number of times to retry the command if it fails to start.
 * @param parallel_exec: 1 if the commands should be executed in parallel, 0 otherwise.
 * @return 1 if the command is successfully started in the background, 0 otherwise.
 */
int runCommandBackground(const char *command, int timeout, int retries, int parallel_exec) {
    pid_t child_pid;
    struct sigaction sa;
    struct rlimit rl;

    // Set up signal handler to terminate the process if it takes too long to start
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGALRM, &sa, NULL) == -1) {
        log_message("Error setting up signal handler");
        return 0;
    }

    // Set resource limits for the child process to prevent excessive usage
    if (getrlimit(RLIMIT_NOFILE, &rl) == -1 || rl.rlim_max < 64) {
        log_message("Error getting or setting resource limit");
        return 0;
    }
    rl.rlim_cur = rl.rlim_max;
    if (setrlimit(RLIMIT_NOFILE, &rl) == -1) {
        log_message("Error setting resource limit");
        return 0;
    }

    // Fork the current process and create a new one to run the command
    child_pid = fork();
    if (child_pid == -1) {
        log_message("Error forking process");
        return 0;
    }

    // Execute the command in the child process
    if (!child_pid) {
        execvp(command, (char * const *) &command);
        log_message("Error executing command");
        _exit(EXIT_FAILURE);
    }

    // If we're not in the child process, wait for it to start or timeout
    if (!parallel_exec) {
        alarm(timeout);
        while (check_process_status(child_pid)) {}
        alarm(0);

        if (waitpid(child_pid, NULL, WNOHANG) == -1 && errno != ECHILD) {
            log_message("Error waiting for child process");
            return 0;
        }
    }

    // If the command failed to start, retry a specified number of times
    for (int i = 1; i <= retries; ++i) {
        if (!parallel_exec && check_process_status(child_pid)) {
            break;
        }
        if (waitpid(child_pid, NULL, WNOHANG) != child_pid) {
            log_message("Error waiting for child process");
            continue;
        }

        // If the child process is no longer running or timed out, return 0
        if (!check_process_status(child_pid)) {
            break;
        }

        // Reset the alarm and try executing the command again after a delay
        alarm(timeout);
        sleep(1);
    }

    // Clean up and return whether the command was successfully executed
    if (waitpid(child_pid, NULL, 0) == -1) {
        log_message("Error waiting for child process");
        return 0;
    }

    return WIFEXITED(WEXITSTATUS(status)) ? 1 : 0;
}

// Implementation of the remaining function prototypes
