        fprintf(stderr, "Error: Input directory is not a valid directory\n");
        return 0;
    }

    // Validate maxPagesPerPdf here

    return 1;
}

int batchConvertJpegToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf) {
    pthread_t threads[MAX_THREADS];
    ConversionArgs args[MAX_THREADS];
    int fileCount = 0;
    int numThreads = 1;

    // Walk the directory and find JPEG files to process.
    DIR *dir = opendir(inputDir);
    if (dir != NULL) {
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            if (strstr(entry->d_name, ".jpg") || strstr(entry->d_name, ".jpeg")) {
                fileCount++;
            }
        }
        closedir(dir);
    } else {
        perror("Error: Cannot open input directory");
        return 1;
    }

    if (fileCount == 0) {
        fprintf(stderr, "Error: No JPEG files found in the input directory\n");
        return 1;
    }

    // Create one thread per CPU core or up to MAX_THREADS.
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int threadsCreated = 0;

    for (int i = 0; i < fileCount && threadsCreated < MAX_THREADS; ++i) {
        if (pthread_create(&threads[threadsCreated], NULL, convertJpegToPdf, &args[threadsCreated])) {
            perror("Error: Failed to create thread");
            return 1;
        }

        strcpy(args[threadsCreated].inputDir, inputDir);
        snprintf(args[threadsCreated].outputDir, MAX_PATH_LENGTH, "%s/%04d.pdf", outputDir, threadsCreated);
        args[threadsCreated].maxPagesPerPdf = maxPagesPerPdf;
        ++threadsCreated;
    }

    // Wait for all threads to finish processing and collect the error codes.
    int errors = 0;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < threadsCreated; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Error: Failed to join thread");
            return 1;
        }

        if (errno != EINVAL) { // Skip EINVAL as it signifies normal thread termination
            ++errors;
        }
    }
    pthread_mutex_unlock(&mutex);

    return errors > 0 ? errors : 0;
}

