        {
            md5.TransformBlock(buffer, 0, bytesRead, _);
        }

        md5.TransformFinalBlock(_emptyBytes => { });
    }

    private async Task DownloadAndCalculateMd5Async(string url, MD5 md5, int chunkSize)
