} LogEntry;

void parse_log_entry(char* line, LogEntry* entry) {
    sscanf(line, "[%lld] %[^ ] %s %s %s %d %lu", &entry->timestamp, entry->ip, entry->method, entry->url, &entry->version[0], &entry->status, &entry->response_size);
}
