public abstract class IDistribution
{
    public abstract float GenerateFloat(float min, float max);
    public abstract int GenerateInt(int min, int max);
}

public sealed class GaussianDistribution : IDistribution
{
    // Implementation details for the Gaussian distribution.
}

public sealed class UniformDistribution : IDistribution
{
    // Implementation details for the uniform distribution.
}

public sealed class ExponentialDistribution : IDistribution
{
    // Implementation details for the exponential distribution.
