public sealed class DynamicValueGenerator
{
    private readonly ConcurrentDictionary<Type, object> _distributions;
    private readonly IDistribution _currentDistribution;
    private readonly (float min, float max) _range;

    public DynamicValueGenerator(Func<string, Type, object> configureDistribution)
    {
        _distributions = new ConcurrentDictionary<Type, object>();
        _currentDistribution = ConfigureDistribution(ConfigureNames.Gaussian);
        _range = (_currentDistribution as GaussianDistribution).Range;
    }

    public float GenerateFloat() => _currentDistribution.GenerateFloat(_range.min, _range.max);
    public int GenerateInt() => (int)_currentDistribution.GenerateFloat(0, double.MaxValue) * (_range.max - _range.min + 1) + _range.min;

    public override string ToString() => $"DynamicValueGenerator[Range: {_range.min}-{_range.max}, Distribution: {_currentDistribution.GetType().Name}]";

    public void SwitchDistribution(string distributionName)
    {
        var newDistribution = ConfigureDistribution(distributionName);
        if (newDistribution is null) throw new ArgumentException("Invalid distribution type.");

        _currentDistribution = newDistribution;
        _range = (_currentDistribution as GaussianDistribution).Range;
    }

    private IDistribution ConfigureDistribution(string distributionName)
    {
        if (!_distributions.TryGetValue(Type.GetTypeFromHandle(Type.GetTypeFromProgID($"{distributionName}.1")), out object config))
        {
            config = ConfigureManager.Instance.LoadConfiguration(distributionName);
            _distributions[config.GetType()] = config;
        }

        return (IDistribution)Activator.CreateInstance(Type.GetTypeFromHandle(Type.GetTypeFromProgID($"{_distributions[config.GetType()].GetType().FullName}.1")), config);
    }
}
