        auto processTask = [&]() {
            while (!dataBuffer.eof()) {
                parser->process(dataBuffer, strand);
            }
        };
        workerThreads.emplace_back(readTask);
        workerThreads.emplace_back(processTask);
    }

    for (auto& thread : workerThreads) thread.join();

    // Write processed data to an encrypted output file
    std::string key, iv;
    // Load encryption key and initialization vector from a configuration file

    std::ofstream ofs(argv[2], std::ios::binary);
    encrypt(key, iv.size(), dataBuffer, ofs);

    statusReporter->reportStatus();
    return 0;
}

