using System.Threading.Tasks;
using System.Data;
using Dapper;
using Newtonsoft.Json;
using Microsoft.Extensions.Caching.Memory;
using Newtonsoft.Json.Linq;

public class XmlAndBinaryParser
{
    private readonly IMemoryCache _cache;
    private readonly string _binaryFilePath;
    private readonly int _cacheDurationMinutes;
    private readonly long _maxCacheSizeBytes;

    public XmlAndBinaryParser(IMemoryCache cache, string binaryFilePath, int cacheDurationMinutes, long maxCacheSizeBytes)
    {
        _cache = cache;
        _binaryFilePath = binaryFilePath;
        _cacheDurationMinutes = cacheDurationMinutes;
        _maxCacheSizeBytes = maxCacheSizeBytes;
    }

    public async Task<JToken> GetFirstMatchingElement(string xmlUrl, string xPathExpression)
    {
        var key = $"{xmlUrl}-{xPathExpression}";
        var cacheItem = _cache.Get(key);

        if (cacheItem != null) return cacheItem.Value as JToken;

        HttpWebRequest request = WebRequest.CreateHttp(xmlUrl);
        using (var httpResponse = await request.GetResponseAsync())
        {
            var xmlStream = httpResponse.GetResponseStream();
            var xmlDocument = new XmlDocument();
            xmlDocument.Load(xmlStream);

            XNamespace ns = null;
            if (!string.IsNullOrEmpty(XmlQualifiedName.Create QualifiedNameFromXPathExpression(xPathExpression).NamespaceURI))
                ns = XmlQualifiedName.Create QualifiedNameFromXPathExpression(xPathExpression).Namespace;

            var xpathNode = xmlDocument.SelectSingleNode(xPathExpression, ns);
            if (xpathNode == null) throw new Exception("Invalid XPath expression or non-existing element");

            using (var memoryStream = new MemoryStream())
            {
                using (var binaryReader = new BinaryReader(_binaryFilePath))
                {
                    memoryStream.Write(binaryReader.ReadBytes((int)binaryReader.BaseStream.Length));
                    _cache.Set(key, memoryStream.ToArray(), new MemoryCacheEntryOptions()
                        .SetAbsoluteExpiration(TimeSpan.FromMinutes(_cacheDurationMinutes))
                        .SetSize(_maxCacheSizeBytes));
                }

                var data = await Task.Run(() => JsonConvert.DeserializeObject<DataTable>(JsonConvert.SerializeObject(xpathNode)));

                using (var connection = new SqlConnection("YourConnectionString"))
                {
                    await connection.OpenAsync();
                    await connection.ExecuteAsync(@"truncate table YourTable");
                    await connection.InsertAllAsync(data);
                }
            }
        }

        return GetFirstMatchingElementFromBinary(xPathExpression, key);
    }

    private JToken GetFirstMatchingElementFromBinary(string xPathExpression, object cacheKey)
    {
        using (var binaryReader = new BinaryReader(_binaryFilePath))
        {
            var dataTable = JsonConvert.DeserializeObject<DataTable>(JsonConvert.SerializeObject(JToken.Parse((new StreamReader(binaryReader)).ReadToEnd()).XPathEvaluate(xPathExpression)));

            if (dataTable.Rows.Count > 0)
                return dataTable.Rows[0][0]; // Assuming the first column of the DataTable contains the desired element
        }

        throw new Exception("Invalid XPath expression or non-existing element in binary file");
    }
}
