use std::collections::HashMap;
use std::sync::Arc;
use reqwest::{Client, RequestBuilder};
use tokio::runtime::Runtime;
use log::{error, info};
use reqwest::header::{HeaderMap, HeaderValue};
use serde::{Deserialize, Serialize};
use reqwest::Error as ReqwestError;

#[derive(Serialize, Deserialize)]
struct TokenResponse {
    access_token: String,
}

struct HttpClientConfig {
    disable_certificate_validation: bool,
    retries: usize,
    retry_interval: std::time::Duration,
    timeout: std::time::Duration,
    custom_headers: HashMap<String, String>,
}

struct HttpClientError {
    kind: ErrorKind,
    message: String,
}

enum ErrorKind {
    Network,
    Server,
    CertificateValidation,
    TokenRefresh,
    Other,
}

impl std::error::Error for HttpClientError {}

fn create_http_client(config: HttpClientConfig) -> Result<RequestBuilder, HttpClientError> {
    let client = Client::builder()
        .dangerously_disable_ssl_validations_if(config.disable_certificate_validation)
        .timeout(Some(config.timeout))
        .build()?;

    let runtime = Runtime::new().unwrap();
    let client = Arc::new(client);

    let mut headers = HeaderMap::new();
    for (key, value) in config.custom_headers {
        headers.insert(key, HeaderValue::from_str(&value).unwrap());
    }

    let request_builder = client.clone().request_builder();

    let refresh_token = if config.retries > 0 {
        Some(async move {
            // Call your authentication service here to refresh the token
            // Handle errors and log them as needed
            // If an error occurs during token refreshing, return Err(HttpClientError::TokenRefresh)
            let response = client.post("https://your-auth-service-url/token")
                .headers(headers.clone())
                .send().await?;

            if response.status() == 401 {
                refresh_token(config).await
            } else {
                let token_response: TokenResponse = response.json().await?;
                info!("Token refreshed successfully");
                Ok(token_response.access_token)
            }
        })
    } else {
        None
    };

    let request_builder = request_builder
        .headers(headers)
        .and_then(|request| {
            async move {
                match refresh_token.as_ref().unwrap().await {
                    Ok(access_token) => {
                        request.header("Authorization", HeaderValue::from_str(&format!("Bearer {}", access_token)).unwrap())
                    }
                    Err(e) => {
                        error!("Error during token refresh: {}", e);
                        Err(HttpClientError { kind: ErrorKind::TokenRefresh, message: e.to_string() })
                    }
                }
            }
            .or_else(|e| {
                error!("Request error: {}", e);
                Err(HttpClientError { kind: ErrorKind::Network, message: e.to_string() })
            })
        })
        .retry(config.retries as u16, config.retry_interval)
        .map_err(|e| HttpClientError { kind: ErrorKind::Server, message: e.to_string() });

    Ok(request_builder)
}
