```java
import java.io.*;
import static java.lang.String.format;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class LoggingProgram {
    private static void logError(String message) {
        System.err.println(format("[ERROR] %s", message));
    }

    private static int executeCommand(String command, String workingDirectory) throws IOException {
        ProcessBuilder builder = new ProcessBuilder(command);
        builder.directory(new File(workingDirectory));

        Path errorLogFile = Paths.get("error_log.txt");
        if (Files.exists(errorLogFile)) Files.deleteIfExists(errorLogFile);

        Process process = builder.start();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
             PrintWriter errorLogger = new PrintWriter(new FileWriter(errorLogFile.toFile(), true))) {

            Thread readThread = new Thread(() -> {
                try {
                    String line;
                    while ((line = reader.readLine()) != null) {
                        logError(String.format("[OUTPUT] %s", line));
                    }
                } catch (IOException e) {
                    logError(e.getMessage());
                }
            });

            readThread.start();

            try {
                process.waitFor();
            } catch (InterruptedException e) {
                logError(e.getMessage());
            } finally {
                process.destroy();
            }

            readThread.join();
        }

        return process.exitValue();
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            logError("Usage: java LoggingProgram command workingDirectory");
            System.exit(1);
        }

        int exitCode = executeCommand(args[0], args[1]);
        logError(String.format("[EXIT_CODE] %d", exitCode));
    }
}
```

This Java program includes a `logError()` function that logs error messages to the console and an optional error log file. The main part of the code is `executeCommand()`, which checks if a given file exists, deletes it if it does, executes a command using `Runtime.getRuntime().exec(String, String, File)`, reads the output and error streams of the executed command, and logs them using the aforementioned logging function. The logging is coherent and integrated into the overall structure of the Java program.

