using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

public class ManageWebsiteLifecycle
{
    private readonly APIClient _apiClient;
    private readonly ConfigManager _configManager;

    public ManageWebsiteLifecycle(APIClient apiClient, ConfigManager configManager)
    {
        _apiClient = apiClient;
        _configManager = configManager;
    }

    public async Task ManageWebsitesAsync(string configFilePath, IEnumerable<string> siteNames, Dictionary<string, List<string>> operations)
    {
        var sites = _configManager.LoadSites(configFilePath);
        var validSites = sites.Where(site => site.Name.All(c => Char.IsLetterOrDigit(c))).ToList();
        if (!validSites.Any())
            throw new ArgumentException("Invalid site names in the configuration file.");

        var tasks = operations.Select(op => ManageWebsiteOperation(op.Key, op.Value, validSites));
        await Task.WhenAll(tasks);
    }

    private async Task ManageWebsiteOperation(string operationName, List<string> sitesWithOperation, IEnumerable<Site> validSites)
    {
        var tasks = sitesWithOperation.Select(site => ManageSiteOperation(site, operationName));
        await Task.WhenAll(tasks);
    }

    private async Task ManageSiteOperation(string siteName, string operationName)
    {
        var site = validSites.FirstOrDefault(s => s.Name == siteName);
        if (site == null)
            throw new ArgumentException("No such site: " + siteName);

        DirectoryInfo dirInfo;
        try
        {
            dirInfo = new DirectoryInfo(site.DirectoryPath);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error validating directory path for site '{siteName}': {ex.Message}");
            return;
        }

        if (!dirInfo.Exists || !dirInfo.GetFiles("web.config").Any())
        {
            Console.WriteLine($"Missing web.config file for site '{siteName}'.");
            return;
        }

        try
        {
            var response = await _apiClient.SendRequestAsync(operationName, siteName);
            if (!response.Success)
                Console.WriteLine($"Error performing operation '{operationName}' on site '{siteName}': {response.ErrorMessage}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error communicating with the API for site '{siteName}': {ex.Message}");
        }
    }
}
```

