public sealed class DynamicValueGenerator
{
    private readonly Dictionary<string, IDistribution> _distributions;
    private readonly object _cacheLock = new object();
    private IDistribution _currentDistribution;

    public DynamicValueGenerator(IDictionary<string, object> config)
    {
        var distributionTypes = new List<Type> { typeof(GaussianDistribution), typeof(UniformDistribution), typeof(ExponentialDistribution) };

        _distributions = config.Where(kvp => distributionTypes.Contains(kvp.Value.GetType()))
            .ToDictionary(kvp => kvp.Key, kvp => Activator.CreateInstance(kvp.Value.GetType(), kvp.Value));
    }

    public void SetDistribution(string distributionName, object parameters)
    {
        _currentDistribution = _distributions[distributionName];
    }

    public float GetRandomFloat()
    {
        return GetRandomFloat(0f, 1f);
    }

    public float GetRandomFloat(float min, float max)
    {
        IDistribution currentDistribution = _currentDistribution ?? throw new InvalidOperationException("No distribution set.");

        lock (_cacheLock)
        {
            if (CurrentCacheContains(min, max))
                return GetFromCache(min, max);
            else
            {
                var value = currentDistribution.GetFloatValue(min, max);
                AddToCache(min, max, value);
                return value;
            }
        }
    }

    public int GetRandomInt()
    {
        return GetRandomInt(0, int.MaxValue);
    }

    public int GetRandomInt(int min, int max)
    {
        IDistribution currentDistribution = _currentDistribution ?? throw new InvalidOperationException("No distribution set.");

        lock (_cacheLock)
        {
            if (CurrentCacheContains(min, max))
                return GetFromCache(min, max);
            else
            {
                var value = currentDistribution.GetIntValue(min, max);
                AddToCache(min, max, value);
                return value;
            }
        }
    }

    private bool CurrentCacheContains(float min, float max)
    {
        lock (_cacheLock)
        {
            return _currentDistribution.GetType().Name + "-" + min + "-" + max + "-value" in _cache;
        }
    }

    private float GetFromCache(float min, float max)
    {
        lock (_cacheLock)
        {
            var key = _currentDistribution.GetType().Name + "-" + min + "-" + max + "-value";
            return _cache[key];
        }
    }

    private void AddToCache(float min, float max, float value)
    {
        lock (_cacheLock)
        {
            var key = _currentDistribution.GetType().Name + "-" + min + "-" + max + "-value";
            _cache[key] = value;
        }
    }

    private readonly Dictionary<string, float> _cache = new Dictionary<string, float>();

    public override string ToString()
    {
        return $"DynamicValueGenerator: Current distribution: {_currentDistribution.GetType().Name}, Range: [{_currentDistribution.MinValue}, {_currentDistribution.MaxValue}]";
    }
}
