    uint32_t getIP() const { return ip_; }

private:
    uint32_t ip_;
};

// NetworkPDUConfig_T structure
struct NetworkPDUConfig_T {
    int packetID;
    IPAddress sourceIP, destinationIP;
    size_t payloadLength;
};

std::vector<NetworkPDUConfig_T> pduList;
constexpr size_t MAX_STRUCTURES = 5000;

// Logging function
void log(const std::string& message) {
    // Implement logging to file or console here
}

int createAndConfigureNetworkPduList(NetworkPDUConfig_T **pduList, size_t *listSize, int maxStructures) {
    if (maxStructures <= 0 || pduList == nullptr || listSize == nullptr) {
        log("Invalid input parameters");
        return -1;
    }

    // Ensure the function does not exceed the maxStructures limit
    if (pduList != nullptr && maxStructures > MAX_STRUCTURES) {
        maxStructures = MAX_STRUCTURES;
    }

    // Use a vector to manage memory efficiently and avoid unnecessary allocations and deallocations
    pduList = new NetworkPDUConfig_T[maxStructures];
    *listSize = 0;

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, MAX_STRUCTURES - 1);

    for (size_t i = 0; i < maxStructures && *listSize < maxStructures; ++*listSize) {
        // Generate unique packetIDs
        pduList[i].packetID = (*listSize);

        // Set sourceIP and destinationIP here (with validation checks)
        pduList[i].sourceIP.getIP() = dis(gen);
        pduList[i].destinationIP.getIP() = dis(gen);

        // Generate random payload lengths within a reasonable range
        std::uniform_int_distribution<> plenDist(10, 1024);
        pduList[i].payloadLength = plenDist(gen);
    }

    // Sort the configurations based on packet payload length in ascending order after creation
    std::sort(pduList, pduList + *listSize, [](const NetworkPDUConfig_T& a, const NetworkPDUConfig_T& b) {
        return a.payloadLength < b.payloadLength;
    });

    return 0;
}
