#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>
#include <pthread.h>

typedef struct {
    int id;
    long offset[3];
    int key;
    double avg; // Added to store average of last two fields
} Record;

static int callback(void *data, int argc, char **argv, char **azColName) {
    Record *record = (Record *)data;

    if (argc == 5) { // Assuming 5 columns in the table
        record->offset[0] = atol(argv[1]);
        record->offset[1] = atol(argv[2]);
        record->offset[2] = atol(argv[3]);
        record->key = atoi(argv[4]);
    }

    return 0;
}

Record *parse_line(char *line) {
    Record *record = (Record *)malloc(sizeof(Record));
    sscanf(line, "%d %lld %lld %lld %d", &record->id, &record->offset[0], &record->offset[1], &record->offset[2], &record->key);
    record->avg = (record->offset[2] + record->offset[1]) / 2.0; // Calculate average of last two fields
    return record;
}

void free_record(Record *record) {
    free(record);
}

static int init_db(sqlite3 **db, const char *filename) {
    int rc = sqlite3_open(filename, db);

    if (rc) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(*db));
        sqlite3_close(*db);
        return 1;
    }

    const char *sql = "CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY, offset1 INTEGER, offset2 INTEGER, offset3 INTEGER, key INTEGER)";
    rc = sqlite3_exec(*db, sql, NULL, NULL, NULL);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(*db));
        sqlite3_close(*db);
        return 1;
    }

    return 0;
}

void* process_file(void *args) {
    FILE *file = (FILE *)args;
    char line[1024];
    Record *record;

    while (fgets(line, sizeof(line), file)) {
        record = parse_line(line);

        sqlite3 *db;
        if (init_db(&db, "database.db")) return NULL; // Exit thread on SQL connection errors

        sqlite3_prepare_v2(db, "INSERT INTO records VALUES (?, ?, ?, ?, ?)", -1, &callback, record, NULL);
        int step = sqlite3_step(sqlite3_get_autocommit(db));
        sqlite3_finalize(sqlite3_get_autocommit(db));
        sqlite3_close(db);

        free_record(record);
    }

    return NULL;
}

int main() {
    pthread_t threads[10]; // Adjust thread count for parallelism requirements
    FILE *file = fopen("data.txt", "r");

    if (!file) {
        fprintf(stderr, "Can't open file: %s\n", strerror(errno));
        return 1;
    }

    for (int i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_create(&threads[i], NULL, process_file, file)) {
            fprintf(stderr, "Thread creation failed\n");
            return 1;
        }
    }

    for (int i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(file);
    return 0;
}
```

