// FinancialApiService.js
class FinancialApiService {
  constructor(baseUrl, maxRetries = 3, retryDelayBaseMs = 1000) {
    this.baseUrl = baseUrl;
    this.maxRetries = maxRetries;
    this.retryDelayBaseMs = retryDelayMs;
  }

  async fetchTransactionAmount(id) {
    let attempts = 0;
    let response;

    do {
      try {
        const url = `${this.baseUrl}/transactions/${id}`;
        response = await fetch(url);
        if (!response.ok) throw new Error(`API returned error: ${response.statusText}`);
        return response.json();
      } catch (error) {
        attempts++;
        console.error(`Fetch attempt for transaction ID ${id} failed with error: ${error.message}. Retrying...`);
        await new Promise(resolve => setTimeout(resolve, this.retryDelayBaseMs * Math.pow(2, attempts)));
      }
    } while (attempts < this.maxRetries);

    if (!response) {
      throw new Error(`Failed to fetch transaction data after ${this.maxRetries} attempts`);
    }
  }
}

// TransactionReducer.js
class TransactionReducer {
  constructor(transactionIds, financialApiService, workerPoolSize = 4, timeoutMs = 60000) {
    this.transactionIds = transactionIds;
    this.financialApiService = financialApiService;
    this.workerPoolSize = workerPoolSize;
    this.timeoutMs = timeoutMs;
  }

  async reduce() {
    const chunkSize = Math.ceil(this.transactionIds.length / this.workerPoolSize);
    const workerPool = new WorkerPool(this.workerPoolSize, this.processTransaction.bind(this));

    let total = 0;
    let processedCount = 0;
    let startTime = Date.now();

    for (let i = 0; i < chunkSize; i++) {
      const chunk = this.transactionIds.slice(i * chunkSize, (i + 1) * chunkSize);
      await workerPool.processChunk(chunk);
    }

    // Wait for all workers to finish processing and cleanup
    await workerPool.drain();
    workerPool.terminate();

    console.log(`Reduction completed in ${Date.now() - startTime}ms`);
    console.log(`Processed ${processedCount} transactions, total: ${total}`);
  }

  async processTransaction(id) {
    try {
      const transaction = await this.financialApiService.fetchTransactionAmount(id);
      return transaction.amount;
    } catch (error) {
      console.error(`Error processing transaction ID ${id}: ${error.message}`);
      return null;
    }
  }
}

// WorkerPool.js
class WorkerPool {
  constructor(workerCount, taskExecutor) {
    this.workers = [];
    this.taskExecutor = taskExecutor;

    for (let i = 0; i < workerCount; i++) {
      const worker = new Worker('Worker.js');
      worker.onmessage = event => this.onMessage(event, worker);
      this.workers.push(worker);
    }
  }

  async processChunk(tasks) {
    const promises = tasks.map(id => this.taskExecutor(id));
    const results = await Promise.all(promises);

    for (let i = 0; i < results.length; i++) {
      if (results[i]) {
        this.dispatchResult(results[i], i);
      }
    }
  }

  drain() {
    return new Promise((resolve, reject) => {
      const drained = () => {
        this.workers.forEach(worker => worker.terminate());
        resolve();
      };

      let idleWorkersCount = this.workers.length;
      this.onMessage = (event, worker) => {
        if (event.data === 'idle') {
          idleWorkersCount--;
          if (idleWorkersCount === 0) drained();
        }
      };
    });
  }

  terminate() {
    this.workers.forEach(worker => worker.terminate());
  }

  onMessage(event, worker) {
    const data = event.data;

    if (typeof data === 'number') {
      // Result from a worker
      console.log(`Received result from worker ${worker.id}: ${data}`);
    } else if (data === 'idle') {
      // Instruct a worker to take the next task
      this.taskExecutorQueue.push(this.taskQueue.shift());
      worker.postMessage('take');
    }
  }
}
```

In this example, the code snippets represent modular classes and functions that implement the required features for the `TransactionReducer`. The FinancialApiService class simulates interaction with an external financial API. The TransactionReducer manages the reduction process in parallel using a worker pool. The WorkerPool handles task distribution, result collection, and cleanup.

