#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum { ECB, EDE, EDE3, CFB } mode_t;

EVP_CIPHER *create_cipher(const char* algorithm, mode_t mode) {
    EVP_CIPHER_CTX *ctx = NULL;
    const EVP_CIPHER *cipher = NULL;

    // Create and initialize the cipher context
    if (!(ctx = EVP_CIPHER_CTX_new())) {
        fprintf(stderr, "Error: Out of memory\n");
        goto err;
    }

    // Select the algorithm and set the mode
    if (!(cipher = EVP_get_cipherbyname(algorithm))) {
        fprintf(stderr, "Error: Invalid algorithm\n");
        goto err;
    }
    switch (mode) {
        case ECB:
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_ECB_MODE_AUTO_PADDING, 0, NULL);
            break;
        case EDE:
        case EDE3:
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_ENC_PADDING, EVP_padding_pkcs7(), NULL);
            // Fallthrough intentionally to ensure only one padding is set
        case CFB:
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_CFB_MODE_AUTO_PADDING, 0, NULL);
            break;
        default:
            fprintf(stderr, "Error: Invalid mode\n");
            goto err;
    }

    // Initialize the cipher context
    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL)) {
        fprintf(stderr, "Error: Failed to initialize the cipher\n");
        goto err;
    }

    // Return the created cipher context as an EVP_CIPHER pointer
    EVP_CIPHER *cipher_ptr = EVP_CIPHER_CTX_get0_cipher(ctx);
    return cipher_ptr;

err:
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

// ... (Other functions to handle encryption, decryption, cleanup and logging)
```

