First, let's create a `ResourceBundle` class that encapsulates the functionality of loading, managing, and accessing the resource bundle:

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <thread>
#include <mutex>
#include <atomic>
#include <condition_variable>

class ResourceBundle {
public:
    struct Item {
        std::string id;
        std::string metadata;
        // Add any additional fields as needed
    };

    virtual ~ResourceBundle() {}
    virtual int count() const = 0;
    virtual const Item& getItem(size_t index) const = 0;
    virtual void loadFromFile(const std::string& filename) = 0;

protected:
    std::vector<Item> items;
    mutex dataMutex;
    condition_variable cvDataReady;
    atomic_bool isLoaded{false};
};
```

Next, create a derived class `FileResourceBundle` that implements the pure virtual methods from `ResourceBundle`. Use smart pointers to manage memory efficiently.

```cpp
#include <memory>
#include <string>
#include <sstream>
#include <iterator>
#include <filesystem>

class FileResourceBundle : public ResourceBundle {
public:
    static std::unique_ptr<FileResourceBundle> loadFromFile(const std::string& filename) {
        auto fileResourceBundle = std::make_unique<FileResourceBundle>();
        fileResourceBundle->loadFromFile(filename);
        return fileResourceBundle;
    }

    int count() const override {
        std::lock_guard<mutex> lock(dataMutex);
        return items.size();
    }

    const Item& getItem(size_t index) const override {
        std::lock_guard<mutex> lock(dataMutex);
        if (index >= items.size())
            throw std::out_of_range("Index out of range");
        return items[index];
    }

    void loadFromFile(const std::string& filename) override {
        std::ifstream file(filename);
        if (!file.is_open())
            throw std::runtime_error("Unable to open the file");

        // Assume the file format is as follows: id metadata ...
        // where each line contains an item's id and metadata separated by a tab character
        std::string line;
        Item currentItem;
        while (std::getline(file, line)) {
            std::istringstream iss(line);
            if (!iss)
                throw std::runtime_error("Corrupted data in file");

            std::string id;
            std::string metadata;
            if (!(iss >> id >> std::ws >> metadata))
                throw std::runtime_error("Invalid format in file");

            currentItem = {id, metadata};
            items.push_back(currentItem);
        }

        isLoaded = true;
        cvDataReady.notify_all();
    }

private:
    FileResourceBundle() {}
};
```

