app.put('/users/:id', async (req, res) => {
  const userId = req.params.id;
  const updatedData = json.parse(req.body);

  if (!updatedData || !Object.keys(updatedData).length) return res.status(400).send({ error: 'Invalid request body' });

  // Load the user from the database, assuming you have a Users collection.
  const user = await loadUserById(userId);

  if (!user) return res.status(404).send({ error: 'User not found' });

  updateLimiter.take();
  try {
    // Merge the updated data with the existing profile data efficiently using Object.assign() or similar approach.
    const mergedUser = new User(user.id, user.name || updatedData.name, user.email || updatedData.email, user.address || updatedData.address);

    await saveUser(mergedUser);
    res.send({ success: true });
  } catch (error) {
    res.status(500).send({ error: error.message });
  } finally {
    updateLimiter.release();
  }
});
