use std::time::{Instant, Duration};
use std::sync::Lazy;
use select::{Document, Predicate};
use reqwest::Client;
use diesel::prelude::*;
use r2d2::{Pool, Manager};
use itertools::Itertools;
use serde_json::{Value, Map};

type Error = Box<dyn std::error::Error + Send + Sync>;
type Result<T> = std::result::Result<T, Error>;

static DB_POOL: Lazy<r2d2::Pool<Manager<sqlite::SqliteConnection>>> = Lazy::new(|| {
    let manager = sqlite::SqliteConnection::establish(":memory:")?;
    r2d2::Pool::new(manager).unwrap()
});

type DataTableReader = Box<dyn std::iter::Iterator<Item=Value>>;

fn dbCommandExecutor(root: Node, selector: &str, test_func: Option<Box<FnMut(&Node) -> Result<()>>, data: Vec<u8>) -> Result<DataTableReader> {
    let start = Instant::now();
    let str_data = String::from_utf8(data)?;

    let document = Document::from_read(&str_data[..]);
    if root != document.root() {
        return Err(Box::new("Root node is not a valid DOM node"));
    }

    let mut elements = Vec::new();
    let matcher = Predicate::find(selector);
    for node in document.select(&matcher).unwrap_or_else(|_| panic!("Invalid CSS selector")) {
        if let Some(ref test_func) = test_func {
            if test_func(&node)? {
                elements.push(node);
            }
        } else {
            elements.push(node);
        }
    }

    let mut connection = DB_POOL.get()?;
    let client = Client::new();
    for node in &elements {
        // Send the node data to the database server asynchronously and ignore the response since we only care about the effect on the DB (assuming there is a function to do this)
        tokio::spawn(async move {
            let req_body = serde_json::to_string(&node)?;
            client.post("http://your-database-server")
                .header("Content-Type", "application/json")
                .body(req_body)
                .send()
                .await?;
        });
    }

    // Query the database and return the result wrapped in a DataTableReader object
    let reader = query_database(&mut connection)?;

    println!("Time taken: {}", start.elapsed().as_millis());
    Ok(Box::new(reader))
}

fn query_database(conn: &mut sqlite::SqliteConnection) -> Result<Vec<Value>> {
    // Write your SQL query here to fetch the data from the database and convert it to a Vec<Value>
    use diesel::expression::{Expression, Expr};
    use diesel::sql_query;
    let rows: Vec<Value> = sql_query("SELECT * FROM table").load(conn)?;
    Ok(rows)
}

fn early_error(err: Error) -> ! {
    println!("Error occurred: {}", err);
    panic!("{}", err);
}
