Here is a basic structure of the Java program that meets your requirements. I've used `java.nio.file` for file operations, `ProcessBuilder` for executing commands, and `Thread.sleep()` for implementing exponential backoff. Note that Java does not have an equivalent to C's `snprintf`, but you can use `String.format()`.

```java
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.TimeUnit;

public class Main {
    private static final int MAX_RETRIES = 3;
    private static final long[] BACKOFF_INTERVALS = {100, 500, 1000};
    private static final String LOG_FILE = "error.log";

    public static void logError(String format, Object... args) {
        try (PrintWriter writer = new PrintWriter(new FileWriter(LOG_FILE, true))) {
            writer.printf(format + "\n", args);
        } catch (IOException e) {
            System.err.println("Error logging: " + e.getMessage());
        }
    }

    public static void deleteIfExists(Path path) {
        if (Files.exists(path)) {
            try {
                Files.deleteIfExists(path);
            } catch (IOException e) {
                logError("Failed to delete %s: %s", path, e.getMessage());
            }
        }
    }

    public static void executeCommand(String command) {
        ProcessBuilder processBuilder = new ProcessBuilder(command);
        Process process;
        try {
            process = processBuilder.start();
            int exitValue = process.waitFor();
            if (exitValue != 0) {
                InputStreamReader errorStreamReader = new InputStreamReader(process.getErrorStream());
                BufferedReader bufferedErrorReader = new BufferedReader(errorStreamReader);
                String line;
                while ((line = bufferedErrorReader.readLine()) != null) {
                    logError("Command error: %s", line);
                }
            }
        } catch (IOException | InterruptedException e) {
            logError("Failed to execute command: %s", e.getMessage());
        }
    }

    public static void retryCommand(Runnable runnable, int retriesLeft) {
        if (retriesLeft > 0) {
            try {
                runnable.run();
            } catch (Exception e) {
                logError("Retrying command %d of %d: %s", retriesLeft + 1, MAX_RETRIES, e.getMessage());
                TimeUnit.MILLISECONDS.sleep(BACKOFF_INTERVALS[retriesLeft - 1]);
                retryCommand(runnable, retriesLeft - 1);
            }
        } else {
            logError("Gave up on command after %d retries", MAX_RETRIES);
        }
    }

    public static void main(String[] args) {
        Path configFile = Paths.get("config.txt");
        deleteIfExists(configFile);

        String[] commands = {"command1", "command2", "command3"}; // replace with your commands

        for (String command : commands) {
            retryCommand(() -> executeCommand(command), MAX_RETRIES);
        }
    }
}
```

