        {
            var chunkSize = 1024 * 1024; // 1MB
            var buffer = MemoryPool<char>.Shared.Rent(chunkSize);

            using var reader = new StreamReader(stream, Encoding.UTF8);
            var json = await reader.ReadToEndAsync();
            using (var memoryStream = new MemoryStream(Encoding.UTF8.GetBytes(json)))
            {
                return await Policy
                    .Handle<HttpRequestException>()
                    .OrResult<HttpResponseMessage>(r => r.IsSendError())
                    .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromMilliseconds(Math.Pow(2, retryAttempt)))
                    .ExecuteAsync(() => FetchSchemaAsync(_httpClient))
                    .ThenAsync(async () =>
