```c
#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    AES_KEY aes;
    unsigned char iv[12];
} AES256GCM_ctx;

void log_error(const char *err_msg) {
    fprintf(stderr, "%s\n", err_msg);
    ERR_print_errors_fp(stderr);
}

AES256GCM_ctx* aes256gcm_init(const unsigned char *password, size_t password_len, const unsigned char *salt, size_t salt_len) {
    EVP_PKEY *key;
    AES256GCM_ctx *ctx = malloc(sizeof(AES256GCM_ctx));
    if (!ctx || !EVP_PBKDF2_init((EVP_CIPHER_CTX *)NULL, EVP_aes_256_gcm(), NULL, password, password_len, salt, salt_len, 1000)) {
        log_error("Failed to initialize PBKDF2 context");
        free(ctx);
        return NULL;
    }

    unsigned char key_derived[32];
    if (!EVP_PBKDF2((EVP_CIPHER_CTX *)NULL, key_derived, sizeof(key_derived), password, password_len, salt, salt_len, 1000, EVP_sha256())) {
        log_error("Failed to derive encryption key");
        free(ctx);
        return NULL;
    }

    AES_set_encrypt_key((const unsigned char *)key_derived, 256, &ctx->aes);
    AES_gcmlength_set(&ctx->aes, AES_GCM_96); // Set IV length to 96 bits (12 bytes)
    randombytes_ex(ctx->iv, sizeof(ctx->iv)); // Generate a random IV

    return ctx;
}

void aes256gcm_cleanup(AES256GCM_ctx *ctx) {
    EVP_CIPHER_CTX_free((EVP_CIPHER_CTX *)(&ctx->aes));
    free(ctx);
}
```

