[HttpPut("{id}")]
public IActionResult Put(int id, [FromBody] ResourceUpdateModel model)
{
    var resource = _context.Resources.Find(id);

    if (resource == null)
        return NotFound();

    if (!ModelState.IsValid)
        return BadRequest(ModelState);

    // Update only the properties that have been sent in the request body
    foreach (var property in typeof(Resource).GetProperties())
    {
        if (model.TryGetValue(property.Name, out object value))
            property.SetValue(resource, value);
    }

    _context.SaveChanges();

    return Ok(resource);
}
```

