char *get_file_hash(const char *path, void (*log_fn)(const char *, ...)) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    FILE *file = fopen(path, "rb");
    if (!file) {
        log_error("Failed to open file for reading.");
        return NULL;
    }
    size_t read_bytes;
    while ((read_bytes = fread(digest + SHA256_DIGEST_LENGTH - read_bytes, 1, read_bytes, file)) > 0) {}
    if (ferror(file)) {
        log_error("Error reading file.");
        return NULL;
    }
    fclose(file);
    HMAC_SHA256((const unsigned char *)key, key_length, digest, SHA256_DIGEST_LENGTH, digest, SHA256_DIGEST_LENGTH);
    char hash[2 * SHA256_DIGEST_LENGTH + 1];
    for (size_t i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        snprintf(hash + i * 2, sizeof(hash), "%02x", digest[i]);
    }
    return hash;
}
