Below is a C++11 solution using the Boost Library for some functionalities. I've created a `ResourceBundle` class that includes loading from a compressed file, concurrency support (using `std::mutex`), and dynamic memory allocation management.

```cpp
#include <iostream>
#include <boost/filesystem.hpp>
#include <boost/filesystem/fstream.hpp>
#include <boost/archive/tar/iterator.hpp>
#include <boost/thread/mutex.hpp>
#include <vector>
#include <memory>

class ResourceBundle {
public:
    explicit ResourceBundle(const std::string& zipPath);
    ~ResourceBundle();

    size_t getNumItems() const;

private:
    bool loadMetadata();
    void fetchAdditionalMetadata(size_t index);

    boost::filesystem::path _zipPath;
    mutable boost::mutex _mutex;
    std::vector<std::unique_ptr<ResourceItem>> _items;
};

ResourceBundle::ResourceBundle(const std::string& zipPath) : _zipPath(zipPath), _items() {
    if (!loadMetadata()) {
        throw std::runtime_error("Failed to load resource bundle.");
    }
}

ResourceBundle::~ResourceBundle() {}

size_t ResourceBundle::getNumItems() const {
    std::unique_lock<std::mutex> lock(_mutex);
    return _items.size();
}

bool ResourceBundle::loadMetadata() {
    if (!boost::filesystem::exists(_zipPath)) {
        throw std::runtime_error("Resource bundle file does not exist.");
    }

    boost::archive::tar::input_iterator tarIter(_zipPath);
    for (auto iter = tarIter; iter != tarIter.end(); ++iter) {
        if (!iter->is_regular_file()) {
            continue;
        }

        std::unique_ptr<ResourceItem> item(new ResourceItem());
        if (!item->loadFromFile(iter->path())) {
            std::cerr << "Failed to load resource: " << iter->path() << "\n";
            return false;
        }

        std::unique_lock<std::mutex> lock(_mutex);
        _items.push_back(std::move(item));
    }

    return true;
}

void ResourceBundle::fetchAdditionalMetadata(size_t index) {
    if (index >= _items.size()) {
        throw std::out_of_range("Index out of bounds.");
    }

    // Implement the logic for fetching additional metadata here.
}

// Unit tests go here...
```

