        // Verify the existence and accessibility of the file within the specified path
        if (!boost::filesystem::exists(filePath) || !boost::filesystem::is_regular_file(filePath)) {
            logError("File does not exist or is not a regular file: " + filePath);
            callback("FILE_ISSUE", -1);
            return;
        }

        // Calculate the SHA-256 hash of the file
