            uploadToCloudStorage(filePath, hash, bucketName, metadata);
            callback("SUCCESS", 0);
        } catch (const std::exception& e) {
            logError("Failed to upload file: " + filePath + ", Error: " + e.what());
            callback("UPLOAD_ISSUE", -1);
