import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;
import java.nio.file.Files;
import java.util.zip.GZIPOutputStream;

import com.google.cloud.logging.Logger;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

public class LargeFileSummaryGenerator {
    private final String directory;
    private final Pattern[] keywords;
    private final Logger logger;
    private final OkHttpClient httpClient;
    private final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private final int maxRetries;

    public LargeFileSummaryGenerator(String directory, Pattern[] keywords, Logger logger, OkHttpClient httpClient, int maxRetries) {
        this.directory = directory;
        this.keywords = keywords;
        this.logger = logger;
        this.httpClient = httpClient;
        this.maxRetries = maxRetries;
    }

    public void generateSummaryReport() throws IOException {
        File[] files = new File(directory).listFiles();
        List<String> linesWithKeywords = new ArrayList<>();

        for (File file : files) {
            executor.submit(() -> processFile(file, linesWithKeywords));
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }

        Map<String, Long> keywordCounts = countKeywords(linesWithKeywords);
        String reportContent = generateReport(keywordCounts);
        compressAndUploadReport(reportContent);
    }

    private void processFile(File file, List<String> linesWithKeywords) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(file, StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                for (Pattern pattern : keywords) {
                    if (pattern.matcher(line).find()) {
                        linesWithKeywords.add(line);
                    }
                }
            }
        } catch (Exception e) {
            logger.atError().log("Error processing file: %s", file.getName());
            e.printStackTrace();
        }
    }

    private Map<String, Long> countKeywords(List<String> linesWithKeywords) {
        Map<String, Long> keywordCounts = new HashMap<>();
        for (String line : linesWithKeywords) {
            Arrays.stream(keywords).forEach(pattern -> {
                if (pattern.matcher(line).find()) {
                    keywordCounts.merge(pattern.pattern(), 1L, Long::sum);
                }
            });
        }
        return keywordCounts;
    }

    private String generateReport(Map<String, Long> keywordCounts) {
        // Implement your custom report generation here
        return "Summary Report";
    }

    private void compressAndUploadReport(String reportContent) throws IOException {
        ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
        GZIPOutputStream gzipOut = new GZIPOutputStream(byteStream);
        gzipOut.write(reportContent.getBytes());
        gzipOut.close();

        RequestBody requestBody = RequestBody.create(gzipOut.toByteArray(), MediaType.parse("application/octet-stream"));

        for (int i = 0; i < maxRetries; i++) {
            try {
                Request request = new Request.Builder()
                        .url("<API_UPLOAD_URL>")
                        .post(requestBody)
                        .build();

                Response response = httpClient.newCall(request).execute();
                if (response.isSuccessful()) {
                    logger.atInfo().log("Report uploaded successfully");
                    return;
                } else {
                    logger.atError().log("Failed to upload report: %s", response.message());
                }
            } catch (Exception e) {
                logger.atError().log("API integration error: %s", e.getMessage());
                if (i < maxRetries - 1) {
                    try {
                        Thread.sleep(5000);
                    } catch (InterruptedException ex) {
                        logger.atError().log("Thread interruption error: %s", ex.getMessage());
                    }
                } else {
                    throw new RuntimeException("Max retries reached without success");
                }
            }
        }
    }
}
