public class CacheManager<T>
{
    private static readonly ILog _logger = LogManager.GetLogger(typeof(CacheManager<>));
    private readonly string _binaryFileKey;
    private readonly TimeSpan _cacheRefreshInterval;
    private readonly int _maxListSize;
    private readonly Aes _aes;
    private T[] _cachedData;
    private List<string> _forwardList;

    public CacheManager(IConfiguration configuration)
    {
        _binaryFileKey = configuration["BinaryFileKey"];
        _cacheRefreshInterval = TimeSpan.FromMinutes(configuration.GetValue<int>("CacheRefreshInterval"));
        _maxListSize = configuration.GetValue<int>("MaxListSize");
        _aes = Aes.Create();
    }

    public void AddToForwardList(string item, string value)
    {
        if (_forwardList == null) _forwardList = new List<string>();

        var index = _forwardList.FindIndex(x => x == item);
        if (index != -1)
            _forwardList.Insert(index + 1, value);
        else
            _forwardList.Add(value);

        if (_forwardList.Count > _maxListSize)
            _forwardList.RemoveRange(_maxListSize, _forwardList.Count - _maxListSize);
    }

    private async Task LoadAsync()
    {
        if (File.Exists(_binaryFileKey))
        {
            using var fileStream = File.OpenRead(_binaryFileKey);
            using var cryptoStream = new CryptoStream(fileStream, _aes.CreateDecodeStream(), CryptoStreamMode.Read);
            var serializer = new BinaryFormatter();
            _cachedData = (T[])serializer.Deserialize(cryptoStream);
        }
        else
        {
            _cachedData = LoadFromDatabase();
            SaveToFileAndDatabase();
        }
    }

    private T[] LoadFromDatabase()
    {
        // Implement loading from the database and return the data as an array of T
    }

    private void SaveToFileAndDatabase()
    {
        var serializer = new BinaryFormatter();
        using (var fileStream = File.Create(_binaryFileKey))
        using (var cryptoStream = new CryptoStream(fileStream, _aes.CreateEncodeStream(), CryptoStreamMode.Write))
            serializer.Serialize(cryptoStream, _cachedData);

        // Implement saving to the database here
    }

    public void Initialize()
    {
        Task.Factory.StartNew(LoadAsync, CancellationToken.None, TaskCreationOptions.LongRunning, TaskScheduler.Default);
        Task.Delay(_cacheRefreshInterval).ContinueWith(t => Initialize(), TaskContinuationOptions.NotOnCanceled);
    }
}
