public class CacheManagerTests<T>
{
    private readonly Mock<IConfiguration> _configurationMock;
    private readonly CacheManager<T> _cacheManager;

    public CacheManagerTests()
    {
        _configurationMock = new Mock<IConfiguration>();
        _cacheManager = new CacheManager<T>(_configurationMock.Object);
    }

    [Fact]
    public void AddToForwardList_AddsItemCorrectly()
    {
        // Arrange
        var forwardList = new List<string> {"item1", "item2"};
        _cacheManager._forwardList = forwardList;

        // Act
        _cacheManager.AddToForwardList("item1", "newValue");

        // Assert
        Assert.Equal(new[] { "item1", "newValue", "item2" }, _cacheManager._forwardList.ToArray());
    }

    [Fact]
    public async Task LoadAsync_LoadsDataFromFile()
    {
        // Arrange
        var data = new List<T> { default!, new T(), default! };
        _configurationMock.Setup(x => x["BinaryFileKey"]).Returns("testFile");
        _cacheManager._cachedData = data.ToArray();
        var expected = JsonConvert.SerializeObject(data);
        File.WriteAllText("testFile", expected);

        // Act
        await _cacheManager.LoadAsync();

        // Assert
        CollectionAssert.AreEqual(_cacheManager._cachedData, data.ToArray());
    }

    [Fact]
    public async Task LoadAsync_LoadsDataFromDatabaseIfFileIsMissing()
    {
        // Arrange
        _configurationMock.Setup(x => x["BinaryFileKey"]).Returns("testFile");
        File.Delete("testFile");
        var data = new List<T> { default!, new T(), default! };
        _cacheManager._cachedData = null;
        var expected = JsonConvert.SerializeObject(data);
        // Mock the LoadFromDatabase method to return the data as an array of T
        _cacheManager._configurationMock.Setup(x => x["MaxListSize"]).Returns(10);

        // Act
        await _cacheManager.LoadAsync();

        // Assert
        CollectionAssert.AreEqual(_cacheManager._cachedData, data.ToArray());
    }
}
