                if (!response.isSuccessful()) {
                    // Handle error cases...
                } else {
                    WeatherDataResponse weatherData = response.body();
                    boolean isFromCache = weatherCache.asMap().containsKey(call.request().urlString());

                    if (isFromCache) {
                        cacheHits++;
                    } else {
