/* Function to dynamically generate a state list for a given FSA */
void* gen_state_list(FSA* fsa, int states[], int num_states, int last_state) {
    if (!validate_input(fsa, states, num_states, last_state)) return NULL;

    /* Memory allocation for the new state list */
    int* new_states = (int*)malloc((last_state - num_states + 1) * sizeof(int));
    if (!new_states) {
        custom_error("Memory exhaustion");
        return NULL;
    }

    /* Initialize the new state list */
    memset(new_states, 0, (last_state - num_states + 1) * sizeof(int));

    /* Update the 'next' pointer of the last state in the original list */
    states[last_state] = &new_states[num_states];

    /* Implement your logic for generating the new state list here */

    return new_states;
}

/* Thread-safe wrapper for gen_state_list() */
void* safe_gen_state_list(FSA* fsa, int states[], int num_states, int last_state) {
    semaphore_t lock;
    sem_init(&lock, 0, 1);
    void* result = gen_state_list(fsa, states, num_states, last_state);
    sem_destroy(&lock);
    return result;
}
