```rust
use std::fs::{File, OpenOptions};
use std::io::{BufRead, BufReader};
use std::process::Command;

pub async fn generate_llvm(file_path: &str) -> String {
    let file = File::open(file_path).unwrap();
    let reader = BufReader::new(file);

    println!("Input File:\n");
    for line in reader.lines() {
        match line {
            Ok(line) => println!("{}", line),
            Err(e) => eprintln!("Error reading file: {}", e),
        }
    }

    let mut cmd = Command::new("lexer");
    cmd.arg(file_path);
    let output = cmd.output().await.unwrap();

    if !output.status.success() {
        eprintln!("Error running lexer: {}", String::from_utf8_lossy(&output.stderr));
        return String::new();
    }

    let mut cmd = Command::new("parser");
    cmd.arg(file_path);
    cmd.arg("-o".to_string());
    cmd.arg("ir.ll");
    let output = cmd.output().await.unwrap();

    if !output.status.success() {
        eprintln!("Error running parser: {}", String::from_utf8_lossy(&output.stderr));
        return String::new();
    }

    let mut file = OpenOptions::new()
                      .write(true)
                      .create(true)
                      .open("ir.ll")
                      .unwrap();
    file.write_all(&output.stdout).unwrap();

    std::fs::read_to_string("ir.ll").unwrap()
}
