    CURLcode res = curl_easy_setopt(metadata_curl, CURLOPT_URL, task->filename);
    if (res != CURLE_OK) {
        printf("Error fetching metadata for %s: %s\n", task->filename, curl_easy_strerror(res));
        return NULL;
    }

    res = curl_easy_perform(metadata_curl);
    if (res != CURLE_OK) {
