    snprintf(buf, sizeof(buf), "convert %s %s/output.pdf", task->filename, task->output_dir);
    system(buf);

    return NULL;
}

void process_tasks() {
    task_t tasks[MAX_TASKS];
    int num_tasks = 0;

    // Read input parameters and populate the tasks array here

    for (int i = 0; i < num_tasks; ++i) {
        sem_wait(&sem_concurrency_limit);
        sem_wait(&sem_tasks);
        tasks[num_tasks] = tasks[i];
        pthread_t thread;
        pthread_create(&thread, NULL, convert_image, &tasks[num_tasks]);
        num_tasks++;
    }

    for (int i = 0; i < num_tasks; ++i) {
        pthread_join(thread, NULL);
    }
}

