import org.slf4j.*;
import feign.*;
import feign.hystrix.*;
import software.amazon.aws.sdk.metrics.*;

public class OrderProcessor {
  private static final Logger LOGGER = LoggerFactory.getLogger(OrderProcessor.class);
  private static final MetricStore metricsStore = MetricStore.standard();
  private static final String API_TOKEN;
  private static final ServiceService serviceService;
  private static final OrderValidation orderValidation;
  private static final CircutBreaker<Exception> circuitBreaker = HystrixCommand.Factory.build(
      Setter.withGroupKey(HystrixGroupKey.Factory.asKey("OrderProcessor"))
          .andCommandPropertiesDefaults(
              HystrixCommandProperties.Setter()
                  .withCircuitBreakerRequestVolumeThreshold(10)
                  .withCircuitBreakerErrorPercentThreshold(50)
                  .withCircuitBreakerSleepWindowInMilliseconds(5000))
          .andFallback(FallbackOrderProcessor::process));

  static {
    API_TOKEN = System.getenv("API_TOKEN");
    serviceService = Feign.builder()
        .logLevel(Logger.Level.FULL)
        .decoder(new JacksonDecoder())
        .encoder(new JacksonEncoder())
        .feignClientTimeout(30, TimeUnit.SECONDS)
        .target(ServiceService.class, "http://service-url");
  }

  public static void processOrder(String orderId, List<String> productIds, int[] quantities) {
    Preconditions.checkNotNull(orderId);
    Preconditions.checkArgument(!orderId.isEmpty());
    Preconditions.checkNotNull(productIds);
    Preconditions.checkState(!productIds.isEmpty());
    Preconditions.checkNotNull(quantities);
    Preconditions.checkState(quantities.length == productIds.size());

    OrderValidationResult result = orderValidation.validateOrder(orderId, productIds, quantities);
    if (!result.isValid()) {
      LOGGER.error("Invalid order: {}", result.getMessage());
      return;
    }

    ServiceResponse<Boolean> inventoryCheck = serviceService.checkInventoryAndCredit(API_TOKEN, orderId, productIds, quantities);
    if (!inventoryCheck.isSuccessful() || !inventoryCheck.getBody()) {
      LOGGER.error("Insufficient inventory or financial credits to fulfill the order.");
      return;
    }

    ExecutorService executor = Executors.newSingleThreadExecutor();
    try (executor) {
      Callable<Void> updateOrderTask = () -> {
        serviceService.updateInventoryAndCredit(API_TOKEN, orderId, productIds, quantities);
        return null;
      };

      Future<Void> future = executor.submit(updateOrderTask);
      future.get(5, TimeUnit.SECONDS); // Wait for the task to complete within 5 seconds or throw an exception
    } catch (ExecutionException | InterruptedException | TimeoutException e) {
      LOGGER.error("Error while updating inventory and financial records: {}", e.getMessage());
      retryAndBackoff(updateOrderTask, API_TOKEN);
    }

    NotifyUserService.sendOrderStatusNotification(orderId, "Processing");
    metricsStore.putMetricData(new DimensionDatumPair("OrderProcessor", orderId), new DimensionDatumPair("Action", "Process"));
  }

  private static void retryAndBackoff(Callable<Void> task, String apiToken) {
    int retries = 3;
    long backoff = 1000L; // 1 second initial backoff

    circuitBreaker.getThreadPoolExecutor().execute(() -> {
      while (retries > 0) {
        try {
          task.call();
          break;
        } catch (Exception e) {
          LOGGER.error("Retry attempt failed: {}", e.getMessage());
          if (--retries == 0) {
            throw new RuntimeException(e);
          }
          backoff *= 2L; // Doubling the backoff for each retry attempt
          try {
            Thread.sleep(backoff);
          } catch (InterruptedException ignored) {}
        }
      }
    });
  }
}

public record OrderValidationResult(boolean isValid, String message) { /* Implement your validation logic here */ }

