interface ServiceService {
  @PostMapping("/checkInventoryAndCredit")
  ServiceResponse<Boolean> checkInventoryAndCredit(@Param("apiToken") String apiToken, @Param("orderId") String orderId, @Param("productIds") List<String> productIds, @Param("quantities") int[] quantities);

  @PostMapping("/updateInventoryAndCredit")
  ServiceResponse<Void> updateInventoryAndCredit(@Param("apiToken") String apiToken, @Param("orderId") String orderId, @Param("productIds") List<String> productIds, @Param("quantities") int[] quantities);
}
