using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace YourNamespace
{
    public class HashUtility
    {
        private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(10); // Limit concurrent hash operations to 10
        private readonly Encoding _encoding = Encoding.UTF8;
        private readonly MD5 _md5Hasher = MD5.Create();

        public async Task<string> GetMD5Hash(string input)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentNullException(nameof(input));

            await _semaphore.WaitAsync();

            try
            {
                byte[] inputBytes = _encoding.GetBytes(input);
                byte[] hash = _md5Hasher.ComputeHash(inputBytes);
                return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
            }
            finally
            {
                _semaphore.Release();
            }
        }

        public bool ValidateHashAgainstSalt(string input, string saltValue, string hashedValueWithSalt)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentNullException(nameof(input));

            if (string.IsNullOrEmpty(saltValue))
                throw new ArgumentNullException(nameof(saltValue));

            if (string.IsNullOrEmpty(hashedValueWithSalt))
                throw new ArgumentNullException(nameof(hashedValueWithSalt));

            byte[] saltBytes = _encoding.GetBytes(saltValue);
            byte[] hashedInputBytes = Convert.FromBase64String(hashedValueWithSalt);

            using (var hmac = new HMACMD5(saltBytes))
            {
                byte[] computedHash = hmac.ComputeHash(_encoding.GetBytes(input));

                for (int i = 0; i < computedHash.Length && i < hashedInputBytes.Length; ++i)
                {
                    if (computedHash[i] != hashedInputBytes[i])
                        return false;
                }

                return true;
            }
        }
    }
}
