from io import BytesIO

class ChunkedReader:
    def __init__(self, file, chunk_size=8192):
        self.file = file
        self.chunk_size = chunk_size
        self.position = 0

    def read(self, size=None):
        data = self.file.read(self.chunk_size) if not size else self.file.read(size)
        self.position += len(data)
        return data

    @property
    def is_end(self):
        return self.position >= self.file.seek(0, os.SEEK_END)

