<?php

class Authenticator {
    private $providers = ['google', 'facebook', 'github'];
    private $tokenStorageService;

    public function __construct(TokenStorageService $tokenStorageService) {
        $this->tokenStorageService = $tokenStorageService;
    }

    public function authenticate($provider, $request) {
        try {
            $authenticationUrl = $this->getAuthenticationUrl($provider);
            header('Location: ' . $authenticationUrl);
            exit(); // Redirect to the authentication URL
        } catch (Exception $e) {
            echo "Error: " . $e->getMessage();
            return;
        }

        if ($this->hasSessionStarted()) {
            $accessToken = $this->tokenStorageService->getAccessToken();
            if (!empty($accessToken)) {
                // User is already authenticated and has an active session
                echo "You are logged in.";
                return;
            }
        }

        $callbackUrl = $_SERVER['REQUEST_URI']; // Use the current URI as callback URL for OAuth providers

        $state = bin2hex(random_bytes(16)); // Generate a random state token to prevent CSRF attacks
        session_start();
        $_SESSION['oauth2_state'] = $state;

        $queryParams = array('response_type' => 'code', 'client_id' => $this->getClientId($provider), 'redirect_uri' => rawurlencode($callbackUrl), 'state' => $state);

        foreach (['scope1', 'scope2'] as $scope) { // Add scopes if required by the provider
            $queryParams[$scope] = 'true';
        }

        $authenticationUrl = $this->getAuthenticationUrl($provider) . '?' . http_build_query($queryParams);
        header('Location: ' . $authenticationUrl);
        exit(); // Redirect to the authentication URL
    }

    private function getAuthenticationUrl($provider) {
        switch ($provider) {
            case 'google':
                return 'https://accounts.google.com/o/oauth2/v2/auth';
            case 'facebook':
                return 'https://www.facebook.com/v10.0/dialog/oauth';
            case 'github':
                return 'https://github.com/login/oauth/authorize';
        }
    }

    private function getClientId($provider) {
        switch ($provider) {
            case 'google':
                // Replace with your Google client ID
                return 'YOUR_GOOGLE_CLIENT_ID';
            case 'facebook':
                // Replace with your Facebook App ID
                return 'YOUR_FACEBOOK_APP_ID';
            case 'github':
                // Replace with your GitHub client ID
                return 'YOUR_GITHUB_CLIENT_ID';
        }
    }

    private function hasSessionStarted() {
        if (session_id() == '') {
            session_start();
        }
        return session_status() === PHP_SESSION_ACTIVE;
    }
}

