    // Replace this with your own implementation for handling network shares
    public interface IFileReader
    {
        Stream OpenRead(string filePath);
    }

    public class FileReader : IFileReader
    {
        private readonly string _networkShare;

        public FileReader(string networkShare)
        {
            _networkShare = networkShare;
        }

        public Stream OpenRead(string fileName)
        {
            return new NetworkStream(new FileStream(_networkShare + "/" + fileName, FileMode.Open), fileAccess: FileAccess.Read);
        }
    }

    public class DeserializationService
    {
        private readonly IFileReader _fileReader;

        public DeserializationService(IFileReader fileReader)
        {
            _fileReader = fileReader;
        }

        private async Task<T> DeserializeAsync<T>(Stream stream)
        {
            var formatter = new BinaryFormatter();
            await using (stream)
            {
                FileMetadata metadata;
                try
                {
                    metadata = (FileMetadata)formatter.Deserialize(stream);
                }
                catch (SerializationException ex)
                {
                    throw new DeserializationException("Corrupted file.", ex);
                }

                Type dataType = metadata.DataType;
                if (!typeof(NetworkData).IsAssignableFrom(dataType))
                {
                    throw new ArgumentException($"Unexpected data type: {dataType.Name}");
                }

                try
                {
                    return (T)formatter.Deserialize(stream);
                }
                catch (SerializationException ex)
                {
                    throw new DeserializationException("Failed to deserialize data.", ex);
                }
            }
        }

        public async Task<T> LoadDataAsync<T>(string filePath)
        {
            Stream stream = _fileReader.OpenRead(filePath);
            return await DeserializeAsync<T>(stream);
        }
    }

    public sealed class DeserializationException : Exception
    {
        public DeserializationException()
        {
        }

        public DeserializationException(string message) : base(message)
        {
        }

        public DeserializationException(string message, Exception innerException) : base(message, innerException)
        {
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            if (args.Length < 1)
            {
                Console.WriteLine("Usage: LoadData.exe <filePath>");
                return;
            }

            var fileReader = new FileReader(@"\\network-share\data");
            var deserializationService = new DeserializationService(fileReader);

            try
            {
                dynamic result = await deserializationService.LoadDataAsync<dynamic>(args[0]);

                Console.WriteLine($"Loaded data of type: {result.GetType().Name}");
                // Print the properties or fields of the loaded object as appropriate
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error occurred during deserialization process.");
                Console.WriteLine(ex.Message);
            }
        }
    }
}
