#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <time.h>

// Device structure definition
typedef struct Device {
    char name[64];
    struct in_addr ip;
    unsigned short port;
    struct ConfigSettings *settings;
} Device;

// ConfigSettings structure definition
typedef struct ConfigSettings {
    unsigned long bandwidth_limit;
    unsigned char priority_level;
    void (*callback)(struct ConfigSettings*);
} ConfigSettings;

// External logging function (replace with your logging implementation)
void log(const char *message);

// Timeout-safe callback function wrapper
typedef struct CallbackWrapper {
    void (*func)(struct ConfigSettings*);
    struct timespec timeout; // nanoseconds
} CallbackWrapper;

int process_devices(Device **devices, size_t count) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (!devices || !count) return EINVAL; // Invalid device list

    for (size_t i = 0; i < count; ++i) {
        Device *device = devices[i];

        if (!device->ip.s_addr || ntohl(device->ip.s_addr) == INADDR_LOOPBACK) return EINVAL; // Invalid IP address
        if (device->port < 1 || device->port > 65535) return EINVAL; // Invalid port number
        if (!device->settings) return EINVAL; // Missing configuration settings
    }

    for (size_t i = 0; i < count; ++i) {
        Device *device = devices[i];

        CallbackWrapper cb_wrapper = {.func = device->settings->callback};
        cb_wrapper.timeout = (struct timespec){.tv_sec = 5, .tv_nsec = 0}; // Timeout after 5 seconds

        pthread_t thread;
        int rc = pthread_create(&thread, NULL, process_device_callback, &cb_wrapper);
        if (rc) {
            log("Error: Failed to create a processing thread.");
            return rc;
        }

        // Join the processing thread before moving on to the next device
        pthread_join(thread, NULL);
    }

    return 0;
}

void *process_device_callback(void *arg) {
    CallbackWrapper *cb_wrapper = arg;
    struct timespec remaining = cb_wrapper->timeout;

    while (remaining.tv_sec > 0 || remaining.tv_nsec > 0) {
        // Call the callback function if it's not already running
        if (!cb_wrapper->func) break;

        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);

        if (current_time.tv_sec - cb_wrapper->timeout.tv_sec +
            current_time.tv_nsec - cb_wrapper->timeout.tv_nsec >= 0) {
            log("Error: Callback function execution timed out.");
            break;
        }

        usleep(1000000); // Sleep for 1 second to give the callback function some time to run
    }

    if (cb_wrapper->func) cb_wrapper->func(cb_wrapper->settings);

    return NULL;
}

