using Microsoft.Extensions.Logging;

namespace GameConfigManager
{
    public class ConfigurationManager
    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<ConfigurationManager> _logger;
        private readonly Stack<IDictionary<string, string>> _configStacks;
        private readonly IServiceScopeFactory _serviceScopeFactory;

        public ConfigurationManager(IConfiguration configuration, ILogger<ConfigurationManager> logger, IServiceScopeFactory serviceScopeFactory)
        {
            _configuration = configuration;
            _logger = logger;
            _configStacks = new Stack<IDictionary<string, string>>();
            _serviceScopeFactory = serviceScopeFactory;
        }

        public void LoadConfiguration(string configFile)
        {
            try
            {
                var xmlSettings = XDocument.Load(configFile);
                var settings = new Dictionary<string, string>();

                foreach (var element in xmlSettings.Root.Elements())
                {
                    if (!settings.ContainsKey(element.Name.LocalName))
                        settings[element.Name.LocalName] = string.Empty;

                    settings[element.Name.LocalName] = element.Value;
                }

                _configStacks.Push(settings);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to load configuration file.");
            }
        }

        public void LoadConfigurationsSequentially(string[] configFiles)
        {
            foreach (var file in configFiles)
                LoadConfiguration(file);
        }

        public IDictionary<string, string> CurrentSettings => _configStacks.Peek();

        public void ApplyChanges()
        {
            using var scope = _serviceScopeFactory.CreateScope();
            var configurationValidator = scope.ServiceProvider.GetRequiredService<IConfigurationValidator>();

            if (!configurationValidator.Validate(CurrentSettings))
            {
                _logger.LogError("Invalid configuration settings detected.");
                return;
            }

            // Implement game environment configuration application logic here
        }
    }

    public interface IConfigurationValidator
    {
        bool Validate(IDictionary<string, string> settings);
    }

