    {
        private readonly string _connectionString;

        public DatabaseConfigSerializer(string connectionString) => _connectionString = connectionString;

        public void Serialize(IDictionary<string, string> settings)
        {
            // Implement serialization to the database here
        }

        public IDictionary<string, string> Deserialize()
        {
            // Implement deserialization from the database here
            throw new NotImplementedException();
        }
    }
}
