using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Xunit;

namespace DecryptionClass
{
    public class DecryptionService
    {
        private readonly byte[] _aesKey;
        private readonly byte[] _aesIV;
        private readonly AesMode _decryptionMode;

        public DecryptionService(AesKeyGenerationMethod keyGenMethod = AesKeyGenerationMethod.Rfc2898DeriveBytes,
                                AesIvGenerationMethod ivGenMethod = AesIvGenerationMethod.RandomNumberGenerator)
        {
            _aesKey = keyGenMethod switch
            {
                AesKeyGenerationMethod.Default => new byte[32], // Default 256 bit key
                AesKeyGenerationMethod.Rfc2898DeriveBytes => Rfc2898DeriveBytes.GenerateKey(),
                _ => throw new ArgumentException($"Invalid {nameof(AesKeyGenerationMethod)}: {keyGenMethod}")
            };

            _aesIV = ivGenMethod switch
            {
                AesIvGenerationMethod.Default => new byte[16], // Default 128 bit IV
                AesIvGenerationMethod.RandomNumberGenerator => new RNGCryptoServiceProvider().GetBytes(16),
                _ => throw new ArgumentException($"Invalid {nameof(AesIvGenerationMethod)}: {ivGenMethod}")
            };

            _decryptionMode = AesMode.Cbc; // Default decryption mode is CBC
        }

        public DecryptionService(byte[] aesKey, byte[] aesIV, AesMode decryptionMode)
        {
            _aesKey = aesKey;
            _aesIV = aesIV;
            _decryptionMode = decryptionMode;
        }

        public DecryptionService SetDecryptionMode(AesMode mode) => new DecryptionService(_aesKey, _aesIV, mode);

        public byte[] DecryptCbc(byte[] cipherText, out byte[] originalPlaintextLength)
        {
            using (var aes = Aes.Create())
            {
                aes.Key = _aesKey;
                aes.IV = _aesIV;
                var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

                using (var msCipherText = new MemoryStream(cipherText))
                using (var cs = new CryptoStream(msCipherText, decryptor, CryptoStreamMode.Read))
                {
                    var plaintextWithPadding = new byte[cs.ReadByte()]; // Read the original plaintext length
                    using (var msPlaintext = new MemoryStream(plaintextWithPadding))
                    {
                        cs.CopyTo(msPlaintext);
                        originalPlaintextLength = BitConverter.GetBytes((int)msPlaintext.Length)[0]; // Strip off the padding and store the original plaintext length
                        return msPlaintext.ToArray();
                    }
                }
            }
        }

        public byte[] DecryptGcm(byte[] cipherText, byte[] authenticationTag)
        {
            using (var aes = Aes.Create())
            {
                aes.Key = _aesKey;
                aes.IV = _aesIV;

                var decryptor = aes.CreateDecryptor(); // GCM doesn't require an explicit IV, it uses authentication tag
                using (var gcm = new GcmBlockCipher(decryptor) { AuthenticationTag = authenticationTag })
                using (var msCipherText = new MemoryStream(cipherText))
                using (var cs = new CryptoStream(msCipherText, gcm, CryptoStreamMode.Read))
                {
                    return gcm.DoFinal();
                }
            }
        }

        public class AesKeyGenerationMethod
        {
            public static readonly AesKeyGenerationMethod Default = null;
            public static readonly AesKeyGenerationMethod Rfc2898DeriveBytes = null;
        }

        public class AesIvGenerationMethod
        {
            public static readonly AesIvGenerationMethod Default = null;
            public static readonly AesIvGenerationMethod RandomNumberGenerator = null;
        }
    }

    public enum AesMode { Cbc, Gcm }

    public class DecryptionServiceTests
    {
        [Fact]
        public void TestDecryptCbc()
        {
            // Arrange
            var cipherText = ...; // Provide ciphertext for testing
            var originalPlaintext = Encoding.UTF8.GetBytes("Hello, World!");
            var expectedPlaintextWithPadding = ...; // Calculate the padded plaintext length and provide it for testing

            using (var aes = Aes.Create())
            {
                aes.Key = _aesKey;
                aes.IV = _aesIV;
                var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

                using (var msPlaintext = new MemoryStream(originalPlaintext))
                using (var cs = new CryptoStream(msPlaintext, encryptor, CryptoStreamMode.Write))
                using (var msCipherText = new MemoryStream())
                {
                    cs.CopyTo(msCipherText);
                    var cipherTextForTesting = msCipherText.ToArray(); // Get the ciphertext for testing
                    Assert.Equal(cipherText, cipherTextForTesting);
                }
            }

            // Act & Assert
            var decryptedPlaintext = new DecryptionService().DecryptCbc(cipherText, out byte[] originalPlaintextLength);
            Assert.Equal(originalPlaintextWithPadding, originalPlaintextLength);
            Assert.Equal(originalPlaintext, decryptedPlaintext);
        }

        [Fact]
        public void TestDecryptGcm()
        {
            // Arrange
            var cipherText = ...; // Provide ciphertext for testing
            var originalPlaintext = Encoding.UTF8.GetBytes("Hello, World!");
            var authenticationTag = ...; // Provide the authentication tag for testing

            using (var aes = Aes.Create())
            {
                aes.Key = _aesKey;
                aes.IV = _aesIV;
                var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

                using (var msPlaintext = new MemoryStream(originalPlaintext))
                using (var cs = new CryptoStream(msPlaintext, encryptor, CryptoStreamMode.Write))
                {
                    using (var msCipherText = new MemoryStream())
                    using (var gcm = new GcmBlockCipher(aes.CreateEncryptor()))
                    {
                        gcm.Init(true, authenticationTag); // Initialize the GCM for encryption
                        cs.CopyTo(msCipherText);
                        var cipherTextForTesting = msCipherText.ToArray(); // Get the ciphertext for testing
                        Assert.Equal(cipherText, cipherTextForTesting);

                        gcm.Init(false, authenticationTag); // Initialize the GCM for decryption
                        var decryptedPlaintext = gcm.DoFinal();
                        Assert.Equal(originalPlaintext, decryptedPlaintext);
                    }
                }
            }
        }
    }
}
