void process_logs() {
    struct stat st;
    char path[1024];
    DIR* dir;

    snprintf(path, sizeof(path), "./log/%Y-%m");
    dir = opendir(path);

    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir))) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        snprintf(path, sizeof(path), "./log/%Y-%m/%s", entry->d_name, entry->d_name);
        dir = opendir(path);

        if (!dir) continue;

        pthread_t thread_id;
        while ((entry = readdir(dir))) {
            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

            snprintf(path, sizeof(path), "./log/%Y-%m/%s/%s", entry->d_name, entry->d_name, entry->d_name);

            struct stat s;
            if (lstat(path, &s) == -1 || S_ISDIR(s.st_mode)) continue;

            pthread_create(&thread_id, NULL, (void*(*)(void*))parse_log, path);
        }
    }
}

void* parse_log(void* path) {
    FILE* file = fopen((char *)path, "r");

    if (!file) return NULL;

    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        // Call the parse_log function to process each line and update log_entries
    }

    fclose(file);
    return NULL;
}

void average_response_size() {
    double sum = 0.0, count = 0.0;

    pthread_mutex_lock(&log_entries_mutex);
    for (int i = log_entry_count - 2; i >= 0 && i < log_entry_count; --i) {
        sum += log_entries[i].size;
        count++;
    }
    pthread_mutex_unlock(&log_entries_mutex);

    if (count > 1) printf("Average response size: %.2f\n", sum / count);
}

int main() {
    while (1) {
        process_logs();
        average_response_size();
        sleep(1);
    }

    return 0;
}
