using System;
using System.Data;
using System.IO;
using System.IO.Compression;
using System.Net;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Diagnostics.Tracing;

public class CompressedDataSender
{
    private readonly EventSource _logger = new EventSource("CompressedDataSender", Guid.NewGuid());
    private readonly AsyncLocal<Stopwatch> _queryWatch, _transmissionWatch, _compressionWatch;

    public async Task<IDataReader> SendCompressedByteArrayAsync(byte[] data)
    {
        using (var memoryStream = new MemoryStream())
        {
            await using var compressedStream = new GzipStream(memoryStream, CompressionLevel.Optimal);
            await compressedStream.WriteAsync(data, 0, data.Length);

            _compressionWatch.Value.Stop();
            _logger.CompressionRatio((double)data.LongLength / memoryStream.Length).WriteEvent();
            _compressionWatch = AsyncLocal.Create(() => new Stopwatch());

            using (var networkStream = await WebRequest.Create("http://remote-database-server/api/compressedsave").GetResponseAsync().ConfigureAwait(false).GetResult().GetRequestStream())
            {
                await memoryStream.CopyToAsync(networkStream);

                _transmissionWatch.Value.Stop();
                _logger.TransmissionTime(_transmissionWatch.Value.ElapsedMilliseconds).WriteEvent();
                _transmissionWatch = AsyncLocal.Create(() => new Stopwatch());
            }

            using var reader = await Task.Run(async () =>
            {
                var response = await WebRequest.Create("http://remote-database-server/api/compressedquery").GetResponseAsync().ConfigureAwait(false).GetResult();
                using (var streamReader = new StreamReader(response.GetResponseStream()))
                {
                    _queryWatch.Value.Stop();
                    _logger.QueryExecutionTime(_queryWatch.Value.ElapsedMilliseconds).WriteEvent();
                    _queryWatch = AsyncLocal.Create(() => new Stopwatch());

                    return streamReader.ReadToEnd().AsDataReader();
                }
            }).ConfigureAwait(false);

            return reader;
        }
    }

    public void QueryExecutionTime(long elapsedMilliseconds)
    {
        _queryWatch.Value.Reset();
        _queryWatch.Value.Start();
    }

    public void CompressionRatio(double ratio)
    {
        _compressionWatch.Value.Reset();
        _compressionWatch.Value.Start();
    }

    public void TransmissionTime(long elapsedMilliseconds)
    {
        _transmissionWatch.Value.Reset();
        _transmissionWatch.Value.Start();
    }
