```rust
use std::fs::remove_file;
use std::io::{self, Write};
use std::path::Path;
use reqwest::Client;
use reqwest::header::{HeaderMap, HeaderValue};
use log::{LogFormatter, SetLoggerError, LogLevelFilter};
use log4rs::{append::console::Target, config::ConfigBuilder, root::Root};
use serde_json::json;
use chrono::{DateTime, Utc};

const LOG_FILE: &str = "log.txt";

fn disable_certificate_validation() -> bool {
    true
}

fn create_client(disable_cert_val: bool) -> Client {
    let mut headers = HeaderMap::new();
    headers.insert("User-Agent", HeaderValue::from_static("MyProgram/1.0"));

    reqwest::Client::builder()
        .default_headers(headers)
        .tickets(true)
        .danger_configuration()
        .build().unwrap().set_global_ssl_hostname_verifier(|_, _| true)
        .set_timeout(Some(reqwest::r#async::Timeout::new(10, reqwest::r#async::ConnectionTimeout::Any)))
        .set_redirect(reqwest::redirect::Policy::custom({
            |location| {
                match location.url().scheme() {
                    Some("https") => reqwest::redirect::Strategy::follow_no_max,
                    _ => reqwest::redirect::Strategy::none(),
                }
            }
        }))
        .on_error(move |e| {
            if let Err(e) = e {
                println!("Request error: {}", e);
                log!("Error: {}", e);
            }
        })
        .build().unwrap()
}

fn request_builder(client: &Client, url: &str) -> reqwest::blocking::RequestBuilder {
    client.get(url).disable_ssl_verification_if_host_is_invalid().build().expect("Error building request")
}

fn log(message: &str) {
    let format = |record| {
        writeln!(io::stderr(), "{} - [{}] {}", record.level(), Utc::now().format("%Y-%m-%d %H:%M:%S"), message).unwrap();
    };

    match log4rs::init_config()
            .append_console_target()
                .set_filter(log::LevelFilter::Info)
                .set_formatter(Box::new(LogFormatter::new()))
                .build().map(|_| ())
                .map_err(|e| println!("Error setting up logger: {}", e)) {
        Ok(_) => format(format!(r#"{}"#, message)),
        Err(e) => println!("Error setting up logger: {}", e),
    }
}

fn main() -> std::io::Result<()> {
    remove_file(Path::new(LOG_FILE)).ok();

    let client = create_client(disable_certificate_validation());
    let url = "https://example.com";
    let req = request_builder(&client, url).send()?;

    log!("Sending request to {}", url);

    if let Ok(response) = req.send() {
        response.content_type().and_then(|ct| ct.to_str()).map(|ct| log!("Content-Type: {}", ct)).unwrap();

        let mut body = String::new();
        let _ = response.read_to_string(&mut body)?;
        log!("Response Body:\n{}", &body);
    } else {
        log!("Error sending request.");
    }

    Ok(())
}
```

This code creates an HTTP client, builds a `RequestBuilder`, and sends the request to the specified URL. If the request is successful, it logs the Content-Type header and response body. The logging function is coherent and integrated into the overall structure of the Rust program using log4rs. Additionally, the program checks for and deletes a log file before sending the HTTP request.

