        private readonly RequestDelegate _next;
        private readonly ICmsService _cmsService;
        private readonly CacheStrategy _cacheStrategy;

        public CmsContentMiddleware(RequestDelegate next, ICmsService cmsService, CacheStrategy cacheStrategy)
        {
            _next = next;
            _cmsService = cmsService;
            _cacheStrategy = cacheStrategy;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            if (context.Request.Method == HttpMethods.Post && context.Request.HasFormContentType)
            {
                var pageSectionId = context.Request.Form["pageSectionId"];
                var elementId = context.Request.Form["elementId"];
                var content = context.Request.Form["content"];

                if (string.IsNullOrEmpty(pageSectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(content))
                {
                    await SendErrorResponseAsync(context, "Missing required parameters.");
                    return;
                }

                var cachedContent = _cacheStrategy.Get(pageSectionId + elementId);

                if (cachedContent != null)
                {
                    await context.Response.WriteAsync(cachedContent);
                }
                else
                {
                    var decryptedContent = await FetchAndDecryptContentAsync(_cmsService, pageSectionId, elementId);
                    await context.Response.WriteAsync(decryptedContent);
                    _cacheStrategy.Set(pageSectionId + elementId, decryptedContent);
                }
            }
            else
            {
                await _next(context);
            }
        }

        private async Task SendErrorResponseAsync(HttpContext context, string errorMessage)
        {
            context.Response.ContentType = "application/json";
            context.Response.StatusCode = (int)HttpStatusCode.BadRequest;
            await context.Response.WriteAsync(errorMessage);
        }

