import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.your_api_library.PokemonApiClient; // replace with the actual library name and imports
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap; // for caching mechanism
import java.util.stream.Collectors;
import java.util.ArrayList;

public class PokemonWeaknesses {
    private static final Logger LOGGER = LoggerFactory.getLogger(PokemonWeaknesses.class);
    private static final Map<String, ArrayList<String>> cache = new ConcurrentHashMap<>(); // for caching mechanism

    public String getPokemonWeaknesses(Pokemon pokemon) {
        try {
            String pokemonType = PokemonApiClient.getPokemonType(pokemon.getId()); // replace with actual API call
            if (cache.containsKey(pokemonType)) {
                return cache.get(pokemonType).stream().collect(Collectors.joining(", "));
            }

            String weaknesses = switch (pokemonType) {
                case "Fire" -> "Water, Ground";
                case "Water" -> "Electric, Grass";
                case "Grass" -> "Poison, Fire, Flying";
                case "Electric" -> "Ground";
                case "Ice" -> "Fighting, Rock, Steel";
                case "Fighting" -> "Fairy";
                case "Poison" -> "Ground, Psychic";
                case "Ground" -> "Water, Grass, Ice, Electric";
                case "Rock" -> "Water, Grass";
                case "Flying" -> "Electric, Rock";
                case "Psychic" -> "Bug, Ghost, Dark";
                case "Bug" -> "Fighting, Flying, Fire, Psychic";
                case "Ghost" -> "Dark";
                case "Dragon" -> "Ice, Dragon";
                case "Dark" -> "Psychic, Fairy";
                case "Steel" -> "Fire"; // Steel Pokemon do not have weaknesses against other types
                default -> throw new IllegalStateException("Invalid Pokemon Type: " + pokemonType);
            };

            cache.putIfAbsent(pokemonType, new ArrayList<>(Arrays.asList(weaknesses.split(","))));
            return weaknesses;
        } catch (Exception e) {
            LOGGER.error("Error while retrieving Pokemon's type or weaknesses", e);
            throw new RuntimeException("Failed to retrieve Pokemon's weaknesses", e);
        }
    }
}
