```rust
use reqwest::Client;
use serde_derive::Deserialize;
use std::collections::HashMap;
use std::env;
use tokio::sync::RwLock;
use url::Url;

type Cache = RwLock<HashMap<String, serde_json::Value>>;

#[derive(Deserialize)]
struct ApiData { /* Define the structure based on your API response */ }

async fn fetch_data<T: Deserialize>(client: &Client, url: Url) -> Result<T, reqwest::Error> {
    let resp = client.get(url).send().await?.json::<T>()?;
    Ok(resp)
}

fn get_cached_data(cache: &Cache, key: &str) -> Option<serde_json::Value> {
    cache.read().map(|m| m.get(key).cloned())
}

async fn put_cached_data(cache: &mut Cache, key: String, value: serde_json::Value) {
    let mut map = cache.write().unwrap();
    map.insert(key, value);
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let api_url = Url::parse(env::args().nth(1).unwrap())?;
    let method = env::args().nth(2)?;
    let params: HashMap<String, String> = env::args().skip(3)
                            .zip(std::iter::repeat("="))
                            .map(|(k, v)| (k, v.next().unwrap_or("")))
                            .collect();

    let client = Client::new();
    let cache = Cache::new(HashMap::new());

    match (method.as_str(), params.get("endpoint")) {
        ("get", Some(ep)) => {
            let key = format!("{}-{}", method, ep);
            if let Some(data) = get_cached_data(&cache, &key) {
                println!("{:?}", data);
            } else {
                match fetch_data::<ApiData>(&client, api_url.join(ep).unwrap())
                     .await {
                    Ok(resp) => {
                        put_cached_data(&mut cache, key, serde_json::to_value(resp)?);
                        println!("{:?}", resp);
                    }
                    Err(err) => {
                        eprintln!("Error fetching data: {}", err);
                    }
                }
            }
        },
        ("post", Some(_)) | _ => {
            eprintln!("Invalid request. Please use the following format:\n\t./program API_URL GET/POST [endpoint] [params...]");
            std::process::exit(1);
        }
    }

    Ok(())
}
```

