#include "cloud_storage.h"
#include "parsing_rules.h"

void parse_config(const char* config_file, json_object** parsed_config);
void read_log_from_cloud(const char* input_file, cloud_storage_t* storage, off_t* file_size);
void write_output_to_cloud(const char* output_file, cloud_storage_t* storage, const void* data, size_t size);
bool apply_parsing_rules(const json_object* config, const void* input, size_t size, void** output);

int main(int argc, char** argv) {
    if (argc != 4) {
        printf("Usage: %s <config_file> <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    json_object* parsed_config = NULL;
    parse_config(argv[1], &parsed_config);

    cloud_storage_t input_cloud, output_cloud;
    off_t input_file_size;
    read_log_from_cloud(argv[2], &input_cloud, &input_file_size);

    void* input_data = malloc(input_file_size);
    read(input_cloud.fd, input_data, input_file_size);

    void* output_data = NULL;
    apply_parsing_rules(parsed_config, input_data, input_file_size, &output_data);

    write_output_to_cloud(argv[3], &output_cloud, output_data, sizeof(void*) + input_file_size);

    free(input_data);
    free(output_data);
    json_object_put(parsed_config);

    return 0;
}
