// Function prototypes
void readData(FILE*, void**);
bool isNumber(const char*);
void swap(void*, void*);
void freeArray(void**, size_t);

int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <file>\n", argv[0]);
        return 1;
    }

    FILE* file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return 2;
    }

    // Determine the data type of the first number read from the file.
    void* dataTypePointer = NULL;
    readData(file, &dataTypePointer);

    size_t numElements = 0;
    void** array = malloc(sizeof(void*) * numElements);
    if (!array) {
        perror("Error allocating memory for the array");
        fclose(file);
        return 3;
    }

    while (readData(file, &array[numElements])) {
        numElements++;
        array = realloc(array, sizeof(void*) * (numElements + 1));
        if (!array) {
            perror("Error resizing the array");
            freeArray(array, numElements);
            fclose(file);
            return 3;
        }
    }
    fclose(file);

    qsort(array, numElements, sizeof(void*), (int (*)(const void*, const void*))compareValues);

    printf("Largest value: ");
    if (isinf(*(float*)array[numElements - 1])) {
        printf("%f\n", *(float*)array[numElements - 1]);
    } else {
        printf("%d\n", *(int*)array[numElements - 1]);
    }

    freeArray(array, numElements);
    return 0;
}

bool isNumber(const char* str) {
    // Implement a function to check if the given string represents a valid number.
    // This implementation is simplified and may not handle all edge cases.
    // You can improve it according to your needs.
    int i = 0;
    bool hasPoint = false;

    if (*str == '-') i++;
    for (; str[i]; i++) {
        if (isdigit(str[i])) continue;
        switch (str[i]) {
            case '.':
                if (hasPoint || i == 0) return false;
                hasPoint = true;
                break;
            case 'e':
                if (i == 0) return false;
                if (!isdigit(str[i + 1])) return false;
                while (isdigit(str[++i]));
                if (str[i] != '+' && str[i] != '-') return false;
                i++;
                break;
            default:
                return false;
        }
    }
    return true;
}

void readData(FILE* file, void** dataPointer) {
    char line[1024];
    if (!fgets(line, sizeof(line), file)) return false;

    if (strlen(line) == sizeof(line) - 1) { // Check for newline character.
        printf("Warning: Truncated line in the input file.\n");
    }

    char* numberStart = line;
    while (*numberStart && *numberStart != '\n') numberStart++;
    if (!isNumber(line)) {
        fprintf(stderr, "Error: Invalid number '%s'.\n", line);
        return false;
    }

    // Allocate memory for the appropriate data type.
    float* numPointer = malloc(sizeof(float));
    if (!numPointer) {
        perror("Error allocating memory for a float");
        return false;
    }

    sscanf(line, "%f", numPointer);
    *dataPointer = numPointer;
    return true;
}

void swap(void* a, void* b) {
    void* temp = malloc(sizeof(*a));
    if (!temp) {
        perror("Error allocating temporary memory");
        abort(); // It's crucial to handle this case correctly.
    }
    memcpy(temp, a, sizeof(*a));
    memcpy(a, b, sizeof(*b));
    memcpy(b, temp, sizeof(*a));
    free(temp);
}

void freeArray(void** array, size_t numElements) {
    for (size_t i = 0; i < numElements; i++) {
        free(array[i]);
    }
    free(array);
}

int compareValues(const void* a, const void* b) {
    int diff;
    if (sizeof(*a) == sizeof(float)) {
        diff = (*(float*)b - *(float*)a);
    } else {
        diff = (*(int*)b - *(int*)a);
    }
    return diff > 0 ? 1 : (diff < 0 ? -1 : 0);
}
```

