class FinancialAPI:
    def __init__(self, api_name, base_url, rate_limit, retry_attempts):
        self.api_name = api_name
        self.base_url = base_url
        self.rate_limit = rate_limit
        self.retry_attempts = retry_attempts
        self.cache = redis.Redis()

    async def fetch_data(self, symbol, timeframe):
        cache_key = f"{self.api_name}:{symbol}:{timeframe}"
        cached_data = self.cache.get(cache_key)
        if cached_data:
            return json.loads(cached_data)

        url = f"{self.base_url}/{timeframe}/{symbol}"
        response = None
        for attempt in range(1, self.retry_attempts + 1):
            try:
                response = requests.get(url)
                if response.status_code == 200:
                    break
            except Exception as e:
                print(f"Error fetching data from {self.api_name}: {e}")
                await asyncio.sleep(timedelta(seconds=attempt * 5))

        if response and response.status_code == 200:
            self.cache.setex(cache_key, 600, response.content)
            return json.loads(response.content)
        else:
            raise Exception(f"Failed to fetch data from {self.api_name}")

class StockDataProcessor:
