                     FinancialAPI("Bloomberg", "https://api.bloomberg.com/markets/", 200, 4)]
        self.executor = ThreadPoolExecutor(max_workers=10)
        self.cache = redis.Redis()

    async def process_data(self, symbols, timeframe):
        data_by_symbol = {}

        future_to_api = {}
        for api in self.apis:
            future = self.executor.submit(api.fetch_data, symbols[0], timeframe)
            future_to_api[future] = api
            for symbol in symbols[1:]:
                future = self.executor.submit(api.fetch_data, symbol, timeframe)
                future_to_api[future] = api

        await asyncio.gather(*future_to_api)

        for future, data in future_to_api:
            api = future_to_api[future].api_name
            data_by_symbol[api] = data['time_series']

