        }
        char cwd_str[PATH_MAX];
        strncpy(cwd_str, cwd.path, PATH_MAX - 1);
        cwd_str[PATH_MAX - 1] = '\0';

        if (strlen(path.path) + strlen(cwd_str) > max_size) {
            free(path.path);
            set_error_message("Path combined with current working directory exceeded the size limit.");
            return NULL;
        }

        path_join(&path, cwd_str);
    }

    char *resolved_path = resolve_symlink(path.path);
    if (resolved_path == NULL) {
        clean_up(&path);
        set_error_message("Failed to resolve symbolic link.");
        return NULL;
    }

    if (custom_cwd != NULL && strlen(custom_cwd) > 0) {
        PathData custom_dir = {strdup(custom_cwd), strlen(custom_cwd)};
        if (strlen(resolved_path) + custom_dir.len >= max_size) {
            free(resolved_path);
            clean_up(&custom_dir);
            set_error_message("Path combined with custom directory exceeded the size limit.");
            return NULL;
        }
        path_join(&custom_dir, resolved_path);
        free(resolved_path);
        resolved_path = malloc(custom_dir.len + 1);
        strcpy(resolved_path, custom_dir.path);
        clean_up(&custom_dir);
    }

    if (!is_valid_path(resolved_path, max_size, true)) {
        free(resolved_path);
        set_error_message("Invalid path.");
        return NULL;
    }

    return resolved_path;
}
