#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <semaphore.h>

/**
 * @brief Manages a semaphore for concurrent access to shared resources.
 *
 * @param name A unique identifier for the semaphore.
 * @param initial_value The starting value of the semaphore.
 */
semaphore_t* create_semaphore(const char* name, int initial_value) {
    semaphore_t* sem = malloc(sizeof(semaphore_t));
    if (!sem) {
        fprintf(stderr, "Failed to allocate memory for semaphore.\n");
        return NULL;
    }

    memset(sem, 0, sizeof(semaphore_t));

    if (sem_init(&sem->handle, 0, initial_value)) {
        fprintf(stderr, "Failed to initialize semaphore: %s\n", strerror(errno));
        free(sem);
        return NULL;
    }

    sem->name = name;
    sem->acquired = 0;
    sem->released = 0;

    return sem;
}

/**
 * @brief Acquires the semaphore if available.
 *
 * @param sem The managed semaphore to acquire.
 */
void acquire_semaphore(semaphore_t* sem) {
    if (sem_wait(&sem->handle)) {
        fprintf(stderr, "Failed to acquire semaphore: %s\n", strerror(errno));
    } else {
        sem->acquired++;
    }
}

/**
 * @brief Releases the semaphore.
 *
 * @param sem The managed semaphore to release.
 */
void release_semaphore(semaphore_t* sem) {
    if (sem->acquired > 0) {
        sem->released++;
        sem_post(&sem->handle);
        sem->acquired--;
    } else {
        fprintf(stderr, "Tried to release an unused semaphore: %s\n", sem->name);
    }
}

/**
 * @brief Deletes the semaphore and frees up resources.
 *
 * @param sem The managed semaphore to delete.
 */
void destroy_semaphore(semaphore_t* sem) {
    if (sem_destroy(&sem->handle)) {
        fprintf(stderr, "Failed to destroy semaphore: %s\n", strerror(errno));
    } else {
        free(sem);
    }
}
```

