const { exec, spawn } = require('child_process');
const axios = require('axios');
const os = require('os');
const util = require('util');
const { promisify } = require('util');
const winston = require('winston');
const rateLimit = require('express-rate-limit');

// Configuration
const maxConcurrentProcesses = 5;
const commandTimeout = 60000; // 1 minute timeout
const logFormat = { timestamp: true, label: 'shellExec' };
const logInstance = new (winston.createLogger)({
  transports: [new winston.transports.Console(logFormat)],
});
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute window
  max: maxConcurrentProcesses,
});

// Helper function to execute command synchronously using 'exec'
const execSync = util.promisify(exec);

// Helper function to execute command asynchronously using 'spawn'
async function spawnAsync(command, options) {
  const process = spawn(command, options);
  let output = '';

  process.stdout.on('data', (data) => {
    output += data;
  });

  process.stderr.on('data', (errorData) => {
    logInstance.error(`Command execution error: ${errorData}`);
  });

  process.on('close', (code) => {
    if (code === 0) {
      logInstance.info(`Command executed successfully`);
    } else {
      logInstance.error(`Command execution failed with code ${code}`);
    }
  });

  return new Promise((resolve, reject) => {
    process.on('error', reject);
    process.on('exit', resolve);
  }).then(() => output);
}

// Main function to securely execute a command and stream the output in real-time
async function execCommand(command, options = {}) {
  const { asyncMode = false } = options;

  try {
    limiter.check({}, (err) => {
      if (err) {
        logInstance.warn(`Rate limit exceeded`);
        throw err;
      }

      if (os.type() === 'Windows NT') {
        const commandArgs = command.split(' ');
        execSync(commandArgs[0], { cwd: process.cwd(), encoding: 'utf8' })
          .stderr.on('data', (errorData) => {
            logInstance.error(`Command execution error: ${errorData}`);
          })
          .timeout(commandTimeout)
          .then((result) => {
            if (asyncMode) {
              logInstance.info(`Command executed successfully`);
              return result;
            } else {
              logInstance.info(`Command executed and output streamed to the browser`);
            }
          })
          .catch((error) => {
            if (!asyncMode) {
              logInstance.error(`Command execution failed: ${error}`);
            }
            throw error;
          });
      } else {
        // For macOS and Linux, use 'spawnAsync' for asynchronous execution or execute synchronously if required
        const commandArgs = asyncMode ? [command] : [command.split(' ')];
        return asyncMode ? spawnAsync(commandArgs) : execSync(commandArgs[0], { cwd: process.cwd(), encoding: 'utf8' })
          .stderr.on('data', (errorData) => {
            logInstance.error(`Command execution error: ${errorData}`);
          })
          .timeout(commandTimeout)
          .then((result) => {
            if (!asyncMode) {
              logInstance.info(`Command executed and output streamed to the browser`);
              return result;
            } else {
              logInstance.info(`Command executed successfully`);
              return result;
            }
          })
          .catch((error) => {
            if (!asyncMode) {
              logInstance.error(`Command execution failed: ${error}`);
            }
            throw error;
          });
      }
    });
  } catch (err) {
    logInstance.error(`Error executing command: ${err.message}`);
    throw err;
  }
}
