import os
import sys
import subprocess
import time
import signal
import psutil
import json
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import timedelta
from urllib.parse import urlencode

class CommandRunner:
    def __init__(self, max_concurrent=10, timeout=60, rate_limit=60):
        self.max_concurrent = max_concurrent
        self.timeout = timeout
        self.rate_limit = rate_limit
        self.semaphore = semaphore_creator(self.max_concurrent)
        self.executor = ThreadPoolExecutor()
        self.monitor_url = "YOUR_MONITORING_URL"

    def execute(self, command, args=None, cwd=None, env=None, stdout_callback=None, timeout=-1):
        if not command:
            raise ValueError("Command must be provided")

        start_time = time.time()
        now = int(round(time.time()))
        semaphore_acquire()

        try:
            process = subprocess.Popen(command, shell=True if os.name == 'posix' else None,
                                      stdout=subprocess.PIPE, stderr=subprocess.STDOUM, cwd=cwd, env=env)

            if timeout > 0 and process.poll() is None:
                remaining_time = timeout - (time.time() - start_time)
                if remaining_time > 0:
                    time.sleep(remaining_time)
                else:
                    process.terminate()
                    process.wait(timeout=1)
                    if process.poll() is None:
                        process.kill()

            stdout, stderr = process.communicate()
            status_code = process.returncode

            if status_code != 0:
                error_message = f"Command '{command}' failed with return code {status_code}"
                self._log_error(error_message)
                if stderr:
                    self._log_error(f"Error message: {stderr.decode('utf-8')}")
                raise subprocess.CalledProcessError(returncode=status_code, cmd=command, output=stdout, errors=stderr)

            if timeout > 0 and timeout != -1:
                elapsed_time = time.time() - start_time
                if elapsed_time > timeout:
                    raise TimeoutError(f"Command '{command}' execution timed out after {timeout} seconds")

            if stdout_callback:
                for line in iter(lambda: process.stderr.readline(), b''):
                    stdout_callback(line)

            data = {"command": command, "args": args or [], "status_code": status_code,
                    "elapsed_time": elapsed_time, "start_time": start_time, "now": now}
            self._send_to_monitor(data)

        except Exception as e:
            error_message = f"Command '{command}' execution failed with error: {str(e)}"
            self._log_error(error_message)
            raise

        finally:
            semaphore_release()

    def _send_to_monitor(self, data):
        if self.monitor_url:
            request_data = {"data": json.dumps(data)}
            request_url = f"{self.monitor_url}?{urlencode(request_data)}"
            requests.post(request_url)

    def _log_error(self, error_message):
        # Implement logging function here using a library of your choice (e.g., logging or syslog)
        pass

def semaphore_creator(max_semaphores):
    return threading.Semaphore(max_semaphores)

def semaphore_acquire():
    semaphore.acquire()
    if time.time() - last_release > rate_limit:
        executor.submit(rate_limiter)
    last_release = time.time()

def semaphore_release():
    global semaphore, last_release
    semaphore.release()
    last_release = 0

def rate_limiter():
    time.sleep(rate_limit)
