        resource = db.Model.query.filter_by(id=id).first()
        if not resource:
            raise HTTPException(status_code=404, detail="Resource not found")

        for key, value in body.items():
            setattr(resource, key, value)

        session.commit()
        return resource

async def delete_resource(id: int):
