```javascript
const express = require('express');
const bodyParser = require('body-parser');
const axios = require('axios');
const bluebird = require('bluebird');
const chalk = require('chalk');

class RemoteExec {
  constructor(config) {
    this.apiUrl = config.apiUrl;
    this.accessToken = config.accessToken;
    // Add more config options if needed (e.g. timeout, retries, etc.)
  }

  async executeCommand(command) {
    const response = await axios.post(`${this.apiUrl}/execute`, { command });
    return response.data;
  }
}

const app = express();
app.use(bodyParser.json());

let executingTasks = {};
const maxConcurrentTasks = 100;

app.post('/tasks', async (req, res) => {
  const newTaskId = Date.now() + '_' + Math.floor(Math.random() * 1e6);

  if (Object.keys(executingTasks).length >= maxConcurrentTasks) {
    executingTasks[newTaskId] = req;
    res.status(202).send({ taskId: newTaskId });
    return;
  }

  try {
    const remoteExec = new RemoteExec(req.body);
    const result = await remoteExec.executeCommand(req.body.command);

    executingTasks[newTaskId] = req;
    res.send(result);

    setTimeout(() => {
      delete executingTasks[newTaskId];
    }, result.duration); // Send the duration of command execution for logging purposes
  } catch (error) {
    console.error(`Error executing command: ${error.message}`);
    res.status(500).send({ error });
  }
});

// Add logging middleware here to track task status and errors
app.listen(3000, () => {
  console.log(`Remote exec server listening on port 3000`);
});
