```cpp
#include <vector>
#include <algorithm>
#include <memory>
#include <stdexcept>

template<typename T, size_t Dimensions>
class KDTree {
private:
    struct Node {
        T point;
        std::unique_ptr<Node> left, right;
        size_t dimension;
        explicit Node(const T& point, size_t dimension) : point(point), dimension(dimension), left(nullptr), right(nullptr) {}
    };

    void balance(Node* node);
    Node* createNode(const T& point, size_t dimension);
    size_t getMedian(std::vector<Node*>& nodes);

    std::vector<Node*> roots;
    size_t capacity;

public:
    KDTree(size_t numPoints, size_t dimensions, size_t maxCapacity) : capacity(maxCapacity) {
        if (numPoints > capacity)
            throw std::invalid_argument("Number of initial points exceeds the maximum capacity");
        initialize_kdtree(dimensions, numPoints);
    }

    void insert(const T& point) {
        if (roots.size() >= capacity)
            balance(roots[0].get());
        roots[0] = createNode(point, (rootIndex + 1) % Dimensions);
    }

    void remove(const T& point) {
        for (auto it = roots.begin(); it != roots.end(); ) {
            if ((*it)->point == point) {
                std::unique_ptr<Node> child = std::move((*it)->left ? std::move((*it)->left) : std::move((*it)->right));
                delete *it;
                it = roots.erase(it);
                if (child) {
                    (*child)->left = nullptr;
                    roots[0] = std::move(child);
                }
                break;
            }
            ++it;
        }
        balance(roots[0].get());
    }

    const T& nearestNeighbor(const T& queryPoint) const {
        double minDistanceSq = std::numeric_limits<double>::max();
        const T* nearestPoint = nullptr;
        for (const auto& node : roots) {
            double distanceSq = squaredDistance(node->point, queryPoint);
            if (distanceSq < minDistanceSq) {
                minDistanceSq = distanceSq;
                nearestPoint = &node->point;
            }
        }
        return *nearestPoint;
    }

private:
    size_t rootIndex = 0;

    void initialize_kdtree(size_t dimensions, size_t numPoints) {
        // Assuming that the points are provided as a single array with each dimension following the other
        std::vector<Node*> nodes(numPoints);
        for (size_t i = 0; i < numPoints; ++i)
            nodes[i] = createNode({ i / dimensions, i % dimensions }, i % dimensions);
        buildKDTree(nodes.data(), nodes.size(), dimensions);
    }

    void buildKDTree(Node* nodes, size_t numNodes, size_t dimension) {
        if (numNodes <= 1)
            return;

        std::sort(nodes, nodes + numNodes, [dimension](const Node* lhs, const Node* rhs) {
            return lhs->point[dimension] < rhs->point[dimension];
        });

        size_t mid = getMedian(nodes, numNodes);
        auto newNode = createNode({ 0.0 }, dimension);
        newNode->left = std::unique_ptr<Node>(new Node(*nodes[mid]));
        nodes[mid]->left = nullptr;
        buildKDTree(nodes, mid, (dimension + 1) % Dimensions);
        buildKDTree(nodes + mid + 1, numNodes - mid - 1, dimension);
    }

    double squaredDistance(const T& p1, const T& p2) const {
        double distance = 0.0;
        for (size_t i = 0; i < Dimensions; ++i)
            distance += (p1[i] - p2[i]) * (p1[i] - p2[i]);
        return distance;
    }
};
```

This code provides a basic implementation of the k-d tree in C++. It assumes that the points are stored as an array of `Dimensions` values, with each point following the previous one. The error handling and memory management are not fully optimized but serve as a starting point for further development. You'll need to implement the balancing algorithm in the `balance()` function and allocate/deallocate memory efficiently according to your specific use case.

