typedef std::map<std::string, RSA*> TokenStore;

// Function to validate OAuth2 access token response
bool is_valid_token(const char* json) {
    Jsonsson* j = json_loads(json, 0, NULL);
    if (!j) return false;

    bool valid = true;
    const char* token_type = json_object_get(j, "token_type");
    if (strcmp(token_type, "Bearer") != 0) {
        valid = false;
        std::cout << "Invalid token type" << std::endl;
    }

    int expires_in = json_object_get_number(json, "expires_in");
    if (expires_in <= 0 || expires_in > 3600) {
        valid = false;
        std::cout << "Invalid expiration time" << std::endl;
    }

    const char* scope = json_object_get(j, "scope");
    if (!json_array_contains(j, scope, scope_set)) {
        valid = false;
        std::cout << "Invalid scope" << std::endl;
    }

    if (json_has_member(j, "refresh_token")) {
        const char* refresh_token = json_object_get(j, "refresh_token");
        redistdb* db = redisConnect("localhost", 6379);
        if (!db) {
            valid = false;
            std::cout << "Redis connection error" << std::endl;
            return valid;
        }

        redisReply* reply = (redisReply*)redisCommand(db, "GET %s", refresh_token);
        if (!reply || reply->type != REDIS_REPLY_STRING) {
            valid = false;
            std::cout << "Refresh token not found or invalid" << std::endl;
            freeReplyObject(reply);
            redisFree(db);
            return valid;
        }

        time_t expiration = atoi(reply->str);
        if (time(NULL) > expiration) {
            valid = false;
            std::cout << "Refresh token has expired" << std::endl;
        }

        freeReplyObject(reply);
        redisFree(db);
    }

    // Implement support for multiple token types, JWT validation, heuristics-based token invalidation, and rate limiting here.

    json_decref(j);
    return valid;
}

// ... (Implement the remaining functionality as specified)
