char* appendSlash(char* str, int maxLength) {
    char *result = (char*)malloc((maxLength + 1) * sizeof(char));
    if (str != NULL && strlen(str) <= maxLength) {
        strcpy(result, str);
        result[strlen(str)] = '/';
        return result;
    } else {
        free(result);
        return NULL;
    }
}
