```java
import java.io.*;
import java.util.Properties;
import java.text.SimpleDateFormat;
import java.util.Date;

public class CommandExecutor {
    private static Properties config;
    private static SimpleDateFormat timestampFormatter = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

    public static void main(String[] args) throws Exception {
        loadConfig(); // Load configuration file here

        String[] commands = {"command1", "command2"}; // Commands to execute

        for (String command : commands) {
            log("INFO", timestampFormatter.format(new Date()), "Start executing command: " + command);
            Process process = Runtime.getRuntime().exec(command, null, new File(config.getProperty("workingDirectory")));

            InputStream errorStream = process.getErrorStream();
            InputStreamReader errorReader = new InputStreamReader(errorStream);
            BufferedReader errorBuffer = new BufferedReader(errorReader);

            String line;
            while ((line = errorBuffer.readLine()) != null) {
                log("ERROR", timestampFormatter.format(new Date()), "Error executing command: " + command + ": " + line);
            }

            InputStream inputStream = process.getInputStream();
            InputStreamReader inputReader = new InputStreamReader(inputStream);
            BufferedReader inputBuffer = new BufferedReader(inputReader);

            String inputLine;
            while ((inputLine = inputBuffer.readLine()) != null) {
                log("INFO", timestampFormatter.format(new Date()), "Output executing command: " + command + ": " + inputLine);
            }

            process.waitFor(); // Wait for the command to complete
        }
    }

    private static void log(String severity, String timestamp, String message) {
        // Logging implementation here
    }

    private static void loadConfig() throws IOException {
        if (config == null) {
            config = new Properties();
            config.load(new FileInputStream("config.properties"));
        }
    }
}
```

