2. dataCollector.ts:

```typescript
import * as crypto from 'crypto';
import { WebSocketService } from './websocket';

export interface DataFilterConfig {
  contentType: string;
}

export class DataCollector {
  private webSocketService: WebSocketService;
  private data: any[] = [];
  private isPaused = true;
  private encryptionConfig: any;

  constructor(private filterConfig: DataFilterConfig, private encryptionConfig: any) {}

  setWebSocketService(webSocketService: WebSocketService) {
    this.webSocketService = webSocketService;
  }

  pause() {
    this.isPaused = true;
  }

  resume() {
    this.isPaused = false;
  }

  async handleMessage(data: any) {
    if (this.isPaused || !data.contentType.match(this.filterConfig.contentType)) return;

    try {
      data = await this.encryptData(data);
      this.data.push(data);
    } catch (error) {
      console.error(`Error encrypting data: ${error.message}`);
    }
  }

  async encryptData(data: any) {
    const cipher = crypto.createCipheriv(
      'aes-256-cbc',
      this.generateKey(),
      this.getIV()
    );
    let encrypted = cipher.update(JSON.stringify(data), 'utf8', 'hex') + cipher.final('hex');
    return JSON.parse(Buffer.from(encrypted, 'hex').toString());
  }

  private generateKey(): Buffer {
    return crypto.pbkdf2Sync(this.encryptionConfig.key, this.encryptionConfig.salt, 100000, 64, 'sha512');
  }

  private getIV(): Buffer {
    const ivBuffer = crypto.randomBytes(16);
    return ivBuffer;
  }
}
```

