import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.client.RestTemplate;
import reactor.core.publisher.Mono;

@RestController
public class PokemonController {

    private final RestTemplate restTemplate;
    private final ConfigurableApplicationContext context;

    @Autowired
    public PokemonController(RestTemplate restTemplate, ConfigurableApplicationContext context) {
        this.restTemplate = restTemplate;
        this.context = context;
    }

    // API endpoint to retrieve a given Pokemon's information
    @GetMapping("/pokemon/{id}")
    public Mono<Pokemon> getPokemonById(@PathVariable int id) {
        return restTemplate.getForEntity("http://api-gateway/pokemon/" + id, Pokemon.class)
                .onErrorResume((exception) -> this.retrieveFromAlternateSource(id));
    }

    // Caching annotation for caching Pokemon data in the Spring Cache Abstraction
    @Cacheable("pokemonCache")
    private Mono<Pokemon> retrieveFromPrimarySource(int id) {
        return Mono.justOrEmpty(this.restTemplate.getForEntity("http://primary-api/pokemon/" + id, Pokemon.class));
    }

    // Implement retrying logic for failed API calls to the primary source
    private Mono<Pokemon> retrieveFromAlternateSource(int id) {
        return this.retryOperations()
                .retry((exception) -> exception.getStatusCodeValueAsInt() == 503)
                .flatMap((Mono<Pokemon>) this::retrieveFromSecondarySource);
    }

    // Make a request to the alternate API source if the primary one is unavailable
    private Mono<Pokemon> retrieveFromSecondarySource(int id) {
        return Mono.justOrEmpty(this.restTemplate.getForEntity("http://secondary-api/pokemon/" + id, Pokemon.class));
    }
}
