                inputStream = ImageIO.createImageInputFromFile(new File(imageSource));
            } else if (imageSource.startsWith("http")) {
                URL url = new URL(imageSource);
                inputStream = ImageIO.createImageInputStream(url);
            } else if (imageSource.equalsIgnoreCase("camera")) {
                // Implement camera feed connection logic here
