                throw new IllegalArgumentException("Invalid image source: " + imageSource);
            }

            try (ImageCompressorInputStream compressorStream = new ImageCompressorInputStream(inputStream)) {
                ImageIO.write(ImageIO.read(compressorStream), "jpg", storage.getBucket(System.property("storageBucket")).createBlob(userId + "-compressed-" + imageSource.substring(imageSource.lastIndexOf('/'))));
            } catch (IIOInvalidTreeException | IOException e) {
                throw new RuntimeException(e);
            }
        } catch (Exception e) {
            // Handle exceptions and log errors here
        }
    }

    public void executeImageCompressionTasks() {
        Queue<Runnable> tasks = new LinkedBlockingQueue<>(100);
        Runnable worker = () -> {
            while (true) {
                try {
                    tasks.take().run();
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        };
        executor.submit(worker);

        // Add image compression tasks to the queue here
    }
}

