std::unordered_map<std::string, std::variant<int, double, std::string, bool>> loadConfig(const std::string& filePath) {
    static std::mutex configMutex;
    static std::unordered_map<std::string, std::variant<int, double, std::string, bool>> cachedConfig;
    static std::atomic_bool isFileModified{false};

    if (isFileModified.load()) {
        // File has been modified since last load, reload it
        cachedConfig.clear();
    }

    {
        std::lock_guard<std::mutex> lock(configMutex);
        if (cachedConfig.empty()) {
            try {
                fs::path configPath = getConfigFilePath();
                std::ifstream inputFile(configPath);

                if (!inputFile) {
                    throw std::runtime_error("Could not open configuration file");
                }

                json j;
                inputFile >> j;

                // Validate the JSON against a predefined schema here...

                for (const auto& item : j.items()) {
                    cachedConfig[item.key()] = item.value();
                }
            } catch (const std::exception& e) {
                std::cerr << "Error loading configuration: " << e.what() << '\n';
            }
        }
    }

    return cachedConfig;
}

std::filesystem::path getConfigFilePath() {
    const std::string envVar = "APP_CONFIG_PATH";
    const std::string defaultFilePath = "config.json";

    auto configPath = fs::current_path();
    if (auto envIt = std::getenv(envVar)) {
        configPath /= envIt;
    }

    return configPath / (envVar + ".json") || configPath / defaultFilePath;
}

