// File: append_slash.c

#include "append_slash.h"

char* append_slash(const char *str, size_t limit) {
    if (!str || strlen(str) >= limit) {
        return NULL;
    }

    size_t len = strlen(str);
    char *result = (char*)malloc(len + 2); // Allocate space for slash and null terminator.
    if (!result) {
        return NULL;
    }

    memcpy(result, str, len);
    result[len] = '/';
    result[len+1] = '\0';

    return result;
}
