int populateList(sqlite3 *db, int numElements, int logEnabled, NFAPI_CRC_INDICATION_PDU_T **list) {
    int rc = 0;
    sqlite3_stmt *stmt = NULL;
    if (!db || !numElements || numElements > 1000) {
        log("Invalid arguments");
        rc = -1;
        goto cleanup;
    }

    *list = malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        log("Memory allocation failure");
        rc = -2;
        goto cleanup;
    }

    const char *sql = "SELECT rxi_tag, rnti FROM ue_info";
    if (sqlite3_prepare(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        log("Database query failed");
        rc = -3;
        goto cleanup;
    }

    int i = 0;
    while ((rc == SQLITE_ROW) && (i < numElements)) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (*list + i);
        pdu->rxi_tag = sqlite3_column_int(stmt, 0);
        pdu->rnti = sqlite3_column_int(stmt, 1);
        pdu->crcflag = rand() % 2;
        if (pdu->crcflag < 0) {
            log("Invalid CRCFLAG value");
            continue;
        }
        i++;
    }

cleanup:
    if (stmt) sqlite3_finalize(stmt);
    if (db && rc != SQLITE_OK) sqlite3_close(db);
    return rc;
}

int main(int argc, char *argv[]) {
