            throw new ArgumentException("Invalid directory path.");

        DirectoryInfo dirInfo = new DirectoryInfo(directoryPath);

        if (!dirInfo.Exists || !dirInfo.GetFiles("web.config").Any())
            return null;

        var siteDetails = new SiteDetail { DirectoryPath = directoryPath, SiteName = siteName };
        _configManager.SaveSiteDetails(siteDetails);

        string webServerType = GetWebServerType(directoryPath);

        ProcessStartInfo startInfo = GetProcessStartInfo(webServerType, siteName);

        try
        {
            var process = new Process();
            process.StartInfo = startInfo;

            if (!process.Start())
                LogError($"Failed to start the website: {startInfo.FileName}");

            return process;
        }
        catch (Exception ex)
        {
            LogError($"Error starting the website: {ex.Message}");
            return null;
        }
    }

    private string GetWebServerType(string directoryPath)
    {
        var iisKey = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\InetStp");
        if (iisKey != null && File.Exists(Path.Combine(directoryPath, "applicationHost.config")))
            return "IIS";

        // Implement checks for other web servers like Apache here

        return "";
    }

    private ProcessStartInfo GetProcessStartInfo(string webServerType, string siteName)
    {
        var startInfo = new ProcessStartInfo();

        switch (webServerType)
        {
            case "IIS":
                startInfo.FileName = "iisreset";
                startInfo.Arguments = $"/noprestart /noforce /site:{siteName}";
                break;

            // Implement arguments for other web servers here
        }

        startInfo.RedirectStandardOutput = true;
        startInfo.UseShellExecute = false;

        return startInfo;
    }

