    public async Task<Pokemon> GetPokemonAsync(int id)
    {
        var cachedResponse = _memoryCache.Get(id);

        if (cachedResponse != null)
            return JsonSerializer.Deserialize<Pokemon>(cachedResponse as string);

        var response = await FetchPokemonData(id);
        var pokemon = JsonSerializer.Deserialize<Pokemon>(response);

        _memoryCache.Set(id, response, new MemoryCacheEntryOptions().AbsoluteExpirationRelativeToNow(TimeSpan.FromMinutes(5)));

        await ValidatePokemonData(pokemon);

        return pokemon;
    }

    private async Task<string> FetchPokemonData(int id)
    {
        var response = await _httpClient.GetAsync($"https://pokeapi.co/api/v2/pokemon/{id}");
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync();
    }

