void load_parsing_rules(char* config_file, ParsingRules** parsed_rules) {
    // Read the configuration file and parse it into a JSON object
    JsonObject *root = json_object_from_file(config_file);

    // Iterate through each rule in the JSON object and create ParsingRule instances
    JsonArray* rules = json_object_get_array(root, "rules");
    for (size_t i = 0; i < json_array_length(rules); ++i) {
        ParsingRule *rule = new_parsing_rule();
        // Load rule properties from the JSON object and initialize the ParsingRule instance
        json_object* current_rule = json_array_get_obj(rules, i);
        // ...
    }

    // Store the parsed rules in the provided pointer
    *parsed_rules = g_ptr_array_new();
    for (size_t i = 0; i < json_array_length(rules); ++i) {
        g_ptr_array_add(*parsed_rules, g_object_ref(g_ptr_array_index(rules, i)));
    }
}
