```c
#include <stdio.h>
#include <stdlib.h>
#include <tiffio.h>
#include <string.h>

typedef struct {
    char *password;
    TIFF *connection;
    void (*callback)(const char *, const TIFF*, void*);
    int bits_per_sample;
    int sample_per_pixel;
} CustomData;

int crossover(CustomData *data) {
    if (!data || !data->password || !data->connection || !data->callback) return -1;

    if (TIFFGetField(data->connection, TIFFTAG_IMAGEDESCRIPTION) != NULL) return -2;

    if (TIFFGetField(data->connection, TIFFTAG_BITSPERSAMPLE) < 1 || TIFFGetField(data->connection, TIFFTAG_BITSPERSAMPLE) > 16) {
        fprintf(stderr, "Unsupported bits per sample.\n");
        return -3;
    }

    data->bits_per_sample = TIFFGetField(data->connection, TIFFTAG_BITSPERSAMPLE);
    data->sample_per_pixel = TIFFGetFieldDefaulted(data->connection, TIFFTAG_SAMPLESPERPIXEL, 1);

    if (data->sample_per_pixel > 4) {
        int extra_samples = data->sample_per_pixel - 4;
        fprintf(stderr, "There are %d extra samples in the image.\n", extra_samples);
    }

    data->callback("Image information extracted.", data->connection, NULL);

    return 0;
}
```

