static pthread_once_t once = PTHREAD_ONCE_INIT;
static void (*log_func)(const char *, ...) = NULL;

void init_logger(void (*func)(const char *, ...)) {
    pthread_once(&once, func);
    log_func = func;
}

int safeStringCopy(const char *src, char *dest, size_t destSize) {
    assert(src && dest && log_func);

    size_t srcLen = strlen(src);
    if (srcLen > destSize - 1) {
        if (log_func)
            log_func("safeStringCopy: String too long for destination buffer.");
        return -1;
    }

    strncpy(dest, src, destSize - 1);
    dest[destSize - 1] = '\0';

    return (size_t)srcLen + 1;
