```javascript
const fs = require('fs-extra');
const path = require('path');
const readableStreamFor = require('readable-stream-for');
const streamBuffers = require('stream-buffers');

const MAX_FILE_SIZE = 1e6; // 1MB in bytes

async function readDirectory(directoryPath) {
  try {
    const filesAndDirectories = await fs.readdir(directoryPath, { withFileTypes: true });
    const results = [];

    for (const file of filesAndDirectories) {
      if (!file.isHidden) {
        const fullFilePath = path.join(directoryPath, file.name);
        const stats = await fs.stat(fullFilePath);

        if (stats.isDirectory()) {
          results.push(...await readDirectory(fullFilePath));
        } else if (stats.size <= MAX_FILE_SIZE) {
          const contentPromise = new Promise((resolve, reject) => {
            const stream = fs.createReadStream(fullFilePath);
            const bufferStream = streamBuffers.pipeline(stream, new streamBuffers.WritableStream({}));

            readableStreamFor(bufferStream, async (err, buffers) => {
              if (err) {
                console.warn(`Error reading file ${fullFilePath}:`, err);
                return;
              }
              resolve({ filename: fullFilePath, content: buffers.join('') });
            });
          });

          results.push(contentPromise);
        } else {
          console.warn(`Skipping large file ${fullFilePath} (size exceeds ${MAX_FILE_SIZE} bytes)`);
        }
      }
    }

    return await Promise.all(results);
  } catch (error) {
    console.error('Error reading directory:', error);
    throw error;
  }
}
```

This code uses `fs-extra`, `readable-stream-for`, and `stream-buffers` libraries for better asynchronous file handling and resource management. The function reads a given directory recursively, filters out hidden files, attempts to read non-hidden files, skips files larger than 1MB, and handles errors gracefully by logging a warning message and moving on to the next file.

