    public class ClinicStatusUpdaterMiddleware
    {
        private readonly RequestDelegate _next;
        private IDatabase _redisDatabase;
        private IClinicContext _clinicContext;
        private IEmailService _emailService;
        private ICmsService _cmsService;
        private IAuditService _auditService;

        public ClinicStatusUpdaterMiddleware(RequestDelegate next, IDatabase redisDatabase, IClinicContext clinicContext, IEmailService emailService, ICmsService cmsService, IAuditService auditService)
        {
            _next = next;
            _redisDatabase = redisDatabase;
            _clinicContext = clinicContext;
            _emailService = emailService;
            _cmsService = cmsService;
            _auditService = auditService;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            if (context.Request.Method != HttpMethods.Post || !context.Request.HasFormContentType)
            {
                await _next(context);
                return;
            }

            var clinicId = context.Request.Form["clinicId"];
            var newStatus = context.Request.Form["newStatus"];
            var lastModifiedIpAddress = HttpContext.Current.Request.UserHostAddress;
            var lastModifiedByUserId = int.Parse(context.Request.Form["lastModifiedByUserId"]);

            if (string.IsNullOrEmpty(clinicId) || string.IsNullOrEmpty(newStatus))
            {
                await SendErrorResponseAsync(context, "Invalid input: Both clinic ID and new status are required.");
                return;
            }

            var cachedClinic = await _redisDatabase.GetStringAsync($"clinic:{clinicId}");
            if (cachedClinic != null)
            {
                var clinic = JsonConvert.DeserializeObject<Clinic>(cachedClinic);
                await UpdateClinicStatusAsync(clinic, newStatus, lastModifiedIpAddress, lastModifiedByUserId);
            }
            else
            {
                var clinic = await _clinicContext.Clinics.FindAsync(clinicId);
                if (clinic == null)
                {
                    await SendErrorResponseAsync(context, $"Clinic with ID '{clinicId}' not found.");
                    return;
                }

                await UpdateClinicStatusAsync(clinic, newStatus, lastModifiedIpAddress, lastModifiedByUserId);
            }

            await _next(context);
        }

        private async Task UpdateClinicStatusAsync(Clinic clinic, string newStatus, string lastModifiedIpAddress, int lastModifiedByUserId)
        {
            try
            {
                using var transaction = await _clinicContext.Database.BeginTransactionAsync();

                clinic.Status = newStatus;
                clinic.LastModifiedIpAddress = lastModifiedIpAddress;
                clinic.LastModifiedByUserId = lastModifiedByUserId;
                clinic.LastModifiedOn = DateTimeOffset.UtcNow;

                await _clinicContext.SaveChangesAsync();
                transaction.Commit();

                // Fetch updated clinic details and apply changes to the CMS using the ICmsService
                var cmsContent = await _cmsService.FetchClinicContentAsync(clinic);
                await _cmsService.ApplyClinicStatusUpdateAsync(clinic, cmsContent);

                // Record the update in the audit system using the IAuditService
                await _auditService.RecordClinicUpdateAsync(lastModifiedByUserId, clinic.Id, clinic.OldStatus, newStatus);

                // Send an email notification to clinic administrators using the IEmailService
                await _emailService.SendClinicStatusUpdatedEmailAsync(clinic);
            }
            catch (Exception ex)
            {
                await _next(context).WithException(ex);
            }
        }

        private async Task SendErrorResponseAsync(HttpContext context, string errorMessage)
        {
            var response = new HttpResponseMessage(HttpStatusCode.BadRequest)
            {
                Content = new StringContent(errorMessage, Encoding.UTF8, "application/json")
            };

            await context.Response.WriteAsync(response);
        }
    }
}
