use std::env;
use std::fs::{self, File};
use std::io::{self, Write};
use std::path::Path;
use std::process::Command;
use std::sync::Arc;
use std::time::Instant;
use sync_lazy::{SyncLazy, SyncLazyInitError};
use tempfile::TempDir;

const MAX_RSS: usize = 1024 * 1024 * 50; // 50 MB
const TIMEOUT: std::time::Duration = std::time::Duration::from_secs(30);

mod logging {
    use super::*;
    use log::{LevelFilter, SetLoggerError};

    pub fn init() -> Result<(), SetLoggerError> {
        let mut builder = env_logger::Builder::new();
        builder.filter_level(LevelFilter::Info)
            .format_timestamp(|tt, _| tt.rfc3339())
            .init()?;
        Ok(())
    }
}

type CompilationResult = Result<(), Box<dyn std::error::Error>>;

struct CompileHook {
    duration: f64,
    file_path: Path,
}

impl CompileHook {
    fn new(file_path: &Path) -> Self {
        CompileHook {
            duration: 0.0,
            file_path: file_path.to_owned(),
        }
    }
}

struct Compiler {
    log_hook: Arc<SyncLazy<CompileHook>>,
}

impl Compiler {
    fn new() -> Self {
        let log_hook = Arc::new(SyncLazy::new(|| CompileHook::new));
        Compiler { log_hook }
    }

    fn compile(&self, src: &str) -> CompilationResult {
        let temp_dir = TempDir::new()?;
        let file_path = temp_dir.path().join("compiled.rs");
        fs::write(file_path, src)?;

        let mut cmd = Command::new("rustc");
        cmd.arg("--crate-name")
            .arg("test")
            .arg("-C")
            .arg("debuginfo=2")
            .arg("-o")
            .arg(&temp_dir.path().join("test"))
            .current_dir(temp_dir.path())
            .arg(&file_path)
            .env("RUSTFLAGS", "-C lto") // Enable Link Time Optimization (LTO) for better performance
            .stderr(io::Stderr);
        let mut process = cmd.spawn()?;

        let start_time = Instant::now();
        let log_hook = self.log_hook.sync_ref();
        let mut rss_tracker = RSSTracker::new(&file_path)?;
        loop {
            match process.poll()? {
                Ok(Some(Output { status, stderr, .. })) => {
                    if !status.success() {
                        eprintln!("Compilation failed for {}: {}", log_hook.file_path.display(), std::str::from_utf8(&stderr).unwrap());
                        return Err(Box::new(compile_error!(log_hook.file_path, status)));
                    } else {
                        let duration = start_time.elapsed().as_secs_f64();
                        log_hook.duration = duration;
                        break;
                    }
                }
                Ok(None) => {
                    if rss_tracker.exceeded_rss_limit() {
                        eprintln!("Compilation aborted for {} due to excessive memory usage.", log_hook.file_path.display());
                        return Err(Box::new(compile_error!(log_hook.file_path, rss_tracker.exceeded_rss_limit())));
                    }
                }
                Err(e) if e.kind() == io::ErrorKind::Interrupted => {
                    eprintln!("Compilation interrupted for {}: {}", log_hook.file_path.display(), e);
                    return Err(Box::new(compile_error!(log_hook.file_path, e)));
                }
                Err(e) => {
                    eprintln!("Error during compilation for {}: {}", log_hook.file_path.display(), e);
                    return Err(Box::new(compile_error!(log_hook.file_path, e)));
                }
            }
        }

        Ok(())
    }
}

struct RSSTracker {
    file_path: Path,
    max_rss: usize,
}

impl RSSTracker {
    fn new(file_path: &Path) -> Result<Self, Box<dyn std::error::Error>> {
        Ok(RSSTracker {
            file_path: file_path.to_owned(),
            max_rss: MAX_RSS,
        })
    }

    fn exceeded_rss_limit(&self) -> bool {
        let output = Command::new("ps")
            .args(&["-o", "rss", "-p", self.pid().unwrap_or(-1).to_string()])
            .output()?;
        let rss: usize = match str::from_utf8(&output.stderr) {
            Ok(s) => s.trim().parse::<usize>().unwrap(),
            Err(_) => return true, // If the output is invalid, assume the process has exceeded the limit
        };
        rss > self.max_rss
    }

    fn pid(&self) -> Option<i32> {
        Command::new("pgrep")
            .arg(format!("rustc {}", self.file_path.display()))
            .output()?
            .status
            .code()
            .map(|code| code as i32)
    }
}

fn compile(src: &str, output: &Path) -> CompilationResult {
    logging::init().unwrap();

    let compiler = Compiler::new();
    compiler.compile(src)?;
    let log_hook = compiler.log_hook.sync_ref();

    // Perform any additional post-compilation processing if necessary

    Ok(())
}

fn main() {
    let src = env::args().nth(1).unwrap();
    let output = Path::new("out").join(Path::new(&src).file_name().unwrap());
    compile(&src, &output).unwrap();
    println!("Compilation succeeded for {} in {}", output.display(), log_duration!(log_hook));
}

#[derive(Debug)]
enum CompileError {
    FileNotFound(Path),
    Timeout,
    Interrupted(io::Error),
    RssLimitExceeded,
    Other(Box<dyn std::error::Error>),
}

impl From<io::Error> for CompileError {
    fn from(e: io::Error) -> Self {
        match e.kind() {
            io::ErrorKind::NotFound => CompileError::FileNotFound(e.file_path()),
            _ if e.kind() == io::ErrorKind::Interrupted => CompileError::Interrupted(e),
            _ => CompileError::Other(Box::new(e)),
        }
    }
}

impl From<SyncLazyInitError> for CompileError {
    fn from(_: SyncLazyInitError) -> Self {
        CompileError::RssLimitExceeded
    }
}

fn compile_error(file_path: Path, e: Box<dyn std::error::Error>) -> CompileError {
    match e.source().map(|s| s.kind()) {
        Some(io::ErrorKind::TimedOut) => CompileError::Timeout,
        _ => CompileError::Other(e),
    }
}

fn log_duration<T>(hook: &CompileHook) -> T {
    hook.duration.thousands() as T
}
