```python
import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging
from functools import wraps

def log(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            result = func(*args, **kwargs)
            return result
        except Exception as e:
            logging.error(f"Error in function {func.__name__}: {e}")
        finally:
            logging.info(f"Finished executing {func.__name__}")
    return wrapper

def hash_file(file_path, hash_value=None):
    def calculate_hash(file_path):
        hasher = hashlib.sha256()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                hasher.update(chunk)
        return hasher.hexdigest()

    hasher = calculate_hash(file_path)

    if hash_value and hasher != hash_value:
        logging.warning(f"The calculated hash for file '{file_path}' does not match the provided hash.")

    return (hasher, os.stat(file_path).st_size, calculate_hash.__time__)

@log
def compute_hashes(files, hash_values=None):
    with ThreadPoolExecutor() as executor:
        futures = [executor.submit(hash_file, file, hash_value) for file in files]
        results = [future.result() for future in as_completed(futures)]

    for result in results:
        (hash, size, time) = result
        logging.info(f"Hash of '{os.path.basename(result[0][0])}' is {hash}, file size is {size}, and computation took {time} seconds.")

# Example usage:
files = ["example1.txt", "example2.txt"]
hash_values = {"example1.txt": "abcdef...", "example2.txt": None}
compute_hashes(files, hash_values)
```

This code defines a `hash_file` function that calculates the SHA-256 hash of a file and a `compute_hashes` function that handles multiple files concurrently using a thread pool. The `compute_hashes` function logs any errors encountered during the process, verifies the hash against a provided hash value if given, and outputs the hash value, file size, and computation time for each file.

The logging is configured to use the `logging` module, and the code uses a decorator (`@log`) to log all executed functions. The example usage at the end demonstrates how to call the `compute_hashes` function with a list of files and optional hash values.

