// Helper function to create a new security provider node
securityProvider* create_provider_node(const char *name, void (*implementation)(void), void *params) {
    securityProvider *new_node = malloc(sizeof(securityProvider));
    if (new_node == NULL) {
        fprintf(stderr, "Failed to allocate memory for new provider node\n");
        exit(1);
    }
    new_node->name = name;
    new_node->implementation = implementation;
    new_node->params = params;
    return new_node;
}

// Helper function to concatenate a list of security providers into a single linked list
void concat_provider_lists(securityProvider **list1, securityProvider **list2) {
    if (*list1 == NULL) {
        *list1 = *list2;
    } else {
        securityProvider *current = *list1;
        while (current->next != NULL) current = current->next;
        current->next = *list2;
    }
}
