import json
import copy
from abc import ABC, abstractmethod
from typing import Dict, Any, Type, Union
from concurrent.futures import ThreadPoolExecutor
import os
import sys
from urllib.request import urlopen

class JSONSchema:
    def __init__(self, schema: Dict[str, Union[str, Dict[str, Dict[str, Any]]]]):
        self.schema = schema

    def validate(self, data: Dict[str, Any]):
        return all([_validate(data[key], self.schema[key]) for key in data])

class JSONFactory(ABC):
    @abstractmethod
    def create(self, json_data: Dict[str, Any], schema: JSONSchema) -> 'JSONObject':
        pass

    @property
    @abstractmethod
    def id(self) -> str:
        pass

class JSONObject(ABC):
    def __init__(self, data: Dict[str, Any]):
        self.data = data

    def to_dict(self) -> Dict[str, Any]:
        return copy.deepcopy(self.data)

    def validate(self, schema: JSONSchema) -> bool:
        return schema.validate(self.data)

class NestedJSONObject(JSONObject):
    def __init__(self, data: Dict[str, Any]):
        super().__init__(data)

class SimpleJSONObject(JSONObject):
    pass

registry = {}

def add_factory(factory: Type[JSONFactory]) -> None:
    registry[factory.id] = factory()

def remove_factory(factory_id: str) -> None:
    if factory_id in registry:
        del registry[factory_id]

def create_object(factory_id: str, json_data: Dict[str, Any], schema: JSONSchema = None) -> Union[NestedJSONObject, SimpleJSONObject]:
    try:
        factory = registry[factory_id]
        if not factory.validate(json_data, schema):
            raise ValueError(f"Invalid data for factory {factory_id}")
        return factory.create(json_data, schema)
    except KeyError:
        raise ValueError(f"Factory with id {factory_id} not found")

def _validate(value: Any, schema: Dict[str, Any]) -> bool:
    if isinstance(schema, str):
        return isinstance(value, schema)
    elif isinstance(schema, dict):
        if not value or not isinstance(value, dict):
            return False
        for key, sub_schema in schema.items():
            if not _validate(value[key], sub_schema):
                return False
        return True
    else:
        return isinstance(value, schema)

def fetch_schemas() -> Dict[str, JSONSchema]:
    url = os.environ.get('CONFIG_URL', 'https://example.com/config.json')
    with urlopen(url) as response:
        data = json.load(response)
        schemas = {}
        for id_, schema in data.items():
            if isinstance(schema, str):
                schemas[id_] = JSONSchema({id_: schema})
            elif isinstance(schema, dict):
                schemas[id_] = JSONSchema(schema)
        return schemas

if __name__ == '__main__':
    # Example usage
    add_factory(MyNestedFactory)
    add_factory(MySimpleFactory)

