void _logConditionHelper(int condition, const char *format, va_list args) {
    static size_t index = 0;
    char buffer[256];

    if (!condition) return; // Skip if condition is not met

    vsnprintf(buffer, sizeof(buffer), format, args);
    if (strlen(buffer) >= sizeof(log_buffer)) {
        // Handle overflow by truncating or discarding the message, and provide a diagnostic
        snprintf(log_buffer, sizeof(log_buffer) - 1, "Buffer overflow: %s", buffer);
        logMessage(log_buffer, LOG_ERROR);
    } else {
        strncpy(log_buffer + index, buffer, sizeof(log_buffer) - index - 1);
        index += strlen(buffer);

        // Flush the buffer when it reaches capacity or a newline is encountered
        if (index >= sizeof(log_buffer) || '\n' == log_buffer[index - 1]) {
            logMessage(log_buffer, LOG_INFO);
            memset(log_buffer, 0, sizeof(log_buffer));
            index = 0;
        }
    }
}

void logCondition(int condition, const char *format, ...) {
    va_list args;
    va_start(args, format);
    _logConditionHelper(condition, format, args);
    va_end(args);
}
