```csharp
using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using NLog;

public class SecureMessageProcessor
{
    private readonly ConcurrentDictionary<string, string> _decryptedCache = new ConcurrentDictionary<string, string>();
    private static readonly Logger _logger = LogManager.GetCurrentClassLogger();

    public byte[] Key { get; set; }
    public byte[] IV { get; set; }
    private TripleDESCryptoServiceProvider _tripleDES;

    public SecureMessageProcessor(byte[] key, byte[] iv)
    {
        Key = key;
        IV = iv;
        _tripleDES = new TripleDESCryptoServiceProvider() { Key = key, IV = iv };
    }

    ~SecureMessageProcessor()
    {
        Dispose(false);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposing)
        {
            _tripleDES?.Dispose();
        }
    }

    public string DecryptMessage(string encodedMessage)
    {
        if (string.IsNullOrEmpty(encodedMessage)) throw new ArgumentNullException(nameof(encodedMessage));
        if (Key == null || IV == null) throw new InvalidOperationException("The key and initialization vector must be set before using the DecryptMessage method.");

        string cacheKey = CreateCacheKey(encodedMessage);
        if (_decryptedCache.TryGetValue(cacheKey, out var decryptedMessage)) return decryptedMessage;

        lock (_decryptedCache)
        {
            byte[] messageBytes = Convert.FromBase64String(encodedMessage);
            using (MemoryStream msDecrypt = new MemoryStream(messageBytes))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, _tripleDES.CreateDecryptor(), CryptoStreamMode.Read))
                {
                    byte[] decryptedMessageBytes = new byte[msDecrypt.Length];
                    int bytesRead = csDecrypt.Read(decryptedMessageBytes, 0, decryptedMessageBytes.Length);
                    if (bytesRead < decryptedMessageBytes.Length) _logger.Warn("Incomplete message decryption.");

                    _decryptedCache[cacheKey] = Encoding.UTF8.GetString(decryptedMessageBytes);
                    return _decryptedCache[cacheKey];
                }
            }
        }
    }

    public byte[] EncryptMessage(string message)
    {
        if (string.IsNullOrEmpty(message)) throw new ArgumentNullException(nameof(message));
        if (Key == null || IV == null) throw new InvalidOperationException("The key and initialization vector must be set before using the EncryptMessage method.");

        byte[] messageBytes = Encoding.UTF8.GetBytes(message);
        using (MemoryStream msEncrypt = new MemoryStream(messageBytes))
        {
            using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, _tripleDES.CreateEncryptor(), CryptoStreamMode.Write))
            {
                byte[] encryptedMessageBytes = msEncrypt.ToArray();
                return Convert.ToBase64String(encryptedMessageBytes);
            }
        }
    }

    private string CreateCacheKey(string encodedMessage) => $"{Convert.ToBase64String(Key)}{encodedMessage}";
}
```

