    // Load environment variables from multiple files and prioritize based on order
    char *dotenv = getenv("DOTENV");
    if (!dotenv) dotenv = ".env";

    FILE *fp = fopen(dotenv, "r");
    char line[4096];

    while (fgets(line, sizeof(line), fp)) {
        size_t pos = strncmp(line, "DB_", 3) == 0 || strncmp(line, "LOG_SYSTEM", 9) == 0;
        if (pos) continue;

        char *var = strtok(line, "=");
        char *val = strtok(NULL, "\r\n");
        setenv(var, val, 1);
