// Helper function to read integers from standard input
void read_integers(std::vector<int>& numbers) {
    std::string line;
    while (std::getline(std::cin, line)) {
        try {
            numbers.push_back(stoi(line));
        } catch (const std::invalid_argument& e) {
            std::cerr << "Invalid input: " << e.what() << '\n';
        }
    }
}

// Helper function to find the largest integer in a vector
int max_integer(const std::vector<int>& numbers) {
    if (numbers.empty()) return 0;
    int max = numbers[0];
    for (const auto& number : numbers)
        if (number > max) max = number;
    return max;
}
