namespace pt = boost::property_tree;
using namespace boost::asio;
using namespace boost::log;

class TlsSession {
public:
    SSL_CTX* ctx;
    SSL* ssl;

    TlsSession() : ctx(nullptr), ssl(nullptr) {}
    ~TlsSession() {
        if (ssl) {
            SSL_free(ssl);
            ssl = nullptr;
        }
        if (ctx) {
            SSL_CTX_free(ctx);
            ctx = nullptr;
        }
    }
};

TlsSession* initializeTls(const std::string& configFilePath) {
    TlsSession* session = new TlsSession();

    try {
        std::ifstream configFile(configFilePath);
        pt::ptree config;
        read_xml(configFile, config);

        const char* tlsVersion = config.get<std::string>("tls_version").c_str();
        const char* cipherSuites = config.get<std::string>("cipher_suites").c_str();

        SSL_load_error_strings();
        ERR_load_BIO_strings();

        OpenSSL_add_all_algorithms();
        SSL_load_error_strings();

        session->ctx = SSL_CTX_new(TLSv1_2_server_method()); // Initialize context with TLS 1.2 support

        if (!SSL_CTX_set_ciphers(session->ctx, cipherSuites)) {
            std::cerr << "Error: Unable to set cipher suites." << std::endl;
            return nullptr;
        }
    } catch (std::exception& e) {
        std::cerr << "Error reading configuration file: " << e.what() << std::endl;
        return nullptr;
    }

    return session;
}

