```javascript
const axios = require('axios');
const _ = require('lodash');
const moment = require('moment-timezone');

const WEATHER_API_URL = 'https://api.weatherapi.com/v1/current.json';
const API_KEY = 'your_api_key';
const MAX_ATTEMPTS = 3;
const CACHE_DURATION_MS = 60 * 60 * 1000; // 1 hour in milliseconds

async function fetchWeatherData(cities, onUpdate) {
    const cache = JSON.parse(localStorage.getItem('weather-cache')) || {};
    const now = moment().unix();

    cities.forEach((city) => {
        const cacheKey = `${city}-${now}`;
        if (cache[city] && cache[city].timestamp >= now - CACHE_DURATION_MS) {
            onUpdate(cache[city]);
            return;
        }

        let attempts = 0;
        const weatherDataPromise = new Promise((resolve, reject) => {
            const options = {
                url: WEATHER_API_URL,
                params: {
                    q: city,
                    key: API_KEY
                }
            };

            const fetchWeatherDataRetry = async () => {
                try {
                    const response = await axios.get(options.url, options);
                    if (response.status === 200) {
                        cache[city] = {
                            data: response.data,
                            timestamp: now
                        };
                        localStorage.setItem('weather-cache', JSON.stringify(cache));
                        onUpdate(cache[city]);
                    }
                } catch (error) {
                    attempts++;
                    if (attempts < MAX_ATTEMPTS) {
                        setTimeout(fetchWeatherDataRetry, Math.pow(2, attempts - 1) * 1000);
                    } else {
                        console.error(`Failed to fetch weather data for ${city}:`, error.message);
                    }
                }
            };

            fetchWeatherDataRetry();
        });

        weatherDataPromise.then(onUpdate).catch((error) => {
            if (attempts < MAX_ATTEMPTS) {
                console.error(`Error fetching weather data for ${city}:`, error);
            }
        });
    });
}
```

