```cpp
#include <algorithm>
#include <cstring>
#include <stdexcept>
#include <forward_list>

constexpr size_t MAX_ELEMENT_LENGTH = 100;

void insert_after_first(std::forward_list<std::string>& list, const std::string& search, const std::string& insert, size_t max_insertions) {
    if (list.empty()) {
        throw std::invalid_argument("The input list is empty");
    }

    size_t count = 0;
    auto it = list.begin();

    for (; it != list.end() && count < max_insertions; ++it, ++count) {
        if (*it == search) {
            std::string copy = *it;
            if (copy.length() > MAX_ELEMENT_LENGTH) {
                copy.resize(MAX_ELEMENT_LENGTH);
            }
            it = list.insert_after(it, insert);
            *it = insert;
            if (it->length() > MAX_ELEMENT_LENGTH) {
                it->resize(MAX_ELEMENT_LENGTH);
            }
            break;
        }
    }

    if (count == max_insertions && it != list.end()) {
        throw std::runtime_error("The search string is not found within the specified range");
    }
}
