public class MoSTStateLoader {
    public static MoSTState loadFromFile(String fileName) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(fileName))) {
            Object object = ois.readObject();

            if (object instanceof MoSTState) {
                return (MoSTState) object;
            } else {
                throw new ClassCastException("Loaded object is not an instance of MoSTState");
            }
        } catch (IOException | ClassNotFoundException | IllegalAccessException | InstantiationException | InvocationTargetException e) {
