#include <string.h>

char* append_slash(const char *str, size_t max_length) {
    size_t len = strlen(str);
    if (len <= max_length) {
        char *new_str = malloc(max_length + 1);
        memcpy(new_str, str, len);
        new_str[len] = '/';
        new_str[len+1] = '\0';
        return new_str;
    }
    return NULL;
}
