```typescript
// index.ts
import yargs from 'yargs';
import chokidar from 'chokidar';
import { loadModules } from './moduleLoader';
import * as log from './logger';

const argv = yargs
  .options({
    // Add your options here, such as --modules for providing a list of modules to load
  })
  .alias('h', 'help')
  .help('help').argv;

if (argv._[0] === 'help') {
  yargs.showHelp();
  process.exit(0);
}

loadModules(argv._)
  .then(() => log.success('All modules executed successfully.'))
  .catch((err) => {
    log.error(`An error occurred: ${err.message}`);
    process.exit(1);
  });

function loadModules(moduleNames: string[]): Promise<void> {
  // Create a map to store modules and their dependencies
  const moduleMap = new Map<string, Module>();

  return new Promise((resolve, reject) => {
    // Watch for changes in the specified modules
    const watcher = chokidar.watch(moduleNames);

    let executedModules: string[] = [];
    let currentModuleName: string | undefined;

    watcher
      .on('add', (file) => {
        if (!currentModuleName) {
          currentModuleName = file;
        }
      })
      .on('change', async (file) => {
        if (currentModuleName === file) {
          try {
            const module = await import(file);
            moduleMap.set(file, module);

            // Check for circular dependencies
            if (moduleMap.has(file)) {
              throw new Error(`Circular dependency detected: ${file}`);
            }

            // Resolve dependencies and execute modules in the correct order
            const dependencies = resolveDependencies(module);
            await loadModules(dependencies);
            executedModules.push(file);

            const { main } = module;
            if (typeof main === 'function') {
              await main();
            } else if (typeof main === 'object' && 'default' in main) {
              await main.default();
            } else {
              throw new Error(`Module ${file} does not export a function or default export.`);
            }
          } catch (err) {
            log.error(
              `An error occurred while executing module ${file}: ${err.message}`
            );
          } finally {
            currentModuleName = undefined;
          }
        }
      })
      .on('end', () => {
        if (executedModules.length === moduleNames.length) {
          resolve();
        } else {
          reject(
            new Error(`Not all modules were executed. Expected: ${moduleNames.length}, Executed: ${executedModules.length}`)
          );
        }
      });
  });
}

function resolveDependencies(module: any): string[] {
  // Implement this function to resolve dependencies for the given module
}

