using System;
using System.Buffers;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;

public class SecureEncryptionManager
{
    private readonly Aes _aes = Aes.Create();
    private readonly RandomNumberGenerator _random = RandomNumberGenerator.Create();

    public byte[] DecryptAES_CBC(byte[] ciphertext, byte[]? iv = null)
    {
        if (iv == null || iv.Length != _aes.BlockSize / 8)
            throw new ArgumentException("Invalid IV length.");

        using var aesAlg = Aes.Create();
        if (aesAlg.Key == _aes.Key) // Key reuse is not recommended but for simplicity...
            iv = iv.Concat(_aes.IV).ToArray();
        else
            Array.Copy(_aes.IV, 0, iv!, aesAlg.BlockSize / 8, _aes.IV.Length);

        using var encryptor = aesAlg.CreateDecryptor(aesAlg.Key, iv);
        using var ms = new MemoryStream(ciphertext);
        using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Read))
            return cs.ToArray();
    }

    public byte[] DecryptAES_GCM(byte[] ciphertext, byte[]? authTag = null)
    {
        if (authTag == null || authTag.Length != _aes.KeySize / 8)
            throw new ArgumentException("Invalid authentication tag length.");

        using var aesAlg = Aes.Create();
        aesAlg.Key = _aes.Key;
        aesAlg.IV = _aes.IV;

        using var decryptor = aesAlg.CreateDecryptor();
        using var gcm = new GcmBlockEncryptionProvider(aesAlg, authTag);
        using var ms = new MemoryStream(ciphertext);
        return gcm.Decrypt(ms, out _);
    }

    public void GenerateKeysAndIVs()
    {
        _aes.GenerateKey();
        _aes.GenerateIV();
    }
}
