import java.io.*;
import java.math.BigInteger;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import okhttp3.*;

public class CloudStorage {
    private static final ExecutorService executor = Executors.newCachedThreadPool();

    public void uploadFileToCloudStorage(String filePath, String bucketName, String directoryPath) throws IOException {
        Path file = Path.of(filePath);
        MessageDigest messageDigest = MessageDigest.getInstance("SHA-256");

        // Calculate the hash of the file
        byte[] hash = calculateFileHash(file);

        // Check if the file exists in the specified location using the calculated hash
        boolean isAlreadyUploaded = checkIfFileExistsInBucket(bucketName, directoryPath, hash);

        if (isAlreadyUploaded) {
            System.out.println("The file already exists in the specified location.");
            return;
        }

        // Create a request for uploading the file to the cloud storage service
        RequestBody requestBody = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("file", file.getFileName().toString(), Files.readAllBytes(file))
                .build();

        // Upload the file to the cloud storage service and handle any errors
        try (OkHttpClient client = new OkHttpClient()) {
            Request request = new Request.Builder()
                    .url("<YOUR_CLOUD_STORAGE_API_URL>")
                    .addHeader("Authorization", "<YOUR_API_KEY>")
                    .post(requestBody)
                    .build();

            Response response = client.newCall(request).execute();

            if (!response.isSuccessful()) {
                System.out.println("Failed to upload the file: " + response.message());
            } else {
                System.out.println("File uploaded successfully.");
            }
        } catch (IOException e) {
            System.err.println("Error while uploading the file: " + e.getMessage());
        }
    }

    public static byte[] calculateFileHash(Path file) throws IOException {
        try (InputStream inputStream = Files.newInputStream(file); InputStream hashInputStream = new DigestInputStream(inputStream, messageDigest)) {
            byte[] buffer = new byte[8 * 1024];
            int bytesRead;
            while ((bytesRead = hashInputStream.read(buffer)) != -1) {
                messageDigest.update(buffer, 0, bytesRead);
            }
        }

        return messageDigest.digest();
    }

