#include <boost/asio.hpp>
#include <boost/beast/http.hpp>
#include <boost/circular_buffer.hpp>
#include <boost/optional.hpp>
#include <boost/thread/tss.hpp>
#include <chrono>
#include <functional>
#include <iostream>
#include <map>
#include <mutex>
#include <queue>
#include <string>
#include <thread>
#include <vector>

namespace ns = boost::asio;
using tcp = ns::ip::tcp;

// External metadata service interface
struct MetadataService {
    virtual boost::optional<std::string> FindVmUuidFromMetadataIp(const std::string& ip) const = 0;
};

class SandeshClient {
public:
    explicit SandeshClient(MetadataService& metadata_service, size_t max_concurrency, int retry_limit);

    void Start();

private:
    void RunWorker();
    void MakeRequest(const std::string& method, const std::string& url, const std::string& body, bool is_post);
    void ProcessResponse(ns::io_context& io_context, beast::http::response<beast::http::string_body> response);

    MetadataService& _metadata_service;
    size_t _max_concurrency;
    int _retry_limit;

    ns::io_context _io_context;
    tcp::socket _socket;
    beast::journal<true> _log;
    boost::circular_buffer<std::pair<std::string, std::function<void(beast::http::response<beast::http::string_body>)>>> _request_queue;
    std::mutex _request_queue_mutex;
    std::vector<std::thread> _workers;
};

SandeshClient::SandeshClient(MetadataService& metadata_service, size_t max_concurrency, int retry_limit)
    : _metadata_service(metadata_service), _max_concurrency(max_concurrency), _retry_limit(retry_limit) {}

void SandeshClient::Start() {
    for (size_t i = 0; i < _max_concurrency; ++i) {
        _workers.emplace_back(&SandeshClient::RunWorker, this);
    }
}

void SandeshClient::RunWorker() {
    while (true) {
        std::unique_lock<std::mutex> lock(_request_queue_mutex);
        auto [method, callback] = _request_queue.front();
        _request_queue.pop_front();
        lock.unlock();

        MakeRequest(method, ..., false); // Replace the ellipsis with the appropriate parameters for your GET request
    }
}

void SandeshClient::MakeRequest(const std::string& method, const std::string& url, const std::string& body, bool is_post) {
    auto self = this;
    beast::error_code ec;
    auto verifier = [self](beast::http::request<beast::http::string_body> req) {
        if (req.method() != beast::http::verb::get && req.method() != beast::http::verb::post)
            self->_log("Invalid method specified");
    };

    auto headers = beast::http::request_headers::collect(beast::bind_front_handler(verifier, this));
    beast::http::request<beast::http::string_body> req{method, url, headers};

    if (is_post) {
        req.set(beast::http::field::content_type, "application/x-www-form-urlencoded");
        req.set(beast::http::field::content_length, body.size());
        req.body() = body;
    }

    beast::journal<true> log("SandeshClient");
    log << boost::asio::detail::get_time_string(ns::get_clock():local_time()) << ": Sending request - " << req;

    auto callback = [this, ec, url, body, is_post, callback](beast::http::response<beast::http::string_body> res) {
        if (ec) {
            log << boost::asio::detail::get_time_string(ns::get_clock():local_time()) << ": Failed to send request - " << url;
        } else {
            log << boost::asio::detail::get_time_string(ns::get_clock():local_time()) << ": Received response - " << res;
        }
        if (res) { // Check if the response is valid
            self->ProcessResponse(_io_context, res);
        } else { // Retry on failure
            auto attempts = _retry_limit - 1;
            std::this_thread::sleep_for(std::chrono::milliseconds(500)); // Throttle request rate
            if (attempts > 0) {
                MakeRequest(method, url, body, is_post);
            }
        }
    };

    _io_context.post([this, ec, url, body, is_post, callback]() mutable {
        _socket.async_connect(_endpoint, [this, ec, url, body, is_post, callback](beast::error_code ec) {
            if (!ec) {
                beast::error_code read_ec;
                beast::flat_buffer buffer;
                req.prepare(buffer);
                write(this->_socket, beast::buffers_to_stream(buffer), boost::asio::transfer_at_least(1), [&](beast::error_code ec, std::size_t) {
                    if (!ec) {
                        buffer.clear();
                        read(this->_socket, buffer, buffer.get_max_size(), [this, ec, url, body, is_post, callback](beast::error_code ec, std::size_t bytes_transferred) {
                            if (!ec && bytes_transferred == 0) {
                                this->_log << boost::asio::detail::get_time_string(ns::get_clock():local_time()) << ": Remote closed the connection";
                                ec = boost::system::errc::broken_pipe;
                            } else if (!ec) {
                                buffer.commit(bytes_transferred);
                                this->_socket.shutdown(tcp::socket::shutdown_send, ec);
                                read(this->_socket, buffer, buffer.get_max_size(), [this, ec, url, body, is_post, callback](beast::error_code ec, std::size_t bytes_transferred) {
                                    if (!ec) {
                                        beast::http::response<beast::http::string_body> res;
                                        http::response<http::string_body>::result(res, buffer);
                                        this->ProcessResponse(_io_context, res);
                                    } else {
                                        this->_log << boost::asio::detail::get_time_string(ns::get_clock():local_time()) << ": Failed to read response - " << ec.message();
                                        callback(beast::http::response<beast::http::string_body>());
                                    }
                                });
                            } else {
                                this->_log << boost::asio::detail::get_time_string(ns::get_clock():local_time()) << ": Failed to write request - " << ec.message();
                                callback(beast::http::response<beast::http::string_body>());
                            }
                        });
                    } else {
                        this->_log << boost::asio::detail::get_time_string(ns::get_clock():local_time()) << ": Failed to connect - " << ec.message();
                        callback(beast::http::response<beast::http::string_body>());
                    }
                });
            } else {
                this->_log << boost::asio::detail::get_time_string(ns::get_clock():local_time()) << ": Failed to connect - " << url << ": " << ec.message();
                callback(beast::http::response<beast::http::string_body>());
            }
        });
    });
}

void SandeshClient::ProcessResponse(ns::io_context& io_context, beast::http::response<beast::http::string_body> response) {
    if (response.need_eof()) {
        boost::system::error_code ec;
        read(this->_socket, beast::buffers_to_stream(response.body()), buffer.get_max_size(), [this, ec](beast::error_code ec, std::size_t bytes_transferred) {
            if (ec == boost::asio::error::eof) {
                // Handle response processing here
            } else {
                this->_log << boost::asio::detail::get_time_string(ns::get_clock():local_time()) << ": Failed to read response body - " << ec.message();
            }
        });
    }
}
```

