1. Create a `cache_manager` module that manages cache strategies using the Singleton pattern.

```python
from abc import ABC, abstractmethod
from typing import Any, Dict
import redis

class CacheManager(metaclass=type(redis.Redis)):
    def __call__(self):
        if not hasattr(self, 'instance'):
            self.instance = self()
        return self.instance

    @abstractmethod
    async def get_cache(self, key: str) -> Any:
        pass

    @abstractmethod
    async def set_cache(self, key: str, value: Any, expiry: int = 3600):
        pass

    async def delete_cache(self, key: str):
        pass
```

2. Create a `redis_cache_manager` class that extends the base CacheManager class and implements its methods using Redis.

```python
class RedisCacheManager(CacheManager):
    def __init__(self, host='localhost', port=6379, db=0):
        self._redis = redis.StrictRedis(host=host, port=port, db=db)

    async def get_cache(self, key: str) -> Any:
        return await self._redis.get(key)

    async def set_cache(self, key: str, value: Any, expiry: int = 3600):
        return await self._redis.set(key, value, ex=expiry)

    async def delete_cache(self, key: str):
        return await self._redis.delete(key)
```

