    int retryAttempts = 0;

public:
    PaymentGateway(const std::string& apiKey, const std::string& paymentGateway) {
        this->apiKey = apiKey;

        if (paymentGateway == "credit_card")
            paymentMethod.reset(new CreditCardPayment());
        else if (paymentGateway == "paypal")
            paymentMethod.reset(new PayPalPayment());
