    int processTransaction(const std::string& transactionData, int& statusCode) {
        auto startTime = std::chrono::system_clock::now();

        try {
            std::string result = paymentMethod->processTransaction(transactionData);
            logInfo("Transaction processed successfully: " + result);

            if (!result.empty()) {
                int transactionId = extractTransactionIdFromResult(result);
                auto cacheExpiration = std::chrono::seconds(30); // Configurable expiration time
                std::lock_guard<std::mutex> lock(cacheMutex);
                transactionCache[transactionId] = result;
                logInfo("Cached transaction result for transaction ID: " + std::to_string(transactionId));
            }

            statusCode = extractStatusCodeFromResult(result);
            return statusCode;
        } catch (const std::exception& e) {
            int errorStatusCode = extractErrorCodeFromException(e);
            logError("Transaction failed with error: " + e.what() + ", error code: " + std::to_string(errorStatusCode));

            if (retryAttempts < 5) {
                logWarning("Retrying transaction...");
                std::this_thread::sleep_for(std::chrono::milliseconds(std::pow(2, retryAttempts + 1) * 100)); // Exponential backoff
                ++retryAttempts;
                return processTransaction(transactionData, statusCode);
            } else {
                logError("Maximum number of retries reached. Marking transaction as failed.");
                statusCode = -1;
            }
        }

        auto endTime = std::chrono::system_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count();
        logInfo("Transaction duration: " + std::to_string(duration) + " ms");
        return statusCode;
    }

