```cpp
#include <vector>
#include <memory>

std::vector<std::unique_ptr<uint8_t[]>>& copyBufferedData(std::vector<std::unique_ptr<uint8_t[]>> &source) {
    std::vector<std::unique_ptr<uint8_t[]>> destination;

    for (auto const& data : source) {
        auto newData = std::make_unique<uint8_t[]>(data->size());
        std::copy(data.get(), data.get() + data->size(), newData.get());
        destination.push_back(std::move(newData));
    }

    return destination;
}
```

