using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Diagnostics;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Moq; // You may need to install this NuGet package for unit tests

public class WebsiteManager
{
    private readonly IConfiguration _config;
    private readonly ILogger<WebsiteManager> _logger;
    private readonly Dictionary<string, Process> _runningProcesses = new Dictionary<string, Process>();

    public WebsiteManager(IConfiguration config, ILogger<WebsiteManager> logger)
    {
        _config = config;
        _logger = logger;
    }

    public async Task<bool> AddAndStartWebsiteAsync(string directoryPath, string siteName)
    {
        if (string.IsNullOrEmpty(directoryPath)) throw new ArgumentException("Directory path cannot be null or empty.");
        if (!Directory.Exists(directoryPath)) throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");

        // Check for web.config file presence in the specified directory.
        var webConfigFile = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFile))
        {
            _logger.LogError($"Missing web.config file at '{webConfigFile}'.");
            return false;
        }

        // Determine the correct web server process based on applicationHost.config presence.
        var iisDetected = File.Exists(_config["WebServer:IISAppHostPath"]);
        string processName = iisDetected ? "iisexpress" : "apache";

        // Integrate with a configuration management system to store and retrieve site details (not included).

        lock (_runningProcesses)
        {
            if (_runningProcesses.ContainsKey(siteName))
            {
                _logger.LogWarning($"The website '{siteName}' is already running.");
                return false;
            }
        }

        try
        {
            var processInfo = new ProcessStartInfo();
            processInfo.FileName = $"{processName}.exe";
            processInfo.Arguments = $"'{webConfigFile}' /site: {siteName}";

            var process = new Process { StartInfo = processInfo };
            process.Start();

            lock (_runningProcesses) _runningProcesses.Add(siteName, process);
            return true;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to start the website '{siteName}'.");
            return false;
        }
    }
}
```

