#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>
#include <time.h>
#include <semaphore.h>
#include <syslog.h>

typedef struct {
    u_char ip[16];
    time_t expiration;
} ResolvedIp;

static sem_t lock;
static ResolvedIp cache[256];
static int num_cache = 0;
static pthread_mutex_t mutex_cache = PTHREAD_MUTEX_INITIALIZER;
static sem_t sem_requests;
static int max_concurrent_requests = 4;

void cleanup(int socket) {
    close(socket);
}

void log_resolution(const char *hostname, u_char *ip, int success) {
    struct tm tm;
    char log_str[256];

    if (success) {
        strftime(&tm, sizeof(tm), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        snprintf(log_str, sizeof(log_str), "DNS resolution success: %s -> %s", hostname, inet_ntoa(*((struct in_addr *)ip)));
    } else {
        strftime(&tm, sizeof(tm), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        snprintf(log_str, sizeof(log_str), "DNS resolution failed: %s", hostname);
    }

    syslog(LOG_INFO, log_str);
}

int resolveHostname(const char *hostname, u_char ip[16]) {
    int socket;
    struct addrinfo hints, *result, *ptr;
    int error = 0;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;     /* Allow IPv4 or IPv6 */
    hints.ai_socktype = SOCK_STREAM;/* DNS query type */

    if ((error = getaddrinfo(hostname, NULL, &hints, &result)) != 0) {
        log_resolution(hostname, ip, 0);
        return error;
    }

    socket = socket(result->ai_family, result->ai_socktype, result->ai_protocol);
    if (socket < 0) {
        freeaddrinfo(result);
        log_resolution(hostname, ip, 0);
        return -1;
    }

    sem_wait(&sem_requests);

    if (pthread_mutex_lock(&mutex_cache)) {
        cleanup(socket);
        pthread_mutex_unlock(&mutex_cache);
        freeaddrinfo(result);
        log_resolution(hostname, ip, 0);
        return -1;
    }

    int found = 0;
    for (ptr = cache; ptr < cache + num_cache && !found; ++ptr) {
        if ((time(NULL) <= ptr->expiration) && (memcmp(ptr->ip, ip, sizeof(ptr->ip)) == 0)) {
            found = 1;
        }
    }

    if (found) {
        pthread_mutex_unlock(&mutex_cache);
        sem_post(&sem_requests);
        goto cleanup;
    }

    struct timeval timeout = {5, 0}; /* 5 seconds */
    if (connect(socket, result->ai_addr, result->ai_addrlen) < 0) {
        getnameinfo(result->ai_addr, result->ai_addrlen, ip, sizeof(ip), NULL, 0, NI_NUMERICHOST);
        freeaddrinfo(result);
        log_resolution(hostname, ip, 0);
        cleanup(socket);
        pthread_mutex_unlock(&mutex_cache);
        sem_post(&sem_requests);
        return -1;
    }

    if (getnameinfo(result->ai_addr, result->ai_addrlen, ip, sizeof(ip), NULL, 0, NI_NUMERICHOST) < 0) {
        cleanup(socket);
        log_resolution(hostname, ip, 0);
        pthread_mutex_unlock(&mutex_cache);
        sem_post(&sem_requests);
        return -1;
    }

    memcpy(ptr->ip, ip, sizeof(ptr->ip));
    ptr->expiration = time(NULL) + 60 * 5; /* Cache for 5 minutes */

    pthread_mutex_unlock(&mutex_cache);
    sem_post(&sem_requests);

cleanup:
    freeaddrinfo(result);
    close(socket);

    return 0;
}
```

