    public async Task<string> CalculateMd5HashFromFileAsync(string filePath)
    {
        using (var md5 = MD5.Create())
        {
            await UsingStreamForReadingAsync(File.OpenRead(filePath), stream =>
            {
                var buffer = new byte[CHUNK_SIZE];
                int bytesRead;
                while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
