const asyncReduce = (arr, initialValue, callback, options) => {
  const { validateArray, validateElement, onProgress, verbosity } = options || {};

  if (!Array.isArray(arr)) throw new Error('Input must be an array');
  if (!arr.length) throw new Error('Array cannot be empty');

  let result = initialValue;
  const validElements = [];

  const validateElementFn = (element, index, array) => {
    if (!validateElement || validateElement(element, index, array)) {
      return validElements.push(element);
    }
  };

  if (validateArray && !validateArray(arr)) throw new Error('Input array failed validation');
  arr.forEach(validateElementFn);

  const processElement = async (index, callback) => {
    if (!validElements[index]) return Promise.resolve(result); // Skip invalid elements

    try {
      result = await callback(result, validElements[index], index, arr);
      onProgress && onProgress(`Processed element ${index}: ${result}`);
    } catch (error) {
      console.error(`Error while processing element ${index}: ${error.message}`); // You can customize the error handling as per your requirements
      return Promise.resolve(result);
    }
    return processElement(index + 1, callback);
  };

  const runAsyncReduce = async () => {
    try {
      await processElement(0, callback);
      return result;
    } catch (error) {
      console.error(`An error occurred during reduction: ${error.message}`); // You can customize the error handling as per your requirements
      throw error;
    }
  };

  if (verbosity > 1) console.log('Initializing asynchronous reduce...');
  runAsyncReduce();
};
