import java.util.concurrent.Executors;

public class ChatServer {
  public static void main(String[] args) throws Exception {
    Security.addProvider(new BouncyCastleProvider());
    SSLContext sslCtx = SSLContext.getInstance("TLS");
    sslCtx.init(null, null, null); // Configure your TLS/SSL parameters here

    EventLoopGroup bossGroup = new MultithreadEventLoopGroup(4);
    EventLoopGroup workerGroup = Executors.newWorkingThreadPool(8);

    try {
      final ChatServerHandler chatHandler = new ChatServerHandler();
      ServerBootstrap bootstrap = new ServerBootstrap();
      bootstrap.group(bossGroup, workerGroup)
               .channel(NioServerSocketChannel.class)
               .childHandler(new ChannelInitializer<SocketChannel>() {
                 @Override
                 protected void initChannel(SocketChannel ch) throws Exception {
                   ch.pipeline().addLast(chatHandler);
                 }
               })
               .option(ChannelOption.SO_BACKLOG, 128)
               .childOption(ChannelOption.SO_KEEPALIVE, true)
               .bind(8080).sync(); // Bind to your desired port

      System.out.println("Chat server started on port 8080");
      Thread.onDestroyHook(() -> {
        bossGroup.shutdownGracefully();
        workerGroup.shutdownGracefully();
      });
    } catch (InterruptedException e) {
      e.printStackTrace();
    }
  }
}
