use reqwest::{Client, CertificateValidator};
use std::env;

pub fn init_http_client() -> Client {
    let verify = if env::var("INSECURE").is_err() {
        CertificateValidator::new(true).add_builtin_ca()
    } else {
        CertificateValidator::none()
    };

    Client::builder()
        .default_headers(reqwest::header::HeaderMap::new())
        .certificate_verifier(verify)
        .build()
        .expect("Failed to build HTTP client")
}

pub fn request_builder(url: &str) -> reqwest::RequestBuilder {
    init_http_client().request(reqwest::Method::GET, url)
}
```

