  const apiKey = process.env.API_KEY;
  const headers = {
    'Accept': 'application/json',
    'Content-Type': 'application/json'
  };

  const requests = cityNames.map(city => ({url: `${url}?q=${city}&appid=${apiKey}`, method: 'GET'}));
  let responses, failures = [];

  while (responses.length < cityNames.length) {
    // Exponential backoff and jitter strategy to handle rate limits
    const requestsToProcess = _.take(requests, 10);
    const promises = requestsToProcess.map(({url, method}) => axios[method](url, {headers}));
    responses = await Promise.all(promises).catch((error) => {
      failures.push({city: requestsToProcess[failedIndex].url.split('=')[1], error});
      console.log(`Failed to fetch data for ${requestsToProcess[failedIndex].url.split('=')[1]}:`, error);
