  const validUrlRegex = /(http|https):\/\/(\w+:{1}\w+@)?(\S+)(:[\d]+)?(\/|\/([\w#!:.?+=&%!\/\-]*))?/;

  if (!url.match(validUrlRegex)) {
    throw new Error('Invalid URL');
  }

  const serviceModule = cloudStorageModules[serviceType];

  if (!serviceModule) {
    throw new Error(`Unsupported cloud storage service type: ${serviceType}`);
  }

  // Validate the rate limiter
  // ... (Implement your rate limiter logic here)

  let fileData;

  try {
    const response = await axios.get(url, { responseType: 'arraybuffer' });
    fileData = response.data;
  } catch (error) {
    logger.error(`Failed to download file from URL: ${url}. Error: ${error.message}`);
    throw error;
  }

  if (fileData.length > 100e6) { // 100MB
    const chunkSize = 10e6; // 10MB chunks
    let start = 0;
    let end;

    do {
      end = Math.min(start + chunkSize, fileData.length);
      await serviceModule.uploadChunk({ fileData: fileData.slice(start, end), metadata: { key: 'value' } }); // Upload the current chunk with metadata
      start = end;
    } while (start < fileData.length);
  } else {
    await serviceModule.upload({ fileData, metadata: { key: 'value' } }); // Upload the entire file with metadata
  }
};

