```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>

#define MAX_RECORDS 1000
#define MIN_TIMESTAMP (time_t)0
#define MAX_TIMESTAMP ((time_t)LONG_MAX - 1)
#define MIN_EVENT_ID 1
#define MAX_EVENT_ID 100

typedef struct {
    time_t timestamp;
    int event_id;
    char* message;
} record;

struct logging_system {
    record* records;
    size_t current_index;
    pthread_mutex_t lock;
};

record* create_record() {
    record* new_record = mmap(NULL, sizeof(record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_record == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    return new_record;
}

struct logging_system* initialize_logging_system(size_t num_records) {
    struct logging_system* log_sys = malloc(sizeof(struct logging_system));
    if (!log_sys) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    log_sys->records = calloc(num_records, sizeof(record));
    if (!log_sys->records) {
        perror("calloc failed");
        free(log_sys);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&(log_sys->lock), NULL);
    log_sys->current_index = 0;

    return log_sys;
}

void destroy_logging_system(struct logging_system* log_sys) {
    munmap(log_ys->records, sizeof(record) * log_sys->num_records);
    free(log_sys);
}

int create_and_add_record(struct logging_system* log_sys, const char* message) {
    if (log_sys->current_index >= MAX_RECORDS) {
        fprintf(stderr, "No more space for records.\n");
        return -1;
    }

    record* new_record = create_record();
    new_record->timestamp = time(NULL);
    new_record->event_id = rand() % (MAX_EVENT_ID - MIN_EVENT_ID + 1) + MIN_EVENT_ID;

    size_t message_len = strlen(message) + 1;
    new_record->message = malloc(message_len);
    if (!new_record->message) {
        perror("malloc failed");
        free(new_record);
        return -1;
    }

    strcpy(new_record->message, message);

    pthread_mutex_lock(&(log_sys->lock));
    log_sys->records[log_sys->current_index] = *new_record;
    log_sys->current_index++;
    pthread_mutex_unlock(&(log_sys->lock));

    return 0;
}
```

In this code, I created a `struct logging_system` to manage the collection of `record` structures. The initialization function, `initialize_logging_system`, dynamically allocates memory for the `records` array and initializes a mutex lock to ensure thread safety. The `create_and_add_record` function creates a new `record` structure with random timestamps and event IDs within specified ranges, handles memory allocation errors, and ensures concurrent access is thread-safe using a mutex lock.

To optimize memory usage, I use mmap for creating the `record` structures, which reduces copying and duplicating data when allocating large amounts of memory. Additionally, I allocate the exact amount of memory needed for each message dynamically, avoiding wasted space.

