```javascript
const fs = require('fs-extra');
const path = require('path');
const AWS = require('aws-sdk');
const { promisify } = require('util');

// Configure S3 client with appropriate region and access keys
const s3 = new AWS.S3({ /* your config here */ });

const readDirectory = async (directory, extension, timeout) => {
  const queue = [];
  let processNextFile = () => {
    if (!queue.length) return;
    const filePath = queue.shift();

    // Skip hidden files or non-matching extensions
    if (filePath.startsWith('.'); || !path.extname(filePath).toLowerCase().endsWith(extension)) {
      processNextFile();
      return;
    }

    const promise = new Promise((resolve, reject) => {
      const fileStream = fs.createReadStream(filePath);

      // Handle error and continue processing other files
      fileStream.on('error', err => {
        console.warn(`Error reading ${filePath}: ${err.message}`);
        return;
      });

      // Check if the file is larger than 1MB, skip it for performance reasons
      fileStream.once('data', chunk => {
        if (chunk.length > 1048576) {
          console.log(`Skipping large file: ${filePath}`);
          return;
        }
      });

      // Read the entire file and upload it to S3 when done
      let data = '';
      fileStream.on('data', chunk => data += chunk);
      fileStream.on('end', () => {
        s3.putObject({ /* your S3 config here */, Body: data, Key: path.relative(directory, filePath) }, (err, data) => {
          if (err) console.warn(`Error uploading ${filePath}: ${err.message}`);
          resolve({ filename: filePath, content: data });
        });
      });
    });

    // Timeout the read operation to prevent hanging on slow or unresponsive files
    const timeoutId = setTimeout(() => {
      console.warn(`Timeout reading ${filePath}`);
      promise.reject(new Error(`Timeout reading ${filePath}`));
    }, timeout);

    fileStream.on('close', () => clearTimeout(timeoutId));

    // Add the file to the processing queue
    queue.push(promise);
  };

  try {
    await promisify(fs.readdir)(directory).then(files => files.forEach(file => queue.push(path.join(directory, file))));
  } catch (err) {
    console.warn(`Error reading ${directory}: ${err.message}`);
  }

  processNextFile();

  // Return a promise that resolves when all files are processed or an error occurs
  return Promise.all(queue);
};
```

