namespace fs = boost::filesystem;
namespace asio = boost::asio;

using MetadataTags = boost::container::flat_map<std::string, std::string>;
class CloudStorageService {
public:
    virtual ~CloudStorageService() {}
    virtual int uploadFile(const std::string& filePath, const std::string& bucketName, const MetadataTags& tags) = 0;
    // ... other API methods to support different cloud storage services
};

struct UploadAndMonitorFileOptions {
    size_t chunkSize = 1 << 20; // Default chunk size is 1MB
    int maxRetries = 3;
    asio::io_service ioService;
};

class UploadAndMonitorFile {
public:
    explicit UploadAndMonitorFile(const UploadAndMonitorFileOptions& options) : m_options(options) {}

    int uploadAndMonitorFile(const std::string& filePath, const std::string& bucketName, const MetadataTags& tags = {}) {
        if (!fs::exists(filePath) || !fs::is_regular_file(filePath)) {
            logError("The specified file does not exist or is not a regular file.");
            return -1;
        }

        std::ifstream inputFile(filePath, std::ios::binary);
        if (!inputFile.is_open()) {
            logError("Failed to open the file for reading.");
            return -1;
        }

        SHA256Context context;
