    public class FilePathValidator
    {
        private const int MaxBufferSize = 1024 * 1024; // 1MB
        public bool IsAbsolute(string path) => string.IsNullOrEmpty(path) || Regex.IsMatch(path, @"^/");

        public string ValidateAndExpandPathIfNeeded(string path, out bool isValid, out string errorMessage)
        {
            if (string.IsNullOrWhiteSpace(path))
            {
                isValid = false;
                errorMessage = "Invalid empty path.";
                return null;
            }

            if (!IsAbsolute(path))
            {
                var currentDir = Environment.CurrentDirectory;
                path = System.IO.Path.Combine(currentDir, path);
            }

            if (System.IO.File.Exists(path) && File.ReadAllText(path).Length > MaxBufferSize)
            {
                isValid = false;
                errorMessage = $"Path '{path}' exceeds the maximum buffer size of {MaxBufferSize} bytes.";
                return null;
            }

            try
            {
                var fileInfo = new FileInfo(path);
                isValid = true;
                errorMessage = string.Empty;
                return path;
            }
            catch (Exception ex)
            {
                isValid = false;
