```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Diagnostics;
using System.Runtime.ExceptionServices;

public class CustomRandomGenerator : IDisposable
{
    private Random _random;
    private (double min, double max) _range;
    private double _meanValue;
    private double _seed;

    private readonly object _lock = new object();
    private readonly List<Action> _logActions = new List<Action>();

    public CustomRandomGenerator()
    {
        SetRange(default, default);
        SetSeed(Environment.TickCount64);
    }

    public void SetRange(double min, double max)
    {
        if (min >= max)
            throw new ArgumentException("Inclusive range must be less than exclusive.");
        _range = (Math.Min(min, max), Math.Max(min, max));
    }

    public void SetRange<T>(Func<T, T> minFunc, Func<T, T> maxFunc)
    {
        if (!typeof(T).IsGenericType || !typeof(T).GetGenericArguments().Any())
            throw new ArgumentException("minFunc and maxFunc must both be generic functions.");

        var min = minFunc.Invoke(default!);
        var max = maxFunc.Invoke(default!);
        SetRange((double)min, (double)max);
    }

    public void SetMeanValue(double meanValue)
    {
        _meanValue = Math.Clamp(meanValue, _range.min, _range.max);
    }

    public double NextDouble()
    {
        LockAndLog();
        return _random.NextDouble() * (_range.max - _range.min) + _range.min + (_meanValue - _range.min);
    }

    public T Next<T>(T defaultValue = default)
    {
        if (!typeof(T).IsGenericType || !typeof(T).GetGenericArguments().Any())
            throw new ArgumentException("T must be a numeric type.");

        var value = NextDouble();
        return (T)(value > _range.max ? defaultValue : (T)Convert.ChangeType(value, typeof(T)));
    }

    public IEnumerable<T> Sequence<T>(int count = 1)
    {
        if (!typeof(T).IsGenericType || !typeof(T).GetGenericArguments().Any())
            throw new ArgumentException("T must be a numeric type.");

        var sequence = Enumerable.Repeat(defaultValue: default, count);
        Parallel.ForEach(sequence, (Action<T>)((item) => item = Next<T>()));
        return sequence;
    }

    public void SetSeed(long seed)
    {
        _seed = Math.Abs(BitConverter.DoubleToBigEndianBytes(new DateTimeOffset(seed).ToUnixTimeSeconds()).AsSpan().Aggregate((a, b) => a ^ b));
        _random = new Random((int)_seed);
    }

    public void Reset()
    {
        SetSeed(Environment.TickCount64);
    }

    public override string ToString()
    {
        return $"Range: [{_range.min}, {_range.max}), Seed: {_seed}, Mean Value: {_meanValue}";
    }

    private void LockAndLog()
    {
        lock (_lock)
        {
            foreach (var action in _logActions) action();
            _logActions.Clear();
        }
    }

    public void Log(Action action)
    {
        _logActions.Add(action);
    }

    public void Dispose()
    {
        // Implement any cleanup or disposal logic here if needed.
    }
}
```

