```python
import heapq
import itertools
from concurrent.futures import ThreadPoolExecutor

def merge_sorted_lists(*lists):
    if not lists:
        return []

    # Use a thread pool for concurrent processing
    executor = ThreadPoolExecutor(max_workers=min(len(lists), 10))

    def compare_and_yield(left, right):
        while True:
            try:
                if not left:
                    next_val = next(right)
                elif not right:
                    next_val = next(left)
                else:
                    next_val = min(next(left), next(right))
            except StopIteration:
                break

            yield next_val

    # Create a generator that produces tuples of (list, iterator pair)
    data = itertools.zip_longest(*(iter(l) for l in lists), fillvalue=(None, None))

    pairs = executor.map(compare_and_yield, data)

    min_heap = []
    heapq.heappush(min_heap, next(pairs))

    while min_heap:
        smallest = heapq.heappop(min_heap)
        yield smallest[0]

        try:
            next_val = smallest[1]
        except TypeError:
            continue

        heapq.heappush(min_heap, (next(pairs), next_val))

    executor.shutdown(wait=False)
```

This function uses a thread pool for concurrent processing and a min-heap for efficient comparison and merging of elements from multiple sorted lists. The external sorting library used is Python's built-in heapq module. The function handles situations where generators produce elements at different rates or fail due to resource limitations by gracefully moving on to the next generator pair in the data stream.

