<?php

function updateClinicStatus($conn, $clinicId) {
    // Validate input
    if (!is_numeric($clinicId)) {
        error_log("Invalid clinic ID: {$clinicId}", E_USER_WARNING);
        return false;
    }

    // Fetch the current clinic data and check if it exists
    $query = "SELECT status, ip_address FROM clinics WHERE id = ?";
    $stmt = mysqli_prepare($conn, $query);
    mysqli_stmt_bind_param($stmt, 'i', $clinicId);
    mysqli_stmt_execute($stmt);
    mysqli_stmt_store_result($stmt);

    if (mysqli_stmt_num_rows($stmt) === 0) {
        error_log("Clinic not found: {$clinicId}", E_USER_WARNING);
        return false;
    }

    // Fetch the current status and IP address
    mysqli_stmt_bind_result($stmt, $currentStatus, $currentIpAddress);
    mysqli_stmt_fetch($stmt);

    // Update the clinic's status, last modified IP address, and last modified timestamp
    $ipAddress = $_SERVER['REMOTE_ADDR'];
    $timestamp = time();
    $query = "UPDATE clinics SET status = ?, ip_address = ?, last_modified_timestamp = ? WHERE id = ?";
    $stmt = mysqli_prepare($conn, $query);
    mysqli_stmt_bind_param($stmt, 'sssi', $newStatus, $ipAddress, $timestamp, $clinicId);

    // Handle database connection issues and retries
    $retries = 3;
    do {
        if (!mysqli_stmt_execute($stmt)) {
            error_log("Failed to execute update query: " . mysqli_error($conn), E_USER_ERROR);
            return false;
        }

        // Fetch the updated clinic data to verify success and ensure data integrity
        $query = "SELECT status, ip_address FROM clinics WHERE id = ?";
        $stmt = mysqli_prepare($conn, $query);
        mysqli_stmt_bind_param($stmt, 'i', $clinicId);
        mysqli_stmt_execute($stmt);
        mysqli_stmt_store_result($stmt);

        if (mysqli_stmt_num_rows($stmt) === 0) {
            error_log("Failed to update clinic: {$clinicId}", E_USER_ERROR);
            return false;
        }

        mysqli_stmt_bind_result($stmt, $updatedStatus, $updatedIpAddress);
        mysqli_stmt_fetch($stmt);

        // Check if the update was successful and data integrity is preserved
        if ($updatedStatus === $newStatus && $updatedIpAddress === $ipAddress) {
            error_log("Clinic updated successfully: {$clinicId}", E_USER_NOTICE);
            return true;
        } else {
            error_log("Failed to update clinic: Data integrity issue", E_USER_ERROR);
            return false;
        }
    } while (--$retries > 0 && mysqli_errno($conn) == MYSQLI_ERR_TIMEOUT);
}
```

