import asyncio
import aiosignal
import json
import requests
from typing import Callable, List, Dict

def fetchAndProcessData(api_urls: List[str], data_processor: Callable[[Dict], Dict] = None, timeout: int = 10, max_concurrent_requests: int = 5) -> Dict:
    tasks = []
    results = {}

    async def api_task(url: str, index: int) -> Dict:
        headers = {
            # Add custom headers if needed
        }
        params = {
            # Add custom query parameters if needed
        }
        try:
            response = await asyncio.wait_for(requests.get(url, headers=headers, params=params, timeout=timeout), timeout=timeout)
        except requests.exceptions.RequestException as e:
            print(f'Error fetching from {url}: {e}')
            return None

        if response.status_code != 200:
            print(f'Invalid status code from {url}: {response.status_code}')
            return None

        data = response.json()
        if not data:
            print(f'Empty response from {url}')
            return None

        try:
            processed_data = data_processor(data) if data_processor else data
        except Exception as e:
            print(f'Error processing data from {url}: {e}')
            return None

        results[index] = processed_data
        return processed_data

    for index, url in enumerate(api_urls):
        tasks.append(asyncio.create_task(api_task(url, index)))

    done, pending = await asyncio.wait(tasks, return_when=asyncio.FIRST_COMPLETED)

    for task in pending:
        if not task.result():
            print('API request timed out or failed')

    return {k: v for k, v in sorted(results.items()) if v is not None}
```

