```rust
use std::fs::File;
use std::io::{BufReader, Read};
use std::path::Path;

use lexer::{Lexer, LexerError};
use parser::{Parser, ParserError};
use ir_generator::{IrGenerator, IrGeneratorError};

pub fn generate_llvm_ir(file_path: &str, grammar_def: &str) -> Result<String, Box<dyn std::error::Error>> {
    let file = File::open(file_path)?;
    let reader = BufReader::new(file);
    let lexer = Lexer::new(reader, grammar_def)?;
    let tokens = lexer.lex()?;
    let parser = Parser::new(tokens, grammar_def)?;
    let ast = parser.parse()?;
    let ir_generator = IrGenerator::new(grammar_def)?;
    let llvm_ir = ir_generator.generate(ast)?;
    Ok(llvm_ir)
}
```

