using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading;
using UnityEngine;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using OpenSSLSharp;

namespace DynamicCryptoGenerator
{
    public class CryptoConfig
    {
        public Dictionary<string, string> Algorithms { get; set; }
        public string ConfigFile { get; set; }
    }

    public abstract class Distribution
    {
        protected RandomSource _randomSource;
        protected int _minValue;
        protected int _maxValue;
        protected bool _isInclusive;
        protected string _type;

        protected Distribution(RandomSource randomSource, int minValue, int maxValue, bool isInclusive, string type)
        {
            _randomSource = randomSource;
            _minValue = minValue;
            _maxValue = maxValue;
            _isInclusive = isInclusive;
            _type = type;
        }

        public abstract int Next();
    }

    public class GaussianDistribution : Distribution
    {
        private readonly double _mean;
        private readonly double _standardDeviation;

        public GaussianDistribution(RandomSource randomSource, double mean, double standardDeviation) : base(randomSource, int.MinValue, int.MaxValue, false, "Gaussian")
        {
            _mean = mean;
            _standardDeviation = standardDeviation;
        }

        public override int Next() => (int)(_mean + _standardDeviation * _randomSource.NextGaussian());
    }

    // Add other distribution classes like UniformDistribution, ExponentialDistribution, etc.

    public class RandomSource
    {
        private readonly HashSet<Type> _distributions;
        private readonly Dictionary<Type, IDictionary<string, object>> _parameters;

        public void AddDistribution(Type distributionType, IDictionary<string, object> parameters)
        {
            _distributions.Add(distributionType);
            _parameters[distributionType] = parameters;
        }

        public T GetRandomValue<T>(Type distributionType, string parameterName) where T : struct
        {
            if (!_distributions.Contains(distributionType))
                throw new ArgumentException($"Invalid distribution type: {distributionType}");

            var distributionParameters = _parameters[distributionType];
            if (!distributionParameters.ContainsKey(parameterName))
                throw new ArgumentException($"Invalid parameter name: {parameterName} for distribution type: {distributionType}");

            dynamic parameters = distributionParameters[parameterName];
            var distribution = Activator.CreateInstance(distributionType, this) as IDistributedRandomSource<T>;
            return distribution.Next();
        }
    }

    public class DynamicCryptoGenerator : IDisposable
    {
        private readonly CryptoConfig _config;
        private readonly RandomSource _randomSource;
        private readonly Dictionary<string, Func<ICryptoTransform>> _algorithms;

        public DynamicCryptoGenerator(CryptoConfig config)
        {
            _config = config;
            _randomSource = new RandomSource();
            LoadAlgorithms();
        }

        private void LoadAlgorithms()
        {
            var cryptoProviderFactory = OpenSsl.Cryptography.CryptoProviderFactory.CreateFromFile(_config.ConfigFile);
            var availableHashes = cryptoProviderFactory.GetAlgorithmNames(HashAlgorithmType.Hash384, HashAlgorithmType.Hash512);
            var availableSymmetrics = cryptoProviderFactory.GetAlgorithmNames(SymmetricEncryptionAlgorithmType.Aes128, SymmetricEncryptionAlgorithmType.ChaCha20);
            var availableAsymmetrics = cryptoProviderFactory.GetAlgorithmNames(AsymmetricEncryptionAlgorithmType.Rsa, AsymmetricEncryptionAlgorithmType.DSA);

            _algorithms = new Dictionary<string, Func<ICryptoTransform>>
            {
                { "AES-256", () => Aes.Create(_config.GetHashFromKey("AES-256-Key"), _config.GetHashFromKey("AES-256-IV")) },
                { "ChaCha20", () => ChaCha20.Create() },
                { "SHA-256", () => SHA256.Create() },
                { "SHA-384", () => SHA384.Create() },
                { "SHA-512", () => SHA512.Create() }
            };
        }

        public ICryptoTransform GetAlgorithm(string algorithm)
        {
            if (_algorithms.TryGetValue(algorithm, out var algorithmFunc))
                return algorithmFunc();

            throw new ArgumentException($"Invalid algorithm: {algorithm}");
        }

        // Implement the rest of the methods as specified in your description

        public override string ToString() => $"DynamicCryptoGenerator {{ Range: [{(int)_randomSource.GetRandomValue<int>(typeof(UniformDistribution), "min")},{(int)_randomSource.GetRandomValue<int>(typeof(UniformDistribution), "max")]}, Distribution: {_randomSource.GetRandomValue<string>(typeof(GaussianDistribution), "type")}}";

        public void Dispose()
        {
            // Implement disposable pattern to cleanup resources here
        }
    }
}
```

