function updateUserPassword($userId, $newPassword) {
    global $db;
    $hashedPassword = hash('sha256', $newPassword); // Hash the password using SHA-256
    $strengthCriteria = preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/', $hashedPassword);
    if ($strengthCriteria === 0) {
        // Log the error and return with an appropriate status code
        logError('Password strength does not meet criteria');
        http_response_code(400);
        die();
    }

    $stmt = $db->prepare("UPDATE users SET password=? WHERE id=?");
    $stmt->execute([$hashedPassword, $userId]);
}
