#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <string.h>
#include <stdlib.h>

void initializeAES256GCM(const char* password, const char* salt, unsigned char* key, uint8_t* iv) {
    // Derive a key using PBKDF2 with SHA-256 and the given password and salt
    int derivingKeyLength = 32;
    unsigned char key[derivingKeyLength];
    PKCS5_PBKDF2_HMAC(SHA256, password, strlen(password), salt, strlen(salt), derivingKeyLength, key);

    // Initialize AES-256-GCM with the derived key and a random initialization vector (iv)
    AES_KEY aes;
    AES_set_encrypt_key(key, 256, &aes);
    randombytes_exact(AES_BLOCK_SIZE, iv);
}
