        {
            _httpClient = httpClient;
        }

        public async Task<bool> AddSensorDataAsync(SensorData data)
        {
            // Atomic update of dashboard with new sensor data
            var response = await _httpClient.PostAsJsonAsync("https://dashboard-api.com/update", data);
            return response.IsSuccessStatusCode;
        }
    }

