using MongoDB.Driver;

namespace CloudEncryptionModule
{
    public interface IDecryptionService
    {
        Task<decimal> DecryptAsync(string fileId, string encryptionKey);
        IMongoCollection<LogEntry> Logs { get; }
        IExternalScriptExecutor ExternalScriptExecutor { get; }
    }

    public abstract class DecryptionService : IDecryptionService
    {
        protected readonly Dictionary<string, IStorageAdapter> Adapters;
        protected readonly ISecureKeyStore KeyStore;
        protected readonly IResourceManager ResourceManager;
        protected readonly IExternalScriptExecutor ExternalScriptExecutor;
        protected IMongoCollection<LogEntry> Logs => _logCollection.Find(_ => true).Observe();

        private MongoDatabase _database;
        private MongoCollectionSettings _logCollectionSettings;
        private IStorageAdapter _currentAdapter;
        private AesManaged _aesAlgorithm;

        protected DecryptionService(IResourceManager resourceManager, ISecureKeyStore keyStore, IEnumerable<IStorageAdapter> adapters, IExternalScriptExecutor externalScriptExecutor)
        {
            Adapters = new Dictionary<string, IStorageAdapter>(adapters);
            KeyStore = keyStore;
            ResourceManager = resourceManager;
            ExternalScriptExecutor = externalScriptExecutor;
            InitializeAesAlgorithm();
        }

        public abstract Task<decimal> DecryptAsync(string fileId, string encryptionKey);

        protected IStorageAdapter CurrentAdapter
        {
            get => _currentAdapter ?? throw new InvalidOperationException("No storage adapter is currently set.");
            private set => _currentAdapter = value;
        }

        protected void SetCurrentAdapter(string name)
        {
            if (!Adapters.TryGetValue(name, out var adapter))
                throw new ArgumentException($"Storage adapter '{name}' not found.", nameof(name));

            CurrentAdapter = adapter;
        }

        protected void SetDatabase(MongoDatabase database)
        {
            _database = database;
            _logCollectionSettings = new MongoCollectionSettings { CollectionName = "Logs" };
        }

        private void InitializeAesAlgorithm()
        {
            var aes = new AesManaged();
            aes.KeySize = 256;
            aes.BlockSize = 128;
            _aesAlgorithm = aes;
        }
    }
}
