public static XElement GetFirstMatchingElement(XDocument doc, string xpath) {
    var nodes = doc.XPathSelectElements(xpath);
    if (nodes.Count() > 1) throw new Exception("Multiple elements found with given name.");
    if (nodes.Count() == 0) throw new Exception("No element found with given name.");
    return nodes.First();
}
