char* addSlashIfNeeded(const char* str, size_t limit) {
    if (strlen(str) >= limit) return NULL;
    char* newStr = malloc(limit + 1);
    strcpy(newStr, str);
    newStr[strlen(str)] = '/';
    return newStr;
}
