import os
import csv
from functools import partial
import logging

def process_csv_directory(directory, filter_condition, output_path, storage_backend, logger=None):
    if not logger:
        logger = logging.getLogger(__name__)

    for file in os.listdir(directory):
        if file.endswith(".csv"):
            file_path = os.path.join(directory, file)

            try:
                with open(file_path, 'r') as csv_file:
                    reader = csv.reader(csv_file)
                    next(reader)  # Skip the header row

                    filtered_data = []
                    for row in reader:
                        if filter_condition(*row):
                            filtered_data.append(row)

                    storage_backend.save_filtered_data(filtered_data, output_path)
            except Exception as e:
                logger.warning(f"Error processing file {file}: {e}")
