import java.util.concurrent.ConcurrentHashMap;
import java.util.zip.GZIPInputStream;

public class Deserializer {
    private static final ConcurrentHashMap<String, Class<?>> classCache = new ConcurrentHashMap<>();
    private static final ObjectMapper objectMapper = new ObjectMapper(); // Assuming you're using Jackson for serialization/deserialization

    public <T> T deserialize(byte[] data) throws IOException {
        // Validate the integrity of the byte array before attempting deserialization
        if (data == null || data.length <= 0) {
            throw new RuntimeException("Invalid or empty byte array.");
        }

        // Attempt to retrieve the class definition from the API if outdated
        Class<?> clazz = getClassFromAPI(data);

        // If the class is not found in the cache, attempt deserialization with the provided class
        if (clazz == null || !classCache.containsKey(clazz.getName())) {
            try (ObjectInputStream ois = new ObjectInputStream(new GZIPInputStream(new ByteArrayInputStream(data)))) {
                return (T) ois.readObject();
            } catch (ClassNotFoundException | ClassCastException e) {
                throw new RuntimeException("Failed to deserialize object with provided class.", e);
            }
        }

        // Return the recently deserialized object from cache if available
        Object obj = classCache.get(clazz.getName());
        if (obj != null && obj instanceof T) {
            return (T) obj;
        }

        try (ObjectInputStream ois = new ObjectInputStream(new GZIPInputStream(new ByteArrayInputStream(data)))) {
            T object = (T) ois.readObject();
            classCache.put(clazz.getName(), object); // Cache the deserialized object for future use
            return object;
        } catch (ClassNotFoundException | ClassCastException e) {
            throw new RuntimeException("Failed to deserialize object with provided class.", e);
        }
    }

    private Class<?> getClassFromAPI(byte[] data) throws IOException, URISyntaxException {
