// Middleware to handle caching and rate limiting
async function rateLimiter(req, res, next) {
  const key = `rate-limit:${req.ip}`;
  const count = await getRedisAsync(key);
  if (count >= 60) { // Rate limit of 60 requests per minute
    return res.status(429).send('Too Many Requests');
  }

  redisClient.incr(key, err => {
    if (err) return next(err);
    next();
  });
}

// Router for weather service endpoints
