using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Data;
using System.Security.Cryptography;
using Newtonsoft.Json;
using CompressionService; // ICompressor, LZ4Stream or GZipStream
using MemoryMappedFileService; // IMemoryMappedFile
using EncryptionService; // IEncrypter
using DatabaseConnection; // IDatabaseConnection

public async Task<DataTableReader> CompressAndSend(byte[] data)
{
    Stopwatch sw = Stopwatch.StartNew();

    using (var compressor = CompressionService.CreateCompressor())
    {
        var compressedData = await Task.Run(() => compressor.Compress(data));
        LogCompressionStats(compressedData, data.Length);

        using (var encrypter = EncryptionService.CreateEncrypter())
        {
            var encryptedData = await Task.Run(() => encrypter.Encrypt(compressedData));
            LogEncryptionStats(encryptedData.Length, compressedData.Length);

            using (var mmf = MemoryMappedFileService.CreateMemoryMappedFile())
            {
                mmf.Write(encryptedData);
                LogMemoryMappedFileUsage();

                var dbConnection = DatabaseConnection.GetConnection();
                await Task.Run(() => dbConnection.Upload(mmf));
                LogDatabaseOperationTime();

                using (var command = dbConnection.CreateCommand())
                {
                    command.CommandText = "SELECT * FROM CompressedData";
                    var reader = new DataTableReader(command.ExecuteReader());
                    return reader;
                }
            }
        }
    }
}

private void LogCompressionStats(byte[] compressed, long originalSize)
{
    var compressionRatio = (originalSize - compressed.Length) / (double)originalSize;
    Console.WriteLine($"Compression ratio: {compressionRatio}");
    _logger.LogInfo("Compression ratio", compressionRatio);
}

private void LogEncryptionStats(int encryptedSize, long compressedSize)
{
    var encryptionOverhead = (encryptedSize - compressedSize) / (double)compressedSize;
    Console.WriteLine($"Encryption overhead: {encryptionOverhead}");
    _logger.LogInfo("Encryption overhead", encryptionOverhead);
}

private void LogMemoryMappedFileUsage()
{
    Console.WriteLine("Memory-mapped file used.");
    _logger.LogInfo("Memory-mapped file usage", "Used");
}

private void LogDatabaseOperationTime()
{
    sw.Stop();
    var dbExecutionTime = sw.ElapsedMilliseconds;
    Console.WriteLine($"Database execution time: {dbExecutionTime} ms");
    _logger.LogInfo("Database operation time", dbExecutionTime);
}
