std::forward_list<std::string> list; // Declare the forward list globally to maintain its lifetime
std::mutex list_mutex;
std::condition_variable cv;

size_t max_insertions = 0;
size_t max_length = 100;

// Function for database connection and storage
void storeList() {
    // Database connection, query and update code here...
}

void insertString(const std::string& searchStr, const std::string& insertStr) {
    std::unique_lock<std::mutex> lock(list_mutex);

    auto it = list.begin();
    size_t count = 0;
    for (; it != list.end() && count < max_insertions; ++it, ++count) {
        if (*it == searchStr) {
            *next(it) = insertStr;
            return;
        }
        if (it->length() > max_length) {
            it = list.erase(it); // Truncate the string and remove it from the list
            storeList(); // Store the modified list in the database
        }
    }

    if (count < max_insertions) {
        list.insert(it, insertStr);
        return;
    }

    lock.unlock();
    list.push_back(insertStr);
    cv.notify_one(); // Notify other threads to check the list again
}

void run() {
    boost::asio::io_service io_service;
    // Database connection and query code here...

    while (true) {
        std::unique_lock<std::mutex> lock(list_mutex);
        cv.wait(lock, [this](){ return !list.empty(); });
        auto it = list.begin();
        if (it != list.end()) {
            insertString(*it, ""); // Remove the first element from the list and call the function to insert it
        }
    }
}
