```java
import java.io.InputStream;
import java.util.ConcurrentHashMap;
import java.util.Map;
import java.util.function.Function;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;
import org.yaml.snakeyaml.introspector.BeanAccessor;
import org.yaml.snakeyaml.errors.YAMLException;
import org.yaml.snakeyaml.introspector.PropertyUtils;

public class ConfigManager {
    private static final ConcurrentHashMap<String, Function<Map<String, Object>, Object>> factoryRegistry = new ConcurrentHashMap<>();
    private static Yaml yaml = new Yaml(new Constructor(Object.class), new BeanAccessor());

    public void addFactory(String id, Function<Map<String, Object>, Object> factory) {
        factoryRegistry.putIfAbsent(id, factory);
    }

    public void removeFactory(String id) {
        factoryRegistry.remove(id);
    }

    public <T> T createInstance(String id, Map<String, Object> configData) {
        Function<Map<String, Object>, T> factory = factoryRegistry.getOrDefault(id, t -> null);
        if (factory == null) {
            throw new IllegalArgumentException("No factory function found for ID: " + id);
        }
        try {
            return factory.apply(configData);
        } catch (Exception e) {
            throw new RuntimeException("Error creating instance using factory function for ID: " + id, e);
        }
    }

    public void loadConfig(String configFile, Class<?> schemaClass) throws YAMLException {
        InputStream inputStream = getClass().getClassLoader().getResourceAsStream(configFile);
        Map<String, Object> configData = yaml.load(inputStream).get(0);
        validateConfigData(configData, schemaClass);
    }

    private void validateConfigData(Map<String, Object> configData, Class<?> schemaClass) {
        try {
            PropertyUtils.copyProperties(configData, schemaClass.newInstance());
        } catch (Exception e) {
            throw new RuntimeException("Validation error: Configuration data does not match the provided schema.");
        }
    }

    public void mergeConfigs(Map<String, Object> baseConfig, Map<String, Object>... additionalConfigs) {
        for (Map<String, Object> config : additionalConfigs) {
            config.entrySet().forEach(baseConfig::putIfAbsent);
        }
    }
}
