```cpp
#include <iostream>
#include <string>
#include <vector>
#include <filesystem>
#include <opencv2/opencv.hpp>
#include <imgargs/imgargs.h> // ImageMagick C++ bindings for command-line image processing
#include <pdfkit/PDFKitAPI.h> // PDFKit API for creating PDFs

namespace fs = std::filesystem;
using namespace cv;
using namespace std;

int convertImagesToPdf(const string &input_dir, const vector<string> &image_files, const string &output_dir, int width) {
    int successfullyConvertedFiles = 0;

    for (const auto &file : image_files) {
        string inputPath = input_dir + "/" + file;
        string outputPath = output_dir + "/" + file.substr(0, file.find(".")) + ".pdf";

        try {
            Mat img = imread(inputPath);
            if (img.empty()) {
                cerr << "Failed to read image: " << inputPath << endl;
                continue;
            }

            resize(img, img, Size(width, static_cast<int>(img.rows * width / img.cols)));

            ImageMagick::Image imgObj(inputPath);
            imgObj.write(outputPath);

            successfullyConvertedFiles++;
        } catch (exception &e) {
            cerr << "Error converting image: " << inputPath << ", Error message: " << e.what() << endl;
        }
    }

    return successfullyConvertedFiles;
}
```
This code assumes you have ImageMagick and PDFKit installed in your system for handling the image-to-PDF conversion and creating PDFs respectively. The `imgargs` library is used for reading images, and OpenCV is used to resize images before converting them to PDF format.

