2. Next, create a function for handling user profile updates using the PATCH method:

```typescript
import { Request, Response } from 'express';

interface User {
  id: number;
  name: string;
  email: string;
  address: {
    street: string;
    city: string;
    state: string;
    country: string;
  };
  phoneNumbers: string[];
}

async function updateUserProfile(
  cache: ICache,
  userId: number,
  req: Request,
  res: Response
): Promise<void> {
  const user = await cache.get(userId) || (await getUserFromDB(userId));

  if (!user) {
    return res.status(404).send({ error: 'User not found' });
  }

  // Handle nested updates, such as updating the address or phone numbers
  const updates = req.body;

  if (updates.name) user.name = updates.name;
  if (updates.email) user.email = updates.email;
  if (updates.address) {
    user.address.street = updates.address.street || user.address.street;
    user.address.city = updates.address.city || user.address.city;
    user.address.state = updates.address.state || user.address.state;
    user.address.country = updates.address.country || user.address.country;
  }
  if (Array.isArray(updates.phoneNumbers)) {
    user.phoneNumbers = updates.phoneNumbers.filter(Boolean);
  }

  await cache.set(userId, user);
  res.status(200).send({ message: 'User profile updated successfully' });
}
```

