#include <forward_list>
#include <string>
#include <memory>
#include <pthread.h>
#include <stdexcept>
#include <iostream>
#include <cstring> // for std::strlen and std::strncpy

// Database system abstraction layer
class IDatabase {
public:
    virtual void insert(const std::string& data) = 0;
    virtual std::forward_list<std::string> fetch() = 0;
    virtual ~IDatabase() {}
};

// Concurrent-safe forward list wrapper
class CSafeForwardList {
private:
    std::forward_list<std::string> list;
    pthread_mutex_t mutex;
public:
    void insert(const std::string& data) {
        pthread_mutex_lock(&mutex);
        if (data.length() > 100) {
            throw std::runtime_error("String exceeds length limit");
        }
        list.insert_after(list.begin(), data);
        pthread_mutex_unlock(&mutex);
    }

    void insert_at_index(size_t index, const std::string& data) {
        if (data.length() > 100) {
            throw std::runtime_error("String exceeds length limit");
        }
        pthread_mutex_lock(&mutex);
        if (index >= list.size()) {
            throw std::out_of_range("Index out of range");
        }
        auto it = list.begin();
        std::advance(it, index);
        list.insert_after(it, data);
        pthread_mutex_unlock(&mutex);
    }

    std::forward_list<std::string>::iterator find(const std::string& search) {
        pthread_mutex_lock(&mutex);
        auto it = list.begin();
        for (; it != list.end(); ++it) {
            if (*it == search) break;
        }
        pthread_mutex_unlock(&mutex);
        return it;
    }

    // Other concurrent-safe operations as needed
};

void thread_safe_function(CSafeForwardList& list, const std::string& search, const std::string& insertion, size_t max_insertions, IDatabase* db) {
    auto it = list.find(search);
    if (it == list.end() && max_insertions > 0) return; // Not found within the first N elements, do nothing.

    // Truncate the string to avoid exceeding the length limit
    char truncated_insertion[101];
    std::strncpy(truncated_insertion, insertion.c_str(), 100);
    truncated_insertion[100] = '\0';

    // Insert the truncated string into the forward list (concurrency-safe)
    list.insert_after(it, truncated_insertion);

    // Integrate with the external database system (handle different types and errors)
    db->insert(truncated_insertion);
}
```

