using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Collections.Generic;
using Amazon.S3;
using Amazon.S3.Model;
using MongoDB.Driver;
using MySql.Data.MySqlClient;
using Npgsql;
using NUnit.Framework;

public class DecryptAndUploadService
{
    private readonly ILoggingService _loggingService;
    private readonly IMemetricsService _metricsService;
    private readonly KeyVaultService _keyVaultService;
    private readonly AmazonS3Client _s3Client;

    public DecryptAndUploadService(ILoggingService loggingService, IMemetricsService metricsService, KeyVaultService keyVaultService, AmazonS3Client s3Client)
    {
        _loggingService = loggingService;
        _metricsService = metricsService;
        _keyVaultService = keyVaultService;
        _s3Client = s3Client;
    }

    public async Task DecryptAndUploadAsync(string filePath, string bucketName, Dictionary<string, string> metadataTags = null)
    {
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("The specified file does not exist.");
        }

        using (var aes = AwaitableEncryptor.CreateAesCbc())
        {
            var keyAndIvLengthsValid = ValidateKeyAndIvLengths(aes);

            if (!keyAndIvLengthsValid)
            {
                throw new InvalidDataException("Invalid key and IV lengths for AES-CBC.");
            }

            var (key, iv) = await _keyVaultService.RetrieveKeyAndIvAsync(filePath);

            using (var cipherTextStream = File.OpenRead(filePath))
            {
                var decryptedData = AwaitableDecryptor.Decrypt(cipherTextStream, aes, ValidatePadding: true);

                if (!decryptedData.IsSuccess)
                {
                    throw new DecryptionFailedException("Decryption failed.");
                }

                var decryptedDataBytes = decryptedData.Result;
                var sha256Hash = CalculateSha256Hash(decryptedDataBytes);

                // Complex data aggregation and transformation tasks, followed by the generation of a customizable PDF report goes here

                await UploadToS3Async(bucketName, decryptedDataBytes, sha256Hash.ToString(), metadataTags);
            }
        }
    }

    private bool ValidateKeyAndIvLengths(AwaitableEncryptor aes)
    {
        var keyLength = aes.Key.Length;
        var ivLength = aes.IV.Length;

        return (keyLength == 32 || keyLength == 24 || keyLength == 16) && ivLength == 16;
    }

    private HashAlgorithm sha256Hash;
    private byte[] Sha256Hash(Stream inputStream)
    {
        if (sha256Hash == null)
        {
            sha256Hash = SHA256.Create();
        }

        var hashBytes = new List<byte>();

        int bufferSize = 4096;
        byte[] buffer = new byte[bufferSize];

        int bytesRead;

        while ((bytesRead = inputStream.Read(buffer, 0, bufferSize)) > 0)
        {
            hashBytes.AddRange(sha256Hash.ComputeHash(buffer, 0, bytesRead));
        }

        return sha256Hash.ComputeHash(hashBytes.ToArray());
    }

    private async Task UploadToS3Async(string bucketName, byte[] fileData, string contentMd5, Dictionary<string, string> metadataTags = null)
    {
        // Implement multipart upload logic here

        try
        {
            var putRequest = new PutObjectRequest
            {
                BucketName = bucketName,
                Key = contentMd5,
                FileName = $"{contentMd5}.{Path.GetExtension(filePath)}",
                ContentBody = fileData,
                Metadata = metadataTags
            };

            await _s3Client.PutObjectAsync(putRequest);
        }
        catch (AmazonS3Exception ex) when (ex.ErrorCode == S3Error.NoSuchBucket || ex.ErrorCode == S3Error.InvalidBucketName)
        {
            throw new BucketNotFoundException("The specified bucket does not exist.");
        }
        catch (AmazonS3Exception ex)
        {
            _loggingService.LogError(ex);
            _metricsService.IncrementUploadErrors();
            throw new S3ApiInteractionErrorException("An error occurred while interacting with the AWS S3 API.");
        }
    }
}
