class WorkerPool {
  constructor() {
    this.workers = new Set();
    this.queue = [];
  }

  static createWorkerPool(poolSize = 4) {
    return new WorkerPool({ poolSize });
  }

  addTask(task) {
    this.queue.push(task);
    this.wakeUpIdleWorkers();
  }

  async processTransaction(transaction) {
    const worker = this.takeWorker();
    if (!worker) await this.waitForWorker();

    return worker.processTransaction(transaction);
  }

  takeWorker() {
    return this.workers.size > 0 ? this.workers.values().next().value : null;
  }

  wakeUpIdleWorkers() {
    for (const worker of Array.from(this.workers)) {
      if (!worker.isBusy) worker.task();
    }
  }

  waitForWorker() {
    return new Promise((resolve) => this.onNewWorker = resolve);
  }

  async addWorker() {
    const worker = new Worker();
    worker.processTransaction = this.processTransaction.bind(this, worker);
    worker.task = () => this.addTask(worker);
    this.workers.add(worker);
    if (this.queue.length > 0) worker.task();
  }
}

class Worker {
