    private final MessageLogger logger;

    public CommandExecutor(ConfigurationManager config) {
        this.config = config;
        this.execPool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.logger = new MessageLogger();
    }

    public void executeCommands() {
        List<Command> commands = config.getCommands();
        for (Command command : commands) {
            logger.log("Starting command: " + command.getName());
            Process process;
            try {
                process = Runtime.getRuntime().exec(command.getCommand());
            } catch (IOException e) {
                logger.logError("Failed to execute command: " + e.getMessage(), "Execution Error");
                continue;
            }
            int retryCount = config.getRetryCount(command.getName());
            for (int i = 0; i < retryCount; ++i) {
                try {
                    process.waitFor(Math.pow(2, i + 1) * 1000);
                    ProcessUtils.streamLogger(process.getErrorStream(), logger::logError);
                    ProcessUtils.streamLogger(process.getInputStream(), logger);
                    int exitValue = process.waitFor();
                    if (exitValue == 0) {
                        logger.log("Command executed successfully: " + command.getName());
                        break;
                    } else {
                        logger.logError("Command execution failed with error code: " + exitValue, "Execution Error");
                    }
                } catch (InterruptedException | IOException e) {
                    logger.logError("Failed to execute command: " + e.getMessage(), "Execution Error");
                }
            }
        }
    }

