        if (future != null && future.isDone()) {
            return future.get().body().bytes();
        } else {
            Response response = future.orNull().orException().getCause();
            if (response == null) {
                // Handle exception here, for example by logging or retrying the request.
                throw new IOException("Failed to get avatar from cache");
            }
            byte[] avatarBytes = getAvatarFromService(userId);
            updateUserProfile(userId, avatarBytes);
            return avatarBytes;
        }
