#include <fcntl.h>
#include <windows.h>

// Utility function for resolving environment variables
char* resolve_env_var(const char* env_var);

char* constructFilePath(const char* filePath, int maxBufferSize, bool isAbsolute, char* errorMessage) {
    size_t len = strlen(filePath);

    // Check if the path exceeds the maximum buffer size
    if (len > maxBufferSize - 1) {
        sprintf(errorMessage, "Error: The provided file path exceeds the maximum buffer size.");
        return NULL;
    }

    char* resolvedPath = malloc(maxBufferSize);
    strncpy(resolvedPath, filePath, len + 1);

    // Handle Windows-style paths
    if (_isa_dosfile(resolvedPath)) {
        DWORD dw driveType;
        _getdrive(&dwDriveType);
        char driveLetter = towupper((char)dwDriveType - 1 + 'A');
        strcpy(resolvedPath, &driveLetter);
        strcat(resolvedPath, ":\\");
    }

    // Replace environment variables with their actual paths
    char* currentPos = resolvedPath;
    char* nextPos;

    while ((nextPos = strchr(currentPos, '$')) != NULL) {
        if (nextPos - resolvedPath + 1 >= maxBufferSize) {
            sprintf(errorMessage, "Error: The environment variable exceeds the maximum buffer size.");
            free(resolvedPath);
            return NULL;
        }

        char* envVar = nextPos + 1;
        char* envResolved = resolve_env_var(envVar);

        if (envResolved == NULL) {
            sprintf(errorMessage, "Error: The provided environment variable is invalid.");
            free(resolvedPath);
            return NULL;
        }

        strncpy(currentPos, envResolved, nextPos - currentPos + 1);
        free(envResolved);
        currentPos += (nextPos - currentPos + 1);
    }

    // Append the current working directory if the path is not absolute
    char cwd[MAX_PATH];
    if (!isAbsolute) {
        getcwd(cwd, sizeof(cwd));
        size_t cwdLen = strlen(cwd);
        size_t pathLen = strlen(resolvedPath);

        if (pathLen + cwdLen > maxBufferSize - 1) {
            sprintf(errorMessage, "Error: The combined file and current working directories exceed the maximum buffer size.");
            free(resolvedPath);
            return NULL;
        }

        strcat(resolvedPath, "/");
        strncat(resolvedPath, cwd, cwdLen + 1);
    }

    // Handle symbolic links and cache frequently accessed directories
    struct stat st_buf;
    if (lstat(resolvedPath, &st_buf) == -1 || S_ISLNK(st_buf.st_mode)) {
        char symlinkPath[MAX_PATH];
        readlink(resolvedPath, symlinkPath, sizeof(symlinkPath));
        free(resolvedPath);
        resolvedPath = constructFilePath(symlinkPath, maxBufferSize, true, errorMessage);
    } else if (st_buf.st_mode & S_IFDIR) {
        // Implement a caching mechanism for frequently accessed directories here
    }

    // Log the path construction process (for debugging purposes)
    char logPath[MAX_PATH];
    strncpy(logPath, resolvedPath, sizeof(logPath));

    // Validate the existence of each directory and construct the full path if necessary
    DIR* dir;
    struct dirent* entry;
    char* token = strtok((char*)resolvedPath, "/");
    while (token != NULL) {
        if (!isAbsolute && !strcmp(token, "..")) {
            if ((dir = opendir("..")) != NULL) {
                closedir(dir);
                char* newToken = token;
                newToken[1] = '\0';
                strcat(resolvedPath, "/");
                strcat(resolvedPath, token);
                strtok(resolvedPath, "/");
                token = newToken + 2;
            } else {
                sprintf(errorMessage, "Error: The parent directory does not exist.");
                free(resolvedPath);
                return NULL;
            }
        } else if ((dir = opendir(token)) == NULL) {
            sprintf(errorMessage, "Error: The specified directory %s does not exist.", token);
            free(resolvedPath);
            return NULL;
        } else {
            closedir(dir);
            strcat(resolvedPath, "/");
        }
        token = strtok(NULL, "/");
    }

    return resolvedPath;
}
```

