  try {
    const id = req.params.id;
    const data = req.body;

    // Check if the identifier is valid
    const resource = await ResourceModel.findById(id);
    if (!resource) throw new Error('Invalid resource identifier');

    // Merge the incoming data with the existing resource, only updating specified fields
    const updatedResource = { ...resource.toObject(), ...data };

    // Save the updated resource to the database and cache
    await ResourceModel.findByIdAndUpdate(id, updatedResource);
    cache.put(id, updatedResource);

    res.status(200).json(updatedResource);
  } catch (error) {
    console.error(error);
    res.status(500).send({ error: 'An error occurred while updating the resource' });
  }
});

// DELETE endpoint for deleting a resource and its related resources, if any
router.delete('/:id', async (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const confirmed = req.body.confirmation || true;

    // Check if the identifier is valid
    const resource = await ResourceModel.findById(id);
    if (!resource) throw new Error('Invalid resource identifier');

    // If confirmation is not provided or false, return an error message
