import time
import random
from django.db import transaction
from drf_yasg import openapi
from drf_yasg.utils import swagger_auto_schema
from rest_framework import status, views, exceptions
from datetime import datetime

from your_project.api.models import Order, Product, Payment
from shipping_service.api.client import ShippingServiceClient
from monitoring_system.api.client import MonitoringSystemClient

@swagger_auto_schema(request_body=openapi.RequestBody(
    required=True,
    description="Order details",
    ref="#/components/schemas/Order"
))
class ProcessOrderView(views.APIView):
    def post(self, request):
        try:
            with transaction.atomic():
                order_data = request.DATA
                order = Order.objects.create(**order_data)

                product = Product.objects.get(id=order_data['product_id'])
                if product.quantity < order_data['quantity']:
                    raise exceptions.ValidationError("Insufficient inventory")

                payment_result = process_payment(order)
                if not payment_result:
                    return Response({"error": "Failed to process payment"}, status=status.HTTP_402_Payment_Required)

                product.quantity -= order_data['quantity']
                product.save()
                order.status = Order.StatusChoices.PROCESSED
                order.save()

                shipment_result = schedule_shipment(order)
                if not shipment_result:
                    return Response({"error": "Failed to schedule shipment"}, status=status.HTTP_503_Service_Unavailable)

                log_action("Processed order #{order_id} successfully", order, MonitoringSystemClient())
                log_payment(payment_result, order, MonitoringSystemClient())
                log_shipment(shipment_result, order, MonitoringSystemClient())

            return Response({"message": "Order processed successfully"}, status=status.HTTP_200_OK)
        except Exception as e:
            log_action(f"Failed to process order #{order_data['order_id']}: {str(e)}", None, MonitoringSystemClient())
            return Response({"error": str(e)}, status=status.HTTP_500_Internal_Server_Error)

def process_payment(order):
    success = False
    MAX_RETRIES = 3
    for attempt in range(MAX_RETRIES + 1):
        try:
            payment = Payment.objects.create(order=order, amount=calculate_total_amount(order))
            payment.make_payment()
            success = True
            break
        except Exception as e:
            if attempt == MAX_RETRIES:
                raise e
            log_error(f"Failed to process payment on order #{order.id}: {str(e)}", None, MonitoringSystemClient())
            time.sleep(5 * attempt)
    return success

def calculate_total_amount(order):
    return order.product.price * order.quantity

def schedule_shipment(order):
    client = ShippingServiceClient()
    response = client.schedule_shipment(order.id)
    if not response.success:
        log_error("Failed to schedule shipment", None, MonitoringSystemClient())
        return False
    return response.data

def log_action(message, object=None, client=None):
    client.log_action(message, object)

def log_payment(result, order, client=None):
    if result:
        client.log_success("Processed payment successfully for order #{order.id}")
    else:
        client.log_error("Failed to process payment for order #{order.id}")

def log_shipment(result, order, client=None):
    if result:
        client.log_success("Scheduled shipment successfully for order #{order.id}")
    else:
        client.log_error("Failed to schedule shipment for order #{order.id}")

def log_error(message, object=None, client=None):
    client.log_error(message, object)
```

