```cpp
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/pkcs5.h>
#include <openssl/hkdf.h>
#include <memory>
#include <stdexcept>

struct AESContext {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[AES_BLOCK_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];
    int padding;
};

std::unique_ptr<AESContext> createAESContext(const uint8_t* password, size_t password_len, const EVP_CIPHER* cipher, AES_MODE mode, unsigned char* tag, size_t tag_len, unsigned char* iv, size_t iv_len, int padding) {
    std::unique_ptr<AESContext> ctx(new AESContext());
    if (!ctx) throw std::bad_alloc();

    ctx->padding = padding;

    if (EVP_EncryptInit_ex(&(ctx->ctx), cipher, NULL, password, iv) != 1) {
        throw std::runtime_error("AES encryption initialization failed");
    }

    switch (mode) {
        case AES_MODE::ECB:
            break;
        case AES_MODE::CBC:
            if (iv == nullptr || iv_len != AES_BLOCK_SIZE) {
                throw std::invalid_argument("Invalid IV length for CBC mode");
            }
            break;
        case AES_MODE::GCM:
            if (tag == nullptr || tag_len < EVP_CIPHER_CTX_tag_length()) {
                throw std::invalid_argument("Invalid GCM tag length");
            }
            ctx->ctx->key_length = sizeof(ctx->key);
            ctx->ctx->iv_length = sizeof(ctx->iv);
            break;
        default:
            throw std::invalid_argument("Unsupported AES mode");
    }

    return ctx;
}

void deriveKeyAndIV(const uint8_t* password, size_t password_len, const EVP_CIPHER* cipher, unsigned char* key, unsigned char* iv, int length) {
    if (PKCS5_PBKDF2_HMAC((EVP_CIPHER*)cipher, key, sizeof(key), password, password_len, iv, length, 1000, EVP_sha256()) <= 0) {
        throw std::runtime_error("Key derivation failed");
    }
}

void deriveKeyAndTag(const uint8_t* password, size_t password_len, const EVP_CIPHER* cipher, unsigned char* key, unsigned char* tag, size_t tag_len) {
    HKDF_CTX* hkdf;
    if (!(hkdf = HKDF_CTX_new())) throw std::bad_alloc();

    const EVP_MD_CTX* hashCtx = EVP_sha256();
    if (1 != HKDF_Init(hkdf, cipher->key, sizeof(cipher->key), hashCtx)) {
        HKDF_free(hkdf);
        throw std::runtime_error("HKDF initialization failed");
    }

    if (1 != HKDF_Update(hkdf, password, password_len)) {
        HKDF_free(hkdf);
        throw std::runtime_error("HKDF update failed");
    }

    if (1 != HKDF_Final(hkdf, key, sizeof(key))) {
        HKDF_free(hkdf);
        throw std::runtime_error("HKDF finalization failed");
    }

    if (tag) {
        if (1 != HKDF_Extract(hkdf, tag, &tag_len)) {
            HKDF_free(hkdf);
            throw std::runtime_error("HKDF extraction failed");
        }
    }

    HKDF_free(hkdf);
}
```

This code uses the OpenSSL library for AES encryption and key derivation functions. The `createAESContext` function takes a password, cipher mode (ECB, CBC, GCM), IV, padding scheme, and tag/tag length (for GCM). It returns a smart pointer to an `AESContext` struct containing the initialized EVP_CIPHER_CTX and other relevant information.

The `deriveKeyAndIV` function generates a key and IV using PKCS5-PBKDF2, while `deriveKeyAndTag` uses HKDF for key derivation and provides an option to derive a tag for GCM mode. Both functions throw exceptions on failure.

