    if (!curl) {
        fprintf(stderr, "Failed to initialize cURL\n");
        return NULL;
    }
    return curl;
}

static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    // Write the received data into a json object
    json_object_pack((json_object *)userdata, ptr, size * nmemb, 0);
    return size * nmemb;
}

int convert_image(Args *args) {
    if (!is_valid_input(args)) {
        fprintf(stderr, "Invalid input\n");
        return 1;
    }

    mkdir(args->output_dir, S_IRWXU | S_IRWXG | S_IROTH | S_IXOTH);
    char pdf_filename[256];
    snprintf(pdf_filename, sizeof(pdf_filename), "%s/%s.pdf", args->output_dir, args->filename);

    // Fetch metadata and create or update the metadata file if provided
    json_object *metadata = get_image_metadata(args->filename);
    if (args->metadata_file) {
        write_json_to_file(args->metadata_file, metadata);
    }

    // Create PDF chunks and convert them asynchronously
    struct pdf_chunk *chunks = create_pdf_chunks(args->filename, args->num_threads);
    pthread_t threads[args->num_threads];

    for (size_t i = 0; i < args->num_threads; ++i) {
        pthread_create(&threads[i], NULL, convert_pdf_chunk, &chunks[i]);
    }

    // Wait for all threads to finish and clean up
    for (size_t i = 0; i < args->num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
    free(chunks);

    return 0;
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s input_file output_directory metadata_file\n", argv[0]);
        return 1;
    }

    Args args = { argv[1], argv[2], argc > 3 ? argv[3] : NULL, argc > 4 ? atoi(argv[4]) : 4 };
    return convert_image(&args);
}
