```c
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>

typedef enum LogLevel {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR
} LogLevel;

struct LogConfig {
    const char *log_filename;
    size_t max_log_length;
    LogLevel log_level;
};

static thread_local struct LogConfig config = {
    .log_filename = "error.log",
    .max_log_length = 4096,
    .log_level = LOG_LEVEL_ERROR
};

static FILE *log_file;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void initLog(const char *filename, size_t max_length, LogLevel level) {
    config.log_filename = filename;
    config.max_log_length = max_length;
    config.log_level = level;
    log_file = fopen(config.log_filename, "a");
}

static void appendLog(const char *format, ...) {
    va_list args;
    size_t buffer_size = 1024;
    char *buffer = malloc(buffer_size);

    if (!buffer) {
        return; // handle error gracefully or throw an exception
    }

    while (1) {
        pthread_mutex_lock(&log_mutex);
        size_t written = vsnprintf(buffer, buffer_size, format, va_arg_list);
        pthread_mutex_unlock(&log_mutex);

        if (written < 0 || written >= buffer_size) {
            buffer_size *= 2;
            buffer = realloc(buffer, buffer_size);
            continue;
        }

        size_t remaining_length = config.max_log_length - ftell(log_file);
        if (written >= remaining_length) {
            written = remaining_length - 1;
        }

        fwrite(buffer, 1, written, log_file);
        fprintf(log_file, "\n");
        free(buffer);
        break;
    }
}

void logCondition(bool condition, const char *format, ...) {
    if (condition && config.log_level <= LOG_LEVEL_ERROR) {
        va_list args;
        va_start(args, format);
        appendLog(format, args);
        va_end(args);
    }
}
```

In this code:
- The `struct LogConfig` stores the configuration options.
- We use a `thread_local` variable `config` for each thread to handle concurrent access to the log mechanism safely.
- `initLog()` initializes the logging configuration and opens the log file.
- `appendLog()` formats and writes the message to the log file, handling memory allocation issues and ensuring that the log message does not exceed the maximum length.
- The `logCondition()` function logs a message only if the specified condition is met and the current log level is either debug or lower (error, warning, info).

