```cpp
#include <nlohmann/json.hpp>
#include <unordered_map>
#include <variant>
#include <mutex>
#include <iostream>
#include <log4cxx/logger.h>
#include <log4cxx/basicconfigurator.h>

namespace json = nlohmann;
std::mutex mtx;

class ConfigLoader {
public:
    ConfigLoader(const std::string& path, const std::unordered_map<std::string, std::type_index>& schema)
        : _schema(schema), _data(), _json(json::parse_file(path)) {
        init();
    }

    auto getConfig() {
        std::lock_guard<std::mutex> lock(mtx);
        return _data;
    }

private:
    void init() {
        for (auto& entry : _json.items()) {
            if (!validateType(entry.key(), entry.value(), _schema[entry.key().get<std::string>()])) {
                log4cxx::LoggerPtr logger = log4cxx::Logger::getLogger("ConfigLoader");
                logger->error("<" + entry.key().get<std::string>() + "> has invalid type.");
            } else {
                _data[entry.key().get<std::string>()] = entry.value();
            }
        }
    }

    bool validateType(const std::string& key, const json::JsonObject& value, const std::type_index& expectedType) {
        try {
            if (expectedType == typeid(int)) {
                return value.get<int>() != nullptr;
            } else if (expectedType == typeid(double)) {
                return value.get<double>() != nullptr;
            } else if (expectedType == typeid(std::string)) {
                return true; // strings are always valid
            } else if (expectedType == typeid(bool)) {
                return value.get<bool>() != nullptr;
            }
        } catch (const std::exception& e) {
            return false;
        }
        return false;
    }

    std::unordered_map<std::string, json::JsonObject> _schema;
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> _data;
    json::JsonObject _json;
};
```

