```cpp
#include <fstream>
#include <stdexcept>
#include <cstdio>
#include <cstring>
#include <system_error>
#include <iostream>

class SafeFileAppender {
public:
    explicit SafeFileAppender(const char* path, const char* data) : filePath_(path), data_(data) {
        if (!filePath_ || strlen(filePath_) > 4096)
            throw std::invalid_argument("File path is invalid or exceeds the maximum length.");
    }

    ~SafeFileAppender() {
        if (file_.is_open())
            file_.close();
    }

    int safeFileAppend() {
        try {
            file_.open(filePath_, std::ios::app | std::ios::binary);
            if (!file_.is_open())
                throw std::system_error(errno, std::generic_category(), "Failed to open file.");

            file << data_;
            return static_cast<int>(data_.size());
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << "\n";
            return -1;
        }
    }

private:
    const char* filePath_;
    const char* data_;
    std::ofstream file_;
};
```

