def get_pokemon_data(pokemon_name):
    url = f'https://pokeapi.co/api/v2/pokemon/{pokemon_name}'
    response = requests.get(url)
    data = response.json()

    weaknesses = [weakness['type']['name'] for weakness in data['types'][1]['damage_relations']['double_damage_from']]
    weather_effects = data['abilities'][0]['effect_entries'][1]['effect']['short_text'].split(',')
    terrain_effects = data['abilities'][1]['effect_entries'][1]['effect']['short_text'].split(',')

    script_tags = render_script_tags(weaknesses, weather_effects, terrain_effects)
    return script_tags

def render_script_tags(weaknesses, weather_effects, terrain_effects):
    script_tags = '<script>\n'
    script_tags += f'  var pokemonWeaknesses = {json.dumps(weaknesses)};\n'
    script_tags += f'  var pokemonWeatherEffects = {json.dumps(weather_effects)};\n'
    script_tags += f'  var pokemonTerrainEffects = {json.dumps(terrain_effects)};\n'
    script_tags += '</script>\n'
    return script_tags
