```javascript
const fs = require('fs-extra');
const path = require('path');
const axios = require('axios');
const readline = require('readline');

// Constants
const VALID_EXTENSIONS = ['.txt', '.md', '.json'];
const API_URL = 'https://file-metadata-api.example.com/v1/metadata';

async function processDirectory(directoryPath) {
  // Check if the directory exists
  try {
    await fs.access(directoryPath);
  } catch (error) {
    console.error(`Directory does not exist: ${directoryPath}`);
    return [];
  }

  const files = await fs.readdir(directoryPath, { withFileTypes: true });

  // Recursively process subdirectories and handle files
  let results = [];
  for (const file of files) {
    const fullFilePath = path.join(directoryPath, file.name);

    if (file.isDirectory()) {
      results = results.concat(await processDirectory(fullFilePath));
    } else if (VALID_EXTENSIONS.includes(file.extname)) {
      const metadata = await fetchMetadata(fullFilePath);
      const content = await readFile(fullFilePath);

      results.push({ filePath: fullFilePath, content, metadata });
    } else {
      console.error(`Invalid file extension in ${fullFilePath}`);
    }
  }

  return results;
}

async function fetchMetadata(filePath) {
  try {
    const response = await axios.get(`${API_URL}/${encodeURIComponent(filePath)}`);
    return response.data;
  } catch (error) {
    console.error(`Error fetching metadata for ${filePath}:`, error.message);
    return null;
  }
}

async function readFile(filePath, options = {}) {
  const stream = fs.createReadStream(filePath, options);
  const rl = readline.createInterface({ input: stream });

  const chunks = [];
  for await (const line of rl) {
    chunks.push(line);
  }

  return chunks.join('');
}

// Unit tests
describe('processDirectory', function () {
  // Add unit test cases here, covering various scenarios and edge cases
});
```

