namespace App\Utils;

use function mb_strimwidth;

class RandomStringGenerator {
    private $length;
    private $charset;

    public function __construct($length = 16, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
        $this->length = $length;
        $this->charset = $charset;
    }

    public function generate() {
        $randomString = '';
        for ($i = 0; $i < $this->length; $i++) {
            $randomString .= $this->charset[rand(0, strlen($this->charset) - 1)];
        }
        return mb_strimwidth($randomString, 0, $this->length, '');
    }
}
