#define _POSIX_C_SOURCE 200809L

#ifdef __linux__
#define EXTERNAL_TOOL "img2pdf"
#else
// Provide the path to the external tool for non-Linux platforms here.
#endif

typedef struct {
    char author[64];
    char title[128];
    char creation_date[32];
} Metadata;

int convert_jpeg_to_pdf(const char *input_file, const char *output_dir, const Metadata *metadata) {
    // Check if input file and output directory are valid.
    struct stat st_in, st_out;
    if (stat(input_file, &st_in) < 0 || S_ISDIR(st_in.st_mode)) {
        perror("Invalid input file.");
        return 1;
    }
    if (stat(output_dir, &st_out) < 0 || S_ISDIR(st_out.st_mode)) {
        perror("Invalid output directory.");
        return 1;
    }

    // Create the output file path.
    char output_path[256];
    snprintf(output_path, sizeof(output_path), "%s/%s.pdf", output_dir, basename(input_file));

    // Combine metadata with the third-party tool command.
    char cmd[1024] = {0};
    snprintf(cmd, sizeof(cmd), "%s -author \"%s\" -title \"%s\" -creator \"%s\" %s", EXTERNAL_TOOL, metadata->author, metadata->title, metadata->creation_date, input_file);

    // Execute the command and handle errors.
    pid_t pid = fork();
    if (pid < 0) {
        perror("Failed to fork.");
        return 1;
    } else if (pid == 0) {
        // Child process: execute the command.
        if (execv(EXTERNAL_TOOL, (char *const *) &cmd) < 0) {
            perror("Failed to execute command.");
            _exit(1);
        }
    } else {
        // Parent process: wait for the child to finish.
        int status;
        if (waitpid(pid, &status, 0) < 0) {
            perror("Waiting for child process failed.");
            return 1;
        }
        if (WEXITSTATUS(status)) {
            printf("Error returned by the third-party tool: %d\n", WEXITSTATUS(status));
            return 1;
        }
    }

    // Check if the output file was created successfully.
    if (stat(output_path, &st_out) < 0 || !S_ISREG(st_out.st_mode)) {
        perror("Failed to create output file.");
        return 1;
    }

    return 0;
}
```
