using namespace std;
using namespace boost::filesystem;
using json = nlohmann::json;
using namespace cpplib;
using namespace cv;

int convertImageToPDF(path imgDir, path configFile, path outDir) {
    int count = 0;
    for (auto& p : recursive_directory_iterator(imgDir)) {
        try {
            if (!is_regular_file(p)) continue;
            string ext = path(p).extension().string();
            Image img(p);
            json rules = json::parse(iostreams::istream<char>(configFile));
            int w = rules["width"].get<int>();
            Size newSize(w, static_cast<int>(static_cast<float>(w) * img.height / img.width));
            Mat resizedImg = imresize(img, newSize);
            PDF doc;
            doc.addImage(resizedImg, ImageType::JPEG);
            doc.save(outDir / p.filename() + ".pdf");
            count++;
        } catch (exception& e) {
            cerr << "Error: " << e.what() << endl;
        }
    }
    return count;
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        cerr << "Usage: ImageConverter input_dir config.json output_dir" << endl;
        return 1;
    }

    path imgDir = argv[1];
    path configFile = argv[2];
    path outDir = argv[3];

    try {
        int result = convertImageToPDF(imgDir, configFile, outDir);
        cout << "Converted " << result << " files successfully." << endl;
    } catch (exception& e) {
        cerr << "Error: " << e.what() << endl;
    }

    return 0;
}
