import os
import re
from collections import defaultdict
import fileinput

def read_lines_and_extract_sequence_number(filename):
    sequences = defaultdict(int)
    for line in sorted(fileinput.input(filename)):
        match = re.search(r'^\d+$', line)
        if match:
            sequences[match.group(0)] += 1
    return sequences[sorted(sequences, key=sequences.get, reverse=True)[0]]
