```c
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>
#include <getopt.h>
#include <libpdf/pdf.h>
#include <magick-config.h>
#include <Image.h>
#include <mutex.h>

struct log_data {
    int image_index;
    char log[4096];
};

static void img_to_pdf(const char* input_path, int pdf_idx);
static void* worker(void* arg);
static mutex_t log_mutex = MUTEX_INITIALIZER_NP;
static pthread_mutex_t thread_counter_lock = PTHREAD_MUTEX_INITIALIZER;
static int num_threads, max_images_per_pdf, total_images, current_thread, image_idx;

int main(int argc, char** argv) {
    const char* input_dir = NULL;
    const char* output_dir = NULL;
    char c;

    while ((c = getopt(argc, argv, "i:o:p:t:")) != -1) {
        switch (c) {
            case 'i':
                input_dir = optarg;
                break;
            case 'o':
                output_dir = optarg;
                break;
            case 'p':
                max_images_per_pdf = atoi(optarg);
                break;
            case 't':
                num_threads = atoi(optarg);
                break;
            default:
                return 1;
        }
    }

    if (!input_dir || !output_dir) {
        fprintf(stderr, "Invalid arguments\n");
        return 1;
    }

    DIR *dir = opendir(input_dir);
    struct dirent* entry;

    total_images = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strchr(entry->d_name, '.') && strcmp(&entry->d_name[strlen(entry->d_name) - 4], ".pdf"))
            total_images++;
    }
    closedir(dir);

    current_thread = num_threads;
    image_idx = 0;

    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, worker, NULL);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

static void* worker(void* arg) {
    while (image_idx < total_images) {
        int pdf_idx = image_idx / max_images_per_pdf;
        const char *input_path = (char*)malloc((strlen(input_dir) + strlen("/")) + 12);
        snprintf(input_path, sizeof(input_path), "%s/%d.%s", input_dir, image_idx++, "jpg"); // Assuming all images are JPEG format

        if (access(input_path, F_OK) != -1 && strchr(input_path, '.') && strcmp(&input_path[strlen(input_path) - 4], ".pdf")) {
            img_to_pdf(input_path, pdf_idx);
        }

        free(input_path);
        pthread_mutex_lock(&thread_counter_lock);
        --current_thread;
        if (current_thread == 0) {
            break;
        }
        pthread_mutex_unlock(&thread_counter_lock);
    }

    return NULL;
}

static void img_to_pdf(const char* input_path, int pdf_idx) {
    Image *image = ReadImage(input_path);
    if (image == NULL) {
        printf("Failed to load image: %s\n", input_path);
        return;
    }

    char log_str[4096];
    snprintf(log_str, sizeof(log_str), "Converting image %d/%d : %s ...\n", image_idx + 1, total_images, input_path);
    printf("%s", log_str);
    MagickSetStdError(&stderr);
    char stderr_buf[4096];
    ErrorInfo error_info;
    MagickSetStandardErrorPixelSize(MagickTrue);
    ErrorInitException(&error_info);
    ExceptionInfo error_details = error_info.exception;
    try {
        WriteImage(image, "PDF", pdf_idx + 1);
    } catch (const char *message) {
        snprintf(stderr_buf, sizeof(stderr_buf), "Error converting image: %s\n%s\n", message, error_details.message);
        fprintf(stderr, "%s", stderr_buf);
    }
    ErrorDestroyException(&error_info);
    DestroyImage(image);

    pthread_mutex_lock(&log_mutex);
    strcat(log_str, stderr_buf);
    printf("%s", log_str);
    fflush(stdout);
    pthread_mutex_unlock(&log_mutex);
}
```

