1. Custom Min-Max Algorithm (In-place, linear time)
```cpp
#include <algorithm>
template<typename Iterator>
void custom_minmax(Iterator first, Iterator last) {
    if (first == last) return;

    Iterator min_it = first;
    Iterator max_it = first;

    std::advance(min_it, 1);
    std::advance(max_it, 1);

    while (min_it != last && max_it != last) {
        if (*min_it < *min_it) min_it = first + std::distance(first, min_it);
        if (*max_it > *max_it) max_it = first + std::distance(first, max_it);
        std::advance(min_it, 1);
        std::advance(max_it, 1);
    }

    // last element handling
    if (std::next(last) != last) {
        if (*last < *min_it) min_it = last;
        if (*last > *max_it) max_it = last;
    }
}
```

