struct list {
    size_t capacity;
    size_t length;
    NFAPI_CRC_INDICATION_PDU_T **elements;
    sem_t *sem;
    pthread_mutex_t *mutex;
    void (*free_func)(NFAPI_CRC_INDICATION_PDU_T*);
    bool compress;
};

void list_init(struct list *list, size_t capacity, void (*free_func)(NFAPI_CRC_INDICATION_PDU_T*), bool compress) {
    list->capacity = capacity;
    list->length = 0;
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * capacity);
    list->free_func = free_func;
    list->compress = compress;
    sem_init(&list->sem, 0, capacity);
    pthread_mutex_init(&list->mutex, NULL);
}

void list_push(struct list *list, NFAPI_CRC_INDICATION_PDU_T *elem) {
    if (list->length >= list->capacity) return;
    sem_wait(&list->sem);
    list->elements[list->length++] = elem;
    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* list_pop(struct list *list) {
    if (list->length == 0) return NULL;
    NFAPI_CRC_INDICATION_PDU_T *elem = list->elements[0];
    memmove(&(list->elements[0]), &(list->elements[1]), sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (list->length - 1));
    list->length--;
    pthread_mutex_lock(&list->mutex);
    sem_post(&list->sem);
    pthread_mutex_unlock(&list->mutex);
    return elem;
}

