from cachetools import TTLCache

# Define API URLs for your chosen stock market APIs (e.g., Alpha Vantage, Yahoo Finance)
APIS = {
    'AlphaVantage': 'https://www.alphavantage.co/query?function=TIME_SERIES_DAILY&symbol={symbol}&apikey={api_key}',
    # Add more APIs here
}

API_CACHE = TTLCache(maxsize=1000, ttl=86400)  # Cache for 1 day

def get_current_time():
    return datetime.datetime.now(pytz.utc).astimezone().replace(tzinfo=pytz.UTC).isoformat() + 'Z'

def fetch_stock_data(symbols, api):
    data = {}
    for symbol in symbols:
        url = APIS[api].format(symbol=symbol, api_key='YOUR_API_KEY')
        response = requests.get(url)
        if response.status_code == 200:
            data[symbol] = response.json()
        else:
            print(f'Error fetching data from {api} for symbol {symbol}: {response.status_code}')
    return data

def main():
    user_timezone = 'America/New_York'  # User's local timezone
    user_local_time = datetime.datetime.now(pytz.timezone(user_timezone)).strftime('%Y-%m-%d %H:%M:%S')
    print(f'Latest data requested at: {user_local_time} (in {user_timezone})')

    symbols = ['AAPL', 'GOOG', 'MSFT']  # List of companies to fetch stock data for
    cached_data = API_CACHE.get(get_current_time()) or {}
    total_requests, hits, misses = 0, 0, 0

    for api in APIS:
        if cached_data and get_current_time() in cached_data:
            data = cached_data[get_current_time()]
            print(f'Using cached data from {api}')
            hits += 1
        else:
            data = fetch_stock_data(symbols, api)
            total_requests += len(APIs)
            if data:
                API_CACHE[get_current_time()] = data
                misses += len(APIs) - hits
            else:
                misses += len(APIs)

    print(f'Total requests made: {total_requests}')
    print(f'Hits from the cache: {hits}')
    print(f'Misses from the cache: {misses}')

if __name__ == "__main__":
    main()
