public class NetworkDataFetcher {
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final OkHttpClient httpClient = new OkHttpClient.Builder()
            .connectTimeout(10, TimeUnit.SECONDS)
            .readTimeout(30, TimeUnit.SECONDS)
            .build();
    private static final ReadWriteLock cacheLock = new ReentrantReadWriteLock();
    private static final ConcurrentHashMap<String, JsonNode> dataCache = new ConcurrentHashMap<>();
    private static final long MAX_AGE_MILLIS = 60 * 1000L; // 1 minute
    private static final int THREAD_POOL_SIZE = Runtime.getRuntime().availableProcessors() * 2;

    public static JsonNode fetchJsonData(String url) throws IOException {
        String cachedData = dataCache.get(url);
        if (cachedData != null && Instant.now().minusMillis(dataCache.get(url).get("time").asLong()) < Instant.now().minusMillis(MAX_AGE_MILLIS)) {
            return cachedData;
        }
        Request request = new Request.Builder()
                .url(url)
                .build();
        Response response = httpClient.newCall(request).execute();
        if (!response.isSuccessful()) {
            throw new IOException("Failed to fetch JSON data: " + response.message());
        }
        dataCache.putIfAbsent(url, objectMapper.readTree(response.body()).set("time", Instant.now()));
        return dataCache.get(url);
    }

