import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;

public class FileProcessor {
    private final ExecutorService executor;
    private final CachingStrategy cachingStrategy;
    private final Logger logger;
    private final ApiClient apiClient;

    // constructor, initializations and fields for configuration options

    public void processDirectory(Path directory) {
        try (Stream<Path> stream = Files.walk(directory)) {
            List<Callable<SummaryReport>> tasks = new ArrayList<>();

            stream.filter(Files::isRegularFile)
                .forEach(file -> {
                    if (isRecentFile(file)) {
                        Pattern pattern = getPattern(); // using caching strategy
                        tasks.add(() -> readAndProcessFile(file, pattern));
                    }
                });

            List<Future<SummaryReport>> results = executor.invokeAll(tasks);
            SummaryReport summaryReport = combineReports(results);

            // upload and notify using ApiClient
            apiClient.uploadAndNotify(summaryReport);
        } catch (IOException | InterruptedException | ExecutionException e) {
            logger.logError("Error during file processing: " + e.getMessage());
        }
    }

    private boolean isRecentFile(Path file) {
        return Files.getLastModifiedTime(file).to(ChronoUnit.MINUTES).compareTo(Config.RECENT_FILE_AGE) > 0;
    }

    // methods for reading, processing files and generating reports
}
