using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Threading;

namespace FileComparator
{
    public class FileComparator
    {
        private HashAlgorithm _hashAlgorithm = SHA256.Create();
        private readonly HashSet<string> _excludedFileTypes;
        private SemaphoreSlim _semaphore = new SemaphoreSlim(Environment.ProcessorCount);

        public FileComparator(HashSet<string> excludedFileTypes)
        {
            _excludedFileTypes = excludedFileTypes;
        }

        public async Task<Dictionary<string, byte[]>> CompareDirectories(string directory1, string directory2)
        {
            var fileChecksums1 = new Dictionary<string, byte[]>();
            var fileChecksums2 = new Dictionary<string, byte[]>();
            await Parallel.ForEachAsync(Directory.EnumerateFiles(directory1), async (file1, token) =>
            {
                _semaphore.Wait();

                try
                {
                    if (!_excludedFileTypes.Contains(Path.GetExtension(file1)))
                        fileChecksums1[file1] = await CalculateFileChecksum(file1);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing file: {file1}, Error message: {ex}");
                }
                finally
                {
                    _semaphore.Release();
                }
            });

            await Parallel.ForEachAsync(Directory.EnumerateFiles(directory2), async (file2, token) =>
            {
                _semaphore.Wait();

                try
                {
                    if (!_excludedFileTypes.Contains(Path.GetExtension(file2)))
                        fileChecksums2[file2] = await CalculateFileChecksum(file2);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error processing file: {file2}, Error message: {ex}");
                }
                finally
                {
                    _semaphore.Release();
                }
            });

            var result = new Dictionary<string, byte[]>();
            foreach (var checksum1 in fileChecksums1)
            {
                if (!fileChecksums2.TryGetValue(checksum1.Key, out var checksum2))
                    result[checksum1.Key] = checksum1.Value;
                else if (!checksum1.Value.SequenceEqual(checksum2.Value))
                    result[checksum1.Key] = checksum1.Value;
            }

            return result;
        }

        private async Task<byte[]> CalculateFileChecksum(string filePath)
        {
            using (var stream = File.OpenRead(filePath))
            {
                var hash = _hashAlgorithm.ComputeHash(stream);
                return hash;
            }
        }
    }
}
```

This code defines the `FileComparator` class, which includes a method to compare two directories and calculate SHA-256 checksums for their files. It uses Parallel Processing for performance improvement and manages exceptions from I/O operations. Additionally, it can exclude certain file types from comparison using an excludedFileTypes parameter in the constructor. The implementation is thread-safe with the help of a SemaphoreSlim.

