        {
            // Check if the user is locked out based on the rules fetched from the external API and the current lockout state in the cache
            var lockoutState = await _cache.GetLockoutStateAsync(user.Id);
            if (lockoutState == null)
                return false;

            var validationRules = await _cache.GetValidationRulesAsync();
            if (!IsWithinLockoutDuration(lockoutState, validationRules))
                return false;

            if (!ShouldLockoutOnFailureCount(lockoutState, validationRules))
                return false;

            return true;
        }
    }
