        public async Task<DataTableReader> TransferAndExecuteQuery(byte[] data)
        {
            var watch = Stopwatch.StartNew();

            // Compress the input data using multiple compression algorithms and select the most efficient one based on performance metrics
            var compressedData = _compressionAlgorithms.Aggregate((bestCompressedData, currentAlgorithm) =>
                CompareAndSelectCompressedData(bestCompressedData, currentAlgorithm, data));

            watch.Restart();

            // Encrypt the data using AES with the generated key
            var encryptedData = Encrypt(compressedData);

            watch.Stop();
            Console.WriteLine($"Encryption time: {watch.ElapsedMilliseconds}ms");

            // Log compression ratio, encryption/decryption time, decompression time, transmission time, and query execution time for each operation
            LogOperationMetrics(nameof(TransferAndExecuteQuery), nameof(Compress), compressedData.Length / data.Length);
            LogOperationMetrics(nameof(TransferAndExecuteQuery), nameof(Encrypt), watch.ElapsedMilliseconds);

            // Send the encrypted data to a remote database server via a network connection
            await SendEncryptedDataAsync(encryptedData);

