            watch.Restart();
            var decompressedData = Decompress(decryptedData);
            watch.Stop();
            Console.WriteLine($"Decompression time: {watch.ElapsedMilliseconds}ms");

            LogOperationMetrics(nameof(TransferAndExecuteQuery), nameof(Decrypt), watch.ElapsedMilliseconds);
            LogOperationMetrics(nameof(TransferAndExecuteQuery), nameof(Decompress), watch.ElapsedMilliseconds);

            // Execute a parameterized query against the database using the received data and return the result in a DataTableReader object
            var connection = new NpgsqlConnection(_connectionString);
            await connection.OpenAsync();
            using (var command = new NpgsqlCommand("YOUR_QUERY", connection))
            {
                command.Parameters.AddWithValue("data", decompressedData); // Replace with your parameterized query and data binding

                watch.Restart();
                var reader = await command.ExecuteReaderAsync(_timeout);
                watch.Stop();
                Console.WriteLine($"Query execution time: {watch.ElapsedMilliseconds}ms");

                LogOperationMetrics(nameof(TransferAndExecuteQuery), nameof(ExecuteQuery), watch.ElapsedMilliseconds);
                return reader;
            }
        }

        private static byte[] CompareAndSelectCompressedData(byte[] bestCompressedData, ICompressionAlgorithm currentAlgorithm, byte[] data)
        {
            var compressedData = currentAlgorithm.Compress(data);
            var compressionRatio = compressedData.Length / data.Length;

            if (compressionRatio > bestCompressedData.Length / bestCompressedData.Length)
                return compressedData;

            return bestCompressedData;
        }

        private static byte[] Encrypt(byte[] data) => _aes.Encrypt(_encoding.GetBytes(data), _aes.CreateEncryptor(), null);

        private static byte[] Decrypt(byte[] encryptedData) => _aes.Decrypt(encryptedData, _aes.CreateDecryptor(), null);

        private static byte[] Decompress(byte[] data)
        {
            using (var inputStream = new MemoryStream(data))
                using (var outputStream = new MemoryStream())
                {
                    var decompressor = LzmaEncoder.CreateDecoder(null, null, -1, LZMAencoder.EDictMode.Copy, false);
                    decompressor.SetInputStream(inputStream);

                    byte[] buffer = new byte[4096];
                    int read;

                    while ((read = decompressor.CodeStream.Read(buffer, 0, buffer.Length)) > 0)
                        outputStream.Write(buffer, 0, read);

                    return outputStream.ToArray();
                }
        }

