```rust
use std::collections::HashMap;
use std::env;
use std::fs::{self, File};
use std::io::{BufRead, BufWriter, Write};
use std::mem;
use std::path::Path;
use std::process::{Command, Stdio};
use rustc_driver::{Driver, DriverError, execute};
use sync_lazy::SyncLazy;
use log::{error, info};

const REPORT_FILE: &str = "compilation_report.txt";
type ErrorReport = Vec<(Path, Vec<String>)>;
type HookReport = HashMap<String, (bool, String)>;

// SyncLazy to install ice hooks
let ice_hooks = HookInstaller::new();

fn compile_files(paths: &[Path]) -> Result<CompilationReport, DriverError> {
    let mut report = CompilationReport {
        compilation_time: 0,
        resident_set_size: (0i64, 0i64),
        errors: Vec::new(),
        warnings: Vec::new(),
        hooks: HookReport::new(),
    };

    let mut current_resident_set_size = getrusage().ru_maxrss;

    for path in paths {
        info!("Compiling {}", path.display());
        let start_time = std::time::Instant::now();
        let output = execute(Driver::new(), &[("-C", "unused-variables"), path])?;

        report.compilation_time += start_time.elapsed().as_millis();
        current_resident_set_size = getrusage().ru_maxrss;

        let warnings = output.warnings().map(|w| w.message()).collect();
        let errors = output.errors().map(|e| (path, e.messages())).collect();

        report.errors.append(&mut errors);
        report.warnings.extend(warnings);

        ice_hooks.install(path, &output)?;
    }

    report.resident_set_size = (current_resident_set_size, getrusage().ru_maxrss);

