    fn install(&self, path: &Path, output: &rustc_driver::Output) -> Result<(), DriverError> {
        let hooks = self.hooks.get();
        for (hook_name, hook_path) in hooks {
            match execute(Command::new("cargo")
                .arg("run")
                .arg("-q")
                .arg(&format!("--manifest-path={}", path.parent().unwrap().display()))
