                .arg(hook_name)
                .arg(output.filename())
                .args(&["--"])
                .stdout(Stdio::null())
                .stderr(Stdio::inherit())
                .spawn()?) {
                Ok(_) => info!("Hook '{}' installed successfully", hook_name),
                Err(e) => error!("Failed to install hook '{}': {}", hook_name, e),
            }
        }
        Ok(())
    }
}

