            var logLines = reader.ReadToEnd().Split(Environment.NewLine, StringSplitOptions.RemoveEmptyEntries);

            var logProvider = _configProvider.Get<ILogProvider>();

            await ParallelLoopHelper.ForAllAsync(logLines, (line) =>
            {
                if (ShouldFilterLine(line))
                {
                    var value = ExtractValueFromLine(line);
                    FilterAndAggregateData(value);
                }
            }, _scheduler.TaskPool);
        }

        private bool ShouldFilterLine(string line)
        {
            if (!_configProvider.Get<RegexPattern>().Matches(line)) return false;
            var threshold = GetThreshold(_configProvider.Get<FilterKey>());
            return value > threshold;
        }

