        private void FilterAndAggregateData(double value)
        {
            var distribution = _distributionFactory();
            distribution.Configure(_thresholdCache[_configProvider.Get<FilterKey>()]);
            distribution.AddSample(value);
        }

        private double GetThreshold(string key)
        {
            if (_thresholdCache.TryGetValue(key, out var threshold)) return threshold;
            threshold = _configProvider.Get<double>(key);
            _thresholdCache.TryUpdate(key, threshold, double.MinValue);
            return threshold;
        }

        public override string ToString()
        {
            return $"Log file: {_logFilePath}, Distribution: {_distributionFactory().GetType().Name}";
        }
    }

