#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char* modifyFileName(const char* inputFileName) {
    // Validate input filename
    if (!inputFileName || !*(inputFileName)) {
        fprintf(stderr, "Error: Invalid filename.\n");
        return NULL;
    }

    size_t fileNameLength = strlen(inputFileName);

    // Allocate memory for new filename and set initial value to zero
    char* newFileName = malloc(fileNameLength + 5);
    memset(newFileName, 0, fileNameLength + 5);

    // Extract base name and original extension
    size_t lastDotIndex = fileNameLength;
    for (size_t i = 0; i < fileNameLength; ++i) {
        if (inputFileName[i] == '.') {
            lastDotIndex = i;
            break;
        }
    }
    strncpy(newFileName, inputFileName, lastDotIndex); // copy base name

    // Determine new extension based on filename criteria
    size_t hasDigits = 0;
    for (size_t i = 0; i < fileNameLength && !hasDigits; ++i) {
        if (inputFileName[i] >= '0' && inputFileName[i] <= '9') {
            hasDigits++;
        }
    }
    switch (hasDigits) {
        case 3:
            strcat(newFileName, ".jpg");
            break;
        case 4:
            strcat(newFileName, ".png");
            break;
        default:
            // If there are no digits or more than 4 digits, set new extension to "txt"
            strcat(newFileName, ".txt");
            break;
    }

    // Handle cases where the filename already has an extension and ensure it is properly modified
    if (lastDotIndex < fileNameLength) {
        char* dotLocation = &newFileName[lastDotIndex];
        size_t originalExtensionLength = fileNameLength - lastDotIndex;
        memmove(&dotLocation[4], &dotLocation[originalExtensionLength], originalExtensionLength + 1); // move extension chars to make space for new extension
    }

    return newFileName;
}

// Unit test implementation goes here
int main() {
    char* filename = "12345678.txt";
    char* modifiedFilename = modifyFileName(filename);
    printf("Modified File Name: %s\n", modifiedFilename);

    free(modifiedFilename); // Free the allocated memory after use
}
