use std::env;
use std::fs::File;
use std::io::{BufReader, Write};
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::sync::OnceCell;
use std::time::Instant;
use sync_lazy::SyncLazy;
use rustc_driver::{CargoToml, CargoWorkingDirectory, Driver, Error, ExitCode, Inputs, Outputs, SessionBuilder, Target};
use reqwest::blocking::Client;

const RSS_THRESHOLD: usize = 100 * 1024 * 1024; // 100 MB

static BUILD_SERVER_API_URL: OnceCell<String> = OnceCell::new();

fn init_build_server_api() {
    match env::var("BUILD_SERVER_API_URL") {
        Ok(url) => BUILD_SERVER_API_URL.set(url).unwrap(),
        Err(_) => eprintln!("Missing environment variable: BUILD_SERVER_API_URL"),
    }
}

fn report_compilation_status(status: CompilationStatus, exit_code: ExitCode) {
    let api_url = BUILD_SERVER_API_URL.get().unwrap();
    let client = Client::new();
    let response = client.post(&api_url)
        .json(&status)
        .send()
        .unwrap();
    if !response.is_ok() {
        eprintln!("Failed to report compilation status: {}", response.text().unwrap());
    }
}

enum CompilationStatus {
    Success(ExitCode),
    Failure(String),
}

fn compile(source_file: &PathBuf) -> Result<CompilationStatus, Box<dyn std::error::Error>> {
    init_build_server_api();

    let mut rss = 0;
    let start = Instant::now();
    let output = LoggingOutput::new(source_file);

    let resident_set_size_before = unsafe { libc::getrlimit(libc::RLIMIT_RSS) };
    rss += resident_set_size_before.as_usize();

    let rustc = Command::new("rustc")
        .stdin(Stdio::piped())
        .stdout(output.clone().into())
        .stderr(output.into());

    // Install the custom logging hook and ice hook.
    let mut driver_builder = SessionBuilder::new();
    let log_hook = SyncLazy::new(|| LogHook::new());
    let rustc_driver = driver_builder
        .log_hook(move || log_hook.with(|h| h.log_hook()))
        .build();

    // Set up input and output parameters for the Rust compiler.
    let inputs = Inputs::new()
        .file(source_file, None)
        .target(Target::host());
    let mut outputs = Outputs::default();

    // Execute the command with the custom logging hook installed.
    let mut process = rustc
        .arg("--crate-name")
        .arg("main")
        .args(inputs)
        .outputs(outputs)
        .spawn()?;
    let (_, stdin) = process.stdin.take().unwrap();

    // Feed the Rust compiler with Cargo.toml and Cargo.lock files if they exist.
    let cargo_toml = CargoToml::from_manifest_path(source_file.parent().unwrap())?;
    let cargo_working_directory = CargoWorkingDirectory::new(cargo_toml)?;
    let cargo_lock = cargo_working_directory.find_manifest_dir()?.join("Cargo.lock");

    if cargo_lock.is_file() {
        let lock_contents = File::open(&cargo_lock)?;
        let lock_reader = BufReader::new(lock_contents);
        let mut lock_input = Inputs::lock();
        for line in lock_reader.lines() {
            if let Ok(line) = line {
                lock_input.add_dependency(line)?;
            }
        }
    }

    // Configure the Rust compiler driver with the custom logging hook and inputs/outputs.
    rustc_driver
        .session(move |sess| {
            sess.set_driver_env("RUSTFLAGS", "-Cignore-this-error");
            sess.set_log_hook(move || log_hook.with(|h| h.log_hook()));
            Ok(())
        })
        .session_inputs(move |sess| {
            sess.add_input(&inputs);
            if let Some(lock_input) = outputs.lock_input() {
                lock_input.clone().into_iter().for_each(|dep| sess.add_input(dep));
            }
            Ok(())
        })
        .execute(process, &cargo_working_directory)?;

    stdin.write_all(b"")?;
    process.wait()?;

    let resident_set_size_after = unsafe { libc::getrlimit(libc::RLIMIT_RSS) };
    rss += resident_set_size_after.as_usize();

    if rss > RSS_THRESHOLD {
        eprintln!("Exceeded maximum allowed resident set size: {}", RSS_THRESHOLD);
        return Err(Box::new(std::io::Error::from_raw_os_error(libc::ENOMEM, "RSS exceeded threshold")));
    }

    let duration = start.elapsed().as_secs();
    eprintln!("Compilation time: {} seconds", duration);

    if process.successfull() {
        report_compilation_status(CompilationStatus::Success(process.code().unwrap()), process.code().unwrap())
    } else {
        let error = process.stderr.take().unwrap().into_string().unwrap();
        eprintln!("Error during compilation: {}", error);
        report_compilation_status(CompilationStatus::Failure(error), ExitCode::USAGE)
    }
}

fn log_hook(hook: &mut dyn FnMut(&str)) -> Box<dyn FnMut(&str)> {
    Box::new(move |message| {
        hook(format!("{} - {}", Instant::now().duration_since(start), message).as_str());
        hook(message);
    })
}

struct LoggingOutput {
    source_file: PathBuf,
    stdout: std::io::Stdio,
}

impl From<LoggingOutput> for std::process::Stdio> {
    fn from(output: LoggingOutput) -> Self {
        output.stdout
    }
}

impl Write for LoggingOutput {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        match self.stdout {
            Stdio::null() => Ok(0),
            _ => {
                self.stdout.write_all(buf)?;
                let duration = Instant::now().duration_since(start);
                eprintln!("{:?}", duration);
                Ok(buf.len())
            }
        }
    }

    fn flush(&mut self) -> std::io::Result<()> {
        match self.stdout {
            Stdio::null() => Ok(()),
            _ => self.stdout.flush(),
        }
    }
}
```

