using System;
using System.Collections.Concurrent;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;
using System.Threading.Tasks;
using log4net;

public class CustomDataStructure { /* Define your custom data structure here */ }

public static async Task<CustomDataStructure> LoadDataAsync(string filePath, ILog log)
{
    ConcurrentDictionary<string, CustomDataStructure> cache = new ConcurrentDictionary<string, CustomDataStructure>();
    lock (cache)
    {
        if (cache.TryGetValue(filePath, out var loadedData))
            return loadedData;
    }

    try
    {
        using (FileStream stream = File.OpenRead(filePath))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            CustomDataStructure data = (CustomDataStructure)formatter.Deserialize(stream);
            if (loadSuccessful: true)
            {
                lock (cache)
                {
                    cache[filePath] = data;
                }
                return data;
            }
        }
    }
    catch (Exception ex)
    {
        log.Error($"Failed to load data from file '{filePath}', error: {ex.Message}");
        throw;
    }

    CustomDataStructure defaultData = new CustomDataStructure(); // Provide a default value if loading fails
    lock (cache)
    {
        cache[filePath] = defaultData;
    }
    return defaultData;
}
