```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>

typedef struct {
    char compression_method[TIFF_MAXIMUM_TAG_VALUE_LEN];
    int bits_per_sample;
    int sample_per_pixel;
    int extra_samples_count;
    TIFFDataDesc extra_samples_info[TIFF_MAX_SAMPLES + 1];
} TiffImageInfo;

TiffImageInfo parse_tiff_image(const char *filename) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: Unable to open file '%s'\n", filename);
        return (TiffImageInfo){};
    }

    TiffImageInfo info;
    memset(&info, 0, sizeof(info));

    if (TIFFGetField(tif, TIFFTAG_COMPRESSION, &info.compression_method, sizeof(info.compression_method)) != sizeof(info.compression_method)) {
        fprintf(stderr, "Error: Missing compression method field in TIFF file\n");
        TIFClose(tif);
        return (TiffImageInfo){};
    }

    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &info.sample_per_pixel) != sizeof(info.sample_per_pixel)) {
        fprintf(stderr, "Error: Missing sample per pixel field in TIFF file\n");
        TIFClose(tif);
        return (TiffImageInfo){};
    }

    int samples_count = TIFFGetFieldDefaulted(tif, TIFFTAG_SAMPLESPERPIXEL, 3);
    info.extra_samples_count = samples_count - info.sample_per_pixel;

    for (int i = 0; i < samples_count; ++i) {
        TIFFDataDesc sample_info;
        if (TIFFGetField(tif, TIFF_RDS_SAMPLEDESCRIPTOR + i, &sample_info, sizeof(sample_info)) != sizeof(sample_info)) {
            fprintf(stderr, "Error: Missing sample %d information in TIFF file\n", i);
            break;
        }

        strncpy(info.extra_samples_info[i].name, sample_info.name, TIFF_MAXIMUM_TAG_VALUE_LEN);
        info.extra_samples_info[i].photometric = sample_info.photometric;
        info.extra_samples_info[i].samples_per_pixel = sample_info.samples_per_scan;
    }

    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &info.bits_per_sample) != sizeof(info.bits_per_sample)) {
        fprintf(stderr, "Error: Missing bits per sample field in TIFF file\n");
    } else if (info.bits_per_sample < 1 || info.bits_per_sample > 16) {
        fprintf(stderr, "Error: Unsupported number of bits per sample (%d)\n", info.bits_per_sample);
        TIFClose(tif);
        return (TiffImageInfo){};
    }

    TIFClose(tif);
    return info;
}
```
This code uses the popular `libtiff` library for reading and parsing the TIFF image file. The function `parse_tiff_image()` returns a structured data type containing the extracted information about the image's compression method, bits per sample, sample per pixel, and details of any extra samples. If any part of the metadata is missing or invalid, the function gracefully handles the situation and returns appropriate error messages or default values.

