#include <time.h>

#define MAX_CONCURRENT 10
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int num_threads = 0;

typedef struct {
    u_char ip[16];
    int err_code;
} ResolveResult;

void* get_ip(const char* hostname) {
    void* result;
    ... // Implement DNS resolution and error handling using getaddrinfo() and gai_strerror()
    return result;
}

int resolveHostname(const char* hostname, ResolveResult* result) {
    pthread_mutex_lock(&mutex);
    while (num_threads == MAX_CONCURRENT) {
        pthread_cond_wait(&cond, &mutex);
    }
    num_threads++;
    pthread_t thread;
    void* res = get_ip(hostname);
    int err_code = (void*)res == NULL ? -1 : 0;
    result->err_code = err_code;
    memcpy(result->ip, res, sizeof(u_char) * 16);
    pthread_create(&thread, NULL, free, res);
    pthread_mutex_unlock(&mutex);
    return err_code;
}
