```python
import os
from celery import Celery, Task
from redis import Redis
import requests

app = Celery("image_processing")
app.config_from_object("celeryconfig")
redis_client = Redis(host=os.getenv('REDIS_HOST'), port=os.getenv('REDIS_PORT'))

class ProcessImageTask(Task):
    def __call__(self, urls, status="pending", *args, **kwargs):
        for url in urls:
            if not isinstance(url, str):
                raise TypeError("Invalid image URL format")
            # Add to task queue
            self.apply_async((url,), queue="image_processing", callbacks=[succeeded, failed], args=args, kwargs=kwargs)

def succeeded(result, **kwargs):
    image_url = result
    status = redis_client.hget("task_queue", image_url) or "pending"
    redis_client.hset("processed_images", image_url, status)

def failed(exc, task_id, **kwargs):
    if exc:
        print(f"Failed to process image {task_id}: {str(exc)}")
        # Add task to retry queue (implement custom logic for retry limits and error handling)

def process_images(urls, status="pending", callback=None):
    if not isinstance(urls, list):
        raise TypeError("Expected a list of image URLs")
    try:
        result = ProcessImageTask.apply_async([urls, status], callback=callback)
        return {"task_id": result.id}
    except Exception as e:
        print(f"Failed to create task: {str(e)}")
        raise e

# Sample callback function for image processing tasks (implement custom logic here)
def process_image(url):
    # Fetch image and perform processing using external API
    response = requests.get(url)
    if response.status_code == 200:
        return "processed"
    raise Exception("Failed to process image")
