using Microsoft.Extensions.Logging;
using Newtonsoft.Json.Linq;

namespace UpdateClinicStatusAPI.Controllers
{
    [Route("api/[controller]")]
    [ApiController]
    public class ClinicsController : ControllerBase
    {
        private readonly DbContext _context;
        private readonly ILogger<ClinicsController> _logger;
        private readonly IMemoryCache _memoryCache;

        public ClinicsController(DbContext context, ILogger<ClinicsController> logger, IMemoryCache memoryCache)
        {
            _context = context;
            _logger = logger;
            _memoryCache = memoryCache;
        }

        [HttpPut("{id}/status")]
        public async Task<IActionResult> UpdateStatus(int id, string status, DateTime? timestamp, string ipAddress)
        {
            try
            {
                if (id <= 0) throw new ArgumentException("Invalid clinic ID");
                if (string.IsNullOrEmpty(status)) throw new ArgumentNullException(nameof(status));
                if (!timestamp.HasValue) throw new ArgumentNullException(nameof(timestamp));
                if (!ipAddress.StartsWith("::") && !ipAddress.StartsWith("inet", StringComparison.OrdinalIgnoreCase) && !System.Net.IPAddress.TryParse(ipAddress, out _)) throw new ArgumentException("Invalid IP address");

                var clinic = await _context.Clinics.FindAsync(id);
                if (clinic == null) throw new KeyNotFoundException("Clinic not found");

                clinic.Status = status;
                clinic.LastUpdatedAt = timestamp.Value;
                clinic.LastUpdatedIpAddress = ipAddress;
                await _context.SaveChangesAsync();

                _logger.LogInformation($"Clinic #{id} status updated by IP address: {ipAddress}");

                return Ok();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, ex.Message);
                throw;
            }
        }
    }
}
