void processArray(const vector<int>& data) {
    UF uf(data.size());
    unordered_map<pair<int, int>, bool> visited;

    vector<future<void>> futures;
    mutex mtx;
    for (size_t i = 0; i < data.size(); ++i) {
        auto it = find_if(data.begin(), data.end(), [&](int num) { return !visited[make_pair(num, i)] && uf.find(num) != uf.find(i); });
        if (it == data.end()) continue;
        int j = distance(data.begin(), it);
        future<void> f = async(launch::async, [&]() {
            lock_guard<mutex> lock(mtx);
            visited[make_pair(j, i)] = true;
            uf.union_set(j, i);
        });
        futures.push_back(move(f));
    }

    for (auto& f : futures) f.wait();
}

