2. SHA-256 hash calculation for a file:

```cpp
#include <openssl/sha.h>

std::vector<unsigned char> sha256(const std::string& filename) {
    FILE* fp = fopen(filename.c_str(), "rb");
    if (!fp) return {};

    unsigned char buffer[BUFFSIZE];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    while (1) {
        size_t bytes = fread(buffer, sizeof(buffer), 1, fp);
        if (!bytes) break;
        SHA256_Update(&ctx, buffer, bytes * sizeof(buffer[0]));
    }
    SHA256_Final(digest, &ctx);
    fclose(fp);

    std::vector<unsigned char> result(sizeof(digest));
    std::copy_n(digest, sizeof(result), result.begin());
    return result;
}
```

