import com.datastax.driver.core.ResultSet;
import com.datastax.driver.core.Row;
import redis.clients.jedis.Jedis;

@SpringBootApplication
@RestController
public class PokemonService {
    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/{id}";
    private static Cluster cassandraCluster;
    private static Jedis redisClient;

    @Autowired
    public void initialize(Cluster cluster, Jedis jedis) {
        this.cassandraCluster = cluster;
        this.redisClient = jedis;
    }

    @GetMapping("/pokemon/{id}")
    public String getPokemon(@PathVariable("id") int id) throws Exception {
        OkHttpClient client = new OkHttpClient();
