    }

    function loadAndExecuteScript(scriptPath) {
        const script = document.createElement('script');
        script.src = scriptPath;
        document.head.appendChild(script);

        script.onload = () => {
            if (script.error) {
                console.error(`Error loading script at ${scriptPath}:`, script.error);
            } else {
                callbackFn();
            }
        };
    }

    const scriptsToLoad = connection.scripts;

    scriptsToLoad.forEach(loadAndExecuteScript);

    return null; // Successful execution returns nothing, no error message
}
