import javax.cache.CacheManager;
import javax.cache.Cache;
import net.schmiz.sshj.*;

public class LogProcessingModule {
    private static final Logger log = LoggerFactory.getLogger(LogProcessingModule.class);
    private static ExecutorService executor;
    private static ScheduledExecutorService reportGenerator;
    private static Cache<String, String> reportCache;
    private static Map<String, Pattern> keywordPatterns;
    private static OkHttpClient httpClient = new OkHttpClient();
    private static List<String> serverUrls;

    public static void main(String[] args) throws Exception {
        // Initialize configuration from a properties file or command line arguments
        // ...

        executor = Executors.newFixedThreadPool(10);
        reportGenerator = Executors.newScheduledThreadPool(1);
        reportCache = CacheManager.create().getCache("reportCache");
        keywordPatterns = new HashMap<>();
        serverUrls = Arrays.asList(/* Read server URLs from configuration */);

        // Start processing log files asynchronously for each remote server
        for (String url : serverUrls) {
            executor.submit(() -> processLogFile(url));
        }

        // Schedule report generation tasks
        reportGenerator.scheduleAtFixedRate(() -> generateReports(), 0, 60, TimeUnit.SECONDS);
    }

    private static void processLogFile(String url) {
        try (Jsch jsch = new JschConfigStore().getDefaultJschConfig(null);
             Session session = jsch.getSession("username", url)) {
            session.setConfig("StrictHostKeyChecking", "no");
            session.connect();

            Channel channel = session.openChannel("sftp");
            channel.connect();
            ChannelSftp channelSftp = (ChannelSftp) channel;
            List<File> files = channelSftp.ls("/path/to/logfiles"); // Replace with the actual path to log files

            for (File file : files) {
                String fileName = file.getFileName().toString();
                if (!fileName.endsWith(".log")) continue;

                ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
                channelSftp.get(fileName, outputStream);
                String logContent = new String(outputStream.toByteArray());

                List<String> lines = Arrays.asList(logContent.split("\n"));
                for (String line : lines) {
                    checkAndProcessLine(line);
                }
            }
        } catch (Exception e) {
            log.error("Error while processing log file from {}", url, e);
        }
    }

    private static void checkAndProcessLine(String line) {
        for (Map.Entry<String, Pattern> entry : keywordPatterns.entry()) {
            Matcher matcher = entry.getValue().matcher(line);
            if (matcher.find()) {
                processKeywordOccurrence(entry.getKey(), line);
            }
        }
    }

    private static void processKeywordOccurrence(String keyword, String line) {
        // Cache the report for this keyword and line, update it if necessary
        String cachedReport = reportCache.get(keyword + ":" + line);
        if (cachedReport != null) {
            log.info("Cached report found: {}", cachedReport);
            return;
        }

        // Execute shell command for generating detailed insights and make API calls
        // ...

        // Save the new report to the cache
        reportCache.put(keyword + ":" + line, generatedReport);
    }

    private static void generateReports() {
        StringBuilder summaryReport = new StringBuilder();
        for (Map.Entry<String, Pattern> entry : keywordPatterns.entrySet()) {
            String keyword = entry.getKey();
            int count = reportCache.getKeys().stream()
                    .filter(k -> k.startsWith(keyword + ":"))
                    .mapToInt(Integer::parseInt)
                    .sum();
            summaryReport.append(keyword).append(": ").append(count).append("\n");
        }

        // Send the summary report to the external reporting API using OkHttpClient
