2. Implement the `resolve()` method in DNSResolver, which accepts a hostname and callback function as parameters, pushes them onto an internal queue, and performs the resolution process concurrently:

```cpp
std::future<std::vector<u_char>> DNSResolver::resolve(const std::string& hostname, const std::function<void(const std::vector<u_char>&)>& callback) {
    _pendingRequests.emplace(_pendingRequests.end(), std::make_pair(hostname, callback));

    // Split the DNS resolution task into smaller chunks and perform it concurrently using async/await pattern
    if (_concurrencyLimit > 1) {
        auto hostnameChunks = splitHostnameIntoChunks(hostname, _chunkSize);
        std::vector<std::future<std::vector<u_char>>> futures;
        for (const auto& chunk : hostnameChunks) {
            futures.emplace_back(_dnsService->resolve(chunk));
        }
        return std::when_all(std::move(futures)).then([this, &callback](const std::vector<std::future<std::vector<u_char>>>& results) {
            // Merge the IP addresses from all resolved chunks and invoke the callback function
            std::vector<u_char> finalResult;
            for (auto& result : results) {
                finalResult.insert(finalResult.end(), result.get().begin(), result.get().end());
            }
            this->_callbackQueue.push([finalResult, callback]() mutable { callback(std::move(finalResult)); });
            return std::make_future<void>(std::function<void()>() {});
        });
    } else {
        // If concurrency limit is 1, perform the resolution sequentially
        _dnsService->resolve(hostname).then([this, &callback](auto resolvedIP) mutable {
            _pendingRequests.pop();
            if (!_pendingRequests.empty()) {
                _currentRequest = _pendingRequests.front().first;
                _callbackQueue.push(_pendingRequests.front().second);
            }
            callback(std::move(resolvedIP));
        });
    }
}
```

