```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Xml.Serialization;
using Newtonsoft.Json;

public class XmlAndBinaryParser
{
    private readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();
    private readonly string _cacheDirectory;
    private readonly TimeSpan _cacheExpiration;

    public XmlAndBinaryParser(string cacheDirectory, TimeSpan cacheExpiration)
    {
        _cacheDirectory = cacheDirectory;
        _cacheExpiration = cacheExpiration;
    }

    public T ParseXml<T>(string filePath)
    {
        var key = $"{filePath}-{typeof(T).FullName}";
        if (_cache.TryGetValue(key, out var cachedResult))
        {
            return (T)cachedResult;
        }

        var serializer = new XmlSerializer(typeof(T));
        using var fileStream = File.OpenRead(filePath);
        var result = (T)serializer.Deserialize(fileStream);

        _cache.TryAdd(key, result);
        File.SetLastWriteTimeUtc(filePath, DateTime.UtcNow);

        GC.Collect();

        return result;
    }

    public void LoadBinary<T>(string filePath)
    {
        var key = $"{filePath}-{typeof(T).FullName}";
        if (_cache.TryGetValue(key, out var cachedResult))
        {
            return;
        }

        using var fileStream = File.OpenRead(filePath);
        BinaryFormatter formatter = new BinaryFormatter();
        using (var memoryStream = new MemoryStream())
        {
            fileStream.CopyTo(memoryStream);
            memoryStream.Seek(0, SeekOrigin.Begin);
            _cache[key] = formatter.Deserialize(memoryStream);
        }
    }

    public void SaveBinary<T>(string filePath, T data)
    {
        BinaryFormatter formatter = new BinaryFormatter();
        using var memoryStream = new MemoryStream();
        using (var fileStream = File.OpenWrite(filePath))
        {
            fileStream.CopyTo(memoryStream);
            memoryStream.Seek(0, SeekOrigin.Begin);
            formatter.Serialize(memoryStream, data);
            memoryStream.CopyTo(fileStream);
        }
    }

    public void ClearCache()
    {
        foreach (var entry in _cache)
        {
            if ((DateTime.UtcNow - entry.Key.Value.LastWriteTimeUtc) > _cacheExpiration)
            {
                _cache.TryRemove(entry.Key, out _);
            }
        }
    }
}
```

