import os
import time
import threading
import logging
import requests
import sqlite3
from collections import deque, namedtuple
from datetime import datetime, timedelta
from urllib.parse import urlencode
from concurrent.futures import ThreadPoolExecutor

# Configuration
MAX_AGE = int(os.getenv('MAX_AGE', '30'))  # seconds
MAX_ACTIVITY_PER_SEC = int(os.getenv('MAX_ACTIVITY_PER_SEC', '50'))
DEVICE_THRESHOLD = float(os.getenv('DEVICE_THRESHOLD', '600'))  # seconds
DB_PATH = os.getenv('DB_PATH', '.db')
API_URL = os.getenv('API_URL', 'https://example-api.com/alert')

UserLog = namedtuple('UserLog', ['user_id', 'activity_type', 'timestamp', 'device_info'])

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s: %(message)s')
logger = logging.getLogger(__name__)

class SessionalUserLog(UserLog):
    def __init__(self, *args, is_login=False, **kwargs):
        super().__init__(*args, **kwargs)
        self._session_id = None if is_login else self.session_id
        self.is_login = is_login

    @property
    def session_id(self):
        return self._session_id or self.user_id

    @session_id.setter
    def session_id(self, value):
        if not hasattr(self, '_session_id'):
            self._session_id = value
        elif self._session_id != value:
            logger.warning('Trying to change user session ID from %r to %r', self._session_id, value)

def _validate_log(log):
    if not isinstance(log, UserLog):
        raise ValueError('Invalid log structure')

    device_info = log.device_info or {}
    for key in ('user_id', 'activity_type', 'timestamp'):
        if key not in log:
            raise ValueError(f'Missing field {key} in the log')

    try:
        log.timestamp = datetime.fromisoformat(log.timestamp)
    except (TypeError, OverflowError, ValueError):
        raise ValueError('Invalid timestamp format')

    if isinstance(device_info, str):
        try:
            device_info = json.loads(device_info)
        except (TypeError, json.JSONDecodeError):
            logger.warning('Device info string is not JSON serializable', exc_info=True)

def _process_log(queue, sessions, devices, rate_limiter, log):
    if log.timestamp < datetime.now() - timedelta(seconds=MAX_AGE):
        return

    _validate_log(log)

    with rate_limiter(lock=sessions[log.user_id]):
        session = sessions[log.user_id]
        if log.is_login:
            session.reset_activity_counter()

        session.last_activity = log.timestamp
        session.activity_counter += 1
        if session.activity_counter > MAX_ACTIVITY_PER_SEC:
            logger.warning(f'Exceeded maximum activity rate for user {log.user_id}')
            return

        session.device = log.device_info or {}
        devices[(session.device, session.last_activity)] = (session, log)

def _update_metrics(devices):
    device_times = defaultdict(float)
    for device, (_, log) in devices.items():
        if log.activity_type == 'logout':
            del devices[device]
            continue
        delta = datetime.now() - log.timestamp
        device_times[(device, log.activity_type)] += delta.total_seconds()
    active_devices = len({device for device, _ in devices.values()})

    average_time_spent = sum(device_times[key][1] for key in device_times if device_times[key][0] > timedelta(seconds=DEVICE_THRESHOLD)) / (time.time() - last_metric_update)
    if average_time_spent >= DEVICE_THRESHOLD:
        payload = {'device': device, 'average_time_spent': average_time_spent}
        try:
            requests.post(API_URL, data=urlencode(payload))
        except Exception as e:
            logger.error('Error sending alert', exc_info=True)
    last_metric_update = time.time()

def _persist_metrics(devices):
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    for device, (_, log) in devices.items():
        if log.activity_type == 'logout':
            continue

        try:
            c.execute('INSERT INTO user_sessions VALUES (?, ?, ?, ?)', (log.user_id, log.timestamp, log.session_id, log.activity_type))
        except Exception as e:
            logger.error('Error persisting metrics', exc_info=True)
    conn.commit()
    conn.close()

def process_user_activity_logs(queue):
    sessions = {uid: SessionalUserLog(uid, None) for uid in set([log.user_id for log in queue])}
    devices = {}
    rate_limiter = threading.RLock()

    def worker():
        while True:
            log = queue.get()
            _process_log(queue, sessions, devices, rate_limiter, log)
            queue.task_done()

    with ThreadPoolExecutor(max_workers=10) as executor:
        [executor.submit(worker) for _ in range(10)]

    while not queue.empty():
        _process_log(queue, sessions, devices, rate_limiter, queue.get())
    executor.shutdown()

    _update_metrics(devices)
    _persist_metrics(devices)
```

