import time
import random
from collections import namedtuple
from threading import Lock, Semaphate
import smtplib
import email.utils
from typing import Optional

RateLimiter = namedtuple('RateLimiter', 'rate_limit_per_hour, remaining')

class RateLimiterSemaphore(object):
    def __init__(self, rate_limit_per_hour: int) -> None:
        self.lock = Semaphore(rate_limit_per_hour)
        self.reset_time = time.time()

    def acquire(self, blocking: bool = True, timeout: Optional[float] = None) -> bool:
        now = time.time()
        if now < self.reset_time + 3600:
            remaining = max(self.rate_limit_per_hour - (now - self.reset_time), 0)
            self.remaining = RateLimiter(rate_limit_per_hour, remaining)
        else:
            self.reset()
            remaining = self.rate_limit_per_hour

        return self.lock.acquire(blocking=blocking, timeout=timeout) and (self.remaining.remaining > 1)

    def reset(self):
        self.reset_time = time.time()
        self.remaining = RateLimiter(rate_limit_per_hour=self.rate_limit_per_hour, remaining=self.rate_limit_per_hour)

class DatabaseDAO:
