```java
import com.google.common.cache.*;
import okhttp3.*;
import java.io.IOException;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;

public class AvatarManager {
    private final Cache<Long, Future<Response>> avatarCache = CacheBuilder.newBuilder()
            .expireAfterAccess(10, TimeUnit.MINUTES)
            .maximumSize(500)
            .build(keyRemovalListener(evictionTreshold -> 0.75));

    private final AvatarService avatarService;
    private final UserSettings userSettings;

    public AvatarManager(AvatarService avatarService, UserSettings userSettings) {
        this.avatarService = avatarService;
        this.userSettings = userSettings;
    }

    public Response getUserAvatar(Long userId) throws ExecutionException, InterruptedException, IOException {
        Future<Response> future = avatarCache.getIfPresent(userId);
        if (future != null && !future.isDone()) {
            return future.get();
        }

        Response response = avatarService.retrieveAvatar(userId);
        if (!response.isSuccessful()) {
            throw new IOException("Failed to retrieve avatar: " + response.code());
        }

        avatarCache.put(userId, CompletableFuture.completedFuture(response));
        userSettings.updateUserAvatar(userId, response.body().byteStream());
        return response;
    }

    private LoadingCache.OnEvictionListener<Long, Future<Response>> keyRemovalListener(EvictionNotificationListener evictionListener) {
        return (notification, remove) -> {
            if (remove) {
                try {
                    userSettings.deleteUserAvatar(notification.key());
                } catch (IOException e) {
                    // Log the error for later inspection
                }
            }
            evictionListener.onEviction(notification);
        };
    }
}
```

