pub async fn process_logs(path: impl AsRef<Path>, schema: &str) -> Result<Vec<LogStat>, Error> {
    let pool = ThreadPoolBuilder::new().num_threads(8).build().unwrap();

    let mut stats = Vec::with_capacity(pool.available_parallelelism());
    for entry in walkdir::WalkDir::new(path)?.into_iter() {
        let entry = entry?;
        if entry.file_type().is_file() && (entry.path().extension() == Some(vec![".log", ".json", ".csv"])) {
            pool.install(|| process_single_log(&entry.path(), schema)).collect();
        }
    }

    pool.join_all(stats).await?;
    Ok(stats)
}

async fn process_single_log(path: &Path, schema: &str) -> Result<LogStat, Error> {
    // Read the file content and validate it against the given schema
    let content = read_file(path)?;

    match content.extension().and_then(|ext| ext.to_str()) {
        Some("log") => parse_log(&content),
        Some("json") => parse_json(&content),
        Some("csv") => parse_csv(&content),
        _ => return Err(Error::new(IoErrorKind::NotFound, "Invalid file extension")),
    }
}

fn read_file(path: &Path) -> Result<String, IoError> {
    let mut buf = Vec::new();
    BufReader::new(File::open(path)?).read_to_end(&mut buf)?;
    Ok(buf.into_iter().collect())
}

