namespace fs = std::filesystem;
using json = nlohmann::json;
using namespace boost::lockfree;

struct ConfigurationError {
    enum class Type { FileNotFound, JsonError, SchemaError };
    Type type;
    std::string message;
};

class ConfigLoader final {
public:
    explicit ConfigLoader(boost::asio::io_service& ioService)
        : resourceManager_(ioService), cache_(), schemaValidator_() {}

    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> load(const fs::path& path, const std::string& env) {
        auto it = cache_.find(env);
        if (it != cache_.end())
            return it->second;

        spsc_queue<json, spsc_queue_traits<json>> jsonQueue(128);
        resourceManager_.acquire([this, path, env, jsonQueue]() mutable {
            if (loadFromFile(path, env, jsonQueue)) {
                json mergedConfig = mergeConfigurations(jsonQueue.pop_all());
                validateSchema_(mergedConfig);
                cache_[env] = parseFlatConfig(mergedConfig);
            }
        });

        while (!cache_.count(env)) std::this_thread::yield(); // Allow other threads to proceed
        return cache_[env];
    }

private:
    bool loadFromFile(const fs::path& path, const std::string& env, spsc_queue<json>& jsonQueue) {
        try {
            json config = json::parse(std::ifstream(path).dump());
            jsonQueue.push(config);
            return true;
        } catch (const fs::filesystem_error& e) {
            logError("Configuration error", ConfigurationError{ConfigurationError::Type::FileNotFound, e.what()});
            return false;
        } catch (const json::parse_error& e) {
            logError("Configuration error", ConfigurationError{ConfigurationError::Type::JsonError, e.what()});
            return false;
        }
    }

    // Implement the remaining functions as per the engineering focus areas and new requirements
    ...
};

