    public ProcessAndOptimizeImageStream(Region region) {
        executor = new ThreadPoolExecutor(0, MAX_CONCURRENCY, 60L, TimeUnit.SECONDS, new SynchronousQueue<>());
        db = DistributedDatabase.getInstance();
        cloudStorage = CloudStorageApi.getInstance(region);
