    private Map<String, KeyPair> initializeEncryptionKeys() {
        Map<String, KeyPair> keys = new HashMap<>();
        try {
            KeyPairGenerator keyGen = KeyPairGenerator.getInstance("RSA");
            keyGen.initialize(2048);
            for (int i = 0; i < 10; i++) {
                keys.put(String.valueOf(i), keyGen.generateKeyPair());
            }
        } catch (NoSuchAlgorithmException e) {
            log.error("Error initializing encryption keys", e);
        }
        return keys;
    }

    public void processAndUploadImage(Path imageFile, String bucketName, Map<String, String> metadataTags, int quality) {
        try (ByteArrayInputStream inputStream = new ByteArrayInputStream(Files.readAllBytes(imageFile))) {
            Mat mat = new Mat(inputStream);
            optimizeImage(mat, quality);

            ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
            writeOptimizedImage(mat, outputStream);
            byte[] optimizedImageData = outputStream.toByteArray();

            String metadataId = encryptAndStoreMetadata(metadataTags, inputStream.available(), optimizedImageData.length);
            if (metadataId == null) {
                log.error("Failed to store image metadata");
                throw new RuntimeException("Failed to store image metadata");
            }

            PutObjectRequest putRequest = PutObjectRequest.builder()
                    .bucket(bucketName)
                    .key(metadataId)
                    .objectContentType("image/jpeg")
                    .objectContent(optimizedImageData)
                    .tagging(metadataTags)
                    .build();
            uploadImageAsync(putRequest);
        } catch (Exception e) {
            log.error("Error processing and uploading image", e);
            throw new RuntimeException("Error processing and uploading image", e);
        }
    }

    private String encryptAndStoreMetadata(Map<String, String> metadataTags, long inputSize, long outputSize) {
        // Encode metadata tags as a base64 string
        String encodedMetadata = Base64.getEncoder().encodeToString(json.toJsonBytes(metadataTags));

        // Calculate and store the encrypted metadata in the distributed database
        db.put("image_metadata:" + inputSize, encryptionKeys.get(System.currentTimeMillis() % encryptionKeys.size()).getPublic().encoded);
        db.put("image_metadata:" + outputSize, encryptionKeys.get(System.currentTimeMillis() % encryptionKeys.size()).getPrivate().encoded);
        db.put("image_metadata:tagged", encodedMetadata);

        return "image_metadata:" + inputSize;
    }

    // ... (Implement the rest of the function, including optimizeImage, writeOptimizedImage, uploadImageAsync and other necessary methods)

    private void uploadImageAsync(PutObjectRequest putRequest) {
        executor.submit(() -> uploadImage(putRequest));
    }
}
