    public void convert(String outputFile, String inputDir) throws IOException {
        List<Path> imageFiles = FileUtils.listFiles(new File(inputDir), new String[]{"jpg", "jpeg", "png", "gif"}, true);
        for (Path imageFilePath : imageFiles) {
            log("Processing file: " + imageFilePath);
            Map<String, String> metadata = fetchMetadata(imageFilePath);
            BufferedImage bufferedImage = ImageIO.read(imageFilePath.toFile());
            Image pdfImage = createPdfImage(bufferedImage, metadata);
            document.add(pdfImage);
        }

        pdfDocument.close();
        log("PDF generated: " + outputFile);
    }

    private Map<String, String> fetchMetadata(Path imageFilePath) throws IOException {
        Request request = new Request.Builder()
                .url("https://example-image-metadata-service/metadata?file=" + URLEncoder.encode(imageFilePath.toString(), StandardCharsets.UTF_8))
                .build();
        Response response = httpClient.newCall(request).execute();
        if (!response.isSuccessful()) {
            throw new IOException("Failed to fetch metadata for file: " + imageFilePath);
        }
        JsonObject metadataJson = JsonParser.parseString(response.body().string()).getAsJsonObject();
        // You can access the metadata fields using metadataJson.get("fieldName").getAsString()
        return metadataJson;
    }

    private Image createPdfImage(BufferedImage bufferedImage, Map<String, String> metadata) {
        float scaleFactor = getScaleFactor(metadata);
        int width = (int) (bufferedImage.getWidth() * scaleFactor);
        int height = (int) (bufferedImage.getHeight() * scaleFactor);
        Image pdfImage = new Image(pdfDocument, bufferedImage).setAutoScaleToFitWidth(width, height);
        return pdfImage;
    }

    private float getScaleFactor(Map<String, String> metadata) {
        // Implement your logic to calculate the scale factor based on image dimensions and orientation, etc.
        return 1f;
    }

    private void log(String message) {
        System.out.println(TAG + ": " + message);
    }

    public static void main(String[] args) throws Exception {
        ImageToPdf app = new ImageToPdf();
        if (args.length < 2) {
            throw new IllegalArgumentException("Usage: java ImageToPdf <outputFile> <inputDir>");
        }
        String outputFile = args[0];
        String inputDir = args[1];
        app.convert(outputFile, inputDir);
    }
}
