// Define a macro for thread-local storage of the logging function pointer
#ifdef __TLS_SUPPORT__
#define TLS_LOGGING log_t *tls_logger = thread_local(log_t*);
#else
#define TLS_LOGGING /* Empty */
#endif

void dynamicStringCopy(char *dest, size_t destSize, const char *src, logCallback_t logger, void *userData) {
    TLS_LOGGING

    // Validate input encoding and handle potential encoding issues
    if (src == NULL || dest == NULL || destSize == 0) {
        return;
    }

    size_t srcLen = strlen(src);
    char *destEnd = dest + destSize - 1; // Destination end pointer

    // Copy the string and ensure it's null-terminated, handling potential truncation
    size_t copyLength = (srcLen < destSize) ? srcLen : (destSize - 1);
    memcpy(dest, src, copyLength);
    dest[copyLength] = '\0';

    // Log critical truncation events if the string is larger than the buffer
    if (srcLen > copyLength && logger) {
        *tls_logger = logger;
        (*tls_logger)(LOG_CRIT, userData, "String truncated during dynamic copy: %s", src);
    }
}
