  host: 'localhost',
  port: 6379, // Replace with your Redis server address and port
});

app.use(session({
  store: new RedisStore({ client: redisClient }),
  secret: 'your_secret_key',
  resave: false,
  saveUninitialized: false,
}));

async function executeCommandAndGetData(command) {
  let cachedData;

  // Check if data is cached and not older than a certain threshold (e.g., 1 hour)
  redisClient.get(command, async (err, result) => {
    if (err || !result) {
      try {
        const commandOutput = await new Promise((resolve, reject) => {
          child_process.exec(command, (error, stdout, stderr) => {
            if (error) {
              console.error(`Error executing command: ${error}`);
              reject(error);
            } else {
              resolve(stdout);
            }
          });
        });

        // Cache the result for future use
        redisClient.setex(command, 3600, commandOutput); // Set cache time to 1 hour (3600 seconds)

        const data = await fetchDataFromAPI(commandOutput);
        cachedData = data;
      } catch (error) {
        console.error(`Error executing command and fetching API data: ${error}`);
      }
    } else {
      cachedData = JSON.parse(result);
    }

    // Return the final result to be sent to the browser
    return cachedData;
  });
}

async function fetchDataFromAPI(commandOutput) {
  try {
    const apiResponse = await axios.get(`${API_URL}/api/data?output=${encodeURIComponent(commandOutput)}`, {
      headers: {
        Authorization: `Bearer ${API_TOKEN}` // Replace with your API token
      }
    });

    if (apiResponse.status === 200) {
      return apiResponse.data;
    } else {
      console.error(`Error fetching data from the API: ${apiResponse.status} ${apiResponse.statusText}`);
      throw new Error('API error');
    }
  } catch (error) {
    console.error(`Error fetching data from the API: ${error}`);
  }
}

// Your route handler using the executeCommandAndGetData function
app.get('/', async (req, res) => {
  try {
    const data = await executeCommandAndGetData('your_shell_command');
    res.json(data);
  } catch (error) {
    console.error(`Error executing command and fetching API data: ${error}`);
    res.status(500).send('Internal Server Error');
  }
});

app.listen(3000, () => {
  console.log('Server listening on port 3000');
});
```

