    public FileProcessor(String rootDirectory, Pattern keywordPattern, ReportingApi reportingApi, LoggingService loggingService,
                          int maxRetries, long retryIntervalMillis, String logFileCompressFormat) {
        this.rootDirectory = rootDirectory;
        this.keywordPattern = keywordPattern;
        this.cache = new HashMap<>();
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors() * 2);
        this.reportingApi = reportingApi;
        this.loggingService = loggingService;
        this.maxRetries = maxRetries;
        this.retryIntervalMillis = retryIntervalMillis;
        this.logFileCompressFormat = logFileCompressFormat;
    }

    public void process() {
        File rootDir = new File(rootDirectory);
        for (File file : rootDir.listFiles()) {
            if (file.isDirectory()) {
                processDirectory(file);
            } else if (Files.isRegularFile(file.toPath())) {
                processFile(file);
            }
        }
    }

    private void processDirectory(File directory) {
        executor.submit(() -> process(directory));
    }

