    private final ExecutorService executor;
    private final ConcurrentHashMap<String, ImageReader> readers;
    private final ConcurrentHashMap<String, ImageWriter> writers;
    private final MetadataExtractor metadataExtractor;

    public ImageProcessingUtility() {
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.readers = new ConcurrentHashMap<>();
        this.writers = new ConcurrentHashMap<>();
        this.metadataExtractor = new MetadataExtractor(); // Placeholder for your metadata extraction API

