        // ImageIO.getImageWritersByFormatName("gif").forEach(writer -> writers.put(writer.getFormatName(), writer));
    }

    public void processImages(List<String> inputFileNames, List<String> outputFileNames, String targetFormat) throws IOException {
        Callable<Void> task = () -> processImage(inputFileNames.remove(0), outputFileNames.remove(0), targetFormat);
        while (!inputFileNames.isEmpty()) {
            executor.execute(task);
        }
        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.MILLISECONDS);
    }

    private void processImage(String inputFileName, String outputFileName, String targetFormat) throws IOException {
        ImageReader reader = readers.get(ImageIO.getFileTypeFromName(inputFileName).getName());
        ImageWriter writer = writers.get(targetFormat);

        if (reader == null || writer == null) {
            throw new IllegalArgumentException("Unsupported input or output format.");
        }

        try (InputStream inputStream = new FileInputStream(inputFileName)) {
            try (ImageReader readerInstance = ImageIO.createImageReader(inputStream)) {
                readerInstance.setInput(reader);
                BufferedImage image = readerInstance.read(0);

                // Perform transformations like resizing or cropping here
                // Extract EXIF data using metadataExtractor and save it for later use

                try (ImageWriter writerInstance = ImageIO.createImageWriter(new FileOutputStream(outputFileName), writer)) {
                    writer.setOutputFile(writerInstance);
                    writer.writeToSequence(Collections.singletonList(image), null);
                }
            }
        }
    }
}
