fn compile(file_paths: Vec<PathBuf>, timeout: Duration, config: Config) {
    let start = SystemTime::now();
    let mut total_duration = Duration::from_secs(0);
    let mut total_rss = 0;
    let mut error_count = 0;

    for file_path in &file_paths {
        if !file_path.exists() {
            log("error", format!("File {} does not exist", file_path.display()));
            continue;
        }

        match compile_single(file_path, timeout, config) {
            Ok((exit_code, compiled_rss)) => {
                total_duration += SystemTime::now().duration_since(start).unwrap();
                total_rss += compiled_rss;
                if total_rss > MAX_RSS {
                    RETURN_CODE.store(127, Ordering::SeqCst);
                    break;
                }
            }
            Err(e) => {
                error_count += 1;
                log("error", e.to_string());
            }
        }
    }

    if error_count > 0 || total_rss > MAX_RSS {
        RETURN_CODE.store(1);
    } else {
        call_build_server(RETURN_CODE.load(Ordering::SeqCst), total_duration, file_paths[0].clone(), vec![]).await;
    }
}

