    return new Promise((resolve, reject) => {
      try {
        if (!label || typeof label !== 'string') {
          console.error(`Invalid test label: ${label}`);
          resolve(null);
          return;
        }

        const module = require(`${options.moduleName}`);
        currentResult = callback(currentResult, label, module[testFunction]);

        if (results.includes(null)) {
          console.log('Test suite failed.');
          reject();
          return;
        }

        resetLibrary();
      } catch (error) {
        console.error(`Error during test ${label}:`, error);
        resolve(null);
      }
    });
  };

  const runTests = async (testCases, verbose = false) => {
    for (let i = 0; i < testCases.length; i++) {
      if (!testCases[i].label || typeof testCases[i].label !== 'string') {
        console.error('Invalid test case found.');
        return;
      }

      const resetMockLibrary = () => blueslip.reset();

      await testCases[i].testFunction(testCases[i].label, test, resetMockLibrary);

      if (verbose) {
        console.log(`Completed test ${testCases[i].label}`);
      }
    }
  };

  return async (testCases, moduleName, validationFunction, verbose = false) => {
    if (!Array.isArray(testCases)) {
      console.error('Invalid test cases provided.');
      return;
    }

    options = {
      moduleName,
      validationFunction
    };

    blueslip.setup(); // Initialize the mocking library
