using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using System.Threading.Tasks;
using Synchronization = System.Collections.ThreadSafeReadOnlyDictionary<string, Lazy<IDistribution>>;

public class DynamicValueGenerator
{
    private readonly Synchronization _cache;
    private DistributionType _currentDistributionType;
    private object[] _currentDistributionParameters;

    public DynamicValueGenerator(ConfigurationManager config)
    {
        _cache = new Synchronization();
        UpdateDistribution(config.GetCurrentDistribution());
    }

    public void UpdateDistribution(IDistribution distribution)
    {
        if (distribution == null) throw new ArgumentNullException(nameof(distribution));
        _currentDistributionType = distribution.DistributionType;
        _currentDistributionParameters = distribution.Parameters;
        _cache.TryAdd(GetCacheKey(), new Lazy<IDistribution>(CreateDistribution));
    }

    private IDistribution CreateDistribution()
    {
        switch (_currentDistributionType)
        {
            case DistributionType.Gaussian:
                return new GaussianDistribution((float)_currentDistributionParameters[0], (float)_currentDistributionParameters[1]);
            case DistributionType.Uniform:
                return new UniformDistribution((float)_currentDistributionParameters[0], (float)_currentDistributionParameters[1]);
            case DistributionType.Exponential:
                return new ExponentialDistribution(Mathf.Clamp((float)_currentDistributionParameters[0], 0.01f, float.MaxValue));
            default:
                throw new NotSupportedException($"Unsupported distribution type: {_currentDistributionType}");
        }
    }

    public IDistribution GetCurrentDistribution() => _cache[GetCacheKey()].Value;

    private string GetCacheKey() => $"{_currentDistributionType}:{string.Join(",", _currentDistributionParameters.Select(o => o.ToString()))}";

    public float NextFloat() => GetCurrentDistribution().NextFloat();

    public int NextInt(int maxValue) => (int)(GetCurrentDistribution().NextFloat() * maxValue);

    public override string ToString()
    {
        var currentDist = GetCurrentDistribution();
        return $"DynamicValueGenerator: Current Distribution - Type: {currentDist.DistributionType}, Range: [{currentDist.MinValue}, {currentDist.MaxValue}], Parameters: {string.Join(",", _currentDistributionParameters)}";
    }
}
