public interface IDistribution
{
    DistributionType DistributionType { get; }
    float MinValue { get; }
    float MaxValue { get; }
    float NextFloat();
}

public abstract class Distribution : IDistribution
{
    public abstract DistributionType DistributionType { get; }
    public abstract float MinValue { get; }
    public abstract float MaxValue { get; }
    public abstract float NextFloat();
}

public class GaussianDistribution : Distribution
{
    private readonly float _mean, _standardDeviation;

    public GaussianDistribution(float mean, float standardDeviation)
    {
        _mean = mean;
        _standardDeviation = standardDeviation;
    }

    public override DistributionType DistributionType => DistributionType.Gaussian;
    public override float MinValue => float.MinValue;
    public override float MaxValue => float.MaxValue;
    public override float NextFloat() => UnityEngine.Random.Range(_mean - _standardDeviation, _mean + _standardDeviation);
}

public class UniformDistribution : Distribution
{
    private readonly float _minValue, _maxValue;

    public UniformDistribution(float minValue, float maxValue)
    {
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public override DistributionType DistributionType => DistributionType.Uniform;
    public override float MinValue => _minValue;
    public override float MaxValue => _maxValue;
    public override float NextFloat() => UnityEngine.Random.Range(_minValue, _maxValue);
}

public class ExponentialDistribution : Distribution
{
    private readonly float _lambda;

    public ExponentialDistribution(float lambda) => _lambda = lambda;

    public override DistributionType DistributionType => DistributionType.Exponential;
    public override float MinValue => 0f;
    public override float MaxValue => float.MaxValue;
    public override float NextFloat() => -Mathf.Log(UnityEngine.Random.value) / _lambda;
}
