using System;
using System.Xml;
using System.Xml.XPath;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Linq;

public class XPathCache
{
    private readonly Dictionary<string, XPathDocument> _cache = new Dictionary<string, XPathDocument>();
    private int _cacheSize = 100;

    public void ConfigureCache(int size) => _cacheSize = size;

    public XPathDocument GetOrLoadXPathDocument(string source)
    {
        if (_cache.ContainsKey(source)) return _cache[source];

        var document = new XmlDocument();
        if (Uri.IsWellFormedUriString(source, UriKind.Absolute))
            using (var webClient = new WebClient())
                document.LoadXml(webClient.DownloadString(source));
            else
                document.Load(source);

        var xpathDocument = new XPathDocument(document);
        if (_cache.Count > _cacheSize) _cache.RemoveAt(0);
        _cache[source] = xpathDocument;
        return _cache[source];
    }
}

public class ElementNotFoundException : Exception { }
public class MultipleElementsFoundException : Exception { }

public XElement GetFirstMatchingElement(XPathCache cache, string xpath, string xmlSource)
{
    var xpathDocument = cache.GetOrLoadXPathDocument(xmlSource);
    var navigator = xpathDocument.CreateNavigator();
    var nodes = navigator.Select(xpath);

    if (nodes.Count == 0) throw new ElementNotFoundException($"No element found with XPath '{xpath}' in source '{xmlSource}'.");
    if (nodes.Count > 1) throw new MultipleElementsFoundException($"Multiple elements found with XPath '{xpath}' in source '{xmlSource}'. Found {nodes.Count} elements.");

    return ((IReadOnlyCollection<XPathNavigator>)nodes).Cast<XPathNavigator>().First().SelectElement();
}
