        return distr(engine_);
    }

    void MT19937Generator::setMin(int min) {
        if (min >= max_) throw std::invalid_argument("New minimum value must be less than current maximum value.");
        min_ = min;
    }

    void MT19937Generator::setMax(int max) {
        if (max < min_) throw std::invalid_argument("New maximum value must be greater than or equal to current minimum value.");
        max_ = max;
    }

    unsigned long long MT19937Generator::getSeed() const {
        return current_seed_;
    }

    void MT19937Generator::saveSeed() {
        // Implement database communication using the external API.
        // This example uses sqlpp11 for simplicity but can be replaced with your preferred library.
        std::string db_url = "your-db-url";
        sqlpp::connection conn(db_url);
        if (!conn) throw std::runtime_error("Could not connect to the database.");

        auto query = sqlpp::single<sqlpp::statement>(R"(
            INSERT INTO seeds (seed) VALUES (:seed) ON DUPLICATE KEY UPDATE seed=VALUES(seed);
        )");

        try {
            conn.exec_no_results(query.bind("seed", current_seed_));
        } catch (const sqlpp::exception& e) {
            std::cerr << "Error saving seed to the database: " << e.what() << std::endl;
        }
    }
}
