#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <functional>

template<typename Iterator, typename String, size_t N>
void insertion(Iterator begin, Iterator end, const String& search, const String& insertion, std::mutex& mtx) {
    for (auto it = begin; it != end && std::distance(it, end) <= N; ++it) {
        if (*it == search) {
            std::lock_guard<std::mutex> lock(mtx);
            *it += insertion;
            return;
        }
    }
    // Append to the list if search string not found within N elements
    std::lock_guard<std::mutex> lock(mtx);
    it = end;
    *it = insertion;
}
