use log4rs::{append::file::FileAppender, filter::FilterSink, config::{Appender, Config}, logger::Logger};

#[derive(Debug)]
struct HttpRequestOptions {
    url: String,
    tls_config: Option<TlsConnector>,
}

impl FromStr for HttpRequestOptions {
    type Err = Box<dyn std::error::Error>;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let opts: Value = serde_json::from_str(s)?;
        Ok(HttpRequestOptions {
            url: opts["url"].as_str().unwrap().to_owned(),
            tls_config: match opts.get("tls_config") {
                Some(value) => {
                    let connector = TlsConnector::from_pem_file(value["cert"].as_str().unwrap())?;
                    let mut trust_list = TrustList::empty();
                    for pem in value["ca"]
                        .as_array()
                        .ok_or("Invalid format: missing 'ca' field")?
                        .iter()
                    {
                        trust_list.add_client_certs_from_pem(pem)?;
                    }
                    connector.set_native_roots(trust_list)?;
                    Some(connector)
                }
                None => None,
            },
        })
    }
}

// Logging configuration
let logger = Logger::root();
let config = Appender::builder()
    .filter(FilterSink::new(LevelFilter::Trace, Box::new(|record| record.level() >= LevelFilter::Trace)))
    .build("file", FileAppender::new(log4rs::append::file::RollingFileAppenderBuilder::builder()
        .filename("app.log")
        .build()))?;
logger.add_appender(config)?;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} <options>", args[0]);
        return;
    }

    match HttpRequestOptions::from_str(&args[1]) {
        Ok(opts) => {
            let client = Client::builder().tls_connector(opts.tls_config.unwrap_or_else(|| TlsConnector::system_default()));
            let mut req_builder = client.get(&opts.url);

            for (name, value) in reqwest::header::HeaderMap::from_iter(vec![("User-Agent", "MyApp/1.0")]) {
                req_builder = req_builder.header(name, value);
            }

            let mut response = match req_builder.send() {
                Ok(res) => res,
                Err(e) => {
                    eprintln!("Error sending request: {}", e);
                    return;
                }
            };

            if let Some(path) = std::path::Path::new(&opts.url).file_name() {
                if path.exists() {
                    std::fs::remove_file(path).unwrap_or_else(|e| eprintln!("Error removing old file: {}", e));
                }
            }

            let mut response_body = Vec::new();
            match response.read_to_end(&mut response_body) {
                Ok(_) => {
                    println!("\nResponse body:");
                    println!("{}", std::str::from_utf8(&response_body).unwrap());
                }
                Err(e) => {
                    eprintln!("Error reading response body: {}", e);
                }
            };
        }
        Err(e) => {
            eprintln!("Invalid options: {}", e);
        },
    }
}
```

