char* resolve_env_var(const char *env_var);
char* constructFilePath(const char *path, size_t max_buffer_size, bool is_absolute, char *error_msg) {
    size_t path_len = strlen(path);
    if (path_len > max_buffer_size - 1) {
        snprintf(error_msg, sizeof(error_msg), "Path exceeds the maximum buffer size (%zu).", max_buffer_size);
        free(error_msg);
        return NULL;
    }

    char *resolved_path = malloc(max_buffer_size);
    if (!resolved_path) {
        snprintf(error_msg, sizeof(error_msg), "Failed to allocate memory for the resolved path.");
        return NULL;
    }

    strncpy(resolved_path, path, max_buffer_size - 1);
    resolved_path[max_buffer_size - 1] = '\0'; // ensure null-terminated

    char *current_dir = is_absolute ? "" : getcwd(NULL, 0);
    if (!current_dir) {
        snprintf(error_msg, sizeof(error_msg), "Failed to retrieve the current working directory.");
        free(resolved_path);
        return NULL;
    }

    #ifdef _WIN32
        // Replace `~` with %USERPROFILE% and other Windows-style path elements
        for (size_t i = 0; i < path_len; ++i) {
            if (resolved_path[i] == '~') {
                size_t env_var_len = strlen(getenv("USERPROFILE"));
                strncat(resolved_path, getenv("USERPROFILE"), max_buffer_size - i - 1);
                resolved_path[max_buffer_size - 1] = '\0'; // ensure null-terminated
                i += env_var_len;
            } else if (resolved_path[i] == '\\') {
                resolved_path[i] = '/';
            }
        }
    #else
        // Replace `~` with home directory and other Unix-style path elements
        for (size_t i = 0; i < path_len; ++i) {
            if (resolved_path[i] == '~' && resolved_path[i + 1] != '/') {
                size_t home_dir_len = strlen(getenv("HOME"));
                strncat(resolved_path, getenv("HOME"), max_buffer_size - i - 1);
                resolved_path[max_buffer_size - 1] = '\0'; // ensure null-terminated
                i += home_dir_len;
            } else if (resolved_path[i] == '/' && resolved_path[i + 1] == '/') {
                resolved_path[i++] = resolved_path[++i] = '/';
            }
        }
    #endif

    char *current_dir_ptr = strrchr(resolved_path, '/');
    if (!current_dir_ptr || !is_absolute) {
        strncat(resolved_path, current_dir, max_buffer_size - strlen(resolved_path) - 1);
        resolved_path[max_buffer_size - 1] = '\0'; // ensure null-terminated
    }

    char **symlink_paths;
    size_t symlink_count = 0;
    for (size_t i = 0; resolved_path[i]; ++i) {
        if (resolved_path[i] == '/') {
            symlink_paths = realloc(symlink_paths, sizeof(char*) * ++symlink_count);
            symlink_paths[symlink_count - 1] = resolved_path + i + 1;
        }
    }
    if (symlink_count > 0) {
        symlink_paths = realloc(symlink_paths, sizeof(char*) * symlink_count);
        symlink_paths[symlink_count] = NULL;

        #ifdef _WIN32
            DWORD flags = 0;
#else
            int flags = 0;
#endif
        for (size_t i = 0; symlink_paths[i]; ++i) {
            struct stat st;
            if (lstat(symlink_paths[i], &st) == -1 || S_ISLNK(st.st_mode)) {
                char *resolved_symlink = NULL;
#ifdef _WIN32
                    DWORD size = GetLongPathName(GetFullPathName(symlink_paths[i], MAX_PATH, NULL, NULL), NULL);
                    resolved_symlink = malloc(size);
                    if (GetLongPathName(symlink_paths[i], NULL, NULL, resolved_symlink) != 0) {
                        free(resolved_symlink);
                        resolved_symlink = NULL;
                        break;
                    }
#else
                    ssize_t size = readlink(symlink_paths[i], NULL, 0);
                    if (size == -1 || size >= SIZE_MAX) {
                        free(resolved_symlink);
                        resolved_symlink = NULL;
                        break;
                    }
                    resolved_symlink = malloc(size + 1);
#endif
                if (readlink(symlink_paths[i], resolved_symlink, size) != -1) {
                    strncat(resolved_path, resolved_symlink, max_buffer_size - strlen(resolved_path) - 1);
                    resolved_path[max_buffer_size - 1] = '\0'; // ensure null-terminated
                } else {
                    free(resolved_symlink);
                    snprintf(error_msg, sizeof(error_msg), "Failed to read symlink '%s'.", symlink_paths[i]);
                    free(resolved_path);
                    return NULL;
                }
            }
        }
        free(symlink_paths);
    }

    if (access(resolved_path, F_OK) == -1) {
        snprintf(error_msg, sizeof(error_msg), "Invalid file path '%s'.", resolved_path);
        free(resolved_path);
        return NULL;
    }

    return resolved_path;
}

char* resolve_env_var(const char *env_var) {
    if (env_var[0] != '$') {
        return strdup(env_var);
    }

    size_t env_var_len = strlen(env_var + 1);
    char *value = getenv(env_var + 1);
    if (!value) {
        return NULL;
    }

    size_t value_len = strlen(value);
    char *resolved_value = malloc(env_var_len + value_len + 1);
    strncpy(resolved_value, env_var, env_var_len);
    resolved_value[env_var_len] = '=';
    strncat(resolved_value, value, value_len + 1);
    return resolved_value;
}
```

