#include <string.h>
#include <dlfcn.h>
#include <assert.h>
#include <sys/stat.h>
#include <fnmatch.h>

typedef void (*TestFunction)(void);

enum ErrorCodes {
    EC_SUCCESS = 0,
    EC_INVALID_FILENAME = -1,
    EC_FILE_NOT_FOUND = -2,
    EC_INVALID_FILETYPE = -3,
    EC_MAX_FILENAME_LENGTH_EXCEEDED = -4,
};

void test_module_async(const char* filename, TestFunction tests[], int reduction_initial, void (*callback)(const char*, int), const char* extension) {
    // Validate original filename and generate a new one if necessary
    size_t len = strlen(filename);
    if (len >= 255) {
        return callback("Error: Filename exceeds maximum length of 255 characters.", EC_MAX_FILENAME_LENGTH_EXCEEDED);
    }

    int has_extension = fnmatch(".txt|.jpg|.png", filename + (len - 4), FNM_NOESCAPE); // Check for common file types, assuming the extension starts with a dot or is empty
    if (has_extension < 0) {
        return callback("Error: Invalid filename format.", EC_INVALID_FILENAME);
    }

    char* new_filename = malloc(len + 4 + strlen(extension)); // Allocate space for the new filename, including the original name, a period, potential digits, and the extension
    strcpy(new_filename, filename);

    int last_char_is_digit = isdigit(new_filename[len - 1]);
    if (last_char_is_digit) {
        new_filename[len++] = '.';
        while (len < 6 + strlen(extension)) // Ensure there's enough space for at least 3 digits and the extension
            new_filename[len++] = '0';
        int digit = new_filename[--len] - '0';
        memmove(new_filename + len, new_filename + (len - 1), strlen(new_filename + (len - 1)) + 1); // Move the last character (now the first potential digit) to the appropriate position
        snprintf(new_filename + len, 4, "%d", digit); // Append digits based on the last character of the original filename
    } else {
        memmove(new_filename + len, new_filename + (len - 1), strlen(new_filename + (len - 1)) + 1); // Move the last character to the appropriate position for potential digit appending
        snprintf(new_filename + len, 4, "%03d", 0); // Default to appending 3 digits starting from 0 if no digit was found in the original filename
    }

    strcat(new_filename, extension);

    // Load the module and initialize the mocking library
    void* handle = dlopen(new_filename, RTLD_NOW);
    if (!handle) {
        const char* err = dlerror();
        callback(err != NULL ? err : "Error: Failed to load module.", EC_FILE_NOT_FOUND);
        free(new_filename);
        return;
    }

    void (*module_test)(void) = dlsym(handle, "test"); // Get the test function from the loaded module
    if (!module_test) {
        const char* err = dlerror();
        callback(err != NULL ? err : "Error: Failed to find test function in the loaded module.", EC_FILE_NOT_FOUND);
        dlclose(handle);
        free(new_filename);
        return;
    }

    // Perform asynchronous tests using reduce with callbacks and reset blueslip after each test
    void (*reset_blueslip)(void) = NULL; // Assuming you have a function pointer for this
    if (reset_blueslip != NULL) { // Assuming the mocking library has a way to be reset
        void (*test_series)(TestFunction tests[], int reduction_initial, void (*callback)(const char*, int), void (*reset)(void)) = reduce_async(tests, reduction_initial, callback, reset);
        test_series(tests, reduction_initial, callback, reset_blueslip);
    } else {
        printf("Warning: Blueslip does not have a reset function.\n");
        // Implement the test series using your chosen method without the reset functionality
    }

    dlclose(handle);
    free(new_filename);
}
