Below is an example implementation in Node.js using Express.js and MongoDB (Mongoose). This example demonstrates optimistic concurrency control, soft delete mechanism, error handling, and a user-friendly response format for both success and failure scenarios.

```javascript
const express = require('express');
const mongoose = require('mongoose');
const Schema = mongoose.Schema;

// Define Resource model
const resourceSchema = new Schema({
  id: String,
  version: Number,
  data: Object,
  deleted: { type: Boolean, default: false }
});

const Resource = mongoose.model('Resource', resourceSchema);

// Initialize Express app and routes
const app = express();
app.use(express.json());

// Define PUT route for updating a resource
app.put('/api/resource/:id', async (req, res) => {
  try {
    // Find the resource with the given id
    const resource = await Resource.findOne({ id: req.params.id });

    if (!resource) {
      return res.status(404).json({ error: 'Resource not found' });
    }

    // Check if the resource is not deleted and if the version number matches
    if (resource.deleted || resource.version !== req.body.version) {
      return res.status(409).json({ error: 'Invalid or stale data' });
    }

    // Update the resource with new data and increment its version number
    resource.data = req.body.data;
    resource.version++;
    await resource.save();

    res.status(200).json({ success: true, data: resource });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Define DELETE route for soft deleting a resource
app.delete('/api/resource/:id', async (req, res) => {
  try {
    // Find the resource with the given id
    const resource = await Resource.findOne({ id: req.params.id });

    if (!resource) {
      return res.status(404).json({ error: 'Resource not found' });
    }

    // Soft delete the resource by setting deleted to true
    resource.deleted = true;
    await resource.save();

    res.status(200).json({ success: true, data: resource });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Start the server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});
```

