// Custom streaming data processor
class DataProcessor extends Transform {
  constructor(byteCount) {
    super({ objectMode: true });
    this.byteCount = byteCount;
    this.dataBuffer = Buffer.alloc(0);
    this.encodingDetected = null;
  }

  _transform(chunk, encoding, callback) {
    try {
      const newChunk = Buffer.concat([this.dataBuffer, chunk]);
      this.dataBuffer = newChunk;

      if (!this.encodingDetected) {
        // Detect the character encoding of the input stream
        this.encodingDetected = detectEncoding(newChunk);
      }

      const bytesToCopy = Math.min(this.byteCount, newChunk.length);
      const resultBuffer = newChunk.slice(0, bytesToCopy);

      // Log progress and error information as needed
      if (this.byteCount === bytesToCopy) {
        logService.log('Data processed:', resultBuffer.toString(this.encodingDetected));
      } else if (errorDuringProcessing) {
        logService.error('Error during data processing:', errorMessage);
      }

      this.dataBuffer = newChunk.slice(bytesToCopy);
      callback(null, resultBuffer);
    } catch (error) {
      // Handle encoding errors and other exceptions gracefully
      logService.error('Error encountered during data processing:', error.message);
      callback(error);
    }
  }
}

