  const dataProcessor = new DataProcessor(byteCount);
  const throttledStreams = getStreams().map((stream) => throttleStream(stream));

  await Promise.all(throttledStreams.map((stream) =>
    stream.pipe(dataProcessor).on('error', (err) => {
