import java.util.concurrent.*;

public class StockPriceAggregator {
    private static final ExecutorService executor = Executors.newFixedThreadPool(5);
    private static final JsonObject jsonSchema = Json.createObjectBuilder()
            .add("type", "object")
            .add("properties", Json.createObjectBuilder()
                    .add("ticker", Json.createObjectBuilder().add("type", "string"))
            .add("timestamp", Json.createObjectBuilder().add("type", "number"))
            .add("price", Json.createObjectBuilder().add("type", "number")))
            .build();

    public List<StockPrice> fetchAndValidateDailyPrices(List<String> tickers) throws IOException, URISyntaxException {
        List<Future<List<StockPrice>>> futures = new ArrayList<>();
        for (String ticker : tickers) {
            Callable<List<StockPrice>> callable = () -> fetchAndValidatePrice(ticker);
            futures.add(executor.submit(callable));
        }

        List<StockPrice> results = new ArrayList<>();
        for (Future<List<StockPrice>> future : futures) {
            try {
                results.addAll(future.get());
            } catch (ExecutionException | InterruptedException e) {
                logError(e);
            }
        }

        return results;
    }

    private List<StockPrice> fetchAndValidatePrice(String ticker) throws IOException, URISyntaxException {
        List<StockPrice> stockPrices = new ArrayList<>();

        JsonObject jsonSchemaInstance = Json.createObjectBuilder().build();
        SchemaGenerator schemaGen = new SchemaGenerator(jsonSchema);
        JsonSchema jsonSchemaObj = schemaGen.generateJsonSchema(jsonSchemaInstance, false);

        try (InputStream is = getPriceStream(ticker)) {
            JsonReader jsonReader = Json.createReader(is);
            JsonArray jsonArray = jsonReader.readArray();

            ExecutorService priceProcessorExecutor = Executors.newSingleThreadExecutor();
            Queue<JsonObject> priceQueue = new ConcurrentLinkedQueue<>();
            for (JsonValue jsonValue : jsonArray) {
                if (jsonValue instanceof JsonObject) {
                    priceQueue.add((JsonObject) jsonValue);
                }
            }

            priceProcessorExecutor.submit(() -> {
                while (!priceQueue.isEmpty()) {
                    JsonObject jsonObject = priceQueue.poll();
                    if (jsonValidator(jsonSchemaObj, jsonObject)) {
                        StockPrice stockPrice = new Gson().fromJson(jsonReader.readEntity(StockPrice.class).toString(), StockPrice.class);
                        stockPrices.add(stockPrice);
                    } else {
                        logError(new Exception("Invalid data for ticker: " + ticker));
                    }
                }
            });

            priceProcessorExecutor.shutdown();
            while (!priceProcessorExecutor.isTerminated()) {
                // Allow the thread to finish processing any remaining items
            }
        } catch (JsonValidationException e) {
            logError(e);
        }

        return stockPrices;
    }

    private void logError(Throwable throwable) {
        System.err.println("Error occurred: " + throwable.getMessage());
        // Implement logging to a file or external service here
    }

    private InputStream getPriceStream(String ticker) throws URISyntaxException {
        // Replace with your financial API endpoint and credentials
        URI uri = new URI("https://financial-api.com/daily-prices?ticker=" + ticker);
        HttpURLConnection connection = (HttpURLConnection) uri.toURL().openConnection();
        connection.setRequestMethod("GET");
        // Add headers for authentication and other required parameters
        // ...

        return connection.getInputStream();
    }

    private boolean jsonValidator(JsonSchema jsonSchema, JsonValue jsonValue) {
        try {
            Validator validator = Validation.buildDefaultValidatorFactory().newValidator();
            validator.validate(jsonValue, jsonSchema);
            return true;
        } catch (SchemaValidationException e) {
            return false;
        }
    }
}

class StockPrice {
