```cpp
#include <algorithm>
#include <stdexcept>
#include <forward_list>
#include <string>

constexpr int NO_ERROR = 0;
constexpr int KEY_NOT_FOUND = -1;
constexpr int VALUE_EMPTY_ERROR = -2;

bool updateForwardList(std::forward_list<std::string>& list, const std::string& key, const std::string& value) {
    int status = NO_ERROR;

    auto it = list.begin();
    if (it == list.end()) { // If the list is empty, append 'value' at the end
        list.push_back(value);
    } else {
        bool found = false;
        while (it != list.end() && !found) {
            if (*it == key) {
                found = true;
                if (value.empty()) { // Handle the case where value is empty but key is found
                    status = VALUE_EMPTY_ERROR;
                    break;
                }
                it = list.erase_after(it);
                *it = value;
            } else {
                ++it;
            }
        }

        if (!found && key != "") { // If key is not found, append 'value' at the end
            list.push_back(value);
            status = KEY_NOT_FOUND;
        }
    }

    return status == NO_ERROR;
}
