    def __init__(self, device_id: int):
        self.device_id = device_id
        self.total_activity_time = 0.0
        self.user_count = 0
        self.max_avg_time_spent = 0.0
        self.activity_queue = deque(maxlen=1000)

def monitor_device_usage(logs: List[ActivityLog], prometheus_url: str, weather_api_url: str):
    device_metrics = defaultdict(DeviceMetrics)
    weather_data = fetch_weather_data(weather_api_url)

    def process_log(log: ActivityLog):
        device_metrics[log.device_info['id']].activity_queue.append((log.timestamp, log.activity_type))
        device_metrics[log.device_info['id']].total_activity_time += log.timestamp - device_metrics[log.device_info['id']].activity_queue[-1][0]
        device_metrics[log.device_info['id']].user_count += 1

    def update_metrics():
        for device in device_metrics.values():
            if device.activity_queue:
                avg_time_spent = sum([(t - device.activity_queue[0][0]).total_seconds() for t, _ in device.activity_queue]) / len(device.activity_queue)
                device.max_avg_time_spent = max(device.max_avg_time_spent, avg_time_spent)

    def fetch_weather_data(url: str):
        # Fetch weather data from the API and return temperature and humidity as a tuple
        pass

    threading.Thread(target=process_log, args=(logs[i],), name='Log Processor').start()
    while logs:
        time.sleep(1 / len(logs))
        process_index = (time.time() - start_time) % len(logs)
        update_metrics()
        if process_index == 0:
            for device in device_metrics.values():
                if device.max_avg_time_spent > adjust_threshold(weather_data):
                    send_alert(prometheus_url, device.device_id)

def adjust_threshold(weather_data: tuple):
