           MemoryCache = new MemoryCache(new MemoryCacheOptions());
           Providers = new ConcurrentDictionary<string, IDynamicLogProvider>();
       }

       protected TValue GetDistributionParameter<TValue>(string key) => MemoryCache.GetOrCreate(key, entry =>
       {
           var config = Configuration.GetSection("distributions").Get<ConfiguredDistribution<TValue>>();
           return config.Types.First(t => t.Key == key).Value;
       });

       protected abstract Task ConfigureProvidersAsync();

       public virtual void Dispose()
       {
           foreach (var provider in Providers)
               provider.Value.Dispose();
           GC.SuppressFinalize(this);
       }
   }

