```csharp
public class RateLimiter {
    private readonly ConcurrentDictionary<string, int> _updateCounts = new ConcurrentDictionary<string, int>();
    private readonly TimeSpan _rateLimitInterval;

    public RateLimiter(TimeSpan rateLimitInterval) {
        _rateLimitInterval = rateLimitInterval;
    }

    public bool IsRateLimited(string ipAddress) {
        var currentCount = Interlocked.Increment(ref _updateCounts[ipAddress]);
        if (currentCount > 10) {
            _updateCounts[ipAddress] = 0;
            return true;
        }

        var timeSinceLastUpdate = DateTimeOffset.UtcNow - _lastUpdated[ipAddress];
        if (timeSinceLastUpdate < _rateLimitInterval) {
            return true;
        }

        _updateCounts[ipAddress] = 0;
        _lastUpdated[ipAddress] = DateTimeOffset.UtcNow;
        return false;
    }

    private readonly ConcurrentDictionary<string, DateTimeOffset> _lastUpdated = new ConcurrentDictionary<string, DateTimeOffset>();
}
