```java
import java.io.*;
import java.util.concurrent.*;
import com.amazonaws.AmazonServiceException;
import com.amazonaws.SdkClientException;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.AmazonS3ClientBuilder;
import com.amazonaws.util.json.JSONObject;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.concurrent.atomic.AtomicReference;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.PostConstruct;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Deserializer {
    private static final Logger LOGGER = LoggerFactory.getLogger(Deserializer.class);
    private ExecutorService executor = Executors.newCachedThreadPool();
    private AmazonS3 s3Client = null;
    private Map<String, Class<?>> cachedClasses = new HashMap<>();
    private Map<String, JSONObject> cachedConfigs = new HashMap<>();

    @PostConstruct
    public void init() {
        try {
            File configFile = Files.exists(Paths.get("config.json")) ? Paths.get("config.json") : throw new RuntimeException("Missing configuration file");
            JSONObject config = new JSONObject(Files.readString(configFile));
            s3Client = AmazonS3ClientBuilder.standard()
                    .withRegion(config.getString("aws_region"))
                    .withCredentials(
                            AWSStaticCredentialsProvider.create(
                                    config.getString("access_key"),
                                    config.getString("secret_key"),
                                    null))
                    .build();
        } catch (Exception e) {
            LOGGER.error("Error initializing S3 client: {}", e.getMessage());
            throw new RuntimeException(e);
        }
    }

    public <T> T deserialize(byte[] data) throws IOException, ClassNotFoundException {
        AtomicReference<Class<?>> targetClass = new AtomicReference<>();
        ObjectInputStream inputStream = null;
        try {
            synchronized (cachedClasses) {
                if (!cachedClasses.containsKey("targetClass")) {
                    JSONObject config = cachedConfigs.getOrDefault("class_config", new JSONObject());
                    String className = config.getString("target_class");
                    targetClass.set(getClass().getClassLoader().loadClass(className));
                }
            }
            inputStream = new ObjectInputStream(new ByteArrayInputStream(data));
            return (T) inputStream.readObject();
        } catch (Exception e) {
            LOGGER.error("Error deserializing object: {}", e.getMessage());
            throw new RuntimeException(e);
        } finally {
            if (inputStream != null) inputStream.close();
        }
    }

    public void uploadToS3(byte[] data, String bucketName, String key) {
        Runnable uploadTask = () -> {
            try {
                s3Client.putObject(bucketName, key, data);
                LOGGER.info("Uploaded {} to S3: {}", key, bucketName);
            } catch (AmazonServiceException e) {
                LOGGER.error("Error uploading to S3: {}", e.getMessage());
                throw new RuntimeException(e);
            } catch (SdkClientException e) {
                LOGGER.error("SDK error uploading to S3: {}", e.getMessage());
                throw new RuntimeException(e);
            }
        };
        executor.execute(uploadTask);
    }
}
```

