package com.example;

import org.springframework.boot.context.application.Initializer;
import org.springframework.context.ApplicationContext;
import org.springframework.context.ApplicationContextInitializer;
import org.springframework.data.annotation.PersistenceExceptionTranslation;
import org.springframework.data.jpa.repository.config.EnableJpaRepositories;
import org.springframework.data.mongodb.repository.config.EnableMongoRepositories;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.Map;

@RestController
public class DataProcessor {
    private final ExternalApiClient apiClient;
    private final MySQLRepository mysqlRepo;
    private final PostgreSQLRepository postgreSqlRepo;
    private final MongoDBRepository mongoDBRepo;
    private final ReportGenerator reportGenerator;
    private final CacheManager cacheManager;

    public DataProcessor(ExternalApiClient apiClient,
                          MySQLRepository mysqlRepo,
                          PostgreSQLRepository postgreSqlRepo,
                          MongoDBRepository mongoDBRepo,
                          ReportGenerator reportGenerator,
                          CacheManager cacheManager) {
        this.apiClient = apiClient;
        this.mysqlRepo = mysqlRepo;
        this.postgreSqlRepo = postgreSqlRepo;
        this.mongoDBRepo = mongoDBRepo;
        this.reportGenerator = reportGenerator;
        this.cacheManager = cacheManager;
    }

    @GetMapping("/processData")
    public ResponseEntity<Object> processData(@RequestParam Map<String, String> params) {
        // Handle external API request and rate limits, deserialize into objects using Jackson
        Object data = apiClient.fetchData(params);

        // Perform data aggregation and transformation based on the specific database type
        List<Object> transformedData = switch (params.get("dbType")) {
            case "mysql" -> mysqlRepo.aggregateAndTransform(data);
            case "postgresql" -> postgreSqlRepo.aggregateAndTransform(data);
            case "mongodb" -> mongoDBRepo.aggregateAndTransform(data);
            default -> throw new IllegalArgumentException("Unsupported database type");
        };

        // Cache the transformed data for future requests
        cacheManager.putInCache(params, transformedData);

        // Generate a customizable PDF report and return it as a byte array
        byte[] pdfReport = reportGenerator.generateReport(transformedData, params);

        return ResponseEntity.ok().body(pdfReport);
    }
}

@EnableJpaRepositories
interface MySQLRepository extends JpaRepository<MyObject, Long> {
    // Custom query methods for data aggregation and transformation
}

@EnableMongoRepositories
interface MongoDBRepository extends ReactiveMongoRepository<MongoObject, String> {
    // Custom aggregate and transform pipeline methods
}

